INSERT INTO verses (goi, conical, edition_id, version, language_subtag, book, chapter, verse, testament, verse_text) VALUES
(1, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 1, 'OT', 'Au commencement, Dieu créa les cieux et la terre.'),
(2, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 2, 'OT', 'La terre était néant et vide, et les ténèbres couvraient la face de l''abîme, et l''esprit de Dieu planait sur la face des eaux.'),
(3, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 3, 'OT', 'Dieu dit : Que la lumière soit ! Et la lumière fut.'),
(4, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 4, 'OT', 'Dieu vit que la lumière était bonne, et Dieu sépara la lumière d''avec les ténèbres.'),
(5, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 5, 'OT', 'Dieu appela la lumière jour, et les ténèbres, il les appela nuit. Et il y eut un soir, et il y eut un matin : ce fut le premier jour.'),
(6, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 6, 'OT', 'Dieu dit : qu''il y ait un firmament au milieu des eaux, et qu''il sépare les eaux d''avec les eaux.'),
(7, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 7, 'OT', 'Dieu fit le firmament, et il sépara les eaux qui étaient sous le firmament d''avec les eaux qui étaient au-dessus du firmament ; et cela fut ainsi.'),
(8, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 8, 'OT', 'Dieu appela le firmament cieux, et il y eut un soir et il y eut un matin : ce fut le second jour.'),
(9, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 9, 'OT', 'Dieu dit : Que les eaux qui sont sous les cieux se rassemblent en un seul lieu, et que le sec paraisse. Et il en fut ainsi.'),
(10, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 10, 'OT', 'Dieu appela le sec terre, et l''espérance des eaux, il l''appela mer ; et Dieu vit que cela était bon.'),
(11, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 11, 'OT', 'Dieu dit : Que la terre produise de l''herbe, de l''herbe portant de la postérité, un bois faisant du fruit selon son espèce, dont la postérité est en lui, sur la terre ; et il en fut ainsi.'),
(12, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 12, 'OT', 'La terre fit sortir de l''herbe tendre, de l''herbe portant de la postérité selon son espèce, et du bois faisant du fruit, dont la postérité est en lui, selon son espèce ; et Dieu vit que cela était bon.'),
(13, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 13, 'OT', 'Il y eut un soir, il y eut un matin : ce fut le troisième jour.'),
(14, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 14, 'OT', 'Dieu dit : Que des luminaires soient dans le firmament des cieux, pour séparer le jour et la nuit ; qu''ils servent de signes, pour les assignations, pour les jours et pour les années.'),
(15, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 15, 'OT', 'Et ils servirent de luminaires dans le firmament des cieux pour éclairer la terre ; et il en fut ainsi.'),
(16, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 16, 'OT', 'Dieu fit les deux grands luminaires : le grand luminaire pour la domination du jour, et le petit luminaire pour la domination de la nuit, et les étoiles.'),
(17, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 17, 'OT', 'Dieu les plaça dans le firmament des cieux pour éclairer la terre.'),
(18, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 18, 'OT', 'et pour dominer sur le jour et sur la nuit, et pour séparer la lumière des ténèbres ; et Dieu vit que cela était bon.'),
(19, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 19, 'OT', 'Il y eut un soir, il y eut un matin : le quatrième jour.'),
(20, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 20, 'OT', 'Dieu dit : Que les eaux fourmillent d''un reptile, d''une âme vivante, et que l''oiseau vole au-dessus de la terre, à la face du firmament des cieux.'),
(21, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 21, 'OT', 'Dieu créa les grands chacals, et toute âme vivante qui se meut, dont les eaux fourmillèrent selon leurs espèces, et tout oiseau ailé selon son espèce. Et Dieu vit que cela était bon.'),
(22, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 22, 'OT', 'Dieu les bénit, en disant : « Soyez féconds et multipliez-vous, et remplissez les eaux dans les mers, et que l''oiseau abonde sur la terre. »'),
(23, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 23, 'OT', 'Il y eut un soir, il y eut un matin : le cinquième jour.'),
(24, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 24, 'OT', 'Dieu dit : Que la terre produise une âme vivante selon son espèce, du bétail, des reptiles et des bêtes de la terre selon leur espèce. Et cela fut ainsi.'),
(25, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 25, 'OT', 'Dieu fit les bêtes de la terre selon leur espèce, le bétail selon son espèce, et tout reptile du sol selon son espèce, et Dieu vit que cela était bon.'),
(26, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 26, 'OT', 'Dieu dit : Faisons l''homme à notre image, selon notre forme, et qu''ils dominent sur les poissons de la mer, sur les oiseaux des cieux, sur le bétail, sur toute la terre, et sur tout reptile qui rampe sur la terre.'),
(27, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 27, 'OT', 'Dieu créa l''homme à son image, à l''image de Dieu il le créa, mâle et femelle il les créa.'),
(28, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 28, 'OT', 'Dieu les bénit, et Dieu leur dit : Soyez féconds, multipliez-vous, remplissez la terre et soumettez-la, et dominez sur les poissons de la mer, sur les oiseaux des cieux, et sur tout être vivant qui se meut sur la terre.'),
(29, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 29, 'OT', 'Et Dieu dit : Voici, je vous ai donné toute herbe portant postérité, qui est sur la face de toute la terre, et tout bois qui a en lui fruit de bois portant postérité ; cela vous sera pour nourriture.'),
(30, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 30, 'OT', 'Et à tout être vivant de la terre, et à tout oiseau des cieux, et à tout ce qui rampe sur la terre, en qui il y a une âme vivante, toute herbe verte sera pour nourriture ; et cela fut ainsi.'),
(31, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 1, 31, 'OT', 'Dieu vit tout ce qu''il avait fait, et voici, cela était très bon. Et il y eut un soir, et il y eut un matin : le sixième jour.'),
(32, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 1, 'OT', 'Ainsi furent achevés les cieux et la terre, et toute leur armée.'),
(33, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 2, 'OT', 'Dieu acheva au septième jour son ouvrage qu''il avait fait, et il se reposa au septième jour de tout son ouvrage qu''il avait fait.'),
(34, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 3, 'OT', 'Dieu bénit le septième jour et le sanctifia, car en ce jour il se reposa de tout son ouvrage que Dieu avait créé en le faisant.'),
(35, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 4, 'OT', 'Voici les générations des cieux et de la terre lorsqu''ils furent créés, au jour où l''Éternel Dieu fit la terre et les cieux.'),
(36, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 5, 'OT', 'Tout arbrisseau des champs n''était pas encore sur la terre, et toute herbe des champs n''avait pas encore germé, car l''Éternel Dieu n''avait pas fait pleuvoir sur la terre, et il n''y avait pas d''homme pour cultiver le sol.'),
(37, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 6, 'OT', 'Une vapeur montait de la terre et arrosait toute la face du sol.'),
(38, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 7, 'OT', 'L''Éternel Dieu forma l''homme de la poussière de la terre, il souffla dans ses narines un souffle de vie, et l''homme devint une âme vivante.'),
(39, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 8, 'OT', 'L''Éternel Dieu planta un jardin en Éden, à l''orient, et il y plaça l''homme qu''il avait formé.'),
(40, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 9, 'OT', 'L''Éternel Dieu fit pousser de la terre tout bois désirable à l''apparence et bon pour la nourriture, et le bois de la vie au milieu du jardin, et le bois de la connaissance du bien et du mal.'),
(41, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 10, 'OT', 'Un fleuve sortait d''Éden pour arroser le jardin, et de là il se divisait et devenait quatre têtes.'),
(42, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 11, 'OT', 'Le nom du premier est Pischon ; c''est lui qui entoure toute la terre de Havila, où il y a de l''or.'),
(43, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 12, 'OT', 'L''or de cette terre-là est bon ; là se trouvent le bdellium et la pierre d''onyx.'),
(44, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 13, 'OT', 'Le nom du second fleuve est Guihon ; c''est lui qui entoure toute la terre de Cusch.'),
(45, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 14, 'OT', 'Le nom du troisième fleuve est Hiddékel, qui coule à l''orient de l''Assyrie, et le quatrième fleuve est l''Euphrate.'),
(46, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 15, 'OT', 'L''Éternel Dieu prit l''homme et le plaça dans le jardin d''Éden pour le cultiver et pour le garder.'),
(47, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 16, 'OT', 'L''Éternel Dieu donna cet ordre à l''homme : De tout bois du jardin tu pourras manger librement.'),
(48, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 17, 'OT', 'Mais de l''arbre de la connaissance du bien et du mal, tu n''en mangeras point ; car au jour où tu en mangeras, tu mourras certainement.'),
(49, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 18, 'OT', 'L''Éternel Dieu dit : Il n''est pas bon que l''homme soit seul ; je lui ferai un secours qui lui corresponde.'),
(50, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 19, 'OT', 'L''Éternel Dieu forma de la terre tout animal des champs et tout oiseau des cieux, et il les amena à l''homme pour voir comment il les appellerait, et tout être vivant porta le nom que l''homme lui donna.'),
(51, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 20, 'OT', 'L''homme donna des noms à tout le bétail, aux oiseaux des cieux, et à tout animal des champs ; mais pour l''homme, il ne trouva point de secours qui lui corresponde.'),
(52, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 21, 'OT', 'L''Éternel Dieu fit tomber un sommeil profond sur l''homme, et il s''endormit ; puis il prit un de ses côtés, et referma la chair à sa place.'),
(53, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 22, 'OT', 'L''Éternel Dieu bâtit en femme le côté qu''il avait pris de l''homme, et il l''amena à l''homme.'),
(54, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 23, 'OT', 'L''homme dit : Cette fois-ci, c''est l''os de mes os et la chair de ma chair ; on l''appellera femme, car c''est de l''homme qu''elle a été prise.'),
(55, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 24, 'OT', 'C''est pourquoi l''homme quittera son père et sa mère, et s''attachera à sa femme, et ils deviendront une seule chair.'),
(56, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 2, 25, 'OT', 'Tous deux étaient nus, l''homme et sa femme, et ils n''en avaient point honte.'),
(57, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 1, 'OT', 'Le serpent était le plus rusé de tous les animaux des champs que l''Éternel Dieu avait faits, et il dit à la femme : « Est-ce que Dieu a vraiment dit : Vous ne mangerez d''aucun bois du jardin ? »'),
(58, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 2, 'OT', 'La femme dit au serpent : Nous mangeons du fruit du bois du jardin.'),
(59, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 3, 'OT', 'Mais du fruit de l''arbre qui est au milieu du jardin, Dieu a dit : Vous n''en mangerez point et vous n''y toucherez point, de peur que vous ne mouriez.'),
(60, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 4, 'OT', 'Le serpent dit à la femme : Vous ne mourrez point.'),
(61, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 5, 'OT', 'Car Dieu sait qu''au jour où vous en mangerez, vos yeux s''ouvriront, et vous serez comme Dieu, connaissant le bien et le mal.'),
(62, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 6, 'OT', 'La femme vit que le bois était bon pour la nourriture, et qu''il était un désir pour les yeux, et que le bois était convoitable pour rendre sage ; elle prit de son fruit et mangea, et elle en donna aussi à son homme qui était avec elle, et il mangea.'),
(63, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 7, 'OT', 'Alors les yeux de tous deux s''ouvrirent, et ils connurent qu''ils étaient nus ; ils cousirent des feuilles de figuier et se firent des ceintures.'),
(64, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 8, 'OT', 'Ils entendirent la voix de l''Éternel Dieu qui marchait dans le jardin à l''esprit du jour, et l''homme et sa femme se cachèrent de la face de l''Éternel Dieu au milieu du bois du jardin.'),
(65, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 9, 'OT', 'L''Éternel Dieu appela l''homme et lui dit : Où es-tu ?'),
(66, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 10, 'OT', 'Il dit : J''ai entendu ta voix dans le jardin, et j''ai eu peur, car je suis nu, et je me suis caché.'),
(67, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 11, 'OT', 'Il dit : Qui t''a appris que tu es nu ? As-tu mangé du bois dont je t''avais commandé de ne pas manger ?'),
(68, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 12, 'OT', 'L''homme dit : « La femme que tu as mise auprès de moi, c''est elle qui m''a donné du bois, et j''en ai mangé. »'),
(69, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 13, 'OT', 'L''Éternel Dieu dit à la femme : Qu''est-ce que tu as fait ? Et la femme dit : Le serpent m''a trompée, et j''ai mangé.'),
(70, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 14, 'OT', 'L''Éternel Dieu dit au serpent : Parce que tu as fait cela, tu es maudit entre tout le bétail et entre toute vie des champs ; sur ton ventre tu marcheras, et tu mangeras de la poussière tous les jours de ta vie.'),
(71, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 15, 'OT', 'Je mettrai une inimitié entre toi et la femme, et entre ta postérité et sa postérité ; elle te meurtrira la tête, et tu lui meurtriras le talon.'),
(72, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 16, 'OT', 'À la femme il dit : Je multiplierai grandement ta souffrance et ta conception ; c''est dans le travail que tu enfanteras des fils, et ton désir sera vers ton homme, et lui dominera sur toi.'),
(73, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 17, 'OT', 'Et à Adam il dit : Parce que tu as écouté la voix de ta femme, et que tu as mangé du bois dont je t''avais commandé, en disant : Tu n''en mangeras pas, maudite est la terre à cause de toi ; avec souffrance tu en mangeras tous les jours de ta vie.'),
(74, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 18, 'OT', 'Elle te produira des épines et des ronces, et tu mangeras l''herbe des champs.'),
(75, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 19, 'OT', 'À la sueur de ta colère tu mangeras ton pain, jusqu''à ce que tu retournes à la terre, car c''est d''elle que tu as été pris ; car tu es poussière, et tu retourneras à la poussière.'),
(76, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 20, 'OT', 'L''homme donna à sa femme le nom d''Ève, car elle fut la mère de tout vivant.'),
(77, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 21, 'OT', 'L''Éternel Dieu fit pour l''homme et pour sa femme des tuniques de peau, et il les en vêtit.'),
(78, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 22, 'OT', 'L''Éternel Dieu dit : Voici, l''homme est devenu comme l''un de nous, pour connaître le bien et le mal ; et maintenant, qu''il n''étende pas sa main et ne prenne aussi du bois de vie, et ne mange et ne vive pour toujours.'),
(79, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 23, 'OT', 'L''Éternel Dieu le renvoya du jardin d''Éden pour cultiver la terre d''où il avait été tiré.'),
(80, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 3, 24, 'OT', 'Il chassa l''homme, et il plaça à l''orient du jardin d''Éden les chérubins et l''épée flamboyante qui se tourne, avec son enchantement, pour garder le chemin du bois de vie.'),
(81, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 1, 'OT', 'L''homme connut Ève, sa femme ; elle conçut et enfanta Caïn, et elle dit : J''ai acquis un homme avec l''Éternel.'),
(82, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 2, 'OT', 'Elle enfanta encore son frère Abel ; et Abel fut berger de brebis, et Caïn fut cultivateur de la terre.'),
(83, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 3, 'OT', 'Il arriva, au bout de quelque temps, que Caïn offrit des fruits de la terre en offrande à l''Éternel.'),
(84, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 4, 'OT', 'Abel aussi apporta des prémices de son troupeau, des droits d''aînesse de ses brebis et de leur graisse ; et l''Éternel porta son regard sur Abel et sur son offrande.'),
(85, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 5, 'OT', 'Mais il ne regarda pas Caïn ni son offrande ; et Caïn fut très irrité, et sa face fut abattue.'),
(86, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 6, 'OT', 'L''Éternel dit à Caïn : Pourquoi ta colère est-elle brûlante, et pourquoi ton visage est-il abattu ?'),
(87, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 7, 'OT', 'N''est-ce pas que, si tu fais bien, tu relèves la tumeur, et si tu ne fais pas bien, le péché est accroupi à l''entrée ; son désir est vers toi, mais toi, tu domineras sur lui.'),
(88, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 8, 'OT', 'Caïn dit à Abel, son frère ; et il arriva, comme ils étaient dans les champs, que Caïn se leva contre Abel, son frère, et le tua.'),
(89, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 9, 'OT', 'L''Éternel dit à Caïn : Où est Abel, ton frère ? Il répondit : Je ne sais pas ; suis-je le gardien de mon frère ?'),
(90, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 10, 'OT', 'Il dit : Qu''as-tu fait ? La voix du sang de ton frère crie vers moi depuis la terre.'),
(91, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 11, 'OT', 'Maintenant, tu es maudit de la terre qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère.'),
(92, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 12, 'OT', 'Quand tu travailleras la terre, elle ne te donnera plus sa force ; tu seras errant et fugitif sur la terre.'),
(93, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 13, 'OT', 'Caïn dit à l''Éternel : Mon iniquité est trop grande pour être portée.'),
(94, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 14, 'OT', 'Voici que tu m''as chassé aujourd''hui de dessus la face de la terre, et je serai caché de devant ta face ; je serai errant et fugitif sur la terre, et il arrivera que tout homme qui me trouvera me tuera.'),
(95, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 15, 'OT', 'L''Éternel lui dit : C''est pourquoi tout meurtrier de Caïn sera vengé sept fois. Et l''Éternel mit un signe à Caïn, afin que tout homme qui le trouverait ne le frappât point.'),
(96, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 16, 'OT', 'Caïn sortit de devant la face de l''Éternel et habita dans la terre de Nod, à l''orient d''Éden.'),
(97, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 17, 'OT', 'Caïn connut sa femme, et elle conçut et enfanta Hénoc ; et il bâtit une ville, et il appela le nom de la ville du nom de son fils, Hénoc.'),
(98, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 18, 'OT', 'Hénoc engendra Irad, et Irad engendra Mehujaël, et Mehujaël engendra Metuschaël, et Metuschaël engendra Lémec.'),
(99, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 19, 'OT', 'Lémec prit pour lui deux femmes : le nom de la première était Ada, et le nom de la seconde, Tsilla.'),
(100, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 20, 'OT', 'Ada enfanta Jabal ; il fut le père de ceux qui habitent sous la tente et possèdent des troupeaux.'),
(101, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 21, 'OT', 'Le nom de son frère était Jubal ; il fut le père de tous ceux qui jouent de la harpe et du chalumeau.'),
(102, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 22, 'OT', 'Tsilla aussi enfanta Tubal-Caïn, forgeron de tout outil d''airain et de fer ; et la sœur de Tubal-Caïn fut Naama.'),
(103, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 23, 'OT', 'Lémec dit à ses femmes : Ada et Tsilla, écoutez ma voix ; femmes de Lémec, prêtez l''oreille à ma parole : car j''ai tué un homme pour ma plaie, et un enfant pour ma meurtrissure.'),
(104, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 24, 'OT', 'Car sept fois Caïn sera vengé, et Lémec soixante-dix-sept fois.'),
(105, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 25, 'OT', 'Adam connut encore sa femme, et elle enfanta un fils, et elle appela son nom Seth, car Dieu m''a donné une autre postérité à la place d''Abel, parce que Caïn l''a tué.'),
(106, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 4, 26, 'OT', 'Et à Seth aussi, à lui, naquit un fils, et il appela son nom Énosch. Alors on commença à invoquer le nom de l''Éternel.'),
(107, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 1, 'OT', 'Voici le livre des générations d''Adam : au jour où Dieu créa l''homme, à la forme de Dieu il le fit.'),
(108, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 2, 'OT', 'Il les créa mâle et femelle, les bénit, et leur donna le nom d''homme, au jour de leur création.'),
(109, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 3, 'OT', 'Adam vécut cent trente ans, et il engendra un fils à sa forme, selon ses images, et il appela son nom Seth.'),
(110, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 4, 'OT', 'Les jours d''Adam après qu''il eut engendré Seth furent de huit cents ans, et il engendra des fils et des filles.'),
(111, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 5, 'OT', 'Tous les jours qu''Adam vécut furent neuf cents ans et trente ans, et il mourut.'),
(112, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 6, 'OT', 'Seth vécut cent cinq ans, et il engendra Énosch.'),
(113, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 7, 'OT', 'Et Seth vécut, après qu''il eut engendré Énosch, sept ans et huit cents ans, et il engendra des fils et des filles.'),
(114, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 8, 'OT', 'Tous les jours de Seth furent neuf cent douze ans, et il mourut.'),
(115, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 9, 'OT', 'Énosch vécut quatre-vingt-dix ans, et il engendra Kénan.'),
(116, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 10, 'OT', 'Énosch vécut après avoir engendré Kénan huit cent quinze ans, et il engendra des fils et des filles.'),
(117, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 11, 'OT', 'Tous les jours d''Énosch furent neuf cent cinq années, et il mourut.'),
(118, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 12, 'OT', 'Kénan vécut soixante-dix ans, et il engendra Mahalaleel.'),
(119, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 13, 'OT', 'Kénan vécut après avoir engendré Mahalaleel huit cent quarante ans, et il engendra des fils et des filles.'),
(120, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 14, 'OT', 'Tous les jours de Kénan furent dix ans et neuf cents ans, et il mourut.'),
(121, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 15, 'OT', 'Mahalaleel vécut soixante-cinq ans, et il engendra Jéred.'),
(122, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 16, 'OT', 'Mahalaleel vécut, après avoir engendré Jéred, huit cent trente ans, et il engendra des fils et des filles.'),
(123, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 17, 'OT', 'Tous les jours de Mahalaleel furent de quatre-vingt-quinze ans et huit cents ans, et il mourut.'),
(124, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 18, 'OT', 'Jéred vécut cent soixante-deux ans, et il engendra Hénoc.'),
(125, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 19, 'OT', 'Jéred vécut, après avoir engendré Hénoc, huit cents ans, et il engendra des fils et des filles.'),
(126, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 20, 'OT', 'Tous les jours de Jéred furent deux et soixante années et neuf cents années, et il mourut.'),
(127, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 21, 'OT', 'Hénoc vécut soixante-cinq ans, et il engendra Metuschélah.'),
(128, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 22, 'OT', 'Hénoc marcha avec Dieu après avoir engendré Metuschélah, trois cents ans, et il engendra des fils et des filles.'),
(129, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 23, 'OT', 'Tous les jours d''Hénoc furent de trois cent soixante-cinq ans.'),
(130, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 24, 'OT', 'Hénoc marcha avec Dieu, et il ne fut plus, car Dieu le prit.'),
(131, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 25, 'OT', 'Metuschélah vécut cent quatre-vingt-sept ans, et il engendra Lémec.'),
(132, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 26, 'OT', 'Et Métuschélah vécut, après avoir engendré Lémec, deux et quatre-vingts ans et sept cents ans, et il engendra des fils et des filles.'),
(133, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 27, 'OT', 'Tous les jours de Metuschélah furent de neuf et soixante ans et de neuf cents ans, et il mourut.'),
(134, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 28, 'OT', 'Lémec vécut cent quatre-vingt-deux ans, et il engendra un fils.'),
(135, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 29, 'OT', 'Il appela son nom Noé, en disant : Celui-ci nous consolera de notre œuvre et de la souffrance de nos mains, à cause de la terre que l''Éternel a maudite.'),
(136, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 30, 'OT', 'Lémec vécut, après avoir engendré Noé, cinq cent quatre-vingt-quinze ans, et il engendra des fils et des filles.'),
(137, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 31, 'OT', 'Tous les jours de Lémec furent sept et soixante-dix ans, et sept cents ans ; puis il mourut.'),
(138, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 5, 32, 'OT', 'Noé était âgé de cinq cents ans, et Noé engendra Sem, Cham et Japhet.'),
(139, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 1, 'OT', 'Et il arriva que lorsque l''homme commença à se multiplier sur la face de la terre, des filles leur naquirent.'),
(140, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 2, 'OT', 'Les fils de Dieu virent que les filles de l''homme étaient belles, et ils prirent pour eux des femmes parmi toutes celles qu''ils avaient choisies.'),
(141, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 3, 'OT', 'L''Éternel dit : Mon esprit ne demeurera pas toujours dans l''homme, car il n''est que chair ; et ses jours seront de cent vingt ans.'),
(142, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 4, 'OT', 'Les géants étaient sur la terre en ces jours-là, et aussi après cela, lorsque les fils de Dieu vinrent vers les filles de l''homme et qu''elles leur enfantèrent ; ce sont eux les héros qui, depuis toujours, furent les hommes de renom.'),
(143, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 5, 'OT', 'L''Éternel vit que le mal de l''homme était grand sur la terre, et que toute pensée des pensées de son cœur n''était que mal en tout temps, chaque jour.'),
(144, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 6, 'OT', 'L''Éternel se repentit d''avoir fait l''homme sur la terre, et il fut affligé en son cœur.'),
(145, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 7, 'OT', 'L''Éternel dit : J''effacerai l''homme que j''ai créé de dessus la face de la terre, depuis l''homme jusqu''au bétail, jusqu''au reptile et jusqu''à l''oiseau des cieux, car je me repens de les avoir faits.'),
(146, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 8, 'OT', 'Noé trouva grâce aux yeux de l''Éternel.'),
(147, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 9, 'OT', 'Voici les générations de Noé : Noé, homme juste, intègre fut dans ses générations ; avec Dieu marcha Noé.'),
(148, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 10, 'OT', 'Noé engendra trois fils : Sem, Cham et Japhet.'),
(149, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 11, 'OT', 'La terre se corrompit devant la face de Dieu, et la terre se remplit de violence.'),
(150, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 12, 'OT', 'Dieu vit la terre, et voici qu''elle était corrompue, car toute chair avait corrompu son chemin sur la terre.'),
(151, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 13, 'OT', 'Dieu dit à Noé : La fin de toute chair est venue devant ma face, car la terre est remplie de violence à cause d''eux ; et voici, je les détruis avec la terre.'),
(152, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 14, 'OT', 'Fais-toi une arche de bois de gopher ; tu feras des nids dans l''arche, et tu la couvriras de rançon, à l''intérieur de la maison et au dehors.'),
(153, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 15, 'OT', 'Voici comment tu la feras : trois cents coudées la longueur de l''arche, cinquante coudées sa largeur, et trente coudées sa hauteur.'),
(154, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 16, 'OT', 'Fais un midi à l''arche, et tu la termineras à une coudée au-dessus ; et tu mettras l''entrée de l''arche sur son côté ; tu la feras avec des étages inférieurs, seconds et troisièmes.'),
(155, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 17, 'OT', 'Et moi, voici que je fais venir le déluge des eaux sur la terre, pour détruire toute chair en laquelle est un esprit de vie sous les cieux ; tout ce qui est sur la terre périra.'),
(156, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 18, 'OT', 'J''établirai mon alliance avec toi, et tu entreras dans l''arche, toi, tes fils, ta femme, et les femmes de tes fils avec toi.'),
(157, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 19, 'OT', 'Et de tout être vivant, de toute chair, tu feras entrer deux de chaque espèce dans l''arche, pour les faire vivre avec toi ; mâle et femelle ils seront.'),
(158, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 20, 'OT', 'De l''oiseau selon son espèce, et du bétail selon son espèce, de tout reptile de la terre selon son espèce, deux de tout viendront vers toi pour les faire vivre.'),
(159, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 21, 'OT', 'Et toi, prends pour toi de toute nourriture qui se mange, et rassemble-la auprès de toi ; et elle sera pour toi et pour eux comme nourriture.'),
(160, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 6, 22, 'OT', 'Noé fit selon tout ce que Dieu lui avait commandé ; ainsi fit-il.'),
(161, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 1, 'OT', 'L''Éternel dit à Noé : Entre, toi et toute ta maison, dans l''arche, car c''est toi que j''ai vu juste devant ma face dans cette génération.'),
(162, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 2, 'OT', 'De tout le bétail pur, tu prendras pour toi sept par sept, un homme et sa femme ; et du bétail qui n''est pas pur, deux, un homme et sa femme.'),
(163, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 3, 'OT', 'Aussi des oiseaux des cieux, sept et sept, mâle et femelle, pour faire vivre une postérité sur la face de toute la terre.'),
(164, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 4, 'OT', 'Car encore sept jours, et je ferai pleuvoir sur la terre quarante jours et quarante nuits, et j''effacerai de dessus la face de la terre tous les êtres que j''ai faits.'),
(165, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 5, 'OT', 'Noé fit tout ce que l''Éternel lui avait commandé.'),
(166, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 6, 'OT', 'Noé était âgé de six cents ans lorsque le déluge d''eaux vint sur la terre.'),
(167, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 7, 'OT', 'Noé entra dans l''arche, lui, ses fils, sa femme et les femmes de ses fils avec lui, à cause des eaux du déluge, devant la face des eaux du déluge.'),
(168, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 8, 'OT', 'Du bétail pur, et du bétail qui n''est pas pur, et de l''oiseau, et de tout ce qui rampe sur la terre.'),
(169, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 9, 'OT', 'Deux par deux ils vinrent vers Noé, dans l''arche, mâle et femelle, comme Dieu l''avait commandé à Noé.'),
(170, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 10, 'OT', 'Et il arriva qu''au bout de sept jours, les eaux du déluge furent sur la terre.'),
(171, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 11, 'OT', 'L''an six cent de la vie de Noé, au second mois, le dix-septième jour du mois, en ce jour-là, toutes les sources du grand abîme se rompirent, et les fenêtres des cieux s''ouvrirent.'),
(172, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 12, 'OT', 'La pluie fut sur la terre quarante jours et quarante nuits.'),
(173, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 13, 'OT', 'En ce même jour, Noé entra, ainsi que Sem, Cham et Japhet, les fils de Noé, et la femme de Noé, et les trois femmes de ses fils avec eux, dans l''arche.'),
(174, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 14, 'OT', 'Eux et tout animal vivant selon son espèce, et tout le bétail selon son espèce, et tout reptile qui rampe sur la terre selon son espèce, et tout oiseau selon son espèce, tout oiseau, toute aile.'),
(175, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 15, 'OT', 'Ils vinrent vers Noé, dans l''arche, deux à deux, de toute chair en laquelle était un esprit de vie.'),
(176, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 16, 'OT', 'Et ceux qui entraient, mâle et femelle de toute chair, entrèrent comme Dieu le lui avait commandé ; et l''Éternel ferma derrière lui.'),
(177, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 17, 'OT', 'Le déluge fut quarante jours sur la terre, et les eaux crûrent et soulevèrent l''arche, et elle s''éleva au-dessus de la terre.'),
(178, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 18, 'OT', 'Les eaux prévalurent et augmentèrent beaucoup sur la terre, et l''arche allait sur la face des eaux.'),
(179, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 19, 'OT', 'Les eaux prévalurent extrêmement sur la terre, et toutes les hautes montagnes qui sont sous tous les cieux furent couvertes.'),
(180, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 20, 'OT', 'Les eaux s''élevèrent de quinze coudées au-dessus, et les montagnes furent couvertes.'),
(181, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 21, 'OT', 'Toute chair qui se mouvait sur la terre périt, les oiseaux, le bétail, les animaux vivants, et tout reptile qui rampe sur la terre, ainsi que tout homme.'),
(182, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 22, 'OT', 'Tout ce qui avait un souffle d''esprit de vie dans ses narines, de tout ce qui était sur la terre sèche, mourut.'),
(183, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 23, 'OT', 'Il effaça tous les êtres qui étaient sur la face de la terre, depuis l''homme jusqu''au bétail, jusqu''au reptile et jusqu''à l''oiseau des cieux, et ils furent effacés de la terre ; et il ne resta que Noé et ceux qui étaient avec lui dans l''arche.'),
(184, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 7, 24, 'OT', 'Les eaux prévalurent sur la terre cent cinquante jours.'),
(185, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 1, 'OT', 'Dieu se souvint de Noé, de tout ce qui vit et de tout le bétail qui était avec lui dans l''arche ; et Dieu fit passer un vent sur la terre, et les eaux s''apaisèrent.'),
(186, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 2, 'OT', 'Les sources de l''abîme et les fenêtres des cieux furent fermées, et la pluie fut retenue des cieux.'),
(187, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 3, 'OT', 'Les eaux se retirèrent de dessus la terre, allant et revenant, et les eaux diminuèrent à l''extrémité de cent cinquante jours.'),
(188, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 4, 'OT', 'L''arche se reposa au septième mois, le dix-septième jour du mois, sur les montagnes d''Ararat.'),
(189, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 5, 'OT', 'Les eaux allaient en diminuant jusqu''au dixième mois ; au dixième, le premier jour du mois, les sommets des montagnes apparurent.'),
(190, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 6, 'OT', 'Il arriva qu''au bout de quarante jours, Noé ouvrit la fenêtre de l''arche qu''il avait faite.'),
(191, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 7, 'OT', 'Il envoya le corbeau, qui sortit, allant et revenant, jusqu''à ce que les eaux eussent séché de dessus la terre.'),
(192, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 8, 'OT', 'Il envoya la colombe d''auprès de lui, pour voir si les eaux avaient diminué à la face de la terre.'),
(193, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 9, 'OT', 'La colombe ne trouva pas de repos pour la plante de son pied, et elle revint vers lui, vers l''arche, car les eaux couvraient la face de toute la terre ; il étendit sa main, la prit, et la fit entrer auprès de lui dans l''arche.'),
(194, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 10, 'OT', 'Il attendit encore sept autres jours, et il renvoya la colombe hors de l''arche.'),
(195, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 11, 'OT', 'La colombe revint vers lui au temps du soir, et voici, une feuille d''olivier arrachée était dans sa bouche ; et Noé sut que les eaux avaient diminué de dessus la terre.'),
(196, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 12, 'OT', 'Il attendit encore sept autres jours, puis il lâcha la colombe, et elle ne revint plus vers lui.'),
(197, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 13, 'OT', 'Il advint, en l''an six cent un, au premier mois, le premier jour du mois, que les eaux se retirèrent de dessus la terre ; et Noé ôta la couverture de l''arche, et il regarda, et voici, la face de la terre était sèche.'),
(198, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 14, 'OT', 'Au deuxième mois, le vingt-septième jour du mois, la terre fut sèche.'),
(199, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 15, 'OT', 'Dieu parla à Noé, en disant :'),
(200, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 16, 'OT', 'Sors de l''arche, toi et ta femme, et tes fils et les femmes de tes fils avec toi.'),
(201, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 17, 'OT', 'Tout être vivant qui est avec toi, de toute chair, parmi les oiseaux, parmi le bétail et parmi tout reptile qui rampe sur la terre, fais-les sortir avec toi ; qu''ils foisonnent sur la terre, qu''ils soient féconds et qu''ils se multiplient sur la terre.'),
(202, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 18, 'OT', 'Noé sortit, et ses fils, et sa femme, et les femmes de ses fils avec lui.'),
(203, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 19, 'OT', 'Tout être vivant, tout reptile et tout oiseau, tout ce qui se meut sur la terre, selon leurs familles, sortirent de l''arche.'),
(204, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 20, 'OT', 'Noé bâtit un autel à l''Éternel, et il prit de tout le bétail pur et de tout l''oiseau pur, et il offrit des holocaustes sur l''autel.'),
(205, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 21, 'OT', 'L''Éternel sentit l''odeur de l''agréable odeur, et l''Éternel dit en son cœur : Je ne maudirai plus la terre à cause de l''homme, car la pensée du cœur de l''homme est mauvaise dès sa jeunesse ; et je ne frapperai plus tout être vivant comme je l''ai fait.'),
(206, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 8, 22, 'OT', 'Tant que dureront tous les jours de la terre, la postérité et la moisson, le froid et la chaleur, l''été et l''hiver, le jour et la nuit ne cesseront point.'),
(207, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 1, 'OT', 'Dieu bénit Noé et ses fils, et leur dit : Soyez féconds, multipliez-vous, et remplissez la terre.'),
(208, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 2, 'OT', 'Votre terreur et votre effroi seront sur tout animal de la terre, et sur tout oiseau des cieux, sur tout ce qui rampe sur le sol, et sur tous les poissons de la mer ; ils sont livrés entre vos mains.'),
(209, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 3, 'OT', 'Tout reptile qui est vivant sera pour vous une nourriture ; comme l''herbe verte, je vous ai donné tout cela.'),
(210, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 4, 'OT', 'Seulement, la chair avec son âme, son sang, vous ne la mangerez point.'),
(211, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 5, 'OT', 'Et certes, je redemanderai votre sang, pour vos âmes ; de la main de tout être vivant je le redemanderai, et de la main de l''homme, de la main de chacun son frère, je redemanderai l''âme de l''homme.'),
(212, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 6, 'OT', 'Celui qui répand le sang de l''homme, par l''homme son sang sera répandu, car c''est à l''image de Dieu qu''il a fait l''homme.'),
(213, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 7, 'OT', 'Et vous, soyez féconds et multipliez-vous ; pullulez sur la terre et multipliez-vous en elle.'),
(214, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 8, 'OT', 'Dieu dit à Noé et à ses fils avec lui :'),
(215, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 9, 'OT', 'Et moi, voici que j''établis mon alliance avec vous, et avec votre postérité après vous.'),
(216, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 10, 'OT', 'Et avec toute âme vivante qui est avec vous, parmi les oiseaux, parmi le bétail, et parmi tout animal de la terre qui est avec vous, de tout ce qui sortit de l''arche, à tout animal de la terre.'),
(217, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 11, 'OT', 'J''établirai mon alliance avec vous, et toute chair ne sera plus retranchée par les eaux du déluge, et il n''y aura plus de déluge pour détruire la terre.'),
(218, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 12, 'OT', 'Et Dieu dit : Voici le signe de l''alliance que je donne entre moi et vous, et entre toute âme vivante qui est avec vous, pour les générations de toujours.'),
(219, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 13, 'OT', 'J''ai mis mon arc dans la nuée, et il sera pour signe d''alliance entre moi et la terre.'),
(220, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 14, 'OT', 'Et il arrivera que, quand je ferai venir une nuée sur la terre, l''arc sera vu dans la nuée.'),
(221, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 15, 'OT', 'Et je me souviendrai de mon alliance entre moi et vous, et entre toute âme vivante dans toute chair ; et les eaux ne seront plus un déluge pour détruire toute chair.'),
(222, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 16, 'OT', 'L''arc sera dans la nuée, et je le verrai pour me souvenir de l''alliance de toujours entre Dieu et toute âme vivante, en toute chair qui est sur la terre.'),
(223, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 17, 'OT', 'Dieu dit à Noé : Voici le signe de l''alliance que j''ai établie entre moi et toute chair qui est sur la terre.'),
(224, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 18, 'OT', 'Les fils de Noé qui sortirent de l''arche étaient Sem, Cham et Japhet ; et Cham était le père de Canaan.'),
(225, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 19, 'OT', 'Ces trois-là sont les fils de Noé, et c''est d''eux que toute la terre fut dispersée.'),
(226, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 20, 'OT', 'Noé, homme de la terre, commença, et il planta une vigne.'),
(227, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 21, 'OT', 'Il but du vin et s''enivra, et il se découvrit au milieu de sa tente.'),
(228, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 22, 'OT', 'Cham, père de Canaan, vit la nudité de son père, et il le rapporta à ses deux frères, dehors.'),
(229, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 23, 'OT', 'Sem et Japhet prirent le vêtement, le mirent sur l''épaule de tous deux, marchèrent en arrière et couvrirent la nudité de leur père ; leurs faces étaient tournées en arrière, et ils ne virent pas la nudité de leur père.'),
(230, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 24, 'OT', 'Noé se réveilla de son vin, et il sut ce que lui avait fait son fils le plus jeune.'),
(231, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 25, 'OT', 'Il dit : Maudit soit Canaan ! Qu''il soit serviteur des serviteurs pour ses frères.'),
(232, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 26, 'OT', 'Il dit : Béni soit l''Éternel, Dieu de Sem, et que Canaan soit leur serviteur.'),
(233, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 27, 'OT', 'Que Dieu élargisse Japhet, et qu''il habite dans les tentes de Sem, et que Canaan soit son serviteur.'),
(234, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 28, 'OT', 'Noé vécut après le déluge trois cents ans et cinquante ans.'),
(235, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 9, 29, 'OT', 'Tous les jours de Noé furent de neuf cents ans et cinquante ans, et il mourut.'),
(236, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 1, 'OT', 'Voici les générations des fils de Noé : Sem, Cham et Japhet ; et il leur naquit des fils après le déluge.'),
(237, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 2, 'OT', 'Les fils de Japhet : Gomer, Magog, les Mèdes, Javan, Tubal, Méschec et Tiras.'),
(238, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 3, 'OT', 'Les fils de Gomer : Aschkenaz, Riphat et Togarma.'),
(239, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 4, 'OT', 'Les fils de Javan : Élischa et Tarsis, Kittim et Dodanim.'),
(240, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 5, 'OT', 'De ceux-ci furent séparées les îles des nations dans leurs terres, chacun selon sa langue, selon leurs familles, dans leurs nations.'),
(241, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 6, 'OT', 'Les fils de Cham : Cusch, l''Égypte, Puth et Canaan.'),
(242, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 7, 'OT', 'Les fils de Cusch : Séba, Havila, Sabta, Raema et Sabteca ; et les fils de Raema : Séba et Dedan.'),
(243, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 8, 'OT', 'Cusch engendra Nimrod ; il commença à être un homme puissant sur la terre.'),
(244, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 9, 'OT', 'Il fut un vaillant chasseur de gibier devant la face de l''Éternel ; c''est pourquoi l''on dit : Comme Nimrod, vaillant chasseur de gibier devant la face de l''Éternel.'),
(245, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 10, 'OT', 'Le commencement de son royaume fut Babylone, Érec, Accad et Calné, dans la terre de Schinear.'),
(246, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 11, 'OT', 'De cette terre-là sortit l''Assyrie, et il bâtit Ninive, et Rehoboth la ville, et Calach.'),
(247, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 12, 'OT', 'Et Résen, entre Ninive et Calach, c''est la grande ville.'),
(248, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 13, 'OT', 'L''Égypte engendra Ludim, Anamim, Lehabim et Naphtuhim.'),
(249, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 14, 'OT', 'et les Pathrusim, et les Casluhim, d''où sont sortis les Philistins, et les Caphtorim.'),
(250, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 15, 'OT', 'Canaan engendra Sidon, son premier-né, et Heth.'),
(251, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 16, 'OT', 'et le Jébusien, et l''Amoréen, et le Guirgasien.'),
(252, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 17, 'OT', 'et le Hévien, et l''Arkien, et le Sinien.'),
(253, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 18, 'OT', 'et l''Arvadien, et le Tsemarien, et le Hamathien ; et ensuite les familles du Cananéen se dispersèrent.'),
(254, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 19, 'OT', 'La frontière des Cananéens allait de Sidon, vers Guérar, jusqu''à Gaza, et vers Sodome, Gomorrhe, Adma et Tseboïm, jusqu''à Léscha.'),
(255, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 20, 'OT', 'Voici les fils de Cham, selon leurs familles, selon leurs langues, dans leurs terres, parmi leurs nations.'),
(256, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 21, 'OT', 'À Sem aussi, il naquit des enfants, lui qui est le père de tous les fils d''Héber, le frère de Japhet l''aîné.'),
(257, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 22, 'OT', 'Les fils de Sem : Élam, Assyrie, Arpacschad, Lud et Syrie.'),
(258, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 23, 'OT', 'Les fils de Syrie : Uts, Hul, Guéter et Masch.'),
(259, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 24, 'OT', 'Arpacschad engendra Schélach, et Schélach engendra Héber.'),
(260, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 25, 'OT', 'À Héber naquirent deux fils : le nom de l''un était Péleg, car en ses jours la terre fut divisée, et le nom de son frère était Jokthan.'),
(261, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 26, 'OT', 'Jokthan engendra Almodad, Schéleph, Hatsarmaveth et Jérach.'),
(262, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 27, 'OT', 'et Hadoram, et Uzal, et Dikla.'),
(263, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 28, 'OT', 'et Obal, et Abimaël, et Séba.'),
(264, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 29, 'OT', 'Et Ophir, et Havila, et Jobab : tous ceux-là furent fils de Jokthan.'),
(265, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 30, 'OT', 'Leur habitation s''étendait depuis Méscha, jusqu''à Sephar, la montagne de l''orient.'),
(266, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 31, 'OT', 'Voici les fils de Sem, selon leurs familles, selon leurs langues, dans leurs terres, selon leurs nations.'),
(267, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 10, 32, 'OT', 'Voici les familles des fils de Noé, selon leurs générations, dans leurs nations ; et c''est d''eux que les nations se sont séparées sur la terre après le déluge.'),
(268, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 1, 'OT', 'Toute la terre avait une seule lèvre et des paroles uniques.'),
(269, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 2, 'OT', 'Il arriva, lorsqu''ils partirent de l''orient, qu''ils trouvèrent une plaine dans la terre de Schinear, et ils s''y établirent.'),
(270, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 3, 'OT', 'Ils se dirent l''un à l''autre : Allons, faisons des briques, et brûlons-les par la brûlure ; et la brique leur servit de pierre, et le bitume leur servit d''argile.'),
(271, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 4, 'OT', 'Ils dirent : Allons, bâtissons-nous une ville et une tour dont la tête soit dans les cieux, et faisons-nous un nom, de peur que nous soyons dispersés sur la face de toute la terre.'),
(272, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 5, 'OT', 'L''Éternel descendit pour voir la ville et la tour que les fils de l''homme avaient bâties.'),
(273, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 6, 'OT', 'L''Éternel dit : Voici, un seul peuple et une seule lèvre pour tous, et voici ce qu''ils commencent à faire ; et maintenant rien ne leur sera impossible de tout ce qu''ils ont projeté de faire.'),
(274, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 7, 'OT', 'Allons, descendons, et confondons là leur lèvre, afin que nul homme n''entende la lèvre de son ami.'),
(275, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 8, 'OT', 'L''Éternel les dispersa de là sur la face de toute la terre, et ils cessèrent de bâtir la ville.'),
(276, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 9, 'OT', 'C''est pourquoi on l''appela du nom de Babylone, car c''est là que l''Éternel confondit la lèvre de toute la terre, et de là l''Éternel les dispersa sur la face de toute la terre.'),
(277, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 10, 'OT', 'Voici les générations de Sem : Sem, âgé de cent ans, engendra Arpacschad, deux ans après le déluge.'),
(278, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 11, 'OT', 'Sem vécut, après qu''il eut engendré Arpacschad, cinq cents années, et il engendra des fils et des filles.'),
(279, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 12, 'OT', 'Arpacschad vécut trente-cinq ans, et il engendra Schélach.'),
(280, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 13, 'OT', 'Arpacschad vécut, après avoir engendré Schélach, trois cent quatre années, et il engendra des fils et des filles.'),
(281, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 14, 'OT', 'Schélach vécut trente ans, et il engendra Héber.'),
(282, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 15, 'OT', 'Schélach vécut, après avoir engendré Héber, trois ans et quatre cents ans, et il engendra des fils et des filles.'),
(283, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 16, 'OT', 'Héber vécut trente-quatre ans, et il engendra Péleg.'),
(284, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 17, 'OT', 'Héber vécut, après avoir engendré Péleg, quatre cent trente ans, et il engendra des fils et des filles.'),
(285, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 18, 'OT', 'Péleg vécut trente ans, et il engendra Rehu.'),
(286, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 19, 'OT', 'Péleg vécut, après avoir engendré Rehu, deux cent neuf ans, et il engendra des fils et des filles.'),
(287, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 20, 'OT', 'Rehu vécut trente-deux ans, et il engendra Serug.'),
(288, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 21, 'OT', 'Rehu vécut après avoir engendré Serug deux cent sept ans, et il engendra des fils et des filles.'),
(289, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 22, 'OT', 'Serug vécut trente ans, et il engendra Nachor.'),
(290, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 23, 'OT', 'Serug vécut deux cents ans après avoir engendré Nachor, et il engendra des fils et des filles.'),
(291, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 24, 'OT', 'Nachor vécut vingt-neuf ans, et il engendra Térach.'),
(292, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 25, 'OT', 'Nachor vécut, après avoir engendré Térach, cent dix-neuf ans, et il engendra des fils et des filles.'),
(293, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 26, 'OT', 'Térach vécut soixante-dix ans, et il engendra Abram, Nachor et Haran.'),
(294, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 27, 'OT', 'Voici les générations de Térach : Térach engendra Abram, Nachor et Haran ; et Haran engendra Lot.'),
(295, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 28, 'OT', 'Haran mourut en présence de Térach, son père, dans la terre de sa naissance, à Ur des Chaldéens.'),
(296, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 29, 'OT', 'Abram et Nachor prirent pour eux des femmes ; le nom de la femme d''Abram était Saraï, et le nom de la femme de Nachor était Milca, fille de Haran, père de Milca et père de Jisca.'),
(297, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 30, 'OT', 'Saraï était stérile ; elle n''avait point d''enfant.'),
(298, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 31, 'OT', 'Térach prit Abram son fils, et Lot fils de Haran, fils de son fils, et Saraï sa fiancée, femme d''Abram son fils ; ils sortirent avec eux d''Ur des Chaldéens pour aller vers la terre de Canaan, et ils arrivèrent jusqu''à Haran, et ils s''y installèrent.'),
(299, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 11, 32, 'OT', 'Les jours de Térach furent de deux cent cinq années, et Térach mourut à Haran.'),
(300, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 1, 'OT', 'L''Éternel dit à Abram : Va-t''en de ta terre, de ta naissance et de la maison de ton père, vers la terre que je te montrerai.'),
(301, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 2, 'OT', 'Je ferai de toi une grande nation, je te bénirai, et je rendrai ton nom grand, et tu seras une bénédiction.'),
(302, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 3, 'OT', 'Je bénirai ceux qui te bénissent, et celui qui te maudit, je le maudirai ; et en toi seront bénies toutes les familles de la terre.'),
(303, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 4, 'OT', 'Abram partit comme l''Éternel le lui avait dit, et Lot partit avec lui ; Abram était fils de soixante-quinze années lorsqu''il sortit de Haran.'),
(304, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 5, 'OT', 'Abram prit Saraï sa femme, et Lot fils de son frère, et tous leurs biens qu''ils avaient acquis, et les âmes qu''ils avaient faites à Haran ; puis ils sortirent pour aller vers la terre de Canaan, et ils arrivèrent à la terre de Canaan.'),
(305, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 6, 'OT', 'Abram traversa la terre jusqu''au lieu de Sichem, jusqu''au chêne de Moré ; et le Cananéen était alors dans la terre.'),
(306, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 7, 'OT', 'L''Éternel apparut à Abram et dit : « À ta postérité je donnerai cette terre. » Et il bâtit là un autel à l''Éternel, qui lui était apparu.'),
(307, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 8, 'OT', 'Il se déplaça de là vers la montagne, à l''orient de Béthel, et dressa sa tente, ayant Béthel à la mer et Aï à l''orient ; et il bâtit là un autel à l''Éternel, et invoqua le nom de l''Éternel.'),
(308, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 9, 'OT', 'Abram partit, poursuivant sa marche vers le midi.'),
(309, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 10, 'OT', 'Il y eut une famine dans la terre, et Abram descendit en Égypte pour y séjourner, car la famine était lourde dans la terre.'),
(310, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 11, 'OT', 'Il arriva, comme il approchait d''entrer en Égypte, qu''il dit à Saraï, sa femme : Voici, je sais maintenant que tu es une femme belle d''apparence.'),
(311, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 12, 'OT', 'Il arrivera que lorsque les Égyptiens te verront, ils diront : « C''est sa femme », et ils me tueront, mais ils te laisseront vivre.'),
(312, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 13, 'OT', 'Dis donc, je te prie, que tu es ma sœur, afin qu''il me soit bien à cause de toi, et que mon âme vive à cause de toi.'),
(313, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 14, 'OT', 'Il arriva qu''à l''entrée d''Abram en Égypte, les Égyptiens virent la femme, car elle était très belle.'),
(314, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 15, 'OT', 'Les chefs de Pharaon la virent et la louèrent auprès de Pharaon, et la femme fut prise dans la maison de Pharaon.'),
(315, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 16, 'OT', 'Il fit du bien à Abram à cause d''elle, et il eut des brebis, des bœufs, des ânes, des serviteurs, des servantes, des ânesses et des chameaux.'),
(316, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 17, 'OT', 'L''Éternel frappa Pharaon de grandes plaies, ainsi que sa maison, à cause de la parole de Saraï, femme d''Abram.'),
(317, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 18, 'OT', 'Pharaon appela Abram et dit : Qu''est-ce que tu m''as fait ? Pourquoi ne m''as-tu pas déclaré qu''elle est ta femme ?'),
(318, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 19, 'OT', 'Pourquoi as-tu dit : « Elle est ma sœur », et je l''ai prise pour femme ? Et maintenant, voici ta femme ; prends-la et va-t''en.'),
(319, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 12, 20, 'OT', 'Pharaon donna des ordres à des hommes à son sujet, et ils le renvoyèrent, lui et sa femme, et tout ce qui lui appartenait.'),
(320, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 1, 'OT', 'Abram monta d''Égypte, lui et sa femme, et tout ce qui lui appartenait, et Lot avec lui, vers le midi.'),
(321, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 2, 'OT', 'Abram était très riche en troupeaux, en argent et en or.'),
(322, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 3, 'OT', 'Et il poursuivit ses marches depuis le midi jusqu''à Béthel, jusqu''au lieu où sa tente avait été au commencement, entre Béthel et Aï.'),
(323, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 4, 'OT', 'Vers le lieu de l''autel qu''il avait fait là auparavant, et là Abram invoqua le nom de l''Éternel.'),
(324, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 5, 'OT', 'Lot aussi, qui accompagnait Abram, avait des brebis, des bœufs et des tentes.'),
(325, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 6, 'OT', 'La terre ne pouvait pas les porter pour habiter ensemble, car leurs biens étaient nombreux, et ils ne pouvaient pas habiter ensemble.'),
(326, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 7, 'OT', 'Il y eut un procès entre les bergers des troupeaux d''Abram et les bergers des troupeaux de Lot ; et le Cananéen et le Phérézien habitaient alors dans la terre.'),
(327, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 8, 'OT', 'Abram dit à Lot : « Qu''il n''y ait point, je te prie, de querelle entre moi et toi, ni entre mes bergers et tes bergers, car nous sommes des hommes frères. »'),
(328, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 9, 'OT', 'Toute la terre n''est-elle pas devant toi ? Sépare-toi donc de moi : si tu prends la gauche, j''irai à la droite ; et si tu prends la droite, j''irai à la gauche.'),
(329, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 10, 'OT', 'Lot leva les yeux et vit tout le talent du Jourdain, car tout cela était un échanson, devant la face de l''Éternel détruisant Sodome et Gomorrhe, comme le jardin de l''Éternel, comme la terre d''Égypte, en venant vers Tsoar.'),
(330, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 11, 'OT', 'Lot choisit pour lui toute la plaine du Jourdain, et Lot partit vers l''orient, et ils se séparèrent, l''un d''avec l''autre.'),
(331, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 12, 'OT', 'Abram habita dans la terre de Canaan, et Lot habita dans les villes du talent, et il dressa sa tente jusqu''à Sodome.'),
(332, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 13, 'OT', 'Les hommes de Sodome étaient méchants et pécheurs contre l''Éternel, à un très haut degré.'),
(333, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 14, 'OT', 'L''Éternel dit à Abram, après que Lot se fut séparé de lui : Lève maintenant tes yeux et regarde, depuis le lieu où tu es, vers le nord, et vers le midi, et vers l''orient, et vers la mer.'),
(334, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 15, 'OT', 'Car toute la terre que tu vois, je te la donnerai, à toi et à ta postérité, pour toujours.'),
(335, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 16, 'OT', 'Je rendrai ta postérité comme la poussière de la terre, en sorte que si un homme peut compter la poussière de la terre, ta postérité aussi sera comptée.'),
(336, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 17, 'OT', 'Lève-toi, parcours la terre dans sa longueur et dans sa largeur, car je te la donnerai.'),
(337, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 13, 18, 'OT', 'Abram dressa sa tente, vint et s''établit près des chênes de Mamré, qui sont à Hébron, et il bâtit là un autel à l''Éternel.'),
(338, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 1, 'OT', 'Il advint, aux jours d''Amraphel, roi de Schinear, d''Arjoc, roi d''Ellasar, de Kedorlaomer, roi d''Élam, et de Tideal, roi des nations.'),
(339, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 2, 'OT', 'Ils firent la guerre contre Béra, roi de Sodome, et contre Birscha, roi de Gomorrhe, Schineab, roi d''Adma, et Schémeéber, roi de Tseboïm, et le roi de Béla, qui est Tsoar.'),
(340, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 3, 'OT', 'Tous ceux-ci se joignirent vers la vallée de Siddim, qui est la mer de sel.'),
(341, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 4, 'OT', 'Douze ans ils servirent Kedorlaomer, et treize ans ils se révoltèrent.'),
(342, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 5, 'OT', 'La quatorzième année, Kedorlaomer vint, ainsi que les rois qui étaient avec lui, et ils frappèrent les Rephaïm à Aschteroth-Karnaïm, les Zuzim à Ham, et les Émim à Schavé-Kirjathaïm.'),
(343, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 6, 'OT', 'et les Horiens dans leur montagne de Séir, jusqu''au chêne de Paran, qui est près du désert.'),
(344, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 7, 'OT', 'Puis ils firent demi-tour et vinrent à En-Mischpath, qui est Kadès, et ils frappèrent tout le champ des Amalécites, et aussi l''Amoréen qui habitait à Hatsatson-Thamar.'),
(345, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 8, 'OT', 'Le roi de Sodome et le roi de Gomorrhe et le roi d''Adma et le roi de Tseboïm et le roi de Béla, qui est Tsoar, sortirent et rangèrent contre eux une guerre dans la vallée de Siddim.'),
(346, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 9, 'OT', 'contre Kedorlaomer, roi d''Élam, et Tideal, roi des nations, et Amraphel, roi de Schinear, et Arjoc, roi d''Ellasar : quatre rois contre les cinq.'),
(347, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 10, 'OT', 'La vallée de Siddim était pleine de puits de bitume, et le roi de Sodome et de Gomorrhe s''enfuirent et y tombèrent, et ceux qui restèrent s''enfuirent vers la montagne.'),
(348, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 11, 'OT', 'Ils prirent tous les biens de Sodome et de Gomorrhe, et toute leur nourriture, puis ils s''en allèrent.'),
(349, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 12, 'OT', 'Ils prirent Lot et ses biens, le fils du frère d''Abram, et ils s''en allèrent ; et lui habitait à Sodome.'),
(350, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 13, 'OT', 'Le fuyard vint et le rapporta à Abram l''Hébreu, qui demeurait aux chênes de Mamré l''Amoréen, frère d''Eschcol et frère d''Aner, et ils étaient maîtres d''alliance avec Abram.'),
(351, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 14, 'OT', 'Abram apprit que son frère avait été fait prisonnier, et il arma ses serviteurs entraînés, enfants de sa maison, au nombre de trois cent dix-huit, et il les poursuivit jusqu''à Dan.'),
(352, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 15, 'OT', 'Il se répartit contre eux de nuit, lui et ses serviteurs, et les frappa, et les poursuivit jusqu''à Choba, qui est à la gauche de Damas.'),
(353, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 16, 'OT', 'Il ramena tous les biens, et aussi son frère Lot et ses biens, il les ramena, et aussi les femmes et le peuple.'),
(354, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 17, 'OT', 'Le roi de Sodome sortit à sa rencontre, après qu''il fut revenu de frapper Kedorlaomer et les rois qui étaient avec lui, vers la vallée de Schavé, qui est la vallée du roi.'),
(355, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 18, 'OT', 'Melchisédek, roi de Salem, fit sortir du pain et du vin, et il était sacrificateur du Dieu Très-Haut.'),
(356, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 19, 'OT', 'Il le bénit et dit : Béni soit Abram par le Dieu Très-Haut, qui possède les cieux et la terre.'),
(357, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 20, 'OT', 'Béni soit Dieu le Très-Haut, qui a livré tes ennemis entre ta main, et il lui donna la dîme de tout.'),
(358, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 21, 'OT', 'Le roi de Sodome dit à Abram : Donne-moi les âmes, et prends pour toi les biens.'),
(359, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 22, 'OT', 'Abram dit au roi de Sodome : « J''ai levé ma main vers l''Éternel, Dieu Très-Haut, qui a fait les cieux et la terre. »'),
(360, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 23, 'OT', 'Si je prenais un fil jusqu''à une courroie de chaussure, et si je prenais quoi que ce soit de tout ce qui est à toi, tu ne pourrais pas dire : « Moi, j''ai enrichi Abram. »'),
(361, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 14, 24, 'OT', 'Hormis ce qu''ont mangé les jeunes gens, et la part des hommes qui sont allés avec moi—Aner, Eschcol et Mamré—eux, ils prendront leur part.'),
(362, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 1, 'OT', 'Après ces paroles, la parole de l''Éternel fut adressée à Abram dans une vision, disant : Ne crains point, Abram, je suis ton bouclier ; ton salaire est très grand.'),
(363, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 2, 'OT', 'Abram dit : Seigneur, l''Éternel, que me donneras-tu ? Je m''en vais sans enfant, et le fils de ma maison, c''est Éliézer de Damas, l''intendant.'),
(364, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 3, 'OT', 'Abram dit : « Voici, tu ne m''as pas donné de postérité, et voici qu''un fils de ma maison sera mon héritier. »'),
(365, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 4, 'OT', 'Et voici que la parole de l''Éternel lui fut adressée, disant : Celui-ci ne sera pas ton héritier ; mais celui qui sortira de tes entrailles, lui sera ton héritier.'),
(366, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 5, 'OT', 'Il le fit sortir dehors et dit : « Regarde donc vers les cieux, et compte les étoiles, si tu peux les compter. » Et il lui dit : « Ainsi sera ta postérité. »'),
(367, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 6, 'OT', 'Il crut en l''Éternel, et il le lui compta comme justice.'),
(368, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 7, 'OT', 'Il lui dit : « Je suis l''Éternel, qui t''ai fait sortir d''Ur des Chaldéens, pour te donner cette terre afin que tu la possèdes. »'),
(369, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 8, 'OT', 'Il dit : Seigneur, l''Éternel, à quoi connaîtrai-je que je la posséderai ?'),
(370, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 9, 'OT', 'Il lui dit : Prends pour moi une génisse de trois ans, une chèvre de trois ans, un bélier de trois ans, une tourterelle et un oisillon.'),
(371, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 10, 'OT', 'Il prit pour lui tous ces animaux, les coupa par le milieu, et plaça chaque moitié en face de l''autre ; mais il ne coupa pas l''oiseau.'),
(372, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 11, 'OT', 'Les oiseaux de proie descendirent sur les cadavres, et Abram les chassa.'),
(373, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 12, 'OT', 'Le soleil était sur le point de se coucher, et un sommeil profond tomba sur Abram, et voici qu''une terreur, de grandes ténèbres, tombait sur lui.'),
(374, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 13, 'OT', 'Il dit à Abram : Sache certainement que ta postérité sera étrangère dans une terre qui n''est pas la leur, et ils les serviront et les affligeront pendant quatre cents années.'),
(375, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 14, 'OT', 'Je jugerai aussi la nation qu''ils serviront, et après cela ils sortiront avec de grands biens.'),
(376, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 15, 'OT', 'Et toi, tu iras vers tes pères en paix, tu seras enseveli dans une bonne vieillesse.'),
(377, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 16, 'OT', 'Et la quatrième génération reviendra ici, car l''iniquité de l''Amoréen n''est pas encore complète jusqu''ici.'),
(378, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 17, 'OT', 'Le soleil était couché, et les ténèbres étaient venues ; et voici, un four de fumée et un flambeau de feu passèrent entre ces parties.'),
(379, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 18, 'OT', 'En ce jour-là, l''Éternel fit alliance avec Abram, en disant : À ta postérité j''ai donné cette terre, depuis le fleuve d''Égypte jusqu''au grand fleuve, le fleuve de l''Euphrate.'),
(380, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 19, 'OT', 'le Kénien, le Kenizien et les Kadmoniens.'),
(381, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 20, 'OT', 'et le Héthien, et le Phérézien, et les Rephaïm.'),
(382, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 15, 21, 'OT', 'et l''Amoréen, et le Cananéen, et le Guirgasien, et le Jébusien.'),
(383, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 1, 'OT', 'Saraï, femme d''Abram, ne lui avait pas enfanté ; et elle avait une servante égyptienne dont le nom était Agar.'),
(384, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 2, 'OT', 'Saraï dit à Abram : « Voici, l''Éternel m''a empêchée d''enfanter ; va donc vers ma servante, peut-être serai-je édifiée par elle. » Et Abram écouta la voix de Saraï.'),
(385, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 3, 'OT', 'Saraï, femme d''Abram, prit Agar l''Égyptienne, sa servante, au bout de dix années qu''Abram habitait dans la terre de Canaan, et la donna à Abram, son homme, pour lui être femme.'),
(386, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 4, 'OT', 'Il vint vers Agar, et elle conçut ; et elle vit qu''elle avait conçu, et sa maîtresse fut méprisée à ses yeux.'),
(387, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 5, 'OT', 'Saraï dit à Abram : « Que ma violence soit sur toi ! Moi, j''ai donné ma servante dans ton sein ; elle a vu qu''elle était enceinte, et j''ai été méprisée à ses yeux. Que l''Éternel juge entre moi et toi. »'),
(388, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 6, 'OT', 'Abram dit à Saraï : Voici, ta servante est en ta main ; fais-lui ce qui est bon à tes yeux. Et Saraï la maltraita, et elle s''enfuit de devant sa face.'),
(389, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 7, 'OT', 'L''ange de l''Éternel la trouva près de la source des eaux dans le désert, près de la source sur le chemin de Schur.'),
(390, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 8, 'OT', 'Il dit : Agar, servante de Saraï, d''où viens-tu, et où vas-tu ? Elle répondit : Je fuis loin de la face de Saraï, ma maîtresse.'),
(391, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 9, 'OT', 'L''ange de l''Éternel lui dit : Retourne vers ta maîtresse et humilie-toi sous sa main.'),
(392, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 10, 'OT', 'L''ange de l''Éternel lui dit : Je multiplierai beaucoup ta postérité, et elle ne sera pas comptée à cause de sa multitude.'),
(393, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 11, 'OT', 'L''ange de l''Éternel lui dit : Voici que tu es enceinte et tu enfanteras un fils, et tu appelleras son nom Ismaël, car l''Éternel a entendu ton affliction.'),
(394, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 12, 'OT', 'Il sera un âne sauvage parmi les hommes ; sa main sera contre tous, et la main de tous contre lui ; et il habitera en face de tous ses frères.'),
(395, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 13, 'OT', 'Elle appela le nom de l''Éternel qui lui parlait : « Tu es le Dieu de ma vue », car elle dit : « N''ai-je pas même ici vu après celui qui me voit ? »'),
(396, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 14, 'OT', 'C''est pourquoi on appela ce puits le puits de Lachaï-roï ; voici, il est entre Kadès et Béred.'),
(397, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 15, 'OT', 'Agar enfanta un fils à Abram, et Abram appela le nom de son fils qu''Agar avait enfanté : Ismaël.'),
(398, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 16, 16, 'OT', 'Abram était âgé de quatre-vingt-six ans lorsque Agar enfanta Ismaël à Abram.'),
(399, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 1, 'OT', 'Abram était âgé de quatre-vingt-dix-neuf ans, et l''Éternel apparut à Abram et lui dit : Je suis le Dieu Tout-Puissant ; marche devant ma face et sois intègre.'),
(400, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 2, 'OT', 'Je ferai mon alliance entre moi et toi, et je te multiplierai à l''extrême.'),
(401, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 3, 'OT', 'Abram tomba sur sa face, et Dieu lui parla, en disant :'),
(402, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 4, 'OT', 'Moi, voici mon alliance avec toi, et tu deviendras père d''une multitude de nations.'),
(403, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 5, 'OT', 'On ne t''appellera plus du nom d''Abram, mais ton nom sera Abraham, car je t''ai établi père d''une multitude de nations.'),
(404, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 6, 'OT', 'Je te rendrai extrêmement fécond, je ferai de toi des nations, et des rois sortiront de toi.'),
(405, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 7, 'OT', 'J''établirai mon alliance entre moi et toi, et entre ta postérité après toi, pour leurs générations, comme une alliance pour toujours, pour être ton Dieu et le Dieu de ta postérité après toi.'),
(406, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 8, 'OT', 'Je te donnerai, à toi et à ta postérité après toi, la terre de ton séjour, toute la terre de Canaan, en possession pour toujours, et je serai leur Dieu.'),
(407, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 9, 'OT', 'Dieu dit à Abraham : « Et toi, tu garderas mon alliance, toi et ta postérité après toi, selon leurs générations. »'),
(408, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 10, 'OT', 'C''est ici mon alliance que vous garderez entre moi et vous, et entre ta postérité après toi : tout mâle parmi vous sera circoncis.'),
(409, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 11, 'OT', 'Vous circoncirez la chair de votre prépuce, et ce sera un signe d''alliance entre moi et vous.'),
(410, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 12, 'OT', 'Et à l''âge de huit jours, tout mâle parmi vous sera circoncis, selon vos générations : l''enfant né dans la maison et l''acquisition d''argent de tout fils étranger, qui n''est pas de ta postérité.'),
(411, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 13, 'OT', 'On devra circoncire tout enfant né dans ta maison et toute acquisition faite avec ton argent ; et mon alliance sera dans votre chair comme une alliance pour toujours.'),
(412, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 14, 'OT', 'Et le mâle incirconcis qui ne circoncira pas la chair de son prépuce, cette âme sera retranchée de son peuple ; il a rompu mon alliance.'),
(413, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 15, 'OT', 'Dieu dit à Abraham : « Saraï, ta femme, tu n''appelleras pas son nom Saraï, car Sara est son nom. »'),
(414, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 16, 'OT', 'Je la bénirai, et je te donnerai aussi d''elle un fils ; je la bénirai, et elle deviendra des nations ; des rois de peuples sortiront d''elle.'),
(415, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 17, 'OT', 'Abraham tomba sur sa face et rit, et dit en son cœur : Un fils naîtra-t-il à un homme de cent ans, et Sara, âgée de quatre-vingt-dix ans, enfantera-t-elle une fille ?'),
(416, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 18, 'OT', 'Abraham dit à Dieu : « Que Ismaël vive devant ta face ! »'),
(417, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 19, 'OT', 'Dieu dit : « Mais Sara, ta femme, te donnera un fils, et tu appelleras son nom Isaac ; et j''établirai mon alliance avec lui comme une alliance pour toujours, pour sa postérité après lui. »'),
(418, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 20, 'OT', 'Quant à Ismaël, je t''ai entendu : voici, je l''ai béni, je le rendrai fécond et je le multiplierai à l''extrême ; il engendrera douze princes, et je ferai de lui une grande nation.'),
(419, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 21, 'OT', 'Et j''établirai mon alliance avec Isaac, que Sara t''enfantera à cette assignation, l''année suivante.'),
(420, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 22, 'OT', 'Il cessa de parler avec lui, et Dieu monta d''au-dessus d''Abraham.'),
(421, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 23, 'OT', 'Abraham prit Ismaël son fils, et tous les enfants nés dans sa maison, et toutes les acquisitions de son argent, tout mâle parmi les hommes de la maison d''Abraham, et il circoncit la chair de leur prépuce en ce même jour, comme Dieu le lui avait dit.'),
(422, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 24, 'OT', 'Abraham, âgé de quatre-vingt-dix-neuf ans, fut circoncis dans la chair de son prépuce.'),
(423, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 25, 'OT', 'Ismaël, son fils, était âgé de treize ans lorsqu''il fut circoncis dans la chair de son prépuce.'),
(424, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 26, 'OT', 'En ce même jour, Abraham fut circoncis, et Ismaël, son fils.'),
(425, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 17, 27, 'OT', 'Et tous les hommes de sa maison, l''enfant de la maison et l''acquisition d''argent de chez le fils de l''étranger, furent circoncis avec lui.'),
(426, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 1, 'OT', 'L''Éternel lui apparut aux chênes de Mamré, et il était assis à l''entrée de la tente, à la chaleur du jour.'),
(427, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 2, 'OT', 'Il leva les yeux et regarda, et voici, trois hommes se tenaient debout devant lui ; et, les ayant vus, il courut à leur rencontre depuis l''entrée de la tente, et se prosterna jusqu''à terre.'),
(428, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 3, 'OT', 'Il dit : Seigneur, si j''ai trouvé grâce à tes yeux, ne passe point, je te prie, auprès de ton serviteur.'),
(429, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 4, 'OT', 'Qu''on apporte un peu d''eaux, lavez vos pieds, et appuyez-vous sous le bois.'),
(430, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 5, 'OT', 'Je prendrai un morceau de pain, et vous soutiendrez votre cœur ; ensuite vous passerez, car c''est pour cela que vous êtes passés près de votre serviteur. Et ils dirent : Fais ainsi comme tu as parlé.'),
(431, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 6, 'OT', 'Abraham se hâta vers la tente, auprès de Sara, et dit : « Hâte-toi de prendre trois mesures de fleur de farine, pétris et fais des galettes. »'),
(432, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 7, 'OT', 'Abraham courut vers le bœuf, prit un veau tendre et bon, le donna au jeune homme, et celui-ci se hâta de le préparer.'),
(433, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 8, 'OT', 'Il prit de la crème et du lait, et le fils du bœuf qu''il avait préparé, et le mit devant leur face ; et lui se tenait debout près d''eux sous le bois, et ils mangèrent.'),
(434, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 9, 'OT', 'Ils lui dirent : Où est Sara, ta femme ? Et il répondit : Voici, elle est dans la tente.'),
(435, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 10, 'OT', 'Il dit : « Je reviendrai vers toi au temps de la vie, et voici, un fils pour Sara, ta femme ; et Sara écoutait à l''entrée de la tente, et il était derrière elle. »'),
(436, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 11, 'OT', 'Abraham et Sara étaient vieux, avancés en jours ; il avait cessé d''être pour Sara le sentier des femmes.'),
(437, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 12, 'OT', 'Sara rit en son milieu, disant : « Après que je suis devenue vieille, aurais-je du désir, et mon seigneur est vieux ? »'),
(438, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 13, 'OT', 'L''Éternel dit à Abraham : Pourquoi Sara a-t-elle ri, en disant : Est-ce vraiment que j''enfanterais, moi qui suis vieille ?'),
(439, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 14, 'OT', 'Y a-t-il une parole trop difficile pour l''Éternel ? Au temps assigné je reviendrai vers toi, à cette même époque, et Sara aura un fils.'),
(440, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 15, 'OT', 'Sara mentit, disant : « Je n''ai pas ri », car elle eut peur ; et il dit : « Non, mais tu as ri. »'),
(441, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 16, 'OT', 'Les hommes se levèrent de là et regardèrent vers la face de Sodome, et Abraham marchait avec eux pour les reconduire.'),
(442, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 17, 'OT', 'L''Éternel dit : Cacherais-je à Abraham ce que je fais ?'),
(443, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 18, 'OT', 'Abraham deviendra une nation grande et puissante, et toutes les nations de la terre seront bénies en lui.'),
(444, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 19, 'OT', 'Car je l''ai connu, afin qu''il commande à ses fils et à sa maison après lui, et qu''ils gardent le chemin de l''Éternel, en faisant justice et jugement, afin que l''Éternel fasse venir sur Abraham ce qu''il a dit à son sujet.'),
(445, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 20, 'OT', 'L''Éternel dit : Le cri de Sodome et de Gomorrhe est grand, et leur péché est très lourd.'),
(446, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 21, 'OT', 'Je descendrai donc et je verrai si, selon le cri qui est venu jusqu''à moi, ils ont commis un anéantissement complet ; sinon, je le saurai.'),
(447, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 22, 'OT', 'Les hommes se détournèrent de là et allèrent vers Sodome, mais Abraham se tenait encore devant la face de l''Éternel.'),
(448, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 23, 'OT', 'Abraham s''approcha et dit : Fera-tu périr aussi le juste avec le méchant ?'),
(449, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 24, 'OT', 'Peut-être y a-t-il cinquante justes au milieu de la ville ; anéantiras-tu vraiment et ne pardonneras-tu pas au lieu, à cause des cinquante justes qui sont en son milieu ?'),
(450, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 25, 'OT', 'Qu''il te soit loin de faire une telle parole, de faire mourir le juste avec le méchant, et que le juste soit comme le méchant — qu''il te soit loin ! Le juge de toute la terre ne ferait-il pas jugement ?'),
(451, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 26, 'OT', 'L''Éternel dit : Si je trouve dans Sodome cinquante justes au milieu de la ville, je pardonnerai à tout le lieu à cause d''eux.'),
(452, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 27, 'OT', 'Abraham répondit et dit : Voici, j''ai osé parler au Seigneur, moi qui ne suis que poussière et cendre.'),
(453, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 28, 'OT', 'Peut-être manquera-t-il cinq aux cinquante justes ; détruiras-tu pour cinq toute la ville ? Et il dit : Je ne la détruirai pas, si j''y trouve quarante-cinq.'),
(454, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 29, 'OT', 'Il ajouta encore à lui parler, et dit : Peut-être s''en trouvera-t-il là quarante. Et il dit : Je ne le ferai pas, à cause des quarante.'),
(455, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 30, 'OT', 'Il dit : Que le Seigneur ne s''irrite point, je te prie, et je parlerai : peut-être s''y trouvera-t-il trente. Et il dit : Je ne le ferai point, si j''y trouve trente.'),
(456, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 31, 'OT', 'Il dit : Voici, j''ai osé parler au Seigneur ; peut-être s''en trouvera-t-il vingt là. Et il dit : Je ne détruirai pas à cause de ces vingt.'),
(457, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 32, 'OT', 'Il dit : Que le Seigneur ne s''irrite point, je te prie, et je parlerai seulement cette fois : peut-être s''y trouvera-t-il dix. Et il dit : Je ne la détruirai point, à cause de ces dix.'),
(458, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 18, 33, 'OT', 'L''Éternel s''en alla, après qu''il eut fini de parler à Abraham, et Abraham retourna en son lieu.'),
(459, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 1, 'OT', 'Les deux anges arrivèrent à Sodome le soir, et Lot était assis à la porte de Sodome. Lot les vit, se leva pour aller à leur rencontre, et se prosterna le visage contre terre, la colère dans son cœur.'),
(460, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 2, 'OT', 'Il dit : « Voici, je vous prie, mon seigneur, détournez-vous vers la maison de votre serviteur, passez-y la nuit, lavez vos pieds, puis vous vous lèverez de bon matin et vous poursuivrez votre chemin. » Mais ils répondirent : « Non, nous passerons la nuit dans la rue. »'),
(461, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 3, 'OT', 'Il les pressa instamment, et ils se détournèrent vers lui, et ils entrèrent dans sa maison ; il leur prépara un festin, fit cuire des pains sans levain, et ils mangèrent.'),
(462, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 4, 'OT', 'Avant qu''ils se couchent, les hommes de la ville, les hommes de Sodome, entourèrent la maison, depuis le jeune jusqu''au vieux, tout le peuple, d''une extrémité à l''autre.'),
(463, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 5, 'OT', 'Ils appelèrent Lot et lui dirent : « Où sont les hommes qui sont venus chez toi cette nuit ? Fais-les sortir vers nous, et nous les connaîtrons. »'),
(464, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 6, 'OT', 'Lot sortit vers eux à l''entrée, et il ferma la porte derrière lui.'),
(465, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 7, 'OT', 'Il dit : « Je vous en prie, mes frères, ne faites pas ce mal. »'),
(466, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 8, 'OT', 'Voici, j''ai deux filles qui n''ont point connu d''homme ; je vous les amènerai dehors, et faites-leur comme il sera bon à vos yeux ; seulement à ces hommes ne faites aucune parole, car c''est pour cela qu''ils sont venus à l''ombre de ma poutre.'),
(467, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 9, 'OT', 'Ils dirent : « Éloigne-toi ! » et ils ajoutèrent : « Celui-ci est venu pour séjourner, et il ferait le juge ! Maintenant nous te ferons plus de mal qu''à eux. » Et ils pressèrent fort l''homme, Lot, et s''approchèrent pour briser la porte.'),
(468, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 10, 'OT', 'Alors les hommes étendirent leur main, firent entrer Lot vers eux dans la maison, et fermèrent la porte.'),
(469, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 11, 'OT', 'Et ils frappèrent d''aveuglement les hommes qui étaient à l''entrée de la maison, depuis le plus petit jusqu''au plus grand, et ils se lassèrent à chercher l''entrée.'),
(470, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 12, 'OT', 'Les hommes dirent à Lot : « Qui as-tu encore ici ? Gendre, tes fils, tes filles, et tout ce qui t''appartient dans la ville, fais-les sortir de ce lieu. »'),
(471, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 13, 'OT', 'Car nous détruisons ce lieu, car leur cri est grand devant la face de l''Éternel, et l''Éternel nous a envoyés pour le détruire.'),
(472, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 14, 'OT', 'Lot sortit et parla à ses gendres qui prenaient ses filles, et dit : Levez-vous, sortez de ce lieu, car l''Éternel détruit la ville ; mais il fut comme un moqueur aux yeux de ses gendres.'),
(473, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 15, 'OT', 'Et comme l''aurore montait, les anges pressèrent Lot, disant : Lève-toi, prends ta femme et tes deux filles qui se trouvent là, de peur que tu ne sois emporté dans l''iniquité de la ville.'),
(474, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 16, 'OT', 'Il s''attarda, et les hommes le saisirent par la main, par la main de sa femme et par les mains de ses deux filles, par la miséricorde de l''Éternel sur lui ; ils le firent sortir et le laissèrent dehors, hors de la ville.'),
(475, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 17, 'OT', 'Il arriva, comme ils les faisaient sortir dehors, qu''il dit : Sauve-toi, pour ta vie ; ne regarde pas derrière toi, et ne t''arrête pas dans tout le talent ; sauve-toi vers la montagne, de peur que tu ne sois emporté.'),
(476, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 18, 'OT', 'Lot leur dit : « Non, je vous en prie, mon Seigneur. »'),
(477, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 19, 'OT', 'Voici, ton serviteur a trouvé grâce à tes yeux, et tu as magnifié ta bonté que tu as exercée envers moi en préservant mon âme ; mais je ne puis m''enfuir vers la montagne, de peur que le mal ne m''atteigne et que je meure.'),
(478, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 20, 'OT', 'Voici, cette ville est proche pour y fuir, et elle est petite ; que je m''y échappe, je te prie — n''est-elle pas petite ? — et mon âme vivra.'),
(479, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 21, 'OT', 'Il lui dit : Voici, j''ai relevé ta face, même pour cette parole, afin de ne pas renverser la ville dont tu as parlé.'),
(480, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 22, 'OT', 'Hâte-toi de t''y réfugier, car je ne peux faire aucune parole jusqu''à ce que tu y sois arrivé. C''est pourquoi on appela le nom de la ville Tsoar.'),
(481, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 23, 'OT', 'Le soleil se levait sur la terre, et Lot arriva à Tsoar.'),
(482, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 24, 'OT', 'L''Éternel fit pleuvoir sur Sodome et sur Gomorrhe du soufre et du feu, de la part de l''Éternel, depuis les cieux.'),
(483, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 25, 'OT', 'Il renversa ces villes et toute la plaine, et tous les habitants des villes, et le germe de la terre.'),
(484, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 26, 'OT', 'Sa femme regarda derrière lui, et elle devint une garnison de sel.'),
(485, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 27, 'OT', 'Abraham se leva de bon matin, au lieu où il s''était tenu devant l''Éternel.'),
(486, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 28, 'OT', 'Il regarda vers la face de Sodome et de Gomorrhe, et vers toute la face de la terre du talent, et il vit, et voici que la fumée de la terre montait comme la fumée d''une fournaise.'),
(487, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 29, 'OT', 'Il arriva que, lorsque Dieu détruisit les villes de la plaine, Dieu se souvint d''Abraham, et il fit sortir Lot du milieu du renversement, en renversant les villes où Lot avait habité.'),
(488, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 30, 'OT', 'Lot monta de Tsoar et s''établit dans la montagne, et ses deux filles avec lui, car il craignait de s''établir à Tsoar ; il s''établit donc dans la caverne, lui et ses deux filles.'),
(489, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 31, 'OT', 'La première-née dit à la plus jeune : « Notre père est vieux, et il n''y a pas d''homme sur la terre pour venir sur nous selon le chemin de toute la terre. »'),
(490, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 32, 'OT', 'Viens, faisons boire du vin à notre père, et couchons avec lui, et nous conserverons de notre père une postérité.'),
(491, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 33, 'OT', 'Elles firent boire du vin à leur père cette nuit-là, et la première-née vint et coucha avec son père, et il ne sut ni quand elle se coucha ni quand elle se leva.'),
(492, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 34, 'OT', 'Le lendemain, la première-née dit à la plus jeune : Voici, j''ai couché la nuit dernière avec mon père ; faisons-lui boire du vin aussi cette nuit, et entre, couche avec lui, afin que nous conservions de notre père une postérité.'),
(493, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 35, 'OT', 'Elles firent aussi boire du vin à leur père cette nuit-là, et la cadette se leva et coucha avec lui, et il ne sut ni quand elle se coucha ni quand elle se leva.'),
(494, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 36, 'OT', 'Les deux filles de Lot conçurent de leur père.'),
(495, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 37, 'OT', 'La première-née enfanta un fils et appela son nom Moab ; c''est lui le père de Moab jusqu''à ce jour.'),
(496, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 19, 38, 'OT', 'La plus jeune aussi enfanta un fils, et elle appela son nom Ben-Ammi ; c''est lui le père des fils d''Ammon jusqu''à ce jour.'),
(497, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 1, 'OT', 'Abraham partit de là vers la terre du midi, et il habita entre Kadès et Schur, puis il séjourna à Guérar.'),
(498, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 2, 'OT', 'Abraham dit à Sara, sa femme : « Elle est ma sœur » ; et Abimélec, roi de Guérar, envoya et prit Sara.'),
(499, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 3, 'OT', 'Dieu vint vers Abimélec dans un rêve de la nuit et lui dit : Voici, tu es mort à cause de la femme que tu as prise, et elle est possédée d''un maître.'),
(500, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 4, 'OT', 'Abimélec ne s''était pas approché d''elle, et il dit : Seigneur, feras-tu périr une nation même juste ?'),
(501, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 5, 'OT', 'Ne m''a-t-il pas dit : « Elle est ma sœur » ? Et elle-même aussi a dit : « Il est mon frère » ? C''est dans l''intégrité de mon cœur et dans l''innocence de mes mains que j''ai fait cela.'),
(502, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 6, 'OT', 'Dieu lui dit en rêve : « Moi aussi, je savais que c''est dans l''intégrité de ton cœur que tu as fait cela, et moi aussi je t''ai retenu de pécher contre moi ; c''est pourquoi je ne t''ai pas laissé la toucher. »'),
(503, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 7, 'OT', 'Et maintenant, rends la femme de cet homme, car il est prophète, et il priera pour toi, et tu vivras ; mais si tu ne la rends pas, sache que tu mourras certainement, toi et tout ce qui est à toi.'),
(504, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 8, 'OT', 'Abimélec se leva de bon matin, appela tous ses serviteurs, et leur dit toutes ces paroles à leurs oreilles ; et les hommes eurent une grande crainte.'),
(505, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 9, 'OT', 'Abimélec appela Abraham et lui dit : « Que nous as-tu fait ? Et en quoi ai-je péché contre toi, que tu aies fait venir sur moi et sur mon royaume un si grand péché ? Des œuvres qui ne se font pas, tu en as fait avec moi. »'),
(506, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 10, 'OT', 'Abimélec dit à Abraham : Qu''as-tu vu, pour que tu aies fait cette parole ?'),
(507, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 11, 'OT', 'Abraham dit : « Car je me suis dit : Il n''y a certainement aucune crainte de Dieu en ce lieu, et ils me tueront à cause de la parole de ma femme. »'),
(508, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 12, 'OT', 'Et même, en vérité, elle est ma sœur, fille de mon père, mais non fille de ma mère ; et elle est devenue ma femme.'),
(509, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 13, 'OT', 'Il arriva que, lorsque Dieu me fit errer loin de la maison de mon père, je lui dis : « Voici la bonté que tu auras envers moi : dans tout lieu où nous viendrons, dis de moi : Il est mon frère. »'),
(510, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 14, 'OT', 'Abimélec prit des brebis, des bœufs, des serviteurs et des servantes, et les donna à Abraham ; et il lui rendit Sara, sa femme.'),
(511, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 15, 'OT', 'Abimélec dit : Voici, ma terre est devant ta face ; habite où il est bon à tes yeux.'),
(512, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 16, 'OT', 'Et à Sara il dit : Voici, j''ai donné mille argent à ton frère ; voici, cela est pour toi un vêtement pour les yeux, pour tous ceux qui sont avec toi, et pour tout, et tu es justifiée.'),
(513, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 17, 'OT', 'Abraham pria Dieu, et Dieu guérit Abimélec, sa femme et ses servantes, et elles enfantèrent.'),
(514, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 20, 18, 'OT', 'Car l''Éternel avait fermé toute matrice de la maison d''Abimélec, à cause de la parole de Sara, femme d''Abraham.'),
(515, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 1, 'OT', 'L''Éternel visita Sara comme il l''avait dit, et l''Éternel fit pour Sara comme il l''avait parlé.'),
(516, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 2, 'OT', 'Sara conçut et enfanta un fils à Abraham dans sa vieillesse, au temps assigné dont Dieu lui avait parlé.'),
(517, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 3, 'OT', 'Abraham appela le nom de son fils qui lui était né, que Sara lui avait enfanté, Isaac.'),
(518, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 4, 'OT', 'Abraham circoncit son fils Isaac à l''âge de huit jours, comme Dieu le lui avait commandé.'),
(519, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 5, 'OT', 'Abraham était fils de cent années à la naissance pour lui d''Isaac, son fils.'),
(520, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 6, 'OT', 'Sara dit : « Dieu m''a fait une moquerie ; tout homme qui l''entendra rira de moi. »'),
(521, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 7, 'OT', 'Elle dit : Qui aurait dit à Abraham que Sara allaiterait des fils ? Car j''ai enfanté un fils pour sa vieillesse.'),
(522, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 8, 'OT', 'L''enfant grandit et fut sevré, et Abraham fit un grand festin le jour où Isaac fut sevré.'),
(523, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 9, 'OT', 'Sara vit le fils d''Agar l''Égyptienne, qu''elle avait enfanté à Abraham, en train de se moquer.'),
(524, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 10, 'OT', 'Elle dit à Abraham : Chasse cette servante et son fils, car le fils de cette servante n''héritera pas avec mon fils, avec Isaac.'),
(525, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 11, 'OT', 'La parole fut très pénible aux yeux d''Abraham, à cause de son fils.'),
(526, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 12, 'OT', 'Dieu dit à Abraham : Que cela ne soit pas pénible à tes yeux à cause du jeune homme et à cause de ta servante ; tout ce que Sara te dira, écoute sa voix ; car c''est en Isaac que te sera appelée une postérité.'),
(527, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 13, 'OT', 'Et aussi le fils de la servante, je le ferai devenir une nation, car il est ta postérité.'),
(528, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 14, 'OT', 'Abraham se leva de bon matin, prit du pain et une outre d''eaux, les donna à Agar, les plaçant sur son épaule, ainsi que l''enfant, et la renvoya. Elle s''en alla et erra dans le désert de Beer-Schéba.'),
(529, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 15, 'OT', 'L''eau de l''outre vint à manquer, et elle jeta l''enfant sous l''un des arbrisseaux.'),
(530, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 16, 'OT', 'Elle alla donc s''asseoir en face, à distance, comme à un jet d''arc, car elle disait : « Je ne verrai pas la mort de l''enfant. » Et elle s''assit en face, éleva sa voix et pleura.'),
(531, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 17, 'OT', 'Dieu entendit la voix du jeune homme, et l''ange de Dieu appela Agar depuis les cieux et lui dit : « Qu''as-tu, Agar ? Ne crains point, car Dieu a entendu la voix du jeune homme là où il est. »'),
(532, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 18, 'OT', 'Lève-toi, prends le jeune homme et tiens ta main sur lui, car je ferai de lui une grande nation.'),
(533, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 19, 'OT', 'Dieu lui ouvrit les yeux, et elle vit un puits d''eaux ; elle alla, remplit l''outre d''eaux, et donna à boire au jeune.'),
(534, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 20, 'OT', 'Dieu fut avec le jeune homme, et il grandit ; il habita dans le désert, et il devint un tireur d''arc.'),
(535, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 21, 'OT', 'Il habita dans le désert de Paran, et sa mère lui prit une femme de la terre d''Égypte.'),
(536, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 22, 'OT', 'En ce temps-là, Abimélec et Picol, chef de son armée, dirent à Abraham : Dieu est avec toi dans tout ce que tu fais.'),
(537, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 23, 'OT', 'Et maintenant, jure-moi ici par Dieu que tu ne me tromperas pas, ni moi, ni ma postérité, ni mon descendant ; mais selon la bonté que j''ai eue envers toi, tu agiras envers moi et envers la terre où tu as séjourné.'),
(538, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 24, 'OT', 'Abraham dit : « Je jurerai. »'),
(539, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 25, 'OT', 'Abraham fit des reproches à Abimélec au sujet de la cause du puits d''eaux que les serviteurs d''Abimélec avaient usurpé.'),
(540, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 26, 'OT', 'Abimélec dit : Je ne savais pas qui avait fait cette parole, et toi non plus tu ne me l''avais pas apprise, et moi non plus je n''en avais pas entendu parler jusqu''à ce jour.'),
(541, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 27, 'OT', 'Abraham prit des brebis et des bœufs, et les donna à Abimélec, et ils firent tous deux une alliance.'),
(542, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 28, 'OT', 'Abraham plaça sept agnelles du troupeau à part, seules.'),
(543, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 29, 'OT', 'Abimélec dit à Abraham : Que sont ces sept agnelles que tu as mises à part, seules ?'),
(544, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 30, 'OT', 'Il dit : « C''est que tu prendras de ma main ces sept agnelles, à cause de cela, afin que cela me serve de précepte, parce que j''ai creusé ce puits. »'),
(545, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 31, 'OT', 'C''est pourquoi il appela ce lieu Beer-Schéba, car là ils jurèrent tous deux.'),
(546, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 32, 'OT', 'Ils conclurent une alliance à Beer-Schéba ; puis Abimélec et Picol, chef de son armée, se levèrent et retournèrent vers la terre des Philistins.'),
(547, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 33, 'OT', 'Il planta un tamaris à Beer-Schéba, et là il invoqua le nom de l''Éternel, Dieu toujours.'),
(548, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 21, 34, 'OT', 'Abraham demeura dans la terre des Philistins de nombreux jours.'),
(549, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 1, 'OT', 'Il arriva après ces paroles que Dieu mit Abraham à l''épreuve, et lui dit : Abraham ! Et il répondit : Me voici.'),
(550, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 2, 'OT', 'Il dit : Prends maintenant ton fils, ton unique, celui que tu aimes, Isaac, et va-t''en vers la terre de Moriah, et offre-le là en holocauste sur l''une des montagnes que je te dirai.'),
(551, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 3, 'OT', 'Abraham se leva de bon matin, sella son âne, prit avec lui deux de ses jeunes serviteurs et Isaac son fils, fendit du bois pour l''holocauste, puis se leva et alla au lieu que Dieu lui avait dit.'),
(552, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 4, 'OT', 'Le troisième jour, Abraham leva les yeux et vit le lieu de loin.'),
(553, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 5, 'OT', 'Abraham dit à ses jeunes gens : « Restez ici avec l''âne, et moi et le jeune homme nous irons jusqu''à là, et nous nous prosternerons, puis nous reviendrons vers vous. »'),
(554, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 6, 'OT', 'Abraham prit le bois de l''holocauste et le posa sur Isaac, son fils ; il prit dans sa main le feu et le couteau, et ils allèrent tous deux ensemble.'),
(555, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 7, 'OT', 'Isaac dit à Abraham, son père : « Mon père ! » Et Abraham répondit : « Me voici, mon fils. » Et Isaac dit : « Voici le feu et le bois, mais où est l''agneau pour l''holocauste ? »'),
(556, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 8, 'OT', 'Abraham dit : Dieu se pourvoira lui-même de l''agneau pour l''holocauste, mon fils ; et ils allèrent tous deux ensemble.'),
(557, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 9, 'OT', 'Ils arrivèrent au lieu que Dieu lui avait dit, et là Abraham bâtit l''autel, disposa le bois, lia Isaac son fils, et le plaça sur l''autel, par-dessus le bois.'),
(558, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 10, 'OT', 'Abraham étendit sa main et prit le couteau pour égorger son fils.'),
(559, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 11, 'OT', 'L''ange de l''Éternel l''appela depuis les cieux et dit : Abraham, Abraham ! Et il répondit : Me voici.'),
(560, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 12, 'OT', 'N''étends pas ta main vers le jeune homme, et ne lui fais rien, car maintenant je sais que tu crains Dieu, et tu n''as pas épargné ton fils, ton unique, pour moi.'),
(561, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 13, 'OT', 'Abraham leva les yeux, et il vit, et voici un bélier, pris dans le fourré par ses cornes ; et Abraham alla, prit le bélier, et l''offrit en holocauste à la place de son fils.'),
(562, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 14, 'OT', 'Abraham donna à ce lieu le nom d''Éternel pourvoira ; c''est pourquoi l''on dit aujourd''hui : Sur la montagne de l''Éternel il sera vu.'),
(563, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 15, 'OT', 'L''ange de l''Éternel appela Abraham une seconde fois depuis les cieux.'),
(564, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 16, 'OT', 'Il dit : « Par moi-même j''ai juré, déclaration de l''Éternel : parce que tu as fait cette parole et que tu n''as pas épargné ton fils, ton unique. »'),
(565, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 17, 'OT', 'Car je te bénirai abondamment, et je multiplierai grandement ta postérité comme les étoiles des cieux et comme le sable qui est sur le bord de la mer ; et ta postérité possédera la porte de ses ennemis.'),
(566, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 18, 'OT', 'Et en ta postérité seront bénies toutes les nations de la terre, à cause que tu as écouté ma voix.'),
(567, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 19, 'OT', 'Abraham retourna vers ses jeunes gens, et ils se levèrent et allèrent ensemble à Beer-Schéba ; et Abraham habita à Beer-Schéba.'),
(568, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 20, 'OT', 'Il arriva, après ces paroles, qu''on annonça à Abraham : Voici que Milca, elle aussi, a enfanté des fils à Nachor, ton frère.'),
(569, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 21, 'OT', 'Uts, son premier-né, et Buz, son frère, et Kemuel, père de Syrie.'),
(570, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 22, 'OT', 'et Késed, et Hazo, et Pildasch, et Jidlaph, et Bethuel.'),
(571, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 23, 'OT', 'Bethuel engendra Rebecca. Ces huit-là, Milca les enfanta à Nachor, frère d''Abraham.'),
(572, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 22, 24, 'OT', 'Sa concubine, dont le nom était Réuma, enfanta aussi elle Thébach, Gaham, Tahasch et Maaca.'),
(573, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 1, 'OT', 'La vie de Sara fut de cent ans et vingt ans et sept ans ; tels furent les ans de la vie de Sara.'),
(574, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 2, 'OT', 'Sara mourut à Kirjath-Arba, qui est Hébron, dans la terre de Canaan ; et Abraham vint pour faire le deuil de Sara et pour la pleurer.'),
(575, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 3, 'OT', 'Abraham se leva de devant la face de son mort, et parla aux fils de Heth, en disant :'),
(576, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 4, 'OT', 'Je suis un étranger et un résident parmi vous ; donnez-moi une possession de tombeau parmi vous, et j''enterrerai mon mort loin de ma face.'),
(577, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 5, 'OT', 'Les fils de Heth répondirent à Abraham, en lui disant :'),
(578, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 6, 'OT', 'Écoute-nous, mon seigneur : tu es un prince de Dieu au milieu de nous ; dans l''élite de nos tombeaux, enterre ton mort ; aucun homme parmi nous ne te refusera son tombeau pour enterrer ton mort.'),
(579, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 7, 'OT', 'Abraham se leva et se prosterna devant le peuple de la terre, devant les fils de Heth.'),
(580, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 8, 'OT', 'Il leur parla, disant : Si votre âme consent à ce que j''enterre mon mort devant ma face, écoutez-moi et intercédez pour moi auprès d''Éphron, fils de Tsochar.'),
(581, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 9, 'OT', 'Qu''il me donne la caverne de Macpéla qui lui appartient, qui est à l''extrémité de son champ ; pour de l''argent en pleine valeur, qu''il me la cède au milieu de vous, comme possession pour un tombeau.'),
(582, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 10, 'OT', 'Éphron était assis au milieu des fils de Heth, et Éphron le Héthien répondit à Abraham aux oreilles des fils de Heth, à tous ceux qui entraient par la porte de sa ville, en disant :'),
(583, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 11, 'OT', 'Non, mon seigneur, écoute-moi : le champ, je te le donne, et la caverne qui s''y trouve, je te la donne ; aux yeux des fils de mon peuple, je te la donne : enterre ton mort.'),
(584, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 12, 'OT', 'Abraham se prosterna devant le peuple de la terre.'),
(585, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 13, 'OT', 'Il parla à Éphron aux oreilles du peuple de la terre, disant : « Si seulement tu m''écoutais, j''ai donné l''argent du champ ; prends-le de moi, et j''y enterrerai mon mort. »'),
(586, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 14, 'OT', 'Éphron répondit à Abraham, en lui disant :'),
(587, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 15, 'OT', 'Mon seigneur, écoute-moi : une terre de quatre cents sicles d''argent, qu''est-ce que cela entre moi et toi ? Enterre donc ton mort.'),
(588, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 16, 'OT', 'Abraham écouta Éphron, et Abraham pesa pour Éphron l''argent qu''il avait dit aux oreilles des fils de Heth : quatre cents sicles d''argent, ayant cours chez le marchand.'),
(589, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 17, 'OT', 'Le champ d''Éphron, qui était à Macpéla, en face de Mamré, le champ et la caverne qui s''y trouvait, et tout le bois qui était dans le champ, dans toute sa frontière, à l''alentour, fut établi.'),
(590, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 18, 'OT', 'à Abraham, en acquisition, aux yeux des fils de Heth, parmi tous ceux qui entraient par la porte de sa ville.'),
(591, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 19, 'OT', 'Après cela, Abraham enterra Sara, sa femme, dans la caverne du champ de Macpéla, en face de Mamré, qui est Hébron, dans la terre de Canaan.'),
(592, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 23, 20, 'OT', 'Le champ et la caverne qui s''y trouve furent acquis par Abraham comme possession pour un tombeau, de la part des fils de Heth.'),
(593, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 1, 'OT', 'Abraham était vieux, avancé en jours, et l''Éternel avait béni Abraham en tout.'),
(594, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 2, 'OT', 'Abraham dit à son serviteur, l''ancien de sa maison, qui gouvernait sur tout ce qui lui appartenait : « Mets donc ta main sous mon côté. »'),
(595, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 3, 'OT', 'Et je te ferai jurer par l''Éternel, le Dieu des cieux et le Dieu de la terre, que tu ne prendras pas une femme pour mon fils parmi les filles des Cananéens, au milieu desquels j''habite.'),
(596, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 4, 'OT', 'Tu iras vers ma terre et vers ma naissance, et tu prendras une femme pour mon fils Isaac.'),
(597, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 5, 'OT', 'Le serviteur lui dit : Peut-être la femme ne voudra-t-elle pas me suivre dans cette terre ; devrai-je faire revenir ton fils vers la terre d''où tu es sorti ?'),
(598, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 6, 'OT', 'Abraham lui dit : Garde-toi de ramener mon fils là-bas.'),
(599, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 7, 'OT', 'L''Éternel, Dieu des cieux, qui m''a pris de la maison de mon père et de la terre de ma naissance, et qui m''a parlé et qui m''a juré, disant : « À ta postérité je donnerai cette terre », lui enverra son ange devant toi, et tu prendras une femme pour mon fils de là.'),
(600, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 8, 'OT', 'Et si la femme ne veut pas te suivre, tu seras dégagé de ce serment que je te fais ; seulement, tu ne ramèneras pas mon fils là-bas.'),
(601, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 9, 'OT', 'Le serviteur mit sa main sous le côté d''Abraham, son seigneur, et lui jura au sujet de cette parole.'),
(602, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 10, 'OT', 'Le serviteur prit dix chameaux parmi les chameaux de son seigneur, et s''en alla, ayant en sa main toute la bonté de son seigneur ; il se leva et s''en alla vers Aram-Naharaïm, vers la ville de Nachor.'),
(603, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 11, 'OT', 'Il fit s''agenouiller les chameaux dehors, hors de la ville, près du puits des eaux, au temps du soir, au temps où sortent celles qui puisent.'),
(604, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 12, 'OT', 'Il dit : Éternel, Dieu de mon seigneur Abraham, fais-moi rencontrer aujourd''hui ce qui est devant ma face, et use de bonté envers mon seigneur Abraham.'),
(605, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 13, 'OT', 'Voici, je me tiens près de l''œil des eaux, et les filles des hommes de la ville sortent pour puiser des eaux.'),
(606, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 14, 'OT', 'Et il arrivera que la jeune fille à qui je dirai : « Penche donc ta cruche, et je boirai », et qui répondra : « Bois, et je donnerai aussi à boire à tes chameaux », c''est elle que tu as désignée pour ton serviteur Isaac ; et par elle je saurai que tu as fait preuve de bonté envers mon seigneur.'),
(607, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 15, 'OT', 'Il arriva, avant qu''il eût fini de parler, que voici, Rebecca sortait, elle qui était née à Bethuel, fils de Milca, femme de Nachor, frère d''Abraham, et sa cruche était sur son épaule.'),
(608, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 16, 'OT', 'La jeune fille était d''une très belle apparence, vierge, qu''aucun homme n''avait connue ; elle descendit à l''œil de la source, remplit sa cruche, et remonta.'),
(609, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 17, 'OT', 'Le serviteur courut à sa rencontre et dit : Laisse-moi boire, je te prie, un peu d''eaux de ta cruche.'),
(610, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 18, 'OT', 'Elle dit : « Bois, mon seigneur », et elle se hâta de descendre sa cruche sur sa main et lui donna à boire.'),
(611, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 19, 'OT', 'Quand elle eut fini de lui donner à boire, elle dit : « Je puiserai aussi pour tes chameaux, jusqu''à ce qu''ils aient fini de boire. »'),
(612, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 20, 'OT', 'Elle se hâta, vida sa cruche dans l''auge, courut encore au puits pour puiser, et puisa pour tous ses chameaux.'),
(613, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 21, 'OT', 'L''homme la contemplait en silence, pour savoir si l''Éternel ferait réussir son chemin ou non.'),
(614, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 22, 'OT', 'Quand les chameaux eurent fini de boire, l''homme prit un anneau d''or d''un demi-sicle de poids, et deux bracelets pour ses mains, d''un poids de dix sicles d''or.'),
(615, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 23, 'OT', 'Il dit : « De qui es-tu la fille ? Dis-le-moi, je te prie. Y a-t-il dans la maison de ton père un lieu pour nous y loger ? »'),
(616, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 24, 'OT', 'Elle lui dit : « Je suis la fille de Bethuel, fils de Milca, qu''elle a enfanté à Nachor. »'),
(617, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 25, 'OT', 'Elle lui dit : « Nous avons aussi de la paille et du fourrage en abondance, ainsi qu''un lieu pour passer la nuit. »'),
(618, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 26, 'OT', 'L''homme s''inclina et se prosterna devant l''Éternel.'),
(619, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 27, 'OT', 'Béni soit l''Éternel, Dieu de mon seigneur Abraham, qui n''a pas abandonné sa bonté et sa vérité envers mon seigneur ; quant à moi, l''Éternel m''a conduit sur le chemin à la maison des frères de mon seigneur.'),
(620, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 28, 'OT', 'La jeune fille courut et raconta à la maison de sa mère ces paroles.'),
(621, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 29, 'OT', 'Rebecca avait un frère, et son nom était Laban ; et Laban courut vers l''homme, dehors, à l''œil.'),
(622, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 30, 'OT', 'Et il arriva, lorsqu''il vit l''anneau et les bracelets aux mains de sa sœur, et lorsqu''il entendit les paroles de Rebecca sa sœur, disant : Ainsi m''a parlé cet homme, il vint vers l''homme, et voici, il se tenait près des chameaux, près de l''œil.'),
(623, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 31, 'OT', 'Il dit : Entre, béni de l''Éternel ; pourquoi te tiens-tu dehors ? J''ai préparé la maison et un lieu pour les chameaux.'),
(624, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 32, 'OT', 'L''homme entra dans la maison, déchargea les chameaux, donna de la paille et du fourrage aux chameaux, et des eaux pour laver ses pieds et les pieds des hommes qui étaient avec lui.'),
(625, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 33, 'OT', 'On lui servit à manger devant lui, mais il dit : « Je ne mangerai point que je n''aie dit mes paroles. » Et il dit : « Parle. »'),
(626, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 34, 'OT', 'Il dit : Je suis un serviteur d''Abraham.'),
(627, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 35, 'OT', 'L''Éternel a béni mon seigneur abondamment, et il est devenu grand ; il lui a donné des brebis et des bœufs, de l''argent et de l''or, des serviteurs et des servantes, des chameaux et des ânes.'),
(628, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 36, 'OT', 'Sara, femme de mon seigneur, enfanta un fils à mon seigneur après sa vieillesse, et il lui donna tout ce qui était à lui.'),
(629, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 37, 'OT', 'Mon seigneur m''a fait jurer, en disant : Tu ne prendras pas une femme pour mon fils parmi les filles du Cananéen, dans la terre duquel j''habite.'),
(630, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 38, 'OT', 'Si tu ne vas pas à la maison de mon père et à ma famille, tu prendras une femme pour mon fils.'),
(631, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 39, 'OT', 'Et je dis à mon seigneur : Peut-être la femme ne viendra-t-elle pas après moi.'),
(632, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 40, 'OT', 'Il me dit : l''Éternel, devant la face duquel j''ai marché, enverra son ange avec toi, et fera prospérer ton chemin, et tu prendras une femme pour mon fils, de ma famille et de la maison de mon père.'),
(633, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 41, 'OT', 'Alors tu seras quitte de ma malédiction, quand tu viendras vers ma famille ; et s''ils ne te la donnent pas, tu seras libre de ma malédiction.'),
(634, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 42, 'OT', 'Aujourd''hui, je suis venu à l''œil, et j''ai dit : l''Éternel, Dieu de mon seigneur Abraham, si tu veux bien faire réussir mon chemin, sur lequel je marche,'),
(635, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 43, 'OT', 'Voici, je me tiens près de l''œil des eaux, et il arrivera que la jeune fille qui sort pour puiser, et je lui dirai : Donne-moi à boire, je te prie, un peu d''eau de ta cruche.'),
(636, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 44, 'OT', 'Et qu''elle me dise : « Bois toi aussi, et je puiserai aussi pour tes chameaux » — c''est elle, la femme que l''Éternel a désignée pour le fils de mon seigneur.'),
(637, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 45, 'OT', 'Je n''avais pas encore fini de parler à mon cœur, et voici que Rebecca sortait, sa cruche sur son épaule ; elle descendit à la source et puisa de l''eau, et je lui dis : Donne-moi à boire, je te prie.'),
(638, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 46, 'OT', 'Elle se hâta de descendre sa cruche de dessus elle, et dit : Bois, et je donnerai aussi à boire à tes chameaux. Je bus, et elle donna aussi à boire aux chameaux.'),
(639, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 47, 'OT', 'Et je lui demandai et dis : De qui es-tu fille ? Et elle dit : Je suis la fille de Bethuel, fils de Nachor, que Milca lui a enfanté. Et je mis l''anneau sur son nez et les bracelets sur ses mains.'),
(640, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 48, 'OT', 'Je me suis incliné et prosterné devant l''Éternel, et j''ai béni l''Éternel, le Dieu de mon seigneur Abraham, qui m''a conduit dans le chemin de la vérité, pour prendre la fille du frère de mon seigneur pour son fils.'),
(641, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 49, 'OT', 'Or maintenant, si vous faites bonté et vérité envers mon seigneur, déclarez-le-moi ; et si non, déclarez-le-moi, et je me tournerai à droite ou à gauche.'),
(642, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 50, 'OT', 'Laban et Bethuel répondirent et dirent : « De l''Éternel est sortie cette parole ; nous ne pouvons te dire ni mal ni bien. »'),
(643, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 51, 'OT', 'Voici Rebecca devant toi ; prends-la et va, et qu''elle soit femme pour le fils de ton seigneur, comme l''Éternel l''a dit.'),
(644, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 52, 'OT', 'Il arriva que lorsque le serviteur d''Abraham entendit leurs paroles, il se prosterna à terre devant l''Éternel.'),
(645, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 53, 'OT', 'Le serviteur sortit des ustensiles d''argent et des ustensiles d''or et des vêtements, et il les donna à Rebecca ; et il donna des présents à son frère et à sa mère.'),
(646, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 54, 'OT', 'Ils mangèrent et burent, lui et les hommes qui étaient avec lui, et ils passèrent la nuit ; puis ils se levèrent le matin, et il dit : Laissez-moi aller vers mon seigneur.'),
(647, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 55, 'OT', 'Son frère et sa mère dirent : Que la jeune fille reste avec nous quelques jours, ou une dizaine ; ensuite elle partira.'),
(648, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 56, 'OT', 'Il leur dit : Ne me retenez pas, car l''Éternel a fait réussir mon chemin ; laissez-moi partir, et j''irai vers mon seigneur.'),
(649, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 57, 'OT', 'Ils dirent : Appelons la jeune fille et demandons à sa bouche.'),
(650, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 58, 'OT', 'Ils appelèrent Rebecca et lui dirent : « Iras-tu avec cet homme ? » Et elle répondit : « J''irai. »'),
(651, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 59, 'OT', 'Ils renvoyèrent Rebecca, leur sœur, et sa nourrice, et le serviteur d''Abraham, et ses hommes.'),
(652, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 60, 'OT', 'Ils bénirent Rebecca et lui dirent : « Notre sœur, sois la mère de milliers de dix mille, et que ta postérité possède la porte de ceux qui la haïssent. »'),
(653, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 61, 'OT', 'Rebecca se leva avec ses jeunes filles, elles montèrent sur les chameaux et suivirent l''homme ; le serviteur prit Rebecca et s''en alla.'),
(654, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 62, 'OT', 'Et Isaac venait du puits de Lachaï-roï, et il habitait dans la terre du midi.'),
(655, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 63, 'OT', 'Isaac sortit pour méditer dans le champ, à la tombée du soir, et il leva les yeux et vit, et voici que des chameaux arrivaient.'),
(656, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 64, 'OT', 'Rebecca leva les yeux, vit Isaac, et tomba de dessus le chameau.'),
(657, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 65, 'OT', 'Elle dit au serviteur : « Qui est cet homme qui marche dans le champ à notre rencontre ? » Et le serviteur répondit : « C''est mon seigneur. » Alors elle prit le voile et se couvrit.'),
(658, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 66, 'OT', 'Le serviteur raconta à Isaac toutes les paroles qu''il avait faites.'),
(659, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 24, 67, 'OT', 'Isaac la fit entrer dans la tente de Sara, sa mère ; il prit Rebecca, et elle devint sa femme, et il l''aima. Et Isaac fut consolé après la mort de sa mère.'),
(660, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 1, 'OT', 'Abraham prit encore une femme, et son nom était Ketura.'),
(661, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 2, 'OT', 'Elle lui enfanta Zimran, Jokschan, Medan, Madian, Jischbak et Schuach.'),
(662, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 3, 'OT', 'Jokschan engendra Séba et Dedan, et les fils de Dedan furent Aschurim, Letuschim et Leummim.'),
(663, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 4, 'OT', 'Les fils de Madian : Épha, Épher, Hénoc, Abida et Eldaa. Tous ceux-là sont fils de Ketura.'),
(664, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 5, 'OT', 'Abraham donna tout ce qu''il avait à Isaac.'),
(665, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 6, 'OT', 'Et aux fils des concubines qui étaient à Abraham, Abraham donna des dons, et il les renvoya d''auprès d''Isaac, son fils, tandis qu''il vivait encore, vers l''orient, à la terre de l''orient.'),
(666, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 7, 'OT', 'Voici les jours des années de la vie d''Abraham, qu''il vécut : cent ans, soixante-dix ans, et cinq ans.'),
(667, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 8, 'OT', 'Abraham expira et mourut dans une bonne vieillesse, âgé et rassasié de jours, et il fut recueilli auprès de son peuple.'),
(668, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 9, 'OT', 'Isaac et Ismaël, ses fils, l''enterrèrent dans la caverne de Macpéla, dans le champ d''Éphron, fils de Tsochar, le Héthien, qui est en face de Mamré.'),
(669, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 10, 'OT', 'Le champ qu''Abraham avait acheté aux fils de Heth, c''est là qu''Abraham fut enseveli, ainsi que Sara, sa femme.'),
(670, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 11, 'OT', 'Après la mort d''Abraham, Dieu bénit Isaac, son fils, et Isaac habita près du puits de Lachaï-roï.'),
(671, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 12, 'OT', 'Voici les générations d''Ismaël, fils d''Abraham, qu''Agar l''Égyptienne, servante de Sara, enfanta à Abraham.'),
(672, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 13, 'OT', 'Voici les noms des fils d''Ismaël, selon leurs noms, selon leurs générations : le premier-né d''Ismaël, Nebajoth, puis Kédar, Adbeel et Mibsam.'),
(673, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 14, 'OT', 'Mischma, Duma et Massa.'),
(674, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 15, 'OT', 'Hadad et Théma, Jethur, Naphisch et Kedma.'),
(675, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 16, 'OT', 'Voici les fils d''Ismaël, et voici leurs noms, selon leurs parvis et selon leurs demeures : douze princes selon leurs peuples.'),
(676, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 17, 'OT', 'Voici les années de la vie d''Ismaël : cent ans et trente ans et sept ans ; puis il expira et mourut, et fut recueilli auprès de son peuple.'),
(677, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 18, 'OT', 'Ils habitèrent depuis Havila jusqu''à Schur, qui est en face de l''Égypte, en allant vers l''Assyrie ; il s''établit en face de tous ses frères.'),
(678, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 19, 'OT', 'Voici les générations d''Isaac, fils d''Abraham : Abraham engendra Isaac.'),
(679, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 20, 'OT', 'Isaac était âgé de quarante ans lorsqu''il prit Rebecca, fille de Bethuel le Syrien, de Padan-Aram, sœur de Laban le Syrien, pour femme.'),
(680, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 21, 'OT', 'Isaac implora l''Éternel en faveur de sa femme, car elle était stérile ; et l''Éternel se laissa fléchir par lui, et Rebecca, sa femme, conçut.'),
(681, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 22, 'OT', 'Les fils se heurtaient en son milieu, et elle dit : « Si c''est ainsi, pourquoi suis-je là ? » Et elle alla consulter l''Éternel.'),
(682, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 23, 'OT', 'L''Éternel lui dit : Deux nations sont dans ton ventre, et deux peuples se sépareront de tes entrailles ; un peuple sera plus fort que l''autre peuple, et l''aîné servira le cadet.'),
(683, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 24, 'OT', 'Ses jours furent accomplis pour enfanter, et voici, des jumeaux étaient dans son ventre.'),
(684, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 25, 'OT', 'Le premier sortit roux, tout entier comme un manteau de cheveux, et on appela son nom Ésaü.'),
(685, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 26, 'OT', 'Ensuite sortit son frère, sa main tenant le talon d''Ésaü, et on l''appela du nom de Jacob ; et Isaac était âgé de soixante ans quand elle les enfanta.'),
(686, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 27, 'OT', 'Les jeunes gens grandirent, et Ésaü devint un homme habile au gibier, un homme des champs, tandis que Jacob était un homme tranquille, demeurant sous des tentes.'),
(687, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 28, 'OT', 'Isaac aimait Ésaü, car le gibier était dans sa bouche, mais Rebecca aimait Jacob.'),
(688, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 29, 'OT', 'Jacob fit un potage, et Ésaü vint des champs, et il était fatigué.'),
(689, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 30, 'OT', 'Ésaü dit à Jacob : « Fais-moi donc avaler de ce roux, de ce roux-là, car je suis épuisé. » C''est pourquoi on appela son nom Édom.'),
(690, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 31, 'OT', 'Jacob dit : Vends-moi aujourd''hui ton droit d''aînesse.'),
(691, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 32, 'OT', 'Ésaü dit : Voici, je m''en vais mourir ; à quoi me sert donc le droit d''aînesse ?'),
(692, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 33, 'OT', 'Jacob dit : « Jure-le-moi aujourd''hui. » Et il le lui jura, et il vendit son droit d''aînesse à Jacob.'),
(693, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 25, 34, 'OT', 'Jacob donna à Ésaü du pain et un potage de lentilles ; il mangea et but, se leva et s''en alla. Ainsi Ésaü méprisa le droit d''aînesse.'),
(694, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 1, 'OT', 'Il y eut une famine dans la terre, outre la première famine qui avait eu lieu aux jours d''Abraham, et Isaac alla vers Abimélec, roi des Philistins, à Guérar.'),
(695, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 2, 'OT', 'L''Éternel lui apparut et dit : Ne descends pas en Égypte ; demeure dans la terre que je te dirai.'),
(696, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 3, 'OT', 'Habite dans cette terre, et je serai avec toi et je te bénirai ; car à toi et à ta postérité je donnerai toutes ces terres, et je confirmerai le serment que j''ai juré à Abraham ton père.'),
(697, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 4, 'OT', 'Je multiplierai ta postérité comme les étoiles des cieux, et je donnerai à ta postérité toutes ces terres ; et toutes les nations de la terre seront bénies en ta postérité.'),
(698, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 5, 'OT', 'À cause de ce qu''Abraham a écouté ma voix et a gardé mon observance, mes commandements, mes lois et mes lois.'),
(699, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 6, 'OT', 'Isaac habita à Guérar.'),
(700, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 7, 'OT', 'Les hommes du lieu l''interrogèrent au sujet de sa femme, et il dit : « Elle est ma sœur », car il craignait de dire : « Elle est ma femme », de peur que les hommes du lieu ne le tuent à cause de Rebecca, car elle était belle d''apparence.'),
(701, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 8, 'OT', 'Il arriva, lorsque les jours se furent prolongés pour lui là, qu''Abimélec, roi des Philistins, regarda par la fenêtre, et vit, et voici qu''Isaac plaisantait avec Rebecca, sa femme.'),
(702, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 9, 'OT', 'Abimélec appela Isaac et dit : « Certainement, elle est ta femme ! Comment as-tu pu dire : "Elle est ma sœur" ? » Et Isaac lui dit : « Parce que j''ai dit : "De peur que je meure à cause d''elle." »'),
(703, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 10, 'OT', 'Abimélec dit : Qu''est-ce que tu nous as fait ? Peu s''en est fallu que quelqu''un du peuple couche avec ta femme, et tu aurais fait venir sur nous un sacrifice de culpabilité.'),
(704, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 11, 'OT', 'Abimélec donna cet ordre à tout le peuple : « Quiconque touchera à cet homme ou à sa femme sera mis à mort. »'),
(705, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 12, 'OT', 'Isaac sema dans cette terre-là, et il trouva cette année-là un centuple, et l''Éternel le bénit.'),
(706, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 13, 'OT', 'L''homme grandit, et il continua de croître et de s''agrandir, jusqu''à devenir très puissant.'),
(707, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 14, 'OT', 'Il avait des troupeaux de brebis et des troupeaux de bœufs, et une grande maison de serviteurs ; et les Philistins lui portèrent envie.'),
(708, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 15, 'OT', 'Et tous les puits que les serviteurs de son père avaient creusés aux jours d''Abraham, son père, les Philistins les bouchèrent et les remplirent de poussière.'),
(709, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 16, 'OT', 'Abimélec dit à Isaac : « Va-t''en de chez nous, car tu es devenu beaucoup plus puissant que nous. »'),
(710, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 17, 'OT', 'Isaac partit de là, campa près du torrent de Guérar, et y demeura.'),
(711, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 18, 'OT', 'Isaac revint et creusa de nouveau les puits d''eaux qu''on avait creusés aux jours d''Abraham, son père, et que les Philistins avaient bouchés après la mort d''Abraham ; et il leur donna des noms selon les noms que son père leur avait donnés.'),
(712, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 19, 'OT', 'Les serviteurs d''Isaac creusèrent dans le torrent, et ils y trouvèrent un puits d''eaux vives.'),
(713, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 20, 'OT', 'Les bergers de Guérar disputèrent avec les bergers d''Isaac, disant : « À nous les eaux ! » Et il appela le nom du puits Ések, parce qu''ils avaient contesté avec lui.'),
(714, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 21, 'OT', 'Ils creusèrent un autre puits, et ils se querellèrent aussi à son sujet ; et il appela son nom Sitna.'),
(715, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 22, 'OT', 'Il se déplaça de là et creusa un autre puits, et ils ne disputèrent pas à son sujet ; il lui donna le nom de Rehoboth, et dit : « Car maintenant l''Éternel nous a fait place, et nous prospérerons dans la terre. »'),
(716, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 23, 'OT', 'Il monta de là à Beer-Schéba.'),
(717, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 24, 'OT', 'L''Éternel lui apparut cette nuit-là et dit : Je suis le Dieu d''Abraham, ton père ; ne crains point, car je suis avec toi, et je te bénirai et je multiplierai ta postérité à cause d''Abraham, mon serviteur.'),
(718, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 25, 'OT', 'Il bâtit là un autel, invoqua le nom de l''Éternel, et y dressa sa tente ; et là, les serviteurs d''Isaac creusèrent un puits.'),
(719, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 26, 'OT', 'Abimélec vint vers lui depuis Guérar, avec Ahuzath, son ami, et Picol, chef de son armée.'),
(720, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 27, 'OT', 'Isaac leur dit : « Pourquoi êtes-vous venus vers moi, alors que vous me haïssez et m''avez renvoyé de chez vous ? »'),
(721, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 28, 'OT', 'Ils dirent : « Nous avons vu clairement que l''Éternel était avec toi, et nous avons dit : Qu''il y ait donc une malédiction entre nous, entre nous et toi, et nous ferons une alliance avec toi. »'),
(722, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 29, 'OT', 'Si tu ne nous fais pas de mal, comme nous ne t''avons pas touché, et comme nous n''avons fait que du bien envers toi et t''avons renvoyé en paix, tu es maintenant béni de l''Éternel.'),
(723, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 30, 'OT', 'Il leur fit un festin, et ils mangèrent et burent.'),
(724, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 31, 'OT', 'Ils se levèrent de bon matin, et chacun jura à son frère ; puis Isaac les renvoya, et ils s''en allèrent de lui en paix.'),
(725, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 32, 'OT', 'Il advint, en ce jour-là, que les serviteurs d''Isaac vinrent et lui rapportèrent au sujet du puits qu''ils avaient creusé, et ils lui dirent : « Nous avons trouvé des eaux. »'),
(726, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 33, 'OT', 'Il l''appela Shib''a ; c''est pourquoi le nom de la ville est Beer-Schéba jusqu''à ce jour.'),
(727, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 34, 'OT', 'Ésaü était âgé de quarante ans, et il prit pour femme Judith, fille de Beéri le Héthien, et Basmath, fille d''Élon le Héthien.'),
(728, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 26, 35, 'OT', 'Elles furent une amertume d''esprit pour Isaac et pour Rebecca.'),
(729, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 1, 'OT', 'Il advint qu''Isaac étant vieux, et ses yeux s''étant affaiblis au point de ne plus voir, il appela Ésaü, son fils aîné, et lui dit : Mon fils. Et il lui répondit : Me voici.'),
(730, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 2, 'OT', 'Il dit : Voici, je suis devenu vieux ; je ne connais pas le jour de ma mort.'),
(731, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 3, 'OT', 'Maintenant donc, prends, je te prie, tes ustensiles, ton carquois et ton arc, sors dans le champ, et chasse pour moi des provisions.'),
(732, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 4, 'OT', 'Fais-moi des mets délicats comme je les ai aimés, et apporte-les-moi, et je mangerai, à cause de cela mon âme te bénira avant que je meure.'),
(733, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 5, 'OT', 'Rebecca écoutait pendant qu''Isaac parlait à son fils Ésaü, et Ésaü alla au champ pour chasser du gibier à rapporter.'),
(734, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 6, 'OT', 'Rebecca dit à Jacob, son fils : Voici, j''ai entendu ton père parler à Ésaü, ton frère, en disant :'),
(735, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 7, 'OT', 'Apporte-moi du gibier, et fais-moi des mets délicats, afin que je mange, et que je te bénisse devant la face de l''Éternel, devant ma mort.'),
(736, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 8, 'OT', 'Et maintenant, mon fils, écoute ma voix, selon ce que je te commande.'),
(737, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 9, 'OT', 'Va maintenant au troupeau de brebis, et prends-moi de là deux bons chevreaux de chèvres, et j''en ferai des mets délicats pour ton père, comme il les aime.'),
(738, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 10, 'OT', 'Tu l''apporteras à ton père, et il mangera, à cause de cela, afin qu''il te bénisse devant sa face, avant sa mort.'),
(739, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 11, 'OT', 'Jacob dit à Rebecca sa mère : Voici, Ésaü mon frère est un homme velu, et moi je suis un homme lisse.'),
(740, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 12, 'OT', 'Peut-être que mon père me palpera, et je serai à ses yeux comme un trompeur, et j''attirerai sur moi une malédiction et non une bénédiction.'),
(741, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 13, 'OT', 'Sa mère lui dit : « Que ta malédiction retombe sur moi, mon fils ; écoute seulement ma voix, va et prends pour moi. »'),
(742, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 14, 'OT', 'Il alla, les prit et les apporta à sa mère, et sa mère fit des mets délicats comme son père les aimait.'),
(743, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 15, 'OT', 'Rebecca prit les vêtements de délices d''Ésaü, son fils aîné, qui étaient avec elle dans la maison, et elle en vêtit Jacob, son fils cadet.'),
(744, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 16, 'OT', 'Elle mit les peaux des chevreaux de chèvres sur ses mains et sur le champ lisse de son cou.'),
(745, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 17, 'OT', 'Elle donna les mets délicats et le pain qu''elle avait préparés dans la main de Jacob, son fils.'),
(746, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 18, 'OT', 'Il vint vers son père et dit : Mon père, et il dit : Me voici, qui es-tu, mon fils ?'),
(747, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 19, 'OT', 'Jacob dit à son père : « Je suis Ésaü, ton premier-né ; j''ai fait comme tu me l''as dit. Lève-toi donc, assieds-toi, et mange de mon gibier, afin que ton âme me bénisse. »'),
(748, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 20, 'OT', 'Isaac dit à son fils : « Qu''est-ce que tu as trouvé si vite, mon fils ? » Et il dit : « Parce que l''Éternel, ton Dieu, l''a fait venir devant ma face. »'),
(749, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 21, 'OT', 'Isaac dit à Jacob : « Approche donc, et que je te tâte, mon fils, pour savoir si tu es vraiment mon fils Ésaü ou non. »'),
(750, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 22, 'OT', 'Jacob s''approcha d''Isaac, son père, et il le tâta ; puis il dit : « La voix est la voix de Jacob, mais les mains sont les mains d''Ésaü. »'),
(751, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 23, 'OT', 'Il ne le reconnut pas, car ses mains étaient comme les mains d''Ésaü, son frère, velues ; et il le bénit.'),
(752, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 24, 'OT', 'Il dit : « Es-tu bien mon fils Ésaü ? » Et il répondit : « Je le suis. »'),
(753, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 25, 'OT', 'Il dit : « Approche-moi, et je mangerai du gibier de mon fils, afin que mon âme te bénisse. » Il le lui approcha, et il mangea ; puis il lui apporta du vin, et il but.'),
(754, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 26, 'OT', 'Isaac, son père, lui dit : Approche donc, et embrasse-moi, mon fils.'),
(755, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 27, 'OT', 'Il s''approcha, l''embrassa, et sentit l''odeur de ses vêtements ; puis il le bénit, et dit : Voici, l''odeur de mon fils est comme l''odeur d''un champ que l''Éternel a béni.'),
(756, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 28, 'OT', 'Que Dieu te donne de la rosée des cieux et de la graisse de la terre, et une multitude de blé et de moût.'),
(757, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 29, 'OT', 'Que des peuples te servent, et que des nations se prosternent devant toi ; sois le maître de tes frères, et que les fils de ta mère se prosternent devant toi ; maudit soit celui qui te maudit, et béni soit celui qui te bénit.'),
(758, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 30, 'OT', 'Il advint que, lorsqu''Isaac eut fini de bénir Jacob, et que Jacob était à peine sorti de devant la face d''Isaac son père, Ésaü son frère arriva de sa chasse, de son gibier.'),
(759, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 31, 'OT', 'Il fit aussi des mets délicats, et les apporta à son père, et dit à son père : Que mon père se lève et mange du gibier de son fils, afin que ton âme me bénisse.'),
(760, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 32, 'OT', 'Isaac, son père, lui dit : Qui es-tu ? Et il dit : Je suis ton fils, ton premier-né, Ésaü.'),
(761, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 33, 'OT', 'Isaac fut saisi d''une très grande frayeur, jusqu''à en trembler, et dit : Qui donc est celui qui a chassé le gibier et me l''a apporté, et j''ai mangé de tout avant que tu viennes, et je l''ai béni ? Aussi sera-t-il béni.'),
(762, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 34, 'OT', 'Quand Ésaü entendit les paroles de son père, il poussa un cri grand et amer jusqu''à l''extrême, et dit à son père : Bénis-moi aussi, moi, mon père.'),
(763, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 35, 'OT', 'Il dit : « Ton frère est venu avec fraude et a pris ta bénédiction. »'),
(764, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 36, 'OT', 'Il dit : N''a-t-on pas appelé son nom Jacob ? Il m''a supplanté deux fois : il a pris mon droit d''aînesse, et voici que maintenant il a pris ma bénédiction. Puis il dit : N''as-tu pas réservé une bénédiction pour moi ?'),
(765, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 37, 'OT', 'Isaac répondit et dit à Ésaü : Voici, je l''ai établi maître sur toi, et j''ai donné à lui tous ses frères pour serviteurs, et je l''ai soutenu de blé et de moût ; et pour toi, que puis-je donc faire, mon fils ?'),
(766, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 38, 'OT', 'Ésaü dit à son père : N''as-tu qu''une seule bénédiction, mon père ? Bénis-moi aussi, moi, mon père ! Et Ésaü éleva la voix et pleura.'),
(767, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 39, 'OT', 'Isaac, son père, répondit et lui dit : Voici, ta habitation sera de la graisse de la terre, et de la rosée des cieux d''en haut.'),
(768, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 40, 'OT', 'Tu vivras par ton épée, et tu serviras ton frère ; mais il arrivera que, lorsque tu t''agiteras, tu briseras son joug de dessus ton cou.'),
(769, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 41, 'OT', 'Ésaü conçut de la haine contre Jacob, à cause de la bénédiction dont son père l''avait béni, et Ésaü dit en son cœur : Les jours du deuil de mon père approchent, et je tuerai Jacob, mon frère.'),
(770, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 42, 'OT', 'On rapporta à Rebecca les paroles d''Ésaü, son fils aîné ; elle envoya appeler Jacob, son fils cadet, et lui dit : Voici, Ésaü, ton frère, se console en pensant à te tuer.'),
(771, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 43, 'OT', 'Et maintenant, mon fils, écoute ma voix ; lève-toi, fuis vers Laban, mon frère, à Haran.'),
(772, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 44, 'OT', 'Tu demeureras avec lui quelques jours, jusqu''à ce que la fureur de ton frère se détourne.'),
(773, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 45, 'OT', 'Jusqu''à ce que la colère de ton frère se détourne de toi, et qu''il oublie ce que tu lui as fait, alors j''enverrai et je te ferai venir de là. Pourquoi perdrais-je aussi vous deux en un seul jour ?'),
(774, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 27, 46, 'OT', 'Rebecca dit à Isaac : « Je suis dégoûtée de la vie à cause des filles de Heth. Si Jacob prend une femme parmi les filles de Heth, comme celles-ci, parmi les filles de la terre, à quoi me sert la vie ? »'),
(775, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 1, 'OT', 'Isaac appela Jacob, le bénit, et lui donna cet ordre, en disant : Tu ne prendras point de femme parmi les filles de Canaan.'),
(776, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 2, 'OT', 'Lève-toi, va à Padan-Aram, à la maison de Bethuel, père de ta mère, et prends pour toi de là une femme parmi les filles de Laban, frère de ta mère.'),
(777, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 3, 'OT', 'Que Dieu Tout-Puissant te bénisse, te rende fécond et te multiplie, afin que tu deviennes une assemblée de peuples.'),
(778, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 4, 'OT', 'Qu''il te donne la bénédiction d''Abraham, à toi et à ta postérité avec toi, pour que tu possèdes la terre de ton séjour, que Dieu a donnée à Abraham.'),
(779, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 5, 'OT', 'Isaac envoya Jacob, et il alla à Padan-Aram, vers Laban, fils de Bethuel le Syrien, frère de Rebecca, mère de Jacob et d''Ésaü.'),
(780, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 6, 'OT', 'Ésaü vit qu''Isaac avait béni Jacob et l''avait envoyé à Padan-Aram pour y prendre une femme, et qu''en le bénissant il lui avait commandé, en disant : « Tu ne prendras pas une femme parmi les filles de Canaan. »'),
(781, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 7, 'OT', 'Jacob écouta son père et sa mère, et il partit pour Padan-Aram.'),
(782, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 8, 'OT', 'Ésaü vit que les filles de Canaan étaient mauvaises aux yeux d''Isaac, son père.'),
(783, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 9, 'OT', 'Ésaü alla vers Ismaël, et prit Mahalath, fille d''Ismaël, fils d''Abraham, sœur de Nebajoth, en plus de ses femmes, pour lui être femme.'),
(784, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 10, 'OT', 'Jacob sortit de Beer-Schéba et se rendit vers Haran.'),
(785, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 11, 'OT', 'Il atteignit le lieu et y passa la nuit, car le soleil était couché ; il prit des pierres du lieu, les mit à son chevet, et se coucha dans ce lieu.'),
(786, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 12, 'OT', 'Il fit un rêve : voici, une échelle était dressée sur la terre, et son sommet touchait les cieux, et voici, les anges de Dieu montaient et descendaient par elle.'),
(787, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 13, 'OT', 'Et voici que l''Éternel se tenait au-dessus de lui et dit : Je suis l''Éternel, le Dieu d''Abraham ton père et le Dieu d''Isaac ; la terre sur laquelle tu es couché, je te la donnerai, à toi et à ta postérité.'),
(788, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 14, 'OT', 'Et ta postérité sera comme la poussière de la terre, et tu t''étendras vers la mer, vers l''orient, vers le nord et vers le midi, et toutes les familles de la terre seront bénies en toi et en ta postérité.'),
(789, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 15, 'OT', 'Et voici, je suis avec toi, et je te garderai en tout lieu où tu iras, et je te ramènerai à cette terre, car je ne t''abandonnerai point, jusqu''à ce que j''aie fait ce que je t''ai dit.'),
(790, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 16, 'OT', 'Jacob s''éveilla de son sommeil et dit : Certainement, l''Éternel est dans ce lieu, et moi, je ne le savais pas.'),
(791, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 17, 'OT', 'Il eut peur et dit : Que ce lieu est redoutable ! Ce n''est rien d''autre que la maison de Dieu, et c''est ici la porte des cieux.'),
(792, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 18, 'OT', 'Jacob se leva de bon matin, prit la pierre qu''il avait mise à son chevet, la dressa comme un monument, et versa de l''huile sur son sommet.'),
(793, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 19, 'OT', 'Il appela le nom de ce lieu Béthel, mais Luz était le nom de la ville auparavant.'),
(794, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 20, 'OT', 'Jacob fit un vœu, en disant : Si Dieu est avec moi et me garde dans ce chemin où je marche, et me donne du pain à manger et un vêtement à revêtir,'),
(795, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 21, 'OT', 'Et je reviendrai en paix à la maison de mon père, et l''Éternel sera mon Dieu.'),
(796, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 28, 22, 'OT', 'Cette pierre que j''ai dressée comme monument sera une maison de Dieu, et de tout ce que tu me donneras, je te paierai la dîme.'),
(797, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 1, 'OT', 'Jacob leva ses pieds et se rendit vers la terre des fils de l''orient.'),
(798, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 2, 'OT', 'Il vit, et voici, un puits dans le champ, et voici, là trois troupeaux de brebis couchés auprès de lui, car de ce puits les troupeaux s''abreuvaient, et la pierre était grande sur la bouche du puits.'),
(799, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 3, 'OT', 'Et là se rassemblaient tous les troupeaux, et ils roulaient la pierre de dessus la bouche du puits, et ils abreuvaient les brebis, et ils remettaient la pierre sur la bouche du puits en son lieu.'),
(800, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 4, 'OT', 'Jacob leur dit : « Mes frères, d''où êtes-vous ? » Et ils répondirent : « Nous sommes de Haran. »'),
(801, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 5, 'OT', 'Il leur dit : « Connaissez-vous Laban, fils de Nachor ? » Et ils répondirent : « Nous le connaissons. »'),
(802, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 6, 'OT', 'Il leur dit : « Est-ce que la paix est avec lui ? » Et ils répondirent : « La paix est avec lui. » Et voici que Rachel, sa fille, venait avec les brebis.'),
(803, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 7, 'OT', 'Il dit : Voici, le jour est encore grand, ce n''est pas le temps de rassembler les troupeaux ; abreuvez les brebis, et allez les faire paître.'),
(804, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 8, 'OT', 'Ils dirent : Nous ne pouvons pas, jusqu''à ce que tous les troupeaux soient rassemblés, et qu''on roule la pierre de dessus la bouche du puits ; alors nous abreuverons les brebis.'),
(805, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 9, 'OT', 'Il parlait encore avec eux, lorsque Rachel arriva avec les brebis qui appartenaient à son père, car elle était bergère.'),
(806, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 10, 'OT', 'Il arriva que, lorsque Jacob vit Rachel, fille de Laban, frère de sa mère, et les brebis de Laban, frère de sa mère, Jacob s''approcha, roula la pierre de dessus la bouche du puits, et abreuva les brebis de Laban, frère de sa mère.'),
(807, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 11, 'OT', 'Jacob embrassa Rachel, et il éleva sa voix et pleura.'),
(808, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 12, 'OT', 'Jacob raconta à Rachel qu''il était le frère de son père et qu''il était le fils de Rebecca, et elle courut le dire à son père.'),
(809, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 13, 'OT', 'Or, lorsque Laban entendit le bruit de Jacob, fils de sa sœur, il courut à sa rencontre, l''embrassa, le baisa, et le fit entrer dans sa maison ; et Jacob raconta à Laban toutes ces paroles.'),
(810, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 14, 'OT', 'Laban lui dit : « Tu es vraiment mon os et ma chair. » Et il demeura avec lui un mois de jours.'),
(811, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 15, 'OT', 'Laban dit à Jacob : « Parce que tu es mon frère, me servirais-tu pour rien ? Dis-moi quel est ton salaire. »'),
(812, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 16, 'OT', 'Laban avait deux filles ; le nom de l''aînée était Léa, et le nom de la cadette était Rachel.'),
(813, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 17, 'OT', 'Les yeux de Léa étaient délicats, mais Rachel était belle d''apparence et belle de visage.'),
(814, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 18, 'OT', 'Jacob aima Rachel, et dit : Je te servirai sept années pour Rachel, ta fille cadette.'),
(815, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 19, 'OT', 'Laban dit : « Il vaut mieux te la donner à toi que de la donner à un autre homme ; reste avec moi. »'),
(816, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 20, 'OT', 'Jacob servit sept années pour Rachel, et elles furent à ses yeux comme quelques jours, à cause de son amour pour elle.'),
(817, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 21, 'OT', 'Jacob dit à Laban : Donne-moi ma femme, car mes jours sont accomplis, et j''irai vers elle.'),
(818, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 22, 'OT', 'Laban rassembla tous les hommes du lieu et fit un festin.'),
(819, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 23, 'OT', 'Le soir venu, il prit Léa, sa fille, et la lui amena ; et il alla vers elle.'),
(820, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 24, 'OT', 'Laban donna à Léa, sa fille, Zilpa, sa servante, comme servante.'),
(821, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 25, 'OT', 'Le matin venu, voici que c''était Léa. Et il dit à Laban : Qu''est-ce que tu m''as fait ? N''est-ce pas pour Rachel que j''ai servi avec toi ? Et pourquoi m''as-tu trompé ?'),
(822, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 26, 'OT', 'Laban dit : « On ne fait pas ainsi dans notre lieu, donner la cadette avant la première-née. »'),
(823, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 27, 'OT', 'Complète cette semaine, et l''on te donnera aussi celle-ci, pour le service que tu feras avec moi encore sept autres années.'),
(824, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 28, 'OT', 'Jacob fit ainsi, et il acheva cette semaine-là ; puis Laban lui donna Rachel, sa fille, pour femme.'),
(825, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 29, 'OT', 'Laban donna à Rachel, sa fille, Bilha, sa servante, pour être sa servante.'),
(826, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 30, 'OT', 'Il entra aussi auprès de Rachel, et il aima aussi Rachel plus que Léa, et il servit avec lui encore sept autres années.'),
(827, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 31, 'OT', 'L''Éternel vit que Léa était haïe, et il ouvrit sa matrice, mais Rachel était stérile.'),
(828, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 32, 'OT', 'Léa conçut et enfanta un fils, et elle appela son nom Ruben, car elle dit : « Parce que l''Éternel a vu mon affliction, car maintenant mon homme m''aimera. »'),
(829, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 33, 'OT', 'Elle conçut encore, enfanta un fils, et dit : Parce que l''Éternel a entendu que j''étais haïe, il m''a aussi donné celui-ci. Et elle appela son nom Siméon.'),
(830, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 34, 'OT', 'Elle conçut encore, enfanta un fils, et dit : « Cette fois, mon homme s''attachera à moi, car je lui ai enfanté trois fils. » C''est pourquoi on l''appela du nom de Lévi.'),
(831, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 29, 35, 'OT', 'Elle conçut encore, enfanta un fils, et dit : Cette fois, je louerai l''Éternel ; c''est pourquoi elle appela son nom Juda. Puis elle cessa d''enfanter.'),
(832, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 1, 'OT', 'Rachel vit qu''elle n''avait pas enfanté pour Jacob, et Rachel fut jalouse de sa sœur, et dit à Jacob : Donne-moi des fils, sinon je suis morte.'),
(833, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 2, 'OT', 'La colère de Jacob s''enflamma contre Rachel, et il dit : Suis-je à la place de Dieu, qui t''a refusé le fruit du ventre ?'),
(834, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 3, 'OT', 'Elle dit : Voici ma servante Bilha ; va vers elle, et elle enfantera sur mes genoux, et moi aussi je serai édifiée par elle.'),
(835, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 4, 'OT', 'Elle donna donc à Jacob Bilha, sa servante, pour femme, et Jacob alla vers elle.'),
(836, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 5, 'OT', 'Bilha conçut et enfanta un fils à Jacob.'),
(837, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 6, 'OT', 'Rachel dit : « Dieu m''a rendu justice, et il a aussi entendu ma voix et m''a donné un fils. C''est pourquoi elle appela son nom Dan. »'),
(838, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 7, 'OT', 'Elle conçut encore, et Bilha, servante de Rachel, enfanta un second fils pour Jacob.'),
(839, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 8, 'OT', 'Rachel dit : « De lutte de Dieu j''ai lutté avec ma sœur, et j''ai prévalu » ; et elle appela son nom Nephthali.'),
(840, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 9, 'OT', 'Léa vit qu''elle avait cessé d''enfanter, et elle prit Zilpa, sa servante, et la donna à Jacob pour femme.'),
(841, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 10, 'OT', 'Zilpa, servante de Léa, enfanta un fils à Jacob.'),
(842, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 11, 'OT', 'Léa dit : « Bonheur ! » et elle appela son nom Gad.'),
(843, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 12, 'OT', 'Zilpa, servante de Léa, enfanta un second fils à Jacob.'),
(844, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 13, 'OT', 'Léa dit : « Quel bonheur pour moi, car les filles me diront bienheureuse ! » Et elle appela son nom Aser.'),
(845, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 14, 'OT', 'Ruben s''en alla aux jours de la moisson du froment, et trouva des mandragores dans le champ, et les apporta à Léa, sa mère. Et Rachel dit à Léa : Donne-moi, je te prie, des mandragores de ton fils.'),
(846, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 15, 'OT', 'Elle lui dit : Est-ce peu que tu aies pris mon homme, et que tu prennes aussi les mandragores de mon fils ? Et Rachel dit : C''est pourquoi il couchera avec toi cette nuit, en échange des mandragores de ton fils.'),
(847, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 16, 'OT', 'Jacob revint des champs le soir, et Léa sortit à sa rencontre et dit : « C''est vers moi que tu viendras, car je t''ai loué pour les mandragores de mon fils. » Et il coucha avec elle cette nuit-là.'),
(848, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 17, 'OT', 'Dieu écouta Léa, et elle conçut et enfanta à Jacob un cinquième fils.'),
(849, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 18, 'OT', 'Léa dit : « Dieu m''a donné mon salaire, parce que j''ai donné ma servante à mon homme. » Et elle appela son nom Issacar.'),
(850, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 19, 'OT', 'Léa conçut encore et enfanta un sixième fils pour Jacob.'),
(851, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 20, 'OT', 'Léa dit : « Dieu m''a fait un beau don ; cette fois mon homme m''honorera, car je lui ai enfanté six fils. » Et elle appela son nom Zabulon.'),
(852, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 21, 'OT', 'Ensuite, elle enfanta une fille, et elle appela son nom Dina.'),
(853, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 22, 'OT', 'Dieu se souvint de Rachel, et Dieu l''exauça, et ouvrit sa matrice.'),
(854, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 23, 'OT', 'Elle conçut, enfanta un fils, et dit : Dieu a ôté mon opprobre.'),
(855, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 24, 'OT', 'Elle appela son nom Joseph, en disant : Que l''Éternel m''ajoute un autre fils.'),
(856, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 25, 'OT', 'Il arriva, lorsque Rachel eut enfanté Joseph, que Jacob dit à Laban : Renvoie-moi, et je m''en irai vers mon lieu et vers ma terre.'),
(857, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 26, 'OT', 'Donne-moi mes femmes et mes enfants, pour lesquels je t''ai servi, et je m''en irai ; car tu sais le service que je t''ai rendu.'),
(858, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 27, 'OT', 'Laban lui dit : Si j''ai trouvé grâce à tes yeux, j''ai deviné que l''Éternel m''a béni à cause de toi.'),
(859, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 28, 'OT', 'Il dit : Fixe-moi ton salaire, et je le donnerai.'),
(860, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 29, 'OT', 'Il lui dit : « Tu sais comment je t''ai servi, et comment tes troupeaux ont été avec moi. »'),
(861, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 30, 'OT', 'Car peu était ce qui était à toi devant ma face, et il a éclaté en multitude, et l''Éternel t''a béni sur mon pied ; et maintenant, quand ferai-je, moi aussi, pour ma maison ?'),
(862, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 31, 'OT', 'Il dit : Que te donnerai-je ? Et Jacob dit : Tu ne me donneras rien ; si tu fais pour moi cette parole, je reviendrai, je ferai paître tes brebis, je les garderai.'),
(863, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 32, 'OT', 'Je passerai aujourd''hui au milieu de tout ton troupeau, retirant de là tout agneau tacheté et marqueté, et tout agneau brun parmi les agneaux, et tout marqueté et tacheté parmi les chèvres ; et ce sera mon salaire.'),
(864, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 33, 'OT', 'Et ma justice répondra pour moi au jour de demain, quand tu viendras au sujet de mon salaire devant ta face : tout ce qui ne sera pas tacheté ni marqueté parmi les chèvres, et ce qui sera brun parmi les agneaux, sera tenu pour volé chez moi.'),
(865, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 34, 'OT', 'Laban dit : « Qu''il en soit selon ta parole. »'),
(866, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 35, 'OT', 'Ce jour-là, il retira les boucs rayés et tachetés, et toutes les chèvres tachetées et marquetées, tout ce qui avait du blanc, et tout ce qui était brun parmi les agneaux, et il les remit entre les mains de ses fils.'),
(867, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 36, 'OT', 'Il mit un chemin de trois jours entre lui et Jacob, et Jacob faisait paître les brebis de Laban qui restaient.'),
(868, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 37, 'OT', 'Jacob prit pour lui des branches vertes de peuplier, d''amandier et de platane, et y fit des bandes blanches, mettant à nu la dépouille blanche qui était sur les bâtons.'),
(869, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 38, 'OT', 'Il plaça les bâtons qu''il avait écorcés dans les abreuvoirs, dans les auges des eaux, là où les brebis venaient boire, en face des brebis ; et les brebis s''échauffaient en venant boire.'),
(870, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 39, 'OT', 'Les brebis s''échauffèrent vers les bâtons, et les brebis mirent bas des agneaux rayés, tachetés et marquetés.'),
(871, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 40, 'OT', 'Jacob sépara les agneaux, et il tourna la face des brebis vers ce qui était rayé et tout ce qui était brun dans le troupeau de Laban ; il mit ses propres troupeaux à part, seul, et ne les mit pas avec les brebis de Laban.'),
(872, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 41, 'OT', 'Et il arrivait que, dans tout le temps où les brebis vigoureuses entraient en chaleur, Jacob plaçait les bâtons devant les yeux des brebis dans les abreuvoirs, pour les faire concevoir par les bâtons.'),
(873, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 42, 'OT', 'Mais quand les brebis étaient faibles, il ne les mettait pas ; ainsi les faibles étaient pour Laban, et les robustes pour Jacob.'),
(874, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 30, 43, 'OT', 'L''homme devint extrêmement, extrêmement riche, et il eut de nombreuses brebis, des servantes et des serviteurs, des chameaux et des ânes.'),
(875, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 1, 'OT', 'Il entendit les paroles des fils de Laban, disant : Jacob a pris tout ce qui était à notre père, et de ce qui était à notre père il a fait toute cette gloire.'),
(876, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 2, 'OT', 'Jacob vit le visage de Laban, et voici qu''il n''était plus avec lui comme auparavant.'),
(877, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 3, 'OT', 'L''Éternel dit à Jacob : Retourne vers la terre de tes pères et vers ta naissance, et je serai avec toi.'),
(878, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 4, 'OT', 'Jacob envoya appeler Rachel et Léa au champ, vers son troupeau de brebis.'),
(879, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 5, 'OT', 'Il leur dit : « Je vois la face de votre père, qu''elle n''est plus envers moi comme auparavant ; mais le Dieu de mon père a été avec moi. »'),
(880, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 6, 'OT', 'Et vous, vous savez que de toute ma force j''ai servi votre père.'),
(881, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 7, 'OT', 'Et votre père m''a trompé, et il a changé mon salaire dix fois ; mais Dieu ne lui a pas permis de me faire du mal.'),
(882, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 8, 'OT', 'S''il dit ainsi : « Les tachetés seront ton salaire », alors tout le troupeau de brebis enfantera des tachetés ; et s''il dit ainsi : « Les rayés seront ton salaire », alors tout le troupeau de brebis enfantera des rayés.'),
(883, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 9, 'OT', 'Dieu a retiré les troupeaux de votre père et me les a donnés.'),
(884, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 10, 'OT', 'Il arriva, au temps où les brebis entraient en chaleur, que je levai les yeux et vis en rêve : voici, les boucs qui montaient sur les brebis étaient rayés, tachetés et mouchetés.'),
(885, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 11, 'OT', 'L''ange de Dieu me dit dans un rêve : « Jacob ! » Et je répondis : « Me voici. »'),
(886, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 12, 'OT', 'Il dit : Lève maintenant tes yeux et regarde tous les boucs qui montent sur les brebis, rayés, tachetés et marquetés, car j''ai vu tout ce que Laban te fait.'),
(887, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 13, 'OT', 'Je suis le Dieu de Béthel, où tu as oint un monument, où tu m''as fait un vœu ; maintenant, lève-toi, sors de cette terre, et retourne vers la terre de ta naissance.'),
(888, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 14, 'OT', 'Rachel et Léa répondirent et lui dirent : « Avons-nous encore une part et un héritage dans la maison de notre père ? »'),
(889, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 15, 'OT', 'Ne sommes-nous pas comptées comme étrangères par lui, puisqu''il nous a vendues, et il a même dévoré entièrement notre argent ?'),
(890, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 16, 'OT', 'Car toute la richesse que Dieu a retirée de notre père nous appartient, à nous et à nos fils ; et maintenant, fais tout ce que Dieu t''a dit.'),
(891, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 17, 'OT', 'Jacob se leva, et il fit monter ses fils et ses femmes sur les chameaux.'),
(892, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 18, 'OT', 'Il conduisit tout son troupeau et tous ses biens qu''il avait acquis, le troupeau de ses biens qu''il avait obtenu à Padan-Aram, pour venir vers Isaac son père, dans la terre de Canaan.'),
(893, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 19, 'OT', 'Laban était allé tondre ses brebis, et Rachel déroba les théraphim qui appartenaient à son père.'),
(894, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 20, 'OT', 'Jacob déroba le cœur de Laban le Syrien, en ne lui ayant pas dit qu''il fuyait.'),
(895, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 21, 'OT', 'Il s''enfuit, lui et tout ce qui lui appartenait, et se leva, traversa le fleuve, et dirigea sa face vers la montagne de Galaad.'),
(896, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 22, 'OT', 'On apprit à Laban, au troisième jour, que Jacob s''était enfui.'),
(897, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 23, 'OT', 'Il prit ses frères avec lui, et le poursuivit pendant un chemin de sept jours, et l''atteignit sur la montagne de Galaad.'),
(898, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 24, 'OT', 'Dieu vint vers Laban le Syrien dans un rêve de la nuit, et lui dit : Garde-toi de parler avec Jacob, ni en bien ni en mal.'),
(899, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 25, 'OT', 'Laban atteignit Jacob, et Jacob avait planté sa tente sur la montagne, et Laban planta la sienne avec ses frères sur la montagne de Galaad.'),
(900, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 26, 'OT', 'Laban dit à Jacob : Qu''as-tu fait, que tu as volé mon cœur et emmené mes filles comme des captives de l''épée ?'),
(901, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 27, 'OT', 'Pourquoi t''es-tu caché pour fuir, et m''as-tu dérobé, et ne me l''as-tu pas déclaré, afin que je te renvoie avec joie et avec cantiques, avec tambourin et avec harpe ?'),
(902, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 28, 'OT', 'Et tu ne m''as pas laissé embrasser mes fils et mes filles ; maintenant tu as agi follement.'),
(903, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 29, 'OT', 'J''ai le pouvoir en ma main de vous faire du mal, mais le Dieu de votre père m''a parlé la nuit dernière, disant : Garde-toi de parler avec Jacob, ni en bien ni en mal.'),
(904, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 30, 'OT', 'Et maintenant, tu es parti, car tu as ardemment désiré la maison de ton père ; pourquoi as-tu volé mes dieux ?'),
(905, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 31, 'OT', 'Jacob répondit et dit à Laban : Car j''ai eu peur, car j''ai dit : De peur que tu ne m''enlèves tes filles d''auprès de moi.'),
(906, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 32, 'OT', 'Celui chez qui tu trouveras tes dieux ne vivra pas ; devant nos frères, reconnais ce qui est avec moi et prends-le pour toi. Or Jacob ne savait pas que Rachel les avait volés.'),
(907, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 33, 'OT', 'Laban entra dans la tente de Jacob, dans la tente de Léa, et dans la tente des deux servantes, et il ne les trouva pas ; puis il sortit de la tente de Léa et entra dans la tente de Rachel.'),
(908, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 34, 'OT', 'Rachel prit les théraphim, les mit dans les béliers du chameau, et s''assit dessus ; Laban fouilla toute la tente, et ne les trouva pas.'),
(909, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 35, 'OT', 'Elle dit à son père : « Que mon seigneur ne s''irrite pas à tes yeux, car je ne puis me lever devant toi, parce que le chemin des femmes est sur moi. » Il chercha, mais ne trouva pas les théraphim.'),
(910, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 36, 'OT', 'La colère de Jacob s''enflamma, et il querella Laban. Jacob prit la parole et dit à Laban : « Quelle est ma transgression, quel est mon péché, que tu m''aies poursuivi avec tant d''ardeur ? »'),
(911, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 37, 'OT', 'Car tu as fouillé tous mes ustensiles ; qu''as-tu trouvé de tous les ustensiles de ta maison ? Mets-le ici devant mes frères et tes frères, et qu''ils jugent entre nous deux.'),
(912, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 38, 'OT', 'Voici vingt ans que je suis avec toi : tes brebis et tes chèvres n''ont pas avorté, et je n''ai pas mangé les béliers de ton troupeau.'),
(913, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 39, 'OT', 'Je n''ai point apporté de bête déchirée vers toi ; moi-même je la compensais ; de ma main tu la réclamais, que ce fût volé de jour ou volé de nuit.'),
(914, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 40, 'OT', 'J''étais le jour consumé par la chaleur brûlante, et la glace la nuit, et mon sommeil s''enfuyait de mes yeux.'),
(915, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 41, 'OT', 'Voici vingt ans que j''ai passés dans ta maison : je t''ai servi quatorze ans pour tes deux filles, et six ans pour tes brebis, et tu as changé mon salaire dix fois.'),
(916, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 42, 'OT', 'Si le Dieu de mon père, le Dieu d''Abraham, et la frayeur d''Isaac n''avaient pas été pour moi, certes maintenant tu m''aurais renvoyé à vide ; mon affliction et le labeur de mes mains, Dieu les a vus, et il a prononcé le jugement hier.'),
(917, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 43, 'OT', 'Laban répondit et dit à Jacob : Les filles sont mes filles, et les fils sont mes fils, et les brebis sont mes brebis, et tout ce que tu vois est à moi ; et quant à mes filles, que puis-je faire aujourd''hui pour celles-ci, ou pour leurs fils qu''elles ont enfantés ?'),
(918, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 44, 'OT', 'Et maintenant, viens, faisons une alliance, moi et toi, et qu''elle serve de témoin entre moi et toi.'),
(919, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 45, 'OT', 'Jacob prit une pierre et la dressa comme monument.'),
(920, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 46, 'OT', 'Jacob dit à ses frères : « Ramassez des pierres. » Et ils prirent des pierres et firent un monceau, et ils mangèrent là sur le monceau.'),
(921, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 47, 'OT', 'Laban l''appela Jegar-Sahadutha, et Jacob l''appela Galed.'),
(922, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 48, 'OT', 'Laban dit : « Ce monceau est témoin entre moi et toi aujourd''hui. » C''est pourquoi on l''appela du nom de Galed.'),
(923, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 49, 'OT', 'Et Mitspa, dont il dit : Que l''Éternel veille entre moi et toi, quand nous nous serons cachés, un homme de son ami.'),
(924, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 50, 'OT', 'Si tu affliges mes filles, et si tu prends des femmes en plus de mes filles, il n''y a aucun homme avec nous ; vois, Dieu est témoin entre moi et toi.'),
(925, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 51, 'OT', 'Laban dit à Jacob : Voici ce monceau, et voici le monument que j''ai dressé entre moi et toi.'),
(926, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 52, 'OT', 'Ce monceau est témoin, et ce monument est précepte, que je ne passerai pas vers toi ce monceau, et que tu ne passeras pas vers moi ce monceau ni ce monument pour le mal.'),
(927, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 53, 'OT', 'Le Dieu d''Abraham et le Dieu de Nachor jugeront entre nous, le Dieu de leur père. Et Jacob jura par la frayeur de son père Isaac.'),
(928, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 54, 'OT', 'Jacob offrit un sacrifice sur la montagne, et il appela ses frères à manger du pain ; ils mangèrent du pain et passèrent la nuit sur la montagne.'),
(929, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 31, 55, 'OT', 'Laban se leva de bon matin, embrassa ses fils et ses filles, et les bénit ; puis il partit, et Laban retourna en son lieu.'),
(930, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 1, 'OT', 'Jacob poursuivit son chemin, et des anges de Dieu le rencontrèrent.'),
(931, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 2, 'OT', 'Jacob dit, quand il les vit : C''est ici le camp de Dieu ; et il appela le nom de ce lieu Mahanaïm.'),
(932, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 3, 'OT', 'Jacob envoya des messagers devant lui, vers Ésaü son frère, à la terre de Séir, au champ d''Édom.'),
(933, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 4, 'OT', 'Il leur donna cet ordre, en disant : « Ainsi vous parlerez à mon seigneur Ésaü : Ainsi parle ton serviteur Jacob : J''ai séjourné chez Laban, et j''y suis resté jusqu''à présent. »'),
(934, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 5, 'OT', 'J''ai des bœufs et des ânes, des brebis, des serviteurs et des servantes, et j''ai envoyé le dire à mon seigneur, pour trouver grâce à tes yeux.'),
(935, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 6, 'OT', 'Les messagers revinrent vers Jacob, en disant : « Nous sommes allés vers ton frère Ésaü, et voici qu''il vient à ta rencontre, avec quatre cents hommes avec lui. »'),
(936, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 7, 'OT', 'Jacob eut très peur, et il fut angoissé ; il partagea le peuple qui était avec lui, ainsi que les brebis, les bœufs et les chameaux, en deux camps.'),
(937, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 8, 'OT', 'Il dit : Si Ésaü vient contre l''un des camps et le frappe, le camp qui restera sera pour les réchappés.'),
(938, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 9, 'OT', 'Jacob dit : Dieu de mon père Abraham, et Dieu de mon père Isaac, l''Éternel qui m''a dit : Retourne à ta terre et à ta naissance, et je te ferai du bien.'),
(939, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 10, 'OT', 'Je suis trop petit pour toutes les bontés et pour toute la vérité que tu as faites à ton serviteur ; car avec mon bâton j''ai passé ce Jourdain, et maintenant je suis devenu deux camps.'),
(940, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 11, 'OT', 'Délivre-moi, je te prie, de la main de mon frère, de la main d''Ésaü, car je le crains, de peur qu''il ne vienne et ne me frappe, la mère avec les fils.'),
(941, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 12, 'OT', 'Et toi, tu as dit : Je te ferai du bien certainement, et je mettrai ta postérité comme le sable de la mer, qui ne peut se compter à cause de sa multitude.'),
(942, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 13, 'OT', 'Il passa là la nuit, cette nuit-là, et il prit de ce qui lui venait en main une offrande pour Ésaü, son frère.'),
(943, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 14, 'OT', 'Deux cents chèvres et vingt boucs, deux cents brebis et vingt béliers.'),
(944, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 15, 'OT', 'Trente chameaux allaitants avec leurs fils, quarante vaches et dix taureaux, vingt ânesses et dix ânons.'),
(945, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 16, 'OT', 'Il les remit en main de ses serviteurs, chaque troupeau à part, et dit à ses serviteurs : Passez devant moi, et mettez un espace de délivrance entre troupeau et troupeau.'),
(946, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 17, 'OT', 'Il commanda au premier, disant : Quand Ésaü, mon frère, te rencontrera et te demandera, disant : À qui es-tu, et où vas-tu, et à qui appartiennent ceux qui sont devant toi ?'),
(947, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 18, 'OT', 'Tu diras à ton serviteur Jacob : C''est une offrande envoyée à mon seigneur Ésaü, et voici, lui aussi est derrière nous.'),
(948, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 19, 'OT', 'Il commanda aussi au second, et aussi au troisième, et aussi à tous ceux qui suivaient les troupeaux, en disant : Selon cette parole vous parlerez à Ésaü, quand vous le rencontrerez.'),
(949, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 20, 'OT', 'Et vous direz aussi : Voici, ton serviteur Jacob est derrière nous ; car il a dit : J''apaiserai sa face par l''offrande qui va devant moi, et après cela je verrai sa face ; peut-être relèvera-t-il ma face.'),
(950, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 21, 'OT', 'L''offrande passa devant sa face, et il passa cette nuit-là dans le camp.'),
(951, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 22, 'OT', 'Il se leva cette nuit-là, prit ses deux femmes, ses deux servantes et ses onze enfants, et traversa le passage du Jabbok.'),
(952, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 23, 'OT', 'Il les prit, les fit passer le torrent, et fit passer tout ce qui lui appartenait.'),
(953, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 24, 'OT', 'Jacob demeura seul, et un homme lutta avec lui jusqu''à la montée de l''aurore.'),
(954, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 25, 'OT', 'Il vit qu''il ne pouvait pas le vaincre, et il toucha la main du côté de sa hanche ; et la main du côté de la hanche de Jacob fut déboîtée pendant qu''il luttait avec lui.'),
(955, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 26, 'OT', 'Il dit : « Laisse-moi aller, car l''aurore s''est levée. » Mais il répondit : « Je ne te laisserai point aller, si tu ne me bénis pas. »'),
(956, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 27, 'OT', 'Il lui dit : « Quel est ton nom ? » Et il répondit : « Jacob. »'),
(957, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 28, 'OT', 'On ne dira plus ton nom Jacob, mais Israël ; car tu as lutté avec Dieu et avec des hommes, et tu as vaincu.'),
(958, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 29, 'OT', 'Jacob demanda et dit : « De grâce, déclare-moi ton nom. » Et il dit : « Pourquoi demandes-tu mon nom ? » Et il le bénit là.'),
(959, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 30, 'OT', 'Jacob donna à ce lieu le nom de Penuel, car j''ai vu Dieu face à face, et mon âme a été délivrée.'),
(960, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 31, 'OT', 'Le soleil se leva pour lui lorsqu''il passa Penuel, et il boitait sur son côté.'),
(961, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 32, 32, 'OT', 'C''est pourquoi les fils d''Israël ne mangent pas le nerf du tendon qui est sur la main du côté, jusqu''à ce jour, car il a touché la main du côté de Jacob dans le nerf du tendon.'),
(962, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 1, 'OT', 'Jacob leva les yeux et vit, et voici qu''Ésaü arrivait, et avec lui quatre cents hommes ; et il partagea les enfants entre Léa et Rachel, et entre les deux servantes.'),
(963, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 2, 'OT', 'Il plaça les servantes et leurs enfants en premier, et Léa et ses enfants en dernier, et Rachel et Joseph en dernier.'),
(964, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 3, 'OT', 'Et lui passa devant leur face, et se prosterna en terre sept fois, jusqu''à ce qu''il approchât de son frère.'),
(965, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 4, 'OT', 'Ésaü courut à sa rencontre, l''embrassa, se jeta à son cou et le baisa, et ils pleurèrent.'),
(966, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 5, 'OT', 'Il leva les yeux et vit les femmes et les enfants, et dit : « Qui sont ceux-ci pour toi ? » Et il dit : « Les enfants que Dieu a accordés à ton serviteur. »'),
(967, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 6, 'OT', 'Les servantes s''approchèrent, elles et leurs enfants, et se prosternèrent.'),
(968, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 7, 'OT', 'Léa s''approcha aussi avec ses enfants, et ils se prosternèrent ; ensuite Joseph et Rachel s''approchèrent, et ils se prosternèrent.'),
(969, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 8, 'OT', 'Il dit : À qui est tout ce camp que j''ai rencontré ? Et il dit : Pour trouver grâce aux yeux de mon seigneur.'),
(970, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 9, 'OT', 'Ésaü dit : « J''ai en abondance, mon frère ; que ce qui est à toi reste à toi. »'),
(971, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 10, 'OT', 'Jacob dit : Non, je t''en prie ; si j''ai trouvé grâce à tes yeux, reçois mon offrande de ma main ; car c''est pour cela que j''ai vu ta face comme on voit la face de Dieu, et tu m''as agréé.'),
(972, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 11, 'OT', 'Prends, je te prie, ma bénédiction qui t''a été apportée, car Dieu m''a fait grâce, et parce que j''ai de tout ; et il le pressa, et il la prit.'),
(973, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 12, 'OT', 'Il dit : Partons et marchons, et j''irai devant toi.'),
(974, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 13, 'OT', 'Il lui dit : Mon seigneur sait que les enfants sont délicats, et que les brebis et les bœufs qui allaitent sont sur moi ; et si on les pousse un seul jour, toutes les brebis mourront.'),
(975, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 14, 'OT', 'Que mon seigneur passe, je te prie, devant la face de son serviteur ; et moi, je cheminerai lentement, au pas de l''ouvrage qui est devant ma face et au pas des enfants, jusqu''à ce que j''arrive vers mon seigneur à Séir.'),
(976, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 15, 'OT', 'Ésaü dit : « Je vais laisser avec toi une partie du peuple qui est avec moi. » Et il répondit : « Pourquoi cela ? Que je trouve grâce à tes yeux, mon seigneur. »'),
(977, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 16, 'OT', 'Ce jour-là, Ésaü retourna par son chemin vers Séir.'),
(978, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 17, 'OT', 'Jacob partit pour Succoth, et il se bâtit une maison, et pour ses troupeaux il fit des tabernacles ; c''est pourquoi il appela le nom de ce lieu Succoth.'),
(979, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 18, 'OT', 'Jacob arriva sain et sauf à la ville de Sichem, qui est dans la terre de Canaan, lorsqu''il venait de Padan-Aram, et il campa devant la face de la ville.'),
(980, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 19, 'OT', 'Il acheta la portion du champ où il avait dressé sa tente, de la main des fils de Hamor, père de Sichem, pour cent kesitas.'),
(981, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 33, 20, 'OT', 'Il dressa là un autel et l''appela : Dieu, le Dieu d''Israël.'),
(982, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 1, 'OT', 'Dina, fille de Léa, qu''elle avait enfantée à Jacob, sortit pour voir les filles de la terre.'),
(983, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 2, 'OT', 'Sichem, fils de Hamor, le Hévien, prince de la terre, la vit, la prit, coucha avec elle et l''humilia.'),
(984, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 3, 'OT', 'Son âme s''attacha à Dina, fille de Jacob, et il aima la jeune fille, et il parla au cœur de la jeune fille.'),
(985, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 4, 'OT', 'Sichem dit à Hamor, son père : « Prends pour moi cette jeune fille pour femme. »'),
(986, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 5, 'OT', 'Jacob apprit que l''on avait souillé Dina, sa fille, et ses fils étaient avec ses troupeaux dans les champs ; Jacob garda le silence jusqu''à leur retour.'),
(987, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 6, 'OT', 'Hamor, père de Sichem, sortit vers Jacob pour lui parler.'),
(988, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 7, 'OT', 'Les fils de Jacob revinrent des champs lorsqu''ils l''apprirent, et ces hommes furent affligés, et leur colère s''enflamma grandement, parce qu''une infamie avait été commise en Israël, en couchant avec la fille de Jacob, et cela ne doit pas se faire.'),
(989, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 8, 'OT', 'Hamor leur parla en disant : « Sichem, mon fils, a son âme attachée à votre fille ; donnez-la-lui, je vous prie, pour femme. »'),
(990, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 9, 'OT', 'Faites alliance avec nous par mariage ; donnez-nous vos filles, et prenez nos filles pour vous.'),
(991, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 10, 'OT', 'Habitez avec nous ; la terre sera devant votre face ; demeurez-y, trafiquez-y, et prenez-y possession.'),
(992, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 11, 'OT', 'Sichem dit à son père et à ses frères : « Que je trouve grâce à vos yeux, et tout ce que vous me direz, je le donnerai. »'),
(993, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 12, 'OT', 'Accroissez beaucoup sur moi le dot et le don, et je donnerai selon ce que vous me direz ; et donnez-moi la jeune fille pour femme.'),
(994, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 13, 'OT', 'Les fils de Jacob répondirent à Sichem et à Hamor, son père, avec fraude, et parlèrent, parce qu''il avait souillé Dina, leur sœur.'),
(995, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 14, 'OT', 'Ils leur dirent : Nous ne pouvons pas faire cette parole, donner notre sœur à un homme qui a un prépuce, car c''est un opprobre pour nous.'),
(996, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 15, 'OT', 'C''est seulement à cette condition que nous vous agréerons : si vous devenez comme nous, en faisant circoncire tout mâle parmi vous.'),
(997, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 16, 'OT', 'Nous vous donnerons nos filles, et nous prendrons vos filles pour nous, et nous habiterons avec vous, et nous serons un seul peuple.'),
(998, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 17, 'OT', 'Mais si vous ne nous écoutez pas pour vous circoncire, nous prendrons notre fille et nous nous en irons.'),
(999, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 18, 'OT', 'Leurs paroles furent agréables aux yeux de Hamor et aux yeux de Sichem, fils de Hamor.'),
(1000, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 19, 'OT', 'Et le jeune homme ne tarda point à faire cette parole, car il prenait plaisir en la fille de Jacob ; et il était honoré plus que tout ce qui était dans la maison de son père.'),
(1001, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 20, 'OT', 'Hamor et Sichem, son fils, vinrent à la porte de leur ville, et ils parlèrent aux hommes de leur ville, en disant :'),
(1002, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 21, 'OT', 'Ces hommes sont paisibles avec nous ; qu''ils habitent dans la terre et qu''ils y fassent du commerce, et la terre, voici, elle est large de mains devant leur face ; nous prendrons leurs filles pour nous comme femmes, et nous donnerons nos filles à eux.'),
(1003, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 22, 'OT', 'C''est seulement à cette condition que ces hommes consentiront à habiter avec nous, pour devenir un seul peuple : que tout mâle parmi nous soit circoncis, comme ils sont circoncis.'),
(1004, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 23, 'OT', 'Leurs troupeaux, leurs biens et tout leur bétail, ne sont-ils pas à nous ? Seulement, consentons-leur, et ils habiteront avec nous.'),
(1005, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 24, 'OT', 'Tous ceux qui sortaient par la porte de sa ville écoutèrent Hamor et Sichem, son fils, et tout mâle fut circoncis, tous ceux qui sortaient par la porte de sa ville.'),
(1006, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 25, 'OT', 'Le troisième jour, comme ils souffraient, les deux fils de Jacob, Siméon et Lévi, frères de Dina, prirent chacun son épée, vinrent contre la ville en sécurité, et tuèrent tout mâle.'),
(1007, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 26, 'OT', 'Ils tuèrent Hamor et Sichem, son fils, au fil de l''épée ; ils prirent Dina de la maison de Sichem, et ils sortirent.'),
(1008, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 27, 'OT', 'Les fils de Jacob vinrent sur les blessés et pillèrent la ville où l''on avait déshonoré leur sœur.'),
(1009, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 28, 'OT', 'Ils prirent leurs brebis, leurs bœufs et leurs ânes, ainsi que ce qui était dans la ville et ce qui était dans le champ.'),
(1010, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 29, 'OT', 'Et toute leur force, et tous leurs petits enfants, et leurs femmes, ils les prirent et les pillèrent, et tout ce qui était dans la maison.'),
(1011, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 30, 'OT', 'Jacob dit à Siméon et à Lévi : « Vous m''avez troublé, en me rendant odieux aux habitants de la terre, au Cananéen et au Phérézien ; et moi, je suis des hommes de petit nombre, et ils s''assembleront contre moi et me frapperont, et je serai détruit, moi et ma maison. »'),
(1012, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 34, 31, 'OT', 'Ils répondirent : Traitera-t-il notre sœur comme une prostituée ?'),
(1013, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 1, 'OT', 'Dieu dit à Jacob : Lève-toi, monte à Béthel, et demeure là ; fais-y un autel au Dieu qui t''est apparu lorsque tu fuyais devant la face d''Ésaü, ton frère.'),
(1014, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 2, 'OT', 'Jacob dit à sa maison et à tous ceux qui étaient avec lui : Ôtez les dieux étrangers qui sont au milieu de vous, purifiez-vous, et changez vos vêtements.'),
(1015, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 3, 'OT', 'Et levons-nous, et montons à Béthel, et je ferai là un autel à Dieu, qui m''a répondu au jour de ma détresse, et qui a été avec moi dans le chemin où j''ai marché.'),
(1016, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 4, 'OT', 'Ils remirent à Jacob tous les dieux étrangers qui étaient dans leurs mains, et les anneaux qui étaient à leurs oreilles ; et Jacob les enfouit sous le térébinthe qui était près de Sichem.'),
(1017, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 5, 'OT', 'Ils partirent, et la terreur de Dieu fut sur les villes qui étaient à leurs alentours, et ils ne poursuivirent pas les fils de Jacob.'),
(1018, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 6, 'OT', 'Jacob arriva à Luz, qui est dans la terre de Canaan, c''est Béthel, lui et tout le peuple qui était avec lui.'),
(1019, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 7, 'OT', 'Il bâtit là un autel, et il appela ce lieu Dieu de Béthel, car c''est là que Dieu s''était révélé à lui lorsqu''il fuyait devant la face de son frère.'),
(1020, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 8, 'OT', 'Débora, la nourrice de Rebecca, mourut, et elle fut enterrée sous Béthel, sous le chêne ; et il appela son nom Allon-Bacuth.'),
(1021, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 9, 'OT', 'Dieu apparut encore à Jacob, à son retour de Padan-Aram, et il le bénit.'),
(1022, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 10, 'OT', 'Dieu lui dit : Ton nom est Jacob ; on ne t''appellera plus Jacob, mais Israël sera ton nom. Et il appela son nom Israël.'),
(1023, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 11, 'OT', 'Dieu lui dit : « Je suis le Dieu Tout-Puissant. Sois fécond et multiplie-toi ; une nation et une assemblée de nations naîtront de toi, et des rois sortiront de tes reins. »'),
(1024, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 12, 'OT', 'Vous et votre postérité après vous, je vous donnerai la terre que j''ai donnée à Abraham et à Isaac, et je la donnerai à votre postérité après vous, cette terre.'),
(1025, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 13, 'OT', 'Et Dieu s''éleva au-dessus de lui, au lieu où il lui avait parlé.'),
(1026, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 14, 'OT', 'Jacob dressa un monument dans le lieu où il lui avait parlé, un monument de pierre, et il y répandit une libation, et il y versa de l''huile.'),
(1027, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 15, 'OT', 'Jacob appela le nom du lieu où Dieu lui avait parlé : Béthel.'),
(1028, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 16, 'OT', 'Ils partirent de Béthel, et il y avait encore une petite distance de terre pour arriver à Éphrata, lorsque Rachel enfanta, et elle eut un accouchement difficile.'),
(1029, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 17, 'OT', 'Et il arriva que, comme elle peinait à enfanter, la sage-femme lui dit : Ne crains point, car celui-ci aussi est pour toi un fils.'),
(1030, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 18, 'OT', 'Et il arriva, comme son âme s''en allait, car elle mourait, qu''elle appela son nom Ben-Oni ; mais son père l''appela Benjamin.'),
(1031, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 19, 'OT', 'Rachel mourut, et fut enterrée sur le chemin d''Éphrata, qui est Bethléhem.'),
(1032, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 20, 'OT', 'Jacob dressa un monument sur sa sépulture ; c''est le monument de la sépulture de Rachel jusqu''à ce jour.'),
(1033, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 21, 'OT', 'Israël partit, et dressa sa tente au-delà de Migdal-Éder.'),
(1034, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 22, 'OT', 'Il arriva, pendant qu''Israël habitait dans cette terre, que Ruben alla et coucha avec Bilha, la concubine de son père, et Israël l''apprit. Et les fils de Jacob étaient au nombre de douze.'),
(1035, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 23, 'OT', 'Les fils de Léa, premier-né de Jacob : Ruben, Siméon, Lévi, Juda, Issacar et Zabulon.'),
(1036, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 24, 'OT', 'Les fils de Rachel : Joseph et Benjamin.'),
(1037, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 25, 'OT', 'Les fils de Bilha, servante de Rachel : Dan et Nephthali.'),
(1038, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 26, 'OT', 'Les fils de Zilpa, servante de Léa, étaient Gad et Aser ; ce sont les fils de Jacob qui lui furent nés à Padan-Aram.'),
(1039, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 27, 'OT', 'Jacob vint vers Isaac, son père, à Mamré, à Kirjath-Arba, qui est Hébron, où Abraham et Isaac avaient séjourné.'),
(1040, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 28, 'OT', 'Les jours d''Isaac furent de cent quatre-vingts années.'),
(1041, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 35, 29, 'OT', 'Isaac expira et mourut, et fut recueilli auprès de son peuple, vieux et rassasié de jours ; et Ésaü et Jacob, ses fils, l''enterrèrent.'),
(1042, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 1, 'OT', 'Voici les générations d''Ésaü, qui est Édom.'),
(1043, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 2, 'OT', 'Ésaü prit ses femmes parmi les filles de Canaan : Ada, fille d''Élon le Héthien, et Oholibama, fille d''Ana, fille de Tsibeon le Hévien.'),
(1044, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 3, 'OT', 'et Basmath, fille d''Ismaël, sœur de Nebajoth.'),
(1045, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 4, 'OT', 'Ada enfanta à Ésaü Éliphaz, et Basmath enfanta Réuel.'),
(1046, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 5, 'OT', 'Oholibama enfanta Jéusch, Jaelam et Koré ; ce sont là les fils d''Ésaü qui lui naquirent dans la terre de Canaan.'),
(1047, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 6, 'OT', 'Ésaü prit ses femmes, ses fils, ses filles, toutes les âmes de sa maison, ses troupeaux, tout son bétail, et tous ses biens qu''il avait acquis dans la terre de Canaan, et il alla vers une terre, loin de la face de Jacob, son frère.'),
(1048, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 7, 'OT', 'Car leurs biens étaient si nombreux qu''ils ne pouvaient demeurer ensemble, et la terre de leur séjour ne pouvait les porter à cause de la face de leurs troupeaux.'),
(1049, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 8, 'OT', 'Ésaü habita dans la montagne de Séir ; Ésaü, c''est Édom.'),
(1050, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 9, 'OT', 'Voici les générations d''Ésaü, père d''Édom, dans la montagne de Séir.'),
(1051, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 10, 'OT', 'Voici les noms des fils d''Ésaü : Éliphaz, fils d''Ada, femme d''Ésaü ; Réuel, fils de Basmath, femme d''Ésaü.'),
(1052, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 11, 'OT', 'Les fils d''Éliphaz furent Théman, Omar, Tsepho, Gaetham et Kenaz.'),
(1053, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 12, 'OT', 'Thimna était une concubine d''Éliphaz, fils d''Ésaü, et elle enfanta à Éliphaz Amalek ; ce sont les fils d''Ada, femme d''Ésaü.'),
(1054, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 13, 'OT', 'Voici les fils de Réuel : Nachath, Zérach, Schamma et Mizza ; ce furent là les fils de Basmath, femme d''Ésaü.'),
(1055, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 14, 'OT', 'Voici les fils d''Oholibama, fille d''Ana, fille de Tsibeon, femme d''Ésaü ; elle enfanta à Ésaü Jéusch, Jaelam et Koré.'),
(1056, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 15, 'OT', 'Voici les chefs des fils d''Ésaü : les fils d''Éliphaz, premier-né d''Ésaü : le chef Théman, le chef Omar, le chef Tsepho, le chef Kenaz.'),
(1057, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 16, 'OT', 'Chef Koré, chef Gaetham, chef Amalek ; ce sont là les chefs d''Éliphaz dans la terre d''Édom ; ce sont là les fils d''Ada.'),
(1058, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 17, 'OT', 'Et voici les fils de Réuel, fils d''Ésaü : le chef Nachath, le chef Zérach, le chef Schamma, le chef Mizza ; ce sont là les chefs de Réuel dans la terre d''Édom ; ce sont là les fils de Basmath, femme d''Ésaü.'),
(1059, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 18, 'OT', 'Voici les fils d''Oholibama, femme d''Ésaü : le chef Jeusch, le chef Jaelam, le chef Koré. Ce sont les chefs issus d''Oholibama, fille d''Ana, femme d''Ésaü.'),
(1060, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 19, 'OT', 'Voici les fils d''Ésaü, et voici leurs chefs ; c''est lui, Édom.'),
(1061, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 20, 'OT', 'Voici les fils de Séir, le Horiens, habitants de la terre : Lothan, Schobal, Tsibeon et Ana.'),
(1062, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 21, 'OT', 'Dischon, Étser et Dischan : ce sont les chefs des Horiens, les fils de Séir, dans la terre d''Édom.'),
(1063, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 22, 'OT', 'Les fils de Lothan furent Hori et Hémam, et la sœur de Lothan fut Thimna.'),
(1064, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 23, 'OT', 'Voici les fils de Schobal : Alvan, Manahath, Ébal, Schepho et Onam.'),
(1065, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 24, 'OT', 'Voici les fils de Tsibeon : Ajja et Ana. C''est lui, Ana, qui trouva les mulets dans le désert, tandis qu''il faisait paître les ânes de Tsibeon, son père.'),
(1066, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 25, 'OT', 'Voici les fils d''Ana : Dischon, et Oholibama, fille d''Ana.'),
(1067, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 26, 'OT', 'Voici les fils de Dischan : Hemdan, Eschban, Jithran et Keran.'),
(1068, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 27, 'OT', 'Voici les fils d''Étser : Bilhan, Zaavan et Akan.'),
(1069, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 28, 'OT', 'Voici les fils de Dischan : Uts et Aran.'),
(1070, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 29, 'OT', 'Voici les chefs des Horiens : le chef Lothan, le chef Schobal, le chef Tsibeon, le chef Ana.'),
(1071, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 30, 'OT', 'Chef Dischon, chef Étser, chef Dischan : tels furent les chefs des Hori, selon leurs chefs, dans la terre de Séir.'),
(1072, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 31, 'OT', 'Voici les rois qui régnèrent dans la terre d''Édom, avant qu''un roi régnât sur les fils d''Israël, en face de leur règne.'),
(1073, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 32, 'OT', 'Béla, fils de Beor, régna en Édom, et le nom de sa ville était Dinhaba.'),
(1074, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 33, 'OT', 'Béla mourut, et Jobab, fils de Zérach, de Botsra, régna à sa place.'),
(1075, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 34, 'OT', 'Jobab mourut, et Huscham, de la terre des Thémanites, régna à sa place.'),
(1076, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 35, 'OT', 'Huscham mourut, et Hadad, fils de Bedad, qui frappa Madian dans le champ de Moab, régna à sa place ; et le nom de sa ville était Avith.'),
(1077, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 36, 'OT', 'Hadad mourut, et Samla, de Masréka, régna à sa place.'),
(1078, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 37, 'OT', 'Samla mourut, et Saül régna à sa place, de Rehoboth du fleuve.'),
(1079, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 38, 'OT', 'Saül mourut, et Baal-Hanan, fils d''Acbor, régna à sa place.'),
(1080, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 39, 'OT', 'Baal-Hanan, fils d''Acbor, mourut, et Hadar régna à sa place ; le nom de sa ville était Pau, et le nom de sa femme était Mehétabeel, fille de Mathred, fille de Mézahab.'),
(1081, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 40, 'OT', 'Voici les noms des chefs d''Ésaü selon leurs familles, selon leurs lieux, par leurs noms : le chef Thimna, le chef Alva, le chef Jetheth.'),
(1082, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 41, 'OT', 'Chef d''Oholibama, chef d''Éla, chef de Pinon.'),
(1083, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 42, 'OT', 'Chef de Kenaz, chef de Théman, chef de Mibtsar.'),
(1084, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 36, 43, 'OT', 'Chef Magdiel, chef Iram : tels sont les chefs d''Édom selon leurs habitations dans la terre de leur possession. C''est Ésaü, père d''Édom.'),
(1085, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 1, 'OT', 'Jacob habita dans la terre du séjour de son père, dans la terre de Canaan.'),
(1086, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 2, 'OT', 'Voici les générations de Jacob : Joseph, âgé de dix-sept ans, paissait les brebis avec ses frères, et le jeune homme était avec les fils de Bilha et les fils de Zilpa, femmes de son père ; et Joseph rapporta à leur père leurs mauvais propos.'),
(1087, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 3, 'OT', 'Israël aimait Joseph plus que tous ses fils, parce qu''il était pour lui un fils de sa vieillesse, et il lui fit une tunique de couleurs.'),
(1088, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 4, 'OT', 'Ses frères virent que leur père l''aimait plus que tous ses frères, et ils le haïrent, et ils ne pouvaient lui parler en paix.'),
(1089, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 5, 'OT', 'Joseph fit un rêve et le raconta à ses frères, et ils le haïrent encore davantage.'),
(1090, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 6, 'OT', 'Il leur dit : Écoutez donc ce songe que j''ai rêvé.'),
(1091, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 7, 'OT', 'Voici, nous étions en train de lier des gerbes au milieu du champ, et voici, ma gerbe se leva et se tint debout, et voici, vos gerbes l''entourèrent et se prosternèrent devant ma gerbe.'),
(1092, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 8, 'OT', 'Ses frères lui dirent : « Régneras-tu donc sur nous, ou domineras-tu sur nous ? » Et ils le haïrent encore davantage à cause de ses rêves et de ses paroles.'),
(1093, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 9, 'OT', 'Il rêva encore un autre rêve, et il le raconta à ses frères, et dit : Voici, j''ai rêvé encore un rêve, et voici, le soleil et la lune et onze étoiles se prosternaient devant moi.'),
(1094, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 10, 'OT', 'Il le raconta à son père et à ses frères, et son père le réprimanda et lui dit : « Quel est ce rêve que tu as rêvé ? Moi, ta mère et tes frères, devrions-nous venir nous prosterner devant toi jusqu''à terre ? »'),
(1095, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 11, 'OT', 'Ses frères furent jaloux de lui, et son père garda la parole.'),
(1096, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 12, 'OT', 'Ses frères allèrent paître les brebis de leur père à Sichem.'),
(1097, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 13, 'OT', 'Israël dit à Joseph : « Tes frères ne font-ils pas paître le troupeau à Sichem ? Viens, et je t''enverrai vers eux. » Et il lui répondit : « Me voici. »'),
(1098, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 14, 'OT', 'Il lui dit : « Va donc voir la paix de tes frères et la paix des brebis, et rapporte-moi une parole. » Il l''envoya de la vallée d''Hébron, et il arriva à Sichem.'),
(1099, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 15, 'OT', 'Un homme le trouva, et voici qu''il errait dans le champ ; et cet homme lui demanda, en disant : Que cherches-tu ?'),
(1100, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 16, 'OT', 'Il dit : Je cherche mes frères ; dis-moi donc, je te prie, où ils font paître le troupeau.'),
(1101, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 17, 'OT', 'L''homme dit : « Ils sont partis d''ici, car je les ai entendus dire : Allons à Dothan. » Alors Joseph alla après ses frères et les trouva à Dothan.'),
(1102, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 18, 'OT', 'Ils le virent de loin, et avant qu''il s''approchât d''eux, ils complotèrent contre lui pour le faire mourir.'),
(1103, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 19, 'OT', 'Ils se dirent l''un à l''autre, chaque homme à son frère : Voici, le maître des rêves arrive.'),
(1104, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 20, 'OT', 'Venez donc, tuons-le et jetons-le dans l''une des citernes, et nous dirons : « Une bête féroce l''a dévoré », et nous verrons ce que deviendront ses rêves.'),
(1105, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 21, 'OT', 'Ruben entendit et le délivra de leur main, et dit : Ne frappons pas son âme.'),
(1106, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 22, 'OT', 'Ruben leur dit : Ne versez pas de sang ; jetez-le dans cette citerne qui est dans le désert, et ne portez pas la main sur lui, afin de le délivrer de leurs mains, pour le ramener à son père.'),
(1107, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 23, 'OT', 'Il arriva que, lorsque Joseph vint vers ses frères, ils dépouillèrent Joseph de sa tunique, la tunique de couleurs qui était sur lui.'),
(1108, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 24, 'OT', 'Ils le prirent et le jetèrent dans la citerne ; or la citerne était vide, il n''y avait point d''eaux en elle.'),
(1109, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 25, 'OT', 'Ils s''assirent pour manger du pain ; ils levèrent les yeux et virent, et voici qu''une caravane d''Ismaélites venait de Galaad, et leurs chameaux portaient des aromates, du baume et de la myrrhe, allant les faire descendre en Égypte.'),
(1110, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 26, 'OT', 'Juda dit à ses frères : Quel gain y a-t-il à tuer notre frère et à couvrir son sang ?'),
(1111, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 27, 'OT', 'Venez, et vendons-le aux Ismaélites, et que notre main ne soit pas sur lui, car il est notre frère, notre chair. Et ses frères l''écoutèrent.'),
(1112, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 28, 'OT', 'Des hommes madianites, des marchands, passèrent par là ; ils tirèrent Joseph et le firent remonter de la citerne, puis ils vendirent Joseph aux Ismaélites pour vingt pièces d''argent, et ils amenèrent Joseph en Égypte.'),
(1113, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 29, 'OT', 'Ruben retourna à la citerne, et voici que Joseph n''était pas dans la citerne, et il déchira ses vêtements.'),
(1114, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 30, 'OT', 'Il retourna vers ses frères et dit : L''enfant n''est plus, et moi, où irai-je ?'),
(1115, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 31, 'OT', 'Ils prirent la tunique de Joseph, égorgèrent un bouc de chèvres, et trempèrent la tunique dans le sang.'),
(1116, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 32, 'OT', 'Ils envoyèrent la tunique de couleurs et la firent porter à leur père, et dirent : « Nous avons trouvé ceci ; reconnais, je te prie, si c''est la tunique de ton fils ou non. »'),
(1117, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 33, 'OT', 'Il la reconnut et dit : « La tunique de mon fils ! Une bête féroce l''a dévoré ; Joseph a été mis en pièces. »'),
(1118, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 34, 'OT', 'Jacob déchira ses vêtements, mit un sac sur ses reins, et porta le deuil sur son fils pendant de nombreux jours.'),
(1119, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 35, 'OT', 'Tous ses fils et toutes ses filles se levèrent pour le consoler, mais il refusa de se consoler, et il dit : « Je descendrai vers mon fils, en deuil, au séjour des morts. » Et son père le pleura.'),
(1120, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 37, 36, 'OT', 'Les Madianites le vendirent en Égypte à Potiphar, eunuque de Pharaon, chef des gardes du corps.'),
(1121, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 1, 'OT', 'Il arriva en ce temps-là que Juda descendit d''auprès de ses frères, et il se détourna jusqu''à un homme adullamite, dont le nom était Hira.'),
(1122, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 2, 'OT', 'Juda vit là la fille d''un homme cananéen, dont le nom était Schua ; il la prit et vint vers elle.'),
(1123, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 3, 'OT', 'Elle conçut, enfanta un fils, et il appela son nom Er.'),
(1124, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 4, 'OT', 'Elle conçut encore, enfanta un fils, et lui donna le nom d''Onan.'),
(1125, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 5, 'OT', 'Elle conçut encore, enfanta un fils, et lui donna le nom de Schéla ; elle était à Czib lorsqu''elle l''enfanta.'),
(1126, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 6, 'OT', 'Juda prit une femme pour Er, son premier-né, et son nom était Tamar.'),
(1127, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 7, 'OT', 'Er, premier-né de Juda, fut mauvais aux yeux de l''Éternel, et l''Éternel le fit mourir.'),
(1128, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 8, 'OT', 'Juda dit à Onan : « Va vers la femme de ton frère, accomplis envers elle le devoir de beau-frère, et suscite une postérité pour ton frère. »'),
(1129, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 9, 'OT', 'Onan savait que la postérité ne serait pas à lui, et il arrivait que, lorsqu''il allait vers la femme de son frère, il répandait sur la terre, afin de ne pas donner de postérité à son frère.'),
(1130, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 10, 'OT', 'Ce qui fut mauvais aux yeux de l''Éternel, ce qu''il avait fait, et il le fit mourir, lui aussi.'),
(1131, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 11, 'OT', 'Juda dit à Tamar, sa fiancée : « Reste veuve dans la maison de ton père jusqu''à ce que mon fils Schéla grandisse », car il se disait : « De peur qu''il ne meure, lui aussi, comme ses frères. » Et Tamar s''en alla et demeura dans la maison de son père.'),
(1132, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 12, 'OT', 'Les jours passèrent, et la fille de Schua, femme de Juda, mourut ; puis Juda se consola, et il monta vers ceux qui tondaient ses brebis, lui et Hira, son ami l''Adullamite, à Thimna.'),
(1133, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 13, 'OT', 'On le rapporta à Tamar, en disant : Voici, ton beau-père monte à Thimna pour tondre ses brebis.'),
(1134, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 14, 'OT', 'Elle ôta de dessus elle les vêtements de son veuvage, se couvrit d''un voile, s''enveloppa, et s''assit à l''entrée d''Énaïm, qui est sur le chemin de Thimna ; car elle vit que Schéla était devenu grand, et elle ne lui avait pas été donnée pour femme.'),
(1135, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 15, 'OT', 'Juda la vit et la jugea comme une prostituée, car elle avait couvert son visage.'),
(1136, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 16, 'OT', 'Il se détourna vers elle sur le chemin et dit : « Laisse-moi donc venir à toi », car il ne savait pas que c''était sa fiancée. Et elle dit : « Que me donneras-tu, pour que tu viennes à moi ? »'),
(1137, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 17, 'OT', 'Il dit : « J''enverrai un chevreau de chèvres pris du troupeau de brebis. » Elle répondit : « Si tu donnes un gage jusqu''à ce que tu l''envoies. »'),
(1138, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 18, 'OT', 'Il dit : Quel gage te donnerai-je ? Et elle dit : Ton sceau, ton cordon, et ta tribu qui est dans ta main. Et il les lui donna, et il vint vers elle, et elle conçut de lui.'),
(1139, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 19, 'OT', 'Elle se leva, s''en alla, ôta son voile de dessus elle, et revêtit les vêtements de son veuvage.'),
(1140, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 20, 'OT', 'Juda envoya le chevreau des chèvres par la main de son ami l''Adullamite, pour recevoir le gage de la main de la femme, mais il ne la trouva pas.'),
(1141, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 21, 'OT', 'Il interrogea les hommes de son lieu, disant : Où est la prostituée sacrée qui était à Énaïm sur le chemin ? Et ils dirent : Il n''y a pas eu de prostituée sacrée ici.'),
(1142, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 22, 'OT', 'Il retourna vers Juda et dit : « Je ne l''ai pas trouvée, et même les hommes du lieu ont dit : Il n''y a pas eu de prostituée ici. »'),
(1143, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 23, 'OT', 'Juda dit : « Qu''elle le garde, de peur que nous soyons en mépris. Voici, j''ai envoyé ce chevreau, et toi, tu ne l''as pas trouvée. »'),
(1144, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 24, 'OT', 'Il arriva environ trois mois plus tard, et l''on rapporta à Juda en disant : « Tamar, ta fiancée, s''est prostituée, et voici, elle est enceinte de prostitution. » Et Juda dit : « Faites-la sortir, et qu''elle soit brûlée. »'),
(1145, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 25, 'OT', 'Elle était amenée dehors, et elle envoya dire à son beau-père : « C''est de l''homme à qui appartiennent ces choses que je suis enceinte » ; et elle dit : « Reconnais donc à qui sont ce sceau, ces cordons et cette tribu. »'),
(1146, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 26, 'OT', 'Juda les reconnut, et dit : Elle est plus juste que moi, parce que je ne l''ai pas donnée à Schéla, mon fils. Et il ne la connut plus.'),
(1147, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 27, 'OT', 'Il arriva, au temps où elle enfantait, et voici, il y avait des jumeaux dans son ventre.'),
(1148, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 28, 'OT', 'Et il arriva, comme elle enfantait, qu''il tendit la main ; et la sage-femme prit un fil cramoisi et le lia sur sa main, en disant : Celui-ci est sorti le premier.'),
(1149, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 29, 'OT', 'Et comme il retirait sa main, voici que son frère sortit, et elle dit : Quelle brèche tu as faite sur toi ! Et on appela son nom Pérets.'),
(1150, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 38, 30, 'OT', 'Ensuite sortit son frère, celui qui avait sur sa main le cramoisi, et on appela son nom Zérach.'),
(1151, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 1, 'OT', 'Joseph fut descendu en Égypte, et Potiphar, eunuque de Pharaon, chef des gardes du corps, homme égyptien, l''acheta de la main des Ismaélites qui l''y avaient fait descendre.'),
(1152, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 2, 'OT', 'L''Éternel fut avec Joseph, et il devint un homme qui réussissait, et il était dans la maison de son seigneur l''Égyptien.'),
(1153, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 3, 'OT', 'Son seigneur vit que l''Éternel était avec lui, et que tout ce qu''il faisait, l''Éternel le faisait réussir par sa main.'),
(1154, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 4, 'OT', 'Joseph trouva grâce à ses yeux, et il le servit ; et il le préposa sur sa maison, et tout ce qui lui appartenait, il le mit entre ses mains.'),
(1155, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 5, 'OT', 'Il arriva, depuis qu''il l''eut établi sur sa maison et sur tout ce qui lui appartenait, que l''Éternel bénit la maison de l''Égyptien à cause de Joseph, et la bénédiction de l''Éternel fut sur tout ce qui lui appartenait, dans la maison et dans le champ.'),
(1156, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 6, 'OT', 'Il laissa tout ce qui lui appartenait entre les mains de Joseph, et il ne savait rien avec lui, sinon le pain qu''il mangeait. Et Joseph était beau d''apparence et beau d''aspect.'),
(1157, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 7, 'OT', 'Il arriva après ces paroles que la femme de son seigneur porta ses yeux sur Joseph et dit : Couche avec moi.'),
(1158, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 8, 'OT', 'Il refusa et dit à la femme de son seigneur : Voici, mon seigneur ne sait pas ce qui est dans la maison avec moi, et tout ce qu''il a, il l''a remis en ma main.'),
(1159, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 9, 'OT', 'Il n''est pas plus grand que moi dans cette maison, et il ne m''a rien refusé, si ce n''est toi, parce que tu es sa femme ; comment donc ferais-je ce grand mal et pécherais-je contre Dieu ?'),
(1160, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 10, 'OT', 'Il arriva que, comme elle parlait à Joseph jour après jour, il ne l''écouta pas pour coucher auprès d''elle, pour être avec elle.'),
(1161, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 11, 'OT', 'Il arriva, en ce jour-là, qu''il entra dans la maison pour faire son ouvrage, et il n''y avait aucun homme des hommes de la maison là, dans la maison.'),
(1162, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 12, 'OT', 'Elle le saisit par son vêtement, en disant : « Couche avec moi ! » Mais il laissa son vêtement dans sa main, s''enfuit et sortit dehors.'),
(1163, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 13, 'OT', 'Et il arriva que, lorsqu''elle vit qu''il avait laissé son vêtement dans sa main, il s''enfuit dehors.'),
(1164, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 14, 'OT', 'Elle appela les hommes de sa maison et leur dit : « Voyez, il nous a amené un homme hébreu pour se moquer de nous ; il est venu vers moi pour coucher avec moi, et j''ai crié à voix haute. »'),
(1165, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 15, 'OT', 'Et lorsqu''il entendit que j''avais élevé ma voix et que j''avais crié, il abandonna son vêtement auprès de moi, puis il s''enfuit et sortit dehors.'),
(1166, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 16, 'OT', 'Elle déposa son vêtement auprès d''elle, jusqu''à ce que son seigneur vînt à sa maison.'),
(1167, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 17, 'OT', 'Elle lui parla selon ces paroles, en disant : Le serviteur hébreu que tu nous as amené est venu vers moi pour se moquer de moi.'),
(1168, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 18, 'OT', 'Et il arriva que, lorsque j''élevai ma voix et que je criai, il laissa son vêtement auprès de moi et s''enfuit dehors.'),
(1169, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 19, 'OT', 'Lorsque son seigneur entendit les paroles de sa femme, qu''elle lui avait dites en disant : « C''est selon ces paroles que ton serviteur m''a fait », sa colère s''enflamma.'),
(1170, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 20, 'OT', 'Le seigneur de Joseph le prit et le mit dans la maison de la prison, lieu où les prisonniers du roi étaient détenus, et il fut là dans la maison de la prison.'),
(1171, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 21, 'OT', 'L''Éternel fut avec Joseph, et il étendit sur lui sa bonté, et il lui donna sa grâce aux yeux du chef de la maison de la prison.'),
(1172, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 22, 'OT', 'Le chef de la maison de prison remit en la main de Joseph tous les prisonniers qui étaient dans la maison de prison, et tout ce qu''ils faisaient là, c''était lui qui le faisait.'),
(1173, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 39, 23, 'OT', 'Le chef de la maison de la prison ne voyait rien de tout ce qui était sous sa main, parce que l''Éternel était avec lui ; et ce qu''il faisait, l''Éternel le faisait réussir.'),
(1174, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 1, 'OT', 'Il advint après ces paroles que l''échanson du roi d''Égypte et le panetier péchèrent contre leur seigneur, le roi d''Égypte.'),
(1175, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 2, 'OT', 'Pharaon s''irrita contre ses deux eunuques, contre le chef des échansons et contre le chef des panetiers.'),
(1176, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 3, 'OT', 'Il les mit en garde dans la maison du chef des gardes du corps, dans la maison de la prison, lieu où Joseph était enfermé.'),
(1177, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 4, 'OT', 'Le chef des gardes du corps confia Joseph à eux, et il les servait ; et ils passèrent des jours en garde.'),
(1178, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 5, 'OT', 'Tous deux firent un rêve, chacun son rêve, dans une même nuit, chacun selon l''interprétation de son rêve, l''échanson et le panetier du roi d''Égypte, qui étaient enfermés dans la maison de la prison.'),
(1179, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 6, 'OT', 'Joseph vint vers eux le matin, les regarda, et voici qu''ils étaient abattus.'),
(1180, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 7, 'OT', 'Il interrogea les eunuques de Pharaon qui étaient avec lui dans la garde de la maison de son seigneur, en disant : Pourquoi vos faces sont-elles tristes aujourd''hui ?'),
(1181, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 8, 'OT', 'Ils lui dirent : « Nous avons fait un rêve, et il n''y a personne pour l''interpréter. » Joseph leur dit : « Les interprétations n''appartiennent-elles pas à Dieu ? Racontez-le-moi donc, je vous prie. »'),
(1182, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 9, 'OT', 'Le chef des échansons raconta son rêve à Joseph, et lui dit : Dans mon rêve, voici qu''une vigne était devant ma face.'),
(1183, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 10, 'OT', 'Dans la vigne, trois sarments ; et elle, comme elle bourgeonnait, sa fleur montait, ses grappes mûrissaient en raisins.'),
(1184, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 11, 'OT', 'La coupe de Pharaon était dans ma main, et je pris les raisins, et je les pressai dans la coupe de Pharaon, et je donnai la coupe dans la main de Pharaon.'),
(1185, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 12, 'OT', 'Joseph lui dit : Voici son interprétation : les trois sarments sont trois jours.'),
(1186, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 13, 'OT', 'Encore trois jours, et Pharaon élèvera ta tête et te rétablira sur ta base ; et tu mettras la coupe de Pharaon dans sa main, selon le jugement premier, lorsque tu étais son échanson.'),
(1187, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 14, 'OT', 'Mais souviens-toi de moi quand il te sera bien, et fais, je te prie, bonté envers moi, et mentionne-moi à Pharaon, et fais-moi sortir de cette maison.'),
(1188, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 15, 'OT', 'Car j''ai été volé, oui volé de la terre des Hébreux, et même ici je n''ai rien fait pour qu''on me mette dans la citerne.'),
(1189, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 16, 'OT', 'Le chef des panetiers vit que l''interprétation était bonne, et il dit à Joseph : « Moi aussi, dans mon rêve, voici que trois corbeilles de pain blanc étaient sur ma tête. »'),
(1190, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 17, 'OT', 'Et dans la corbeille supérieure, il y avait de toute nourriture de Pharaon, œuvre de boulanger, et l''oiseau les mangeait de la corbeille au-dessus de ma tête.'),
(1191, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 18, 'OT', 'Joseph répondit et dit : Voici son interprétation : les trois corbeilles sont trois jours.'),
(1192, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 19, 'OT', 'Encore trois jours, et Pharaon lèvera ta tête de dessus toi, et te pendra à un bois, et l''oiseau mangera ta chair de dessus toi.'),
(1193, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 20, 'OT', 'Il advint, au troisième jour, le jour de la naissance de Pharaon, qu''il fit un festin pour tous ses serviteurs, et il éleva la tête du chef des échansons et la tête du chef des panetiers au milieu de ses serviteurs.'),
(1194, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 21, 'OT', 'Il rétablit le chef des échansons dans son office d''échanson, et il remit la coupe dans la main de Pharaon.'),
(1195, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 22, 'OT', 'Et le chef des boulangers, il le pendit, comme Joseph le leur avait interprété.'),
(1196, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 40, 23, 'OT', 'Le chef des échansons ne se souvint pas de Joseph, et il l''oublia.'),
(1197, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 1, 'OT', 'Il arriva, au bout de deux années de jours, que Pharaon rêva, et voici, il se tenait debout près du fleuve.'),
(1198, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 2, 'OT', 'Et voici que du fleuve montaient sept vaches, belles d''apparence et grasses de chair, et elles paissaient dans la prairie.'),
(1199, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 3, 'OT', 'Et voici que sept autres vaches, laides d''apparence et maigres de chair, montèrent après elles hors du fleuve, et se tinrent à côté des vaches sur la lèvre du fleuve.'),
(1200, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 4, 'OT', 'Les vaches de mauvaise apparence et maigres de chair dévorèrent les sept vaches de belle apparence et bien portantes, et Pharaon s''éveilla.'),
(1201, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 5, 'OT', 'Il se rendormit et rêva une seconde fois : voici que sept épis montaient sur un seul roseau, gras et beaux.'),
(1202, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 6, 'OT', 'Et voici sept épis minces et brûlés par l''orient, qui poussaient après eux.'),
(1203, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 7, 'OT', 'Les épis maigres dévorèrent les sept épis gras et pleins, et Pharaon s''éveilla, et voici, c''était un rêve.'),
(1204, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 8, 'OT', 'Il arriva qu''au matin son esprit fut troublé, et il envoya appeler tous les magiciens d''Égypte et tous ses sages ; et Pharaon leur raconta son rêve, mais il n''y avait personne qui pût l''interpréter pour Pharaon.'),
(1205, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 9, 'OT', 'Le chef des échansons parla à Pharaon, disant : Je rappelle aujourd''hui mes péchés.'),
(1206, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 10, 'OT', 'Pharaon fut irrité contre ses serviteurs, et il me mit en prison dans la maison du chef des gardes, moi et le chef des panetiers.'),
(1207, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 11, 'OT', 'Nous avons rêvé un rêve dans une même nuit, moi et lui ; chacun selon l''interprétation de son rêve, nous avons rêvé.'),
(1208, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 12, 'OT', 'Et là, avec nous, se trouvait un jeune Hébreu, serviteur du chef des gardes du corps ; nous lui racontâmes nos rêves, et il nous les interpréta, à chacun selon son rêve.'),
(1209, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 13, 'OT', 'Et il advint que, comme il nous l''avait interprété, ainsi il en fut : il me rétablit dans ma base, et lui, il le fit pendre.'),
(1210, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 14, 'OT', 'Pharaon envoya et appela Joseph, et on le fit sortir en hâte de la citerne ; il se rasa, changea ses vêtements, et vint vers Pharaon.'),
(1211, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 15, 'OT', 'Pharaon dit à Joseph : « J''ai rêvé un rêve, et il n''y a personne pour l''interpréter ; et j''ai entendu dire de toi que tu entends un rêve pour l''interpréter. »'),
(1212, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 16, 'OT', 'Joseph répondit à Pharaon, en disant : Ce n''est pas en moi ; Dieu répondra pour la paix de Pharaon.'),
(1213, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 17, 'OT', 'Pharaon parla à Joseph : Dans mon rêve, voici que je me tenais sur la lèvre du fleuve.'),
(1214, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 18, 'OT', 'Et voici que du fleuve montaient sept vaches grasses de chair et belles d''apparence, et elles paissaient dans la prairie.'),
(1215, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 19, 'OT', 'Et voici que sept autres vaches montaient après elles, chétives et de très mauvaise apparence, et maigres de chair ; je n''en ai point vu de semblables dans toute la terre d''Égypte pour la méchanceté.'),
(1216, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 20, 'OT', 'Les vaches maigres et chétives dévorèrent les sept premières vaches grasses.'),
(1217, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 21, 'OT', 'Elles entrèrent dans leur milieu, et l''on ne reconnut pas qu''elles étaient entrées dans leur milieu, et leur apparence était mauvaise comme au commencement, et je m''éveillai.'),
(1218, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 22, 'OT', 'Et je vis en mon rêve : voici, sept épis montaient sur un seul roseau, pleins et bons.'),
(1219, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 23, 'OT', 'Et voici, sept épis maigres et brûlés par l''orient, qui poussaient après eux.'),
(1220, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 24, 'OT', 'Les épis maigres dévorèrent les sept épis beaux, et je le dis aux magiciens, mais personne ne me l''expliqua.'),
(1221, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 25, 'OT', 'Joseph dit à Pharaon : Le rêve de Pharaon est un seul ; ce que Dieu fait, il l''a déclaré à Pharaon.'),
(1222, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 26, 'OT', 'Les sept vaches belles sont sept années, et les sept épis beaux sont sept années ; c''est un seul rêve.'),
(1223, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 27, 'OT', 'Les sept vaches maigres et chétives qui montaient après elles sont sept années, et les sept épis vides, brûlés par le vent d''orient, seront sept années de famine.'),
(1224, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 28, 'OT', 'C''est là la parole que j''ai dite à Pharaon : ce que Dieu fait, il l''a montré à Pharaon.'),
(1225, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 29, 'OT', 'Voici, sept années arrivent, une grande abondance dans toute la terre d''Égypte.'),
(1226, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 30, 'OT', 'Et sept années de famine surviendront après elles, et toute l''abondance sera oubliée dans la terre d''Égypte, et la famine consumera la terre.'),
(1227, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 31, 'OT', 'L''abondance ne sera pas connue dans la terre, à cause de la face de cette famine qui viendra après, car elle sera très lourde.'),
(1228, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 32, 'OT', 'Et quant au fait que le rêve a été donné deux fois à Pharaon, c''est que la parole est établie de la part de Dieu, et Dieu se hâte de l''accomplir.'),
(1229, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 33, 'OT', 'Et maintenant, que Pharaon voie un homme intelligent et sage, et qu''il le mette sur la terre d''Égypte.'),
(1230, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 34, 'OT', 'Que Pharaon agisse et qu''il établisse des préposés sur la terre, et qu''il prélève un cinquième de la terre d''Égypte pendant les sept années d''abondance.'),
(1231, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 35, 'OT', 'Et ils rassembleront toute la nourriture de ces bonnes années qui viennent, et ils entasseront le blé sous la main de Pharaon, comme nourriture dans les villes, et ils le garderont.'),
(1232, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 36, 'OT', 'La nourriture sera un dépôt pour la terre, pour les sept années de famine qui seront dans la terre d''Égypte, et la terre ne sera pas retranchée par la famine.'),
(1233, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 37, 'OT', 'La parole fut bonne aux yeux de Pharaon et aux yeux de tous ses serviteurs.'),
(1234, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 38, 'OT', 'Pharaon dit à ses serviteurs : « Trouverions-nous un homme comme celui-ci, en qui soit l''esprit de Dieu ? »'),
(1235, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 39, 'OT', 'Pharaon dit à Joseph : Puisque Dieu t''a fait connaître tout cela, il n''y a personne d''aussi intelligent et sage que toi.'),
(1236, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 40, 'OT', 'Tu seras sur ma maison, et par ta bouche tout mon peuple sera gouverné ; seulement le trône, je le serai plus grand que toi.'),
(1237, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 41, 'OT', 'Pharaon dit à Joseph : Voici, je t''ai établi sur toute la terre d''Égypte.'),
(1238, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 42, 'OT', 'Pharaon ôta son anneau de sa main et le mit sur la main de Joseph, le revêtit de vêtements de lin fin, et plaça un collier d''or sur son cou.'),
(1239, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 43, 'OT', 'Il le fit monter sur son second char, celui qui lui appartenait, et l''on criait devant lui : « À genoux ! » Et il l''établit sur toute la terre d''Égypte.'),
(1240, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 44, 'OT', 'Pharaon dit à Joseph : « Je suis Pharaon, et sans toi nul homme ne lèvera sa main ni son pied dans toute la terre d''Égypte. »'),
(1241, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 45, 'OT', 'Pharaon donna à Joseph le nom de Tsaphnath-Paenéach, et il lui donna pour femme Asnath, fille de Poti-Phéra, sacrificateur d''On. Et Joseph sortit sur toute la terre d''Égypte.'),
(1242, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 46, 'OT', 'Joseph avait trente ans lorsqu''il se tint devant la face de Pharaon, roi d''Égypte ; et Joseph sortit de devant la face de Pharaon, et il parcourut toute la terre d''Égypte.'),
(1243, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 47, 'OT', 'La terre produisit par poignées pendant les sept années d''abondance.'),
(1244, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 48, 'OT', 'Il rassembla toute la nourriture des sept années qui furent dans la terre d''Égypte, et il mit la nourriture dans les villes ; la nourriture du champ de la ville, qui était dans ses alentours, il la mit dans son milieu.'),
(1245, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 49, 'OT', 'Joseph amassa du blé comme le sable de la mer, en très grande abondance, jusqu''à ce qu''il cesse de le compter, car il n''y avait pas de nombre.'),
(1246, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 50, 'OT', 'Deux fils naquirent à Joseph avant l''arrivée de l''année de famine, que lui enfanta Asnath, fille de Poti-Phéra, sacrificateur d''On.'),
(1247, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 51, 'OT', 'Joseph donna au premier-né le nom de Manassé, car Dieu m''a fait oublier tout mon travail et toute la maison de mon père.'),
(1248, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 52, 'OT', 'Et le nom du second, il l''appela Éphraïm, car Dieu m''a rendu fécond dans la terre de mon affliction.'),
(1249, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 53, 'OT', 'Les sept années d''abondance qui avaient été dans la terre d''Égypte prirent fin.'),
(1250, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 54, 'OT', 'Les sept années de famine commencèrent à venir, comme Joseph l''avait dit, et il y eut famine dans toutes les terres, mais dans toute la terre d''Égypte il y avait du pain.'),
(1251, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 55, 'OT', 'Toute la terre d''Égypte fut affamée, et le peuple cria à Pharaon pour du pain. Pharaon dit à tous les Égyptiens : Allez vers Joseph ; ce qu''il vous dira, faites-le.'),
(1252, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 56, 'OT', 'La famine pesait sur toute la face de la terre, et Joseph ouvrit tout ce qui était en eux et vendit du grain aux Égyptiens, et la famine s''intensifia dans la terre d''Égypte.'),
(1253, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 41, 57, 'OT', 'Et toute la terre vint en Égypte vers Joseph pour acheter du grain, car la famine était forte dans toute la terre.'),
(1254, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 1, 'OT', 'Jacob vit qu''il y avait du blé en Égypte, et Jacob dit à ses fils : Pourquoi vous regardez-vous les uns les autres ?'),
(1255, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 2, 'OT', 'Il dit : Voici, j''ai entendu qu''il y a du blé en Égypte ; descendez là-bas et achetez-en pour nous, afin que nous vivions et ne mourions pas.'),
(1256, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 3, 'OT', 'Les frères de Joseph descendirent au nombre de dix pour acheter du blé en Égypte.'),
(1257, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 4, 'OT', 'Jacob n''envoya pas Benjamin, frère de Joseph, avec ses frères, car il dit : « De peur qu''un malheur ne lui arrive. »'),
(1258, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 5, 'OT', 'Les fils d''Israël vinrent pour acheter du grain au milieu de ceux qui venaient, car la famine était dans la terre de Canaan.'),
(1259, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 6, 'OT', 'Joseph était le gouverneur sur la terre ; c''est lui qui approvisionnait tout le peuple de la terre. Et les frères de Joseph vinrent et se prosternèrent devant lui, le visage contre terre, dans leur colère.'),
(1260, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 7, 'OT', 'Joseph vit ses frères et les reconnut, mais il se fit étranger envers eux et leur parla durement, et il leur dit : « D''où venez-vous ? » Et ils répondirent : « De la terre de Canaan, pour acheter de la nourriture. »'),
(1261, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 8, 'OT', 'Joseph reconnut ses frères, mais eux ne le reconnurent pas.'),
(1262, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 9, 'OT', 'Joseph se souvint des rêves qu''il avait rêvés à leur sujet, et il leur dit : Vous êtes des espions ; c''est pour voir la nudité de la terre que vous êtes venus.'),
(1263, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 10, 'OT', 'Ils lui répondirent : Non, mon seigneur ; tes serviteurs sont venus pour acheter de la nourriture.'),
(1264, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 11, 'OT', 'Nous sommes tous fils d''un même homme ; nous sommes des hommes honnêtes ; tes serviteurs n''ont pas été des espions.'),
(1265, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 12, 'OT', 'Il leur dit : Non, c''est pour voir la nudité de la terre que vous êtes venus.'),
(1266, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 13, 'OT', 'Nous sommes douze serviteurs, tes serviteurs, frères, fils d''un seul homme dans la terre de Canaan ; et voici, le plus jeune est aujourd''hui avec notre père, et l''autre n''est plus.'),
(1267, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 14, 'OT', 'Joseph leur dit : « C''est cela même que je vous ai dit, en disant : Vous êtes des espions. »'),
(1268, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 15, 'OT', 'C''est par là que vous serez éprouvés : par la vie de Pharaon, vous ne sortirez point d''ici, si ce n''est lorsque votre jeune frère viendra ici.'),
(1269, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 16, 'OT', 'Envoyez l''un de vous, et qu''il prenne votre frère ; et vous, soyez retenus prisonniers, et vos paroles seront éprouvées, pour savoir si la vérité est avec vous ; et sinon, par la vie de Pharaon, vous êtes des espions.'),
(1270, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 17, 'OT', 'Il les rassembla sous garde pendant trois jours.'),
(1271, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 18, 'OT', 'Le troisième jour, Joseph leur dit : « Faites ceci et vous vivrez ; je crains Dieu. »'),
(1272, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 19, 'OT', 'Si vous êtes honnêtes, que l''un de vos frères soit retenu dans la maison de votre garde ; et vous, allez, apportez du blé pour la famine de vos maisons.'),
(1273, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 20, 'OT', 'Et amenez-moi votre jeune frère, et vos paroles seront confirmées, et vous ne mourrez point. Et ils firent ainsi.'),
(1274, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 21, 'OT', 'Ils se dirent l''un à l''autre : « Nous sommes vraiment coupables envers notre frère, car nous avons vu la détresse de son âme quand il nous suppliait, et nous ne l''avons pas écouté ; c''est pourquoi cette détresse est venue sur nous. »'),
(1275, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 22, 'OT', 'Ruben leur répondit en disant : « Ne vous avais-je pas parlé en disant : Ne péchez pas contre l''enfant ? Mais vous n''avez pas écouté ; et voici, son sang est réclamé. »'),
(1276, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 23, 'OT', 'Or ils ne savaient pas que Joseph les entendait, car il y avait un interprète entre eux.'),
(1277, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 24, 'OT', 'Il se détourna d''eux et pleura ; puis il revint vers eux et leur parla, et il prit d''auprès d''eux Siméon et le lia sous leurs yeux.'),
(1278, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 25, 'OT', 'Joseph donna l''ordre, et l''on remplit leurs ustensiles de blé, et l''on remit l''argent de chacun dans son sac, et l''on leur donna des provisions pour le chemin ; et il fit ainsi pour eux.'),
(1279, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 26, 'OT', 'Ils chargèrent leur blé sur leurs ânes, et partirent de là.'),
(1280, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 27, 'OT', 'L''un d''eux ouvrit son sac pour donner du fourrage à son âne au lieu de campement, et il vit son argent, et voici qu''il était à la bouche de son sac.'),
(1281, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 28, 'OT', 'Il dit à ses frères : Mon argent a été rendu, et voici, il est même dans mon sac. Alors leur cœur défaillit, et ils tremblèrent, chacun disant à son frère : Qu''est-ce que Dieu nous a fait ?'),
(1282, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 29, 'OT', 'Ils arrivèrent auprès de Jacob, leur père, dans la terre de Canaan, et ils lui racontèrent tout ce qui leur était arrivé, en disant :'),
(1283, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 30, 'OT', 'L''homme, seigneur de la terre, nous a parlé durement et nous a traités comme des espions de la terre.'),
(1284, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 31, 'OT', 'Et nous lui avons dit : Nous sommes des hommes honnêtes ; nous n''avons pas été des espions.'),
(1285, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 32, 'OT', 'Nous sommes douze frères, fils de notre père ; l''un n''est plus, et le plus jeune est aujourd''hui avec notre père dans la terre de Canaan.'),
(1286, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 33, 'OT', 'L''homme, le seigneur de la terre, nous dit : « À ceci je saurai que vous êtes honnêtes : laissez avec moi votre frère, l''un d''entre vous, et prenez de quoi remédier à la famine de vos maisons, et allez-vous-en. »'),
(1287, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 34, 'OT', 'Et amenez votre jeune frère à moi, et je saurai que vous n''êtes pas des espions, mais que vous êtes sincères ; je vous donnerai votre frère, et vous trafiquerez dans la terre.'),
(1288, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 35, 'OT', 'Il arriva, comme ils vidaient leurs sacs, que voici, le paquet d''argent de chacun était dans son sac ; et ils virent leurs paquets d''argent, eux et leur père, et ils eurent peur.'),
(1289, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 36, 'OT', 'Alors Jacob, leur père, leur dit : Vous m''avez privé de mes enfants ; Joseph n''est plus, et Siméon n''est plus, et vous prendriez Benjamin ; toutes ces choses sont tombées sur moi.'),
(1290, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 37, 'OT', 'Ruben dit à son père : « Tu feras mourir mes deux fils si je ne te le ramène pas ; remets-le entre ma main, et je te le rendrai. »'),
(1291, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 42, 38, 'OT', 'Il dit : Mon fils ne descendra pas avec vous, car son frère est mort, et il reste seul ; si un malheur le frappe sur le chemin où vous irez, vous ferez descendre ma vieillesse avec douleur au séjour des morts.'),
(1292, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 1, 'OT', 'La famine était lourde dans la terre.'),
(1293, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 2, 'OT', 'Or, lorsqu''ils eurent fini de manger le blé qu''ils avaient apporté d''Égypte, leur père leur dit : Retournez, achetez-nous un peu de nourriture.'),
(1294, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 3, 'OT', 'Juda lui dit : « Cet homme nous a solennellement averti en disant : "Vous ne verrez pas ma face sans que votre frère soit avec vous." »'),
(1295, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 4, 'OT', 'Si tu envoies notre frère avec nous, nous descendrons et nous t''achèterons de la nourriture.'),
(1296, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 5, 'OT', 'Mais si tu ne l''envoies pas, nous ne descendrons point, car cet homme nous a dit : Vous ne verrez pas ma face, à moins que votre frère ne soit avec vous.'),
(1297, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 6, 'OT', 'Israël dit : Pourquoi m''avez-vous fait du mal, en disant à l''homme que vous aviez encore un frère ?'),
(1298, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 7, 'OT', 'Ils répondirent : Cet homme nous a expressément interrogés sur nous et sur notre naissance, en disant : Votre père vit-il encore ? Avez-vous un frère ? Et nous lui avons rapporté selon ces paroles. Pouvions-nous savoir qu''il dirait : Faites descendre votre frère ?'),
(1299, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 8, 'OT', 'Juda dit à Israël, son père : « Envoie le jeune homme avec moi, et nous nous lèverons et nous irons, et nous vivrons et ne mourrons pas, ni nous, ni toi, ni nos petits enfants. »'),
(1300, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 9, 'OT', 'Moi, je me porte garant de lui ; c''est de ma main que tu le réclameras. Si je ne l''amène pas vers toi et ne le place pas devant ta face, je serai coupable envers toi tous les jours.'),
(1301, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 10, 'OT', 'Car si nous n''avions pas tardé, certes nous serions déjà revenus deux fois.'),
(1302, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 11, 'OT', 'Alors Israël, leur père, leur dit : Si donc il en est ainsi, faites ceci : prenez des meilleures productions de la terre dans vos ustensiles, et faites descendre à l''homme une offrande : un peu de baume et un peu de miel, des aromates et de la myrrhe, des noix et des amandiers.'),
(1303, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 12, 'OT', 'Prenez en vos mains de l''argent en double, et reportez en vos mains l''argent qui a été remis dans la bouche de vos sacs ; peut-être était-ce une méprise.'),
(1304, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 13, 'OT', 'Prenez votre frère, et levez-vous, retournez vers l''homme.'),
(1305, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 14, 'OT', 'Que Dieu Tout-Puissant vous accorde compassion devant la face de l''homme, et qu''il vous renvoie votre autre frère et Benjamin ; et moi, comme j''ai été privé d''enfants, j''en serai privé.'),
(1306, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 15, 'OT', 'Les hommes prirent cette offrande, et ils prirent en leur main une seconde somme d''argent, ainsi que Benjamin ; puis ils se levèrent, descendirent en Égypte, et se tinrent devant la face de Joseph.'),
(1307, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 16, 'OT', 'Joseph vit Benjamin avec eux, et dit à celui qui était sur sa maison : Fais entrer ces hommes dans la maison, tue un massacre et prépare, car ces hommes mangeront avec moi à midi.'),
(1308, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 17, 'OT', 'L''homme fit comme Joseph l''avait dit, et l''homme amena les hommes dans la maison de Joseph.'),
(1309, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 18, 'OT', 'Ces hommes eurent peur, car ils étaient conduits dans la maison de Joseph, et ils dirent : C''est à cause de la parole de l''argent qui est revenu dans nos sacs au commencement que nous sommes amenés ici, pour qu''il se jette sur nous, qu''il fonde sur nous, et qu''il nous prenne comme serviteurs, avec nos ânes.'),
(1310, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 19, 'OT', 'Ils s''approchèrent de l''homme qui était à la tête de la maison de Joseph, et lui parlèrent à l''entrée de la maison.'),
(1311, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 20, 'OT', 'Ils dirent : « De grâce, mon seigneur ! Nous sommes descendus au commencement pour acheter de la nourriture. »'),
(1312, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 21, 'OT', 'Il arriva que, lorsque nous arrivâmes au lieu de campement, nous ouvrîmes nos sacs, et voici que l''argent de chaque homme était à la bouche de son sac, notre argent selon son poids, et nous le rapportâmes dans notre main.'),
(1313, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 22, 'OT', 'Nous avons aussi apporté d''autre argent dans notre main pour acheter de la nourriture ; nous ne savions pas qui a mis notre argent dans nos sacs.'),
(1314, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 23, 'OT', 'Il dit : « Paix à vous, ne craignez point ; votre Dieu et le Dieu de votre père vous a donné un trésor caché dans vos sacs ; votre argent m''est parvenu. » Et il fit sortir Siméon vers eux.'),
(1315, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 24, 'OT', 'L''homme fit entrer ces hommes dans la maison de Joseph, et il donna des eaux, et ils lavèrent leurs pieds, et il donna du fourrage à leurs ânes.'),
(1316, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 25, 'OT', 'Ils préparèrent l''offrande jusqu''à ce que Joseph vienne à midi, car ils avaient entendu qu''ils mangeraient là du pain.'),
(1317, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 26, 'OT', 'Joseph entra dans la maison, et ils lui apportèrent dans la maison l''offrande qui était dans leur main, et ils se prosternèrent devant lui jusqu''à terre.'),
(1318, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 27, 'OT', 'Il leur demanda comment ils allaient, et dit : Votre père, le vieillard dont vous avez parlé, est-il en paix ? Est-il encore en vie ?'),
(1319, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 28, 'OT', 'Ils répondirent : « Paix à ton serviteur, notre père ; il est encore vivant. » Et ils s''inclinèrent et se prosternèrent.'),
(1320, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 29, 'OT', 'Il leva les yeux et vit Benjamin, son frère, fils de sa mère, et dit : « Est-ce là votre jeune frère, dont vous m''avez parlé ? » Et il dit : « Que Dieu te fasse grâce, mon fils. »'),
(1321, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 30, 'OT', 'Joseph se hâta, car sa compassion s''émut envers son frère, et il chercha à pleurer ; il entra dans la chambre et y pleura.'),
(1322, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 31, 'OT', 'Il se lava le visage, sortit, se contint, et dit : Mettez du pain.'),
(1323, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 32, 'OT', 'On lui servit à part, et à eux à part, et aux Égyptiens qui mangeaient avec lui à part, car les Égyptiens ne pouvaient pas manger de pain avec les Hébreux, parce que c''est une abomination pour les Égyptiens.'),
(1324, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 33, 'OT', 'Ils s''assirent devant lui, le premier-né selon son droit d''aînesse, et le plus jeune selon sa jeunesse ; et les hommes se regardèrent avec étonnement, chacun vers son ami.'),
(1325, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 43, 34, 'OT', 'Il prit des présents de devant sa face pour eux, et le présent de Benjamin surpassait de cinq mains les présents de tous les autres ; ils burent et s''enivrèrent avec lui.'),
(1326, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 1, 'OT', 'Il commanda à celui qui était sur sa maison, disant : Remplis les sacs de ces hommes de nourriture, autant qu''ils en peuvent porter, et mets l''argent de chacun à la bouche de son sac.'),
(1327, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 2, 'OT', 'Et tu mettras ma coupe, la coupe d''argent, à la bouche du sac du plus jeune, avec l''argent de son blé ; et il fit selon la parole de Joseph qu''il avait dite.'),
(1328, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 3, 'OT', 'Le matin étant éclairé, les hommes furent renvoyés, eux et leurs ânes.'),
(1329, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 4, 'OT', 'Ils étaient sortis de la ville, sans s''être éloignés, et Joseph dit à celui qui était sur sa maison : Lève-toi, poursuis ces hommes, et quand tu les auras atteints, tu leur diras : Pourquoi avez-vous rendu le mal pour le bien ?'),
(1330, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 5, 'OT', 'N''est-ce pas ceci dans lequel mon seigneur boit, et dont il se sert pour deviner ? Vous avez mal agi dans ce que vous avez fait.'),
(1331, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 6, 'OT', 'Il les atteignit et leur dit ces paroles.'),
(1332, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 7, 'OT', 'Ils lui répondirent : Pourquoi mon seigneur parle-t-il de telles paroles ? Loin de tes serviteurs de faire une telle parole !'),
(1333, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 8, 'OT', 'Voici, l''argent que nous avons trouvé à la bouche de nos sacs, nous te l''avons rendu depuis la terre de Canaan ; et comment volerions-nous de la maison de ton seigneur de l''argent ou de l''or ?'),
(1334, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 9, 'OT', 'Celui de tes serviteurs chez qui il se trouvera mourra, et nous aussi, nous serons serviteurs de mon seigneur.'),
(1335, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 10, 'OT', 'Il dit : Qu''il en soit donc selon vos paroles ! Celui chez qui elle sera trouvée sera mon serviteur, et vous serez innocents.'),
(1336, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 11, 'OT', 'Ils se hâtèrent, et chacun descendit son sac à terre, et chacun ouvrit son sac.'),
(1337, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 12, 'OT', 'Il chercha, commençant par l''aîné et finissant par le plus jeune, et la coupe fut trouvée dans le sac de Benjamin.'),
(1338, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 13, 'OT', 'Ils déchirèrent leurs vêtements, et chaque homme chargea son âne, et ils retournèrent à la ville.'),
(1339, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 14, 'OT', 'Juda et ses frères arrivèrent à la maison de Joseph, et il était encore là, et ils tombèrent devant lui à terre.'),
(1340, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 15, 'OT', 'Joseph leur dit : Quelle est cette œuvre que vous avez faite ? Ne savez-vous pas qu''un homme tel que moi pratique certainement la divination ?'),
(1341, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 16, 'OT', 'Juda dit : Que dirons-nous à mon seigneur ? Que parlerons-nous, et comment nous justifierons-nous ? Dieu a trouvé l''iniquité de tes serviteurs. Nous voici serviteurs de mon seigneur, nous et celui dans la main duquel la coupe a été trouvée.'),
(1342, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 17, 'OT', 'Qu''il me soit loin de faire cela ! L''homme chez qui la coupe a été trouvée en sa main, lui sera mon serviteur ; mais vous, montez en paix vers votre père.'),
(1343, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 18, 'OT', 'Alors Juda s''approcha de lui et dit : De grâce, mon seigneur, que ton serviteur dise une parole aux oreilles de mon seigneur, et que ta colère ne s''enflamme pas contre ton serviteur, car tu es comme Pharaon.'),
(1344, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 19, 'OT', 'Mon seigneur a interrogé ses serviteurs, en disant : Avez-vous un père ou un frère ?'),
(1345, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 20, 'OT', 'Nous avons dit à mon seigneur : Nous avons un père âgé, et un enfant de sa vieillesse, tout jeune ; et son frère est mort, et il est resté seul auprès de sa mère, et son père l''aime.'),
(1346, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 21, 'OT', 'Et elle dit à tes serviteurs : Fais-le descendre vers moi, et je poserai mon œil sur lui.'),
(1347, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 22, 'OT', 'Nous avons dit à mon seigneur : le jeune homme ne peut pas quitter son père ; s''il quitte son père, il mourra.'),
(1348, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 23, 'OT', 'Tu as dit à tes serviteurs : Si votre jeune frère ne descend pas avec vous, vous ne reverrez plus ma face.'),
(1349, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 24, 'OT', 'Il arriva que, lorsque nous montâmes vers ton serviteur, mon père, nous lui rapportâmes les paroles de mon seigneur.'),
(1350, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 25, 'OT', 'Notre père dit : Retournez, achetez-nous un peu de nourriture.'),
(1351, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 26, 'OT', 'Nous avons dit : Nous ne pouvons pas descendre ; si notre jeune frère est avec nous, alors nous descendrons, car nous ne pouvons pas voir la face de l''homme, et notre jeune frère n''est pas avec nous.'),
(1352, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 27, 'OT', 'Ton serviteur, mon père, nous dit : « Vous savez que deux, ma femme m''a enfantés. »'),
(1353, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 28, 'OT', 'L''un d''eux est sorti d''auprès de moi, et j''ai dit : Certainement il a été déchiré, déchiré, et je ne l''ai pas vu jusqu''à présent.'),
(1354, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 29, 'OT', 'Et si vous prenez aussi celui-ci de devant ma face, et qu''un malheur lui arrive, vous ferez descendre ma vieillesse avec mal au séjour des morts.'),
(1355, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 30, 'OT', 'Et maintenant, quand je viendrai vers ton serviteur, mon père, et que le jeune homme ne sera pas avec nous, et que son âme est liée à son âme,'),
(1356, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 31, 'OT', 'Et il arrivera, lorsqu''il verra que le jeune homme n''est pas avec nous, qu''il mourra ; et tes serviteurs feront descendre la vieillesse de ton serviteur, notre père, avec douleur au séjour des morts.'),
(1357, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 32, 'OT', 'Car ton serviteur s''est porté garant pour le jeune homme auprès de mon père, en disant : Si je ne te le ramène pas, je serai coupable envers mon père tous les jours.'),
(1358, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 33, 'OT', 'Que maintenant ton serviteur demeure à la place du jeune homme, comme serviteur de mon seigneur, et que le jeune homme monte avec ses frères.'),
(1359, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 44, 34, 'OT', 'Car comment monterais-je vers mon père, alors que le jeune homme n''est pas avec moi ? De peur que je voie le mal qui atteindrait mon père.'),
(1360, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 1, 'OT', 'Joseph ne put se contenir devant tous ceux qui se tenaient auprès de lui, et il s''écria : « Faites sortir tout homme d''auprès de moi. » Et aucun homme ne resta avec lui lorsque Joseph se fit connaître à ses frères.'),
(1361, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 2, 'OT', 'Il éleva la voix en pleurs, et les Égyptiens l''entendirent, et la maison de Pharaon l''entendit.'),
(1362, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 3, 'OT', 'Joseph dit à ses frères : « Je suis Joseph. Mon père est-il encore vivant ? » Et ses frères ne purent lui répondre, car ils étaient terrifiés devant sa face.'),
(1363, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 4, 'OT', 'Joseph dit à ses frères : « Approchez-vous donc de moi », et ils s''approchèrent. Puis il dit : « Je suis Joseph, votre frère, que vous avez vendu en Égypte. »'),
(1364, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 5, 'OT', 'Et maintenant, ne vous affligez pas et que cela ne vous paraisse pas mauvais à vos yeux, parce que vous m''avez vendu ici ; car c''est pour la subsistance que Dieu m''a envoyé devant vous.'),
(1365, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 6, 'OT', 'Car voici deux années de famine au milieu de la terre, et il y aura encore cinq années sans labourage ni moisson.'),
(1366, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 7, 'OT', 'Dieu m''a envoyé devant vous pour vous laisser un reste sur la terre et pour vous faire vivre par une grande délivrance de réchappés.'),
(1367, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 8, 'OT', 'Et maintenant, ce n''est pas vous qui m''avez envoyé ici, mais Dieu ; et il m''a établi comme père pour Pharaon, et comme seigneur sur toute sa maison, et comme gouverneur sur toute la terre d''Égypte.'),
(1368, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 9, 'OT', 'Hâtez-vous, montez vers mon père, et dites-lui : Ainsi parle ton fils Joseph : Dieu m''a établi seigneur sur toute l''Égypte ; descends vers moi, ne t''arrête pas.'),
(1369, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 10, 'OT', 'Tu habiteras dans la terre de Gosen, et tu seras près de moi, toi, tes fils, et les fils de tes fils, tes brebis, tes bœufs, et tout ce qui est à toi.'),
(1370, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 11, 'OT', 'Je te nourrirai là, car il reste encore cinq années de famine, afin que tu ne sois pas dépouillé, toi, ta maison, et tout ce qui est à toi.'),
(1371, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 12, 'OT', 'Et voici, vos yeux voient, et les yeux de mon frère Benjamin, que c''est ma bouche qui vous parle.'),
(1372, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 13, 'OT', 'Vous raconterez à mon père toute ma gloire en Égypte et tout ce que vous avez vu, et vous vous hâterez de faire descendre ici mon père.'),
(1373, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 14, 'OT', 'Il tomba sur le cou de Benjamin, son frère, et pleura ; et Benjamin pleura sur son cou.'),
(1374, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 15, 'OT', 'Il embrassa tous ses frères et pleura sur eux, et après cela ses frères parlèrent avec lui.'),
(1375, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 16, 'OT', 'La voix se fit entendre dans la maison de Pharaon, disant : Les frères de Joseph sont venus. Et cela fut bon aux yeux de Pharaon et aux yeux de ses serviteurs.'),
(1376, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 17, 'OT', 'Pharaon dit à Joseph : « Dis à tes frères : Faites ceci : chargez votre bétail et allez, revenez à la terre de Canaan. »'),
(1377, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 18, 'OT', 'Prenez votre père et vos maisons, et venez vers moi, et je vous donnerai la bonté de la terre d''Égypte, et vous mangerez la graisse de la terre.'),
(1378, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 19, 'OT', 'Et toi, tu as reçu cet ordre : faites ceci : prenez pour vous, de la terre d''Égypte, des chars pour vos petits enfants et pour vos femmes, et portez votre père, et venez.'),
(1379, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 20, 'OT', 'Que vos yeux n''épargnent pas vos ustensiles, car la bonté de toute la terre d''Égypte est à vous.'),
(1380, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 21, 'OT', 'Les fils d''Israël firent ainsi, et Joseph leur donna des chars selon la bouche de Pharaon, et leur donna des provisions pour le chemin.'),
(1381, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 22, 'OT', 'À tous, il donna à chaque homme des vêtements de rechange, et à Benjamin il donna trois cents pièces d''argent et cinq vêtements de rechange.'),
(1382, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 23, 'OT', 'Et à son père, il envoya de cette manière : dix ânes portant le meilleur de l''Égypte, et dix ânesses portant du blé, du pain et des vivres pour son père, pour le chemin.'),
(1383, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 24, 'OT', 'Il renvoya ses frères, et ils partirent ; et il leur dit : Ne vous querellez pas en chemin.'),
(1384, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 25, 'OT', 'Ils montèrent d''Égypte et arrivèrent dans la terre de Canaan, auprès de Jacob leur père.'),
(1385, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 26, 'OT', 'Ils lui annoncèrent en disant : Joseph est encore vivant, et c''est lui qui gouverne toute la terre d''Égypte. Mais son cœur défaillit, car il ne les crut pas.'),
(1386, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 27, 'OT', 'Ils lui rapportèrent toutes les paroles de Joseph qu''il leur avait dites, et il vit les chars que Joseph avait envoyés pour le porter ; et l''esprit de Jacob, leur père, reprit vie.'),
(1387, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 45, 28, 'OT', 'Israël dit : « C''est assez ; Joseph, mon fils, est encore vivant. J''irai et je le verrai avant que je meure. »'),
(1388, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 1, 'OT', 'Israël partit avec tout ce qui lui appartenait, et vint à Beer-Schéba, et offrit des sacrifices au Dieu de son père Isaac.'),
(1389, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 2, 'OT', 'Dieu dit à Israël dans une vision de la nuit, et il dit : Jacob, Jacob ! Et il dit : Me voici.'),
(1390, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 3, 'OT', 'Il dit : Je suis Dieu, le Dieu de ton père ; ne crains pas de descendre en Égypte, car là je ferai de toi une grande nation.'),
(1391, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 4, 'OT', 'Je descendrai avec toi en Égypte, et moi-même je te ferai aussi remonter ; et Joseph posera sa main sur tes yeux.'),
(1392, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 5, 'OT', 'Jacob se leva de Beer-Schéba, et les fils d''Israël portèrent Jacob leur père, ainsi que leurs petits enfants et leurs femmes, dans les chars que Pharaon avait envoyés pour le transporter.'),
(1393, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 6, 'OT', 'Ils prirent leurs troupeaux et leurs biens qu''ils avaient acquis dans la terre de Canaan, et ils vinrent en Égypte, Jacob et toute sa postérité avec lui.'),
(1394, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 7, 'OT', 'Ses fils et les fils de ses fils avec lui, ses filles et les filles de ses fils, et toute sa postérité, il les fit venir avec lui en Égypte.'),
(1395, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 8, 'OT', 'Voici les noms des fils d''Israël qui vinrent en Égypte : Jacob et ses fils ; le premier-né de Jacob, Ruben.'),
(1396, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 9, 'OT', 'Les fils de Ruben : Hénoc, Pallu, Hetsron et Carmi.'),
(1397, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 10, 'OT', 'Les fils de Siméon : Jemuel, Jamin, Ohad, Jakin, Tsochar, et Saül, fils de la Cananéenne.'),
(1398, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 11, 'OT', 'Les fils de Lévi : Guerschon, Kehath et Merari.'),
(1399, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 12, 'OT', 'Les fils de Juda : Er, Onan, Schéla, Pérets et Zérach ; et Er et Onan moururent dans la terre de Canaan ; et les fils de Pérets furent Hetsron et Hamul.'),
(1400, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 13, 'OT', 'Les fils d''Issacar : Thola, Pua, Job et Schimron.'),
(1401, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 14, 'OT', 'Les fils de Zabulon : Séred, Élon et Jahleel.'),
(1402, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 15, 'OT', 'Voici les fils de Léa, qu''elle enfanta à Jacob en Padan-Aram, et Dina, sa fille ; toutes les âmes de ses fils et de ses filles étaient trente-trois.'),
(1403, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 16, 'OT', 'Les fils de Gad : Tsiphjon, Haggi, Schuni, Etsbon, Éri, Arodites et Areéli.'),
(1404, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 17, 'OT', 'Les fils d''Aser : Jimna, Jischva, Jischvi et Beria, et Sérach, leur sœur ; et les fils de Beria : Héber et Malkiel.'),
(1405, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 18, 'OT', 'Voici les fils de Zilpa, que Laban donna à Léa, sa fille ; et elle enfanta ceux-ci à Jacob : seize âmes.'),
(1406, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 19, 'OT', 'Les fils de Rachel, femme de Jacob : Joseph et Benjamin.'),
(1407, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 20, 'OT', 'Il naquit à Joseph, dans la terre d''Égypte, Manassé et Éphraïm, que lui enfanta Asnath, fille de Poti-Phéra, sacrificateur d''On.'),
(1408, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 21, 'OT', 'Les fils de Benjamin : Béla, Béker, Aschbel, Guéra, Naaman, Éhi, Rosch, Muppim, Huppim et Ard.'),
(1409, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 22, 'OT', 'Voici les fils de Rachel qui naquirent à Jacob : toutes les âmes, quatorze.'),
(1410, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 23, 'OT', 'Les fils de Dan : Huschim.'),
(1411, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 24, 'OT', 'Les fils de Nephthali : Jahtseel, Guni, Jetser et Schillem.'),
(1412, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 25, 'OT', 'Voici les fils de Bilha, que Laban donna à Rachel, sa fille, et elle enfanta ceux-ci à Jacob : en tout, sept âmes.'),
(1413, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 26, 'OT', 'Toutes les âmes qui vinrent avec Jacob en Égypte, issues de son côté, sans les femmes des fils de Jacob : toutes les âmes, soixante-six.'),
(1414, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 27, 'OT', 'Et les fils de Joseph qui lui étaient nés en Égypte : deux âmes ; toutes les âmes de la maison de Jacob qui vinrent en Égypte : soixante-dix.'),
(1415, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 28, 'OT', 'Il envoya Juda devant lui vers Joseph, pour montrer le chemin devant lui vers Gosen, et ils arrivèrent dans la terre de Gosen.'),
(1416, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 29, 'OT', 'Joseph attela son char et monta à la rencontre d''Israël, son père, à Gosen. Il se montra à lui, se jeta à son cou, et pleura sur son cou encore longtemps.'),
(1417, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 30, 'OT', 'Israël dit à Joseph : « Je mourrai cette fois, après avoir vu ta face, car tu es encore vivant. »'),
(1418, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 31, 'OT', 'Joseph dit à ses frères et à la maison de son père : « Je monterai et j''annoncerai à Pharaon, et je lui dirai : Mes frères et la maison de mon père, qui étaient dans la terre de Canaan, sont venus vers moi. »'),
(1419, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 32, 'OT', 'Et les hommes étaient bergers de brebis, car ils étaient des hommes de troupeaux ; et ils ont amené leurs brebis, leurs bœufs, et tout ce qui leur appartenait.'),
(1420, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 33, 'OT', 'Et il arrivera que lorsque Pharaon vous appellera et dira : Quelle est votre œuvre ?'),
(1421, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 46, 34, 'OT', 'Vous direz : « Tes serviteurs ont été des hommes de troupeaux depuis notre jeunesse jusqu''à maintenant, nous et aussi nos pères », afin que vous habitiez dans la terre de Gosen, car tout berger de brebis est une abomination pour les Égyptiens.'),
(1422, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 1, 'OT', 'Joseph vint et le rapporta à Pharaon, et dit : Mon père et mes frères, leurs brebis et leurs bœufs, et tout ce qui leur appartient, sont venus de la terre de Canaan, et voici, ils sont dans la terre de Gosen.'),
(1423, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 2, 'OT', 'Et de l''extrémité de ses frères, il prit cinq hommes, et les plaça devant la face de Pharaon.'),
(1424, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 3, 'OT', 'Pharaon dit à ses frères : « Quelle est votre œuvre ? » Et ils dirent à Pharaon : « Tes serviteurs sont bergers de brebis, nous et nos pères. »'),
(1425, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 4, 'OT', 'Ils dirent à Pharaon : Nous sommes venus pour séjourner dans la terre, car il n''y a pas de pâturage pour les brebis qui appartiennent à tes serviteurs, parce que la famine est lourde dans la terre de Canaan ; et maintenant, que tes serviteurs habitent donc dans la terre de Gosen.'),
(1426, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 5, 'OT', 'Pharaon dit à Joseph : Ton père et tes frères sont venus vers toi.'),
(1427, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 6, 'OT', 'Le pays d''Égypte est devant toi ; établis ton père et tes frères dans le meilleur de la terre ; qu''ils habitent dans la terre de Gosen ; et si tu sais qu''il y a parmi eux des hommes de force, tu les placeras comme chefs de mes troupeaux sur ce qui m''appartient.'),
(1428, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 7, 'OT', 'Joseph amena Jacob, son père, et le plaça devant la face de Pharaon ; et Jacob bénit Pharaon.'),
(1429, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 8, 'OT', 'Pharaon dit à Jacob : Combien sont les jours des années de ta vie ?'),
(1430, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 9, 'OT', 'Jacob dit à Pharaon : Les jours des années de mon séjour sont de cent trente ans ; peu et mauvais ont été les jours des années de ma vie, et ils n''ont pas atteint les jours des années de la vie de mes pères dans les jours de leur séjour.'),
(1431, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 10, 'OT', 'Jacob bénit Pharaon, puis sortit de devant la face de Pharaon.'),
(1432, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 11, 'OT', 'Joseph établit son père et ses frères, et leur donna une possession dans la terre d''Égypte, dans le meilleur de la terre, dans la terre de Ramsès, comme Pharaon l''avait commandé.'),
(1433, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 12, 'OT', 'Joseph pourvut à l''entretien de son père, de ses frères et de toute la maison de son père, en pain, selon la bouche des petits enfants.'),
(1434, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 13, 'OT', 'Il n''y avait point de pain dans toute la terre, car la famine était très lourde, et la terre d''Égypte et la terre de Canaan languissaient à cause de la famine.'),
(1435, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 14, 'OT', 'Joseph recueillit tout l''argent qui se trouvait dans la terre d''Égypte et dans la terre de Canaan, en échange du blé qu''ils achetaient, et Joseph apporta l''argent dans la maison de Pharaon.'),
(1436, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 15, 'OT', 'L''argent manqua dans la terre d''Égypte et dans la terre de Canaan, et tous les Égyptiens vinrent vers Joseph, disant : « Donne-nous du pain ; pourquoi mourrions-nous devant toi ? Car l''argent a fait défaut. »'),
(1437, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 16, 'OT', 'Joseph dit : Donnez vos troupeaux, et je vous donnerai en échange de vos troupeaux, si l''argent est épuisé.'),
(1438, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 17, 'OT', 'Ils amenèrent leurs troupeaux à Joseph, et Joseph leur donna du pain en échange des chevaux, des troupeaux de brebis, des troupeaux de bœufs et des ânes ; et il les sustenta avec du pain, pour tous leurs troupeaux, cette année-là.'),
(1439, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 18, 'OT', 'Cette année-là étant révolue, ils vinrent à lui l''année suivante et lui dirent : « Nous ne cacherons pas à mon seigneur que l''argent est épuisé, et que les troupeaux de bétail sont à mon seigneur ; il ne reste rien devant mon seigneur, sinon nos corps et notre terre. »'),
(1440, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 19, 'OT', 'Pourquoi mourrions-nous sous tes yeux, nous et notre terre ? Achète-nous, nous et notre terre, contre du pain, et nous serons, nous et notre terre, serviteurs de Pharaon ; donne de la postérité, afin que nous vivions et ne mourions pas, et que la terre ne soit pas dévastée.'),
(1441, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 20, 'OT', 'Joseph acheta toute la terre d''Égypte pour Pharaon, car les Égyptiens vendirent chacun son champ, parce que la famine s''était appesantie sur eux, et la terre devint à Pharaon.'),
(1442, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 21, 'OT', 'Et il fit passer le peuple dans les villes, depuis une extrémité de la frontière de l''Égypte jusqu''à son autre extrémité.'),
(1443, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 22, 'OT', 'Seulement la terre des sacrificateurs, il ne l''acheta point, car il y avait un statut pour les sacrificateurs de la part de Pharaon, et ils mangeaient leur statut que Pharaon leur avait donné ; c''est pourquoi ils ne vendirent point leur terre.'),
(1444, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 23, 'OT', 'Joseph dit au peuple : Voici, je vous ai acquis aujourd''hui, vous et votre terre, pour Pharaon ; voici pour vous de la postérité, et vous ensemencierez la terre.'),
(1445, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 24, 'OT', 'Et il arrivera, lors des produits, que vous donnerez un cinquième à Pharaon, et les quatre mains seront à vous pour la postérité du champ, pour votre nourriture, pour ce qui est dans vos maisons, et pour manger de vos petits enfants.'),
(1446, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 25, 'OT', 'Ils dirent : « Tu nous as fait vivre ; que nous trouvions grâce à tes yeux, mon seigneur, et nous serons serviteurs de Pharaon. »'),
(1447, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 26, 'OT', 'Joseph l''établit comme statut jusqu''à ce jour sur la terre d''Égypte, pour Pharaon, le cinquième ; seulement la terre des sacrificateurs seule ne fut pas à Pharaon.'),
(1448, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 27, 'OT', 'Israël habita dans la terre d''Égypte, dans la terre de Gosen ; ils s''y établirent, et ils fructifièrent et se multiplièrent beaucoup.'),
(1449, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 28, 'OT', 'Jacob vécut dans la terre d''Égypte dix-sept ans, et les jours de Jacob, les années de sa vie, furent de cent quarante-sept ans.'),
(1450, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 29, 'OT', 'Les jours d''Israël approchèrent de la mort, et il appela son fils Joseph et lui dit : « Si j''ai trouvé grâce à tes yeux, mets donc ta main sous mon côté, et tu agiras envers moi avec bonté et vérité ; ne m''enterre pas, je te prie, en Égypte. »'),
(1451, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 30, 'OT', 'Je me coucherai avec mes pères, et tu me transporteras hors d''Égypte, et tu m''enseveliras dans leur sépulture. Et il dit : Je ferai selon ta parole.'),
(1452, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 47, 31, 'OT', 'Il dit : « Jure-le-moi. » Et il le lui jura. Puis Israël se prosterna sur la tête du lit.'),
(1453, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 1, 'OT', 'Après ces paroles, on dit à Joseph : Voici, ton père est malade ; et il prit avec lui ses deux fils, Manassé et Éphraïm.'),
(1454, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 2, 'OT', 'On le rapporta à Jacob, et on dit : Voici, ton fils Joseph vient vers toi. Alors Israël rassembla ses forces et s''assit sur le lit.'),
(1455, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 3, 'OT', 'Jacob dit à Joseph : Dieu Tout-Puissant m''est apparu à Luz, dans la terre de Canaan, et il m''a béni.'),
(1456, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 4, 'OT', 'Il m''a dit : Voici, je te rends fécond et je te multiplie, et je te ferai devenir une assemblée de peuples, et je donnerai cette terre à ta postérité après toi, en possession pour toujours.'),
(1457, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 5, 'OT', 'Et maintenant, tes deux fils qui te sont nés dans la terre d''Égypte, avant que je vienne vers toi en Égypte, sont à moi : Éphraïm et Manassé, comme Ruben et Siméon, ils seront à moi.'),
(1458, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 6, 'OT', 'Et ta naissance que tu auras engendrée après eux sera à toi ; c''est sur le nom de leurs frères qu''ils seront appelés dans leur héritage.'),
(1459, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 7, 'OT', 'Et moi, quand je venais de Padan-Aram, Rachel mourut auprès de moi dans la terre de Canaan, sur le chemin, alors qu''il restait encore une petite distance de terre pour arriver à Éphrata ; et je l''enterrai là, sur le chemin d''Éphrata, qui est Bethléhem.'),
(1460, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 8, 'OT', 'Israël vit les fils de Joseph et dit : Qui sont ceux-ci ?'),
(1461, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 9, 'OT', 'Joseph dit à son père : Ce sont mes fils, que Dieu m''a donnés ici. Et il dit : Amène-les, je te prie, vers moi, et je les bénirai.'),
(1462, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 10, 'OT', 'Les yeux d''Israël étaient appesantis par la vieillesse, il ne pouvait pas voir ; il les fit approcher de lui, et il les embrassa et les étreignit.'),
(1463, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 11, 'OT', 'Israël dit à Joseph : Je n''avais pas espéré voir ta face, et voici que Dieu m''a fait voir aussi ta postérité.'),
(1464, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 12, 'OT', 'Joseph les retira d''auprès de ses genoux, et il se prosterna le visage contre terre, dans sa colère.'),
(1465, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 13, 'OT', 'Joseph prit les deux, Éphraïm de sa main droite, à la gauche d''Israël, et Manassé de sa main gauche, à la droite d''Israël, et les fit approcher de lui.'),
(1466, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 14, 'OT', 'Israël étendit sa main droite et la posa sur la tête d''Éphraïm, qui était le plus jeune, et sa main gauche sur la tête de Manassé, croisant ainsi ses mains, car Manassé était le premier-né.'),
(1467, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 15, 'OT', 'Il bénit Joseph et dit : « Le Dieu devant la face duquel ont marché mes pères Abraham et Isaac, le Dieu qui me fait paître depuis ma jeunesse jusqu''à ce jour — »'),
(1468, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 16, 'OT', 'Que l''ange qui me rachète de tout mal bénisse ces jeunes gens, et que mon nom et le nom de mes pères Abraham et Isaac soient invoqués sur eux, et qu''ils multiplient en multitude au milieu de la terre.'),
(1469, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 17, 'OT', 'Joseph vit que son père posait sa main droite sur la tête d''Éphraïm, et cela déplut à ses yeux ; il saisit la main de son père pour l''ôter de dessus la tête d''Éphraïm et la mettre sur la tête de Manassé.'),
(1470, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 18, 'OT', 'Joseph dit à son père : Non, mon père, car celui-ci est le premier-né ; mets ta droite sur sa tête.'),
(1471, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 19, 'OT', 'Son père refusa et dit : Je le sais, mon fils, je le sais ; lui aussi deviendra un peuple, et lui aussi sera grand ; mais son jeune frère sera plus grand que lui, et sa postérité sera le contenu des nations.'),
(1472, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 20, 'OT', 'Il les bénit ce jour-là, en disant : « Par toi Israël bénira, en disant : Que Dieu te fasse comme Éphraïm et comme Manassé. » Et il plaça Éphraïm devant la face de Manassé.'),
(1473, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 21, 'OT', 'Israël dit à Joseph : Voici, je vais mourir ; mais Dieu sera avec vous, et il vous fera revenir vers la terre de vos pères.'),
(1474, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 48, 22, 'OT', 'Et moi, je t''ai donné une épaule de plus qu''à tes frères, que j''ai prise de la main de l''Amoréen avec mon épée et avec mon arc.'),
(1475, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 1, 'OT', 'Jacob appela ses fils et dit : Rassemblez-vous, et je vous annoncerai ce qui vous arrivera à la fin des jours.'),
(1476, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 2, 'OT', 'Rassemblez-vous et écoutez, fils de Jacob, et écoutez Israël, votre père.'),
(1477, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 3, 'OT', 'Ruben, tu es mon premier-né, ma force et le commencement de ma vigueur, le reste de tumeur et le reste de forte.'),
(1478, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 4, 'OT', 'Impétueux comme les eaux, tu ne surpasseras point, car tu es monté sur le lit de ton père ; alors tu as profané ma couche en y montant.'),
(1479, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 5, 'OT', 'Siméon et Lévi sont frères ; leurs ustensiles de violence sont des instruments.'),
(1480, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 6, 'OT', 'Que mon âme n''entre point dans leur conciliabule, que ma gloire ne s''unisse point à leur assemblée, car dans leur colère ils ont tué un homme, et dans leur bienveillance ils ont estropié un bœuf.'),
(1481, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 7, 'OT', 'Maudite soit leur colère, car elle est violente, et leur fureur, car elle est cruelle ; je les diviserai en Jacob et je les disperserai en Israël.'),
(1482, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 8, 'OT', 'Juda, tes frères te loueront ; ta main sera sur le cou de tes ennemis ; les fils de ton père se prosterneront devant toi.'),
(1483, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 9, 'OT', 'Juda est un lionceau ; de la proie, mon fils, tu es monté. Il s''est accroupi, il s''est couché comme un lion, et comme une lionne, qui le fera lever ?'),
(1484, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 10, 'OT', 'Le sceptre ne s''éloignera pas de Juda, ni le législateur d''entre ses pieds, jusqu''à ce que vienne Schilo, et à lui sera l''obéissance des peuples.'),
(1485, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 11, 'OT', 'Il attache son ânon à la vigne, et le fils de son ânesse au plant délicieux ; il lave son vêtement dans le vin, et son manteau dans le sang des raisins.'),
(1486, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 12, 'OT', 'Ses yeux sont plus rouges que le vin, et ses dents plus blanches que le lait.'),
(1487, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 13, 'OT', 'Zabulon habitera sur le rivage des mers, et lui, sur le rivage des navires, et son extrémité touchera Sidon.'),
(1488, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 14, 'OT', 'Issacar est un âne osseux, couché entre les étables.'),
(1489, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 15, 'OT', 'Il vit que le repos était bon, et la terre qu''elle était agréable ; il courba son épaule pour porter, et il devint un serviteur de corvée.'),
(1490, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 16, 'OT', 'Dan jugera son peuple comme l''une des tribus d''Israël.'),
(1491, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 17, 'OT', 'Que Dan soit un serpent sur le chemin, une vipère sur le sentier, qui mord le talon du cheval, et son cavalier tombe en arrière.'),
(1492, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 18, 'OT', 'J''ai espéré ton salut, ô Éternel.'),
(1493, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 19, 'OT', 'Gad, une troupe le talonnera, mais lui talonnera le talon.'),
(1494, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 20, 'OT', 'D''Aser, son pain est gras, et il donnera des délices de roi.'),
(1495, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 21, 'OT', 'Nephthali est une biche lâchée, qui donne de belles paroles.'),
(1496, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 22, 'OT', 'Fils fécond est Joseph, fils fécond près de l''œil ; les filles ont marché sur le mur.'),
(1497, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 23, 'OT', 'Ils l''ont rempli d''amertume, l''ont combattu, et les maîtres des flèches l''ont poursuivi de leur haine.'),
(1498, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 24, 'OT', 'Son arc resta ferme, et les bras de ses mains furent fortifiés par les mains du Puissant de Jacob, de là le berger, la pierre d''Israël.'),
(1499, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 25, 'OT', 'Que le Dieu de ton père te secoure, et que le Tout-Puissant te bénisse, avec les bénédictions des cieux en haut, avec les bénédictions de l''abîme qui est en bas, avec les bénédictions des seins et de la compassion.'),
(1500, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 26, 'OT', 'Les bénédictions de ton père ont surpassé les bénédictions de mes ancêtres, jusqu''à la cime des collines éternelles ; qu''elles soient sur la tête de Joseph et sur le sommet de la tête du naziréen parmi ses frères.'),
(1501, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 27, 'OT', 'Benjamin est un loup qui déchire ; le matin, il dévore la proie, et le soir, il partage le butin.'),
(1502, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 28, 'OT', 'Tous ceux-là sont les tribus d''Israël, douze ; et voici ce que leur père leur dit, et il les bénit : chaque homme selon sa bénédiction, il les bénit.'),
(1503, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 29, 'OT', 'Il leur donna cet ordre et leur dit : « Je vais être recueilli auprès de mon peuple ; enterrez-moi auprès de mes pères, dans la caverne qui est dans le champ d''Éphron le Héthien. »'),
(1504, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 30, 'OT', 'Dans la caverne qui est dans le champ de Macpéla, qui est en face de Mamré, dans la terre de Canaan, qu''Abraham acheta, le champ, d''Éphron le Héthien, pour possession de tombeau.'),
(1505, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 31, 'OT', 'C''est là qu''on a enterré Abraham et Sara, sa femme ; c''est là qu''on a enterré Isaac et Rebecca, sa femme ; et c''est là que j''ai enterré Léa.'),
(1506, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 32, 'OT', 'Les troupeaux du champ et la caverne qui s''y trouve proviennent des fils de Heth.'),
(1507, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 49, 33, 'OT', 'Jacob acheva de donner ses ordres à ses fils, puis il retira ses pieds sur le lit, il rendit l''esprit et fut réuni à son peuple.'),
(1508, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 1, 'OT', 'Joseph tomba sur la face de son père, pleura sur lui et l''embrassa.'),
(1509, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 2, 'OT', 'Joseph ordonna à ses serviteurs, les médecins, d''embaumer son père, et les médecins embaumèrent Israël.'),
(1510, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 3, 'OT', 'On lui consacra quarante jours, car ainsi se remplissent les jours de l''embaumement, et les Égyptiens le pleurèrent soixante-dix jours.'),
(1511, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 4, 'OT', 'Les jours de son deuil passèrent, et Joseph parla à la maison de Pharaon, en disant : Si j''ai trouvé grâce à vos yeux, parlez, je vous prie, aux oreilles de Pharaon, en disant :'),
(1512, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 5, 'OT', 'Mon père m''a fait jurer, en disant : Voici, je meurs ; dans mon tombeau que je me suis creusé dans la terre de Canaan, c''est là que tu m''enseveliras. Maintenant donc, que je monte, je te prie, et j''ensevelirai mon père, puis je reviendrai.'),
(1513, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 6, 'OT', 'Pharaon dit : Monte et enterre ton père, comme il te l''a fait jurer.'),
(1514, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 7, 'OT', 'Joseph monta pour enterrer son père, et avec lui montèrent tous les serviteurs de Pharaon, les anciens de sa maison, et tous les anciens de la terre d''Égypte.'),
(1515, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 8, 'OT', 'Et toute la maison de Joseph, et ses frères, et la maison de son père ; seulement leurs petits enfants, et leurs brebis, et leurs bœufs, ils les laissèrent dans la terre de Gosen.'),
(1516, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 9, 'OT', 'Il monta avec lui aussi des chars et des cavaliers, et le camp était très lourd.'),
(1517, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 10, 'OT', 'Ils arrivèrent jusqu''à l''aire d''Atad, qui est au-delà du Jourdain, et ils y firent un deuil grand et très pesant ; et il fit pour son père un deuil de sept jours.'),
(1518, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 11, 'OT', 'Le Cananéen, habitant de la terre, vit le deuil dans l''aire du buisson d''épines, et ils dirent : « C''est un deuil lourd pour l''Égyptien. » C''est pourquoi on appela son nom Abel-Mitsraïm, qui est au-delà du Jourdain.'),
(1519, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 12, 'OT', 'Ses fils firent pour lui ainsi qu''il le leur avait commandé.'),
(1520, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 13, 'OT', 'Ses fils le portèrent dans la terre de Canaan et l''enterrèrent dans la caverne du champ de Macpéla, qu''Abraham avait achetée, le champ, comme possession de tombeau, à Éphron le Héthien, en face de Mamré.'),
(1521, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 14, 'OT', 'Joseph retourna en Égypte, lui et ses frères, et tous ceux qui étaient montés avec lui pour enterrer son père, après qu''il eut enterré son père.'),
(1522, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 15, 'OT', 'Les frères de Joseph virent que leur père était mort, et ils dirent : « Peut-être Joseph nous haïra-t-il, et il nous rendra certainement tout le mal que nous lui avons fait. »'),
(1523, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 16, 'OT', 'Ils donnèrent cet ordre à Joseph : « Ton père a commandé avant sa mort, en disant : »'),
(1524, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 17, 'OT', 'Ainsi direz-vous à Joseph : « De grâce, pardonne maintenant la transgression de tes frères et leur péché, car ils t''ont fait du mal ; et maintenant, de grâce, pardonne la transgression des serviteurs du Dieu de ton père. » Et Joseph pleura lorsqu''ils lui parlèrent.'),
(1525, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 18, 'OT', 'Ses frères aussi allèrent et tombèrent devant sa face, et ils dirent : Nous voici pour toi comme serviteurs.'),
(1526, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 19, 'OT', 'Joseph leur dit : Ne craignez point ; car suis-je à la place de Dieu ?'),
(1527, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 20, 'OT', 'Quant à vous, vous aviez projeté contre moi un mal, mais Dieu l''a projeté pour un bien, afin de faire comme en ce jour, pour préserver la vie d''un peuple nombreux.'),
(1528, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 21, 'OT', 'Et maintenant, ne craignez point : moi, je vous nourrirai, vous et vos petits enfants. Et il les consola, et il parla à leur cœur.'),
(1529, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 22, 'OT', 'Joseph s''établit en Égypte, lui et la maison de son père, et Joseph vécut cent dix années.'),
(1530, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 23, 'OT', 'Joseph vit les fils d''Éphraïm jusqu''à la troisième génération ; même les fils de Makir, fils de Manassé, naquirent sur les genoux de Joseph.'),
(1531, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 24, 'OT', 'Joseph dit à ses frères : Je vais mourir, mais Dieu ne manquera pas de vous visiter et de vous faire monter de cette terre vers la terre qu''il a jurée à Abraham, à Isaac et à Jacob.'),
(1532, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 25, 'OT', 'Joseph fit jurer les fils d''Israël, en disant : Dieu vous visitera certainement, et vous ferez monter mes os d''ici.'),
(1533, 1, 'GOI_Fr', 'GOI_Fr', 'fr', 'GEN', 50, 26, 'OT', 'Joseph mourut, âgé de cent dix ans, et on l''embauma, et on le mit dans l''arche en Égypte.'),
(1534, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 1, 'OT', 'Voici les noms des fils d''Israël qui vinrent en Égypte avec Jacob, chacun avec sa maison.'),
(1535, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 2, 'OT', 'Ruben, Siméon, Lévi et Juda.'),
(1536, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 3, 'OT', 'Issacar, Zabulon et Benjamin.'),
(1537, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 4, 'OT', 'Dan et Nephthali, Gad et Aser.'),
(1538, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 5, 'OT', 'Toutes les âmes issues du côté de Jacob étaient soixante-dix âmes, et Joseph était en Égypte.'),
(1539, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 6, 'OT', 'Joseph mourut, et tous ses frères, et toute cette génération.'),
(1540, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 7, 'OT', 'Les fils d''Israël furent féconds et pullulèrent, et ils se multiplièrent et devinrent extrêmement, extrêmement puissants, et la terre en fut remplie.'),
(1541, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 8, 'OT', 'Un nouveau roi s''éleva sur l''Égypte, qui ne connaissait pas Joseph.'),
(1542, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 9, 'OT', 'Il dit à son peuple : Voici, le peuple des fils d''Israël est plus nombreux et plus fort que nous.'),
(1543, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 10, 'OT', 'Allons, agissons avec prudence envers lui, de peur qu''il ne se multiplie, et qu''il arrive que, lorsqu''une guerre surviendra, il se joigne aussi à nos ennemis, qu''il combatte contre nous, et qu''il monte hors de la terre.'),
(1544, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 11, 'OT', 'Ils établirent sur eux des chefs de corvée afin de l''affliger par leurs travaux, et ils bâtirent pour Pharaon les villes de magasins, Pithom et Ramsès.'),
(1545, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 12, 'OT', 'Et plus on les opprimait, plus ils se multipliaient et se répandaient ; et ils étaient dégoûtés à cause de la face des fils d''Israël.'),
(1546, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 13, 'OT', 'Les Égyptiens firent servir les fils d''Israël avec dureté.'),
(1547, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 14, 'OT', 'Ils rendirent leur vie amère par un service dur, avec de l''argile et des briques, et par tout service des champs, tout leur service qu''ils leur imposaient avec dureté.'),
(1548, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 15, 'OT', 'Le roi d''Égypte dit aux sages-femmes des Hébreues, dont le nom de l''une était Schiphra, et le nom de la seconde Pua.'),
(1549, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 16, 'OT', 'Il dit : « Quand vous accoucherez les Hébreues, et que vous verrez sur les tours, si c''est un fils, vous le ferez mourir ; mais si c''est une fille, elle vivra. »'),
(1550, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 17, 'OT', 'Les sages-femmes craignirent Dieu, et ne firent pas comme le roi d''Égypte leur avait dit, et elles laissèrent vivre les enfants.'),
(1551, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 18, 'OT', 'Le roi d''Égypte appela les sages-femmes et leur dit : « Pourquoi avez-vous fait cette parole, et avez-vous laissé vivre les enfants ? »'),
(1552, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 19, 'OT', 'Les sages-femmes répondirent à Pharaon : « Parce que les femmes hébreues ne sont pas comme les femmes égyptiennes ; elles sont vigoureuses, et avant que la sage-femme n''arrive auprès d''elles, elles ont déjà enfanté. »'),
(1553, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 20, 'OT', 'Dieu fit du bien aux sages-femmes, et le peuple se multiplia et devint très nombreux.'),
(1554, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 21, 'OT', 'Il arriva que, parce que les sages-femmes craignirent Dieu, il leur fit des maisons.'),
(1555, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 1, 22, 'OT', 'Pharaon donna cet ordre à tout son peuple : « Tout fils qui naîtra, vous le jetterez dans le fleuve, et toute fille, vous la laisserez vivre. »'),
(1556, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 1, 'OT', 'Un homme de la maison de Lévi s''en alla et prit une fille de Lévi.'),
(1557, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 2, 'OT', 'La femme conçut et enfanta un fils ; elle vit qu''il était bon, et elle le cacha trois mois.'),
(1558, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 3, 'OT', 'Elle ne pouvait plus le cacher, elle prit donc pour lui une arche de jonc, la recouvrit de bitume et de poix, y plaça l''enfant, et la déposa dans la mer Rouge, sur la lèvre du fleuve.'),
(1559, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 4, 'OT', 'Sa sœur se tint à distance, pour savoir ce qui lui serait fait.'),
(1560, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 5, 'OT', 'La fille de Pharaon descendit pour se baigner sur le fleuve, et ses jeunes filles marchaient sur la main du fleuve ; elle vit l''arche au milieu du mer Rouge, et elle envoya sa servante et la prit.'),
(1561, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 6, 'OT', 'Elle l''ouvrit, le vit, l''enfant, et voici un jeune garçon qui pleurait ; elle eut compassion de lui et dit : C''est un des enfants des Hébreux.'),
(1562, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 7, 'OT', 'Sa sœur dit à la fille de Pharaon : « Irai-je appeler pour toi une femme nourrice d''entre les Hébreues, afin qu''elle allaite pour toi l''enfant ? »'),
(1563, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 8, 'OT', 'La fille de Pharaon lui dit : « Va ! » Et la jeune fille s''en alla, et elle appela la mère de l''enfant.'),
(1564, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 9, 'OT', 'La fille de Pharaon lui dit : « Emmène cet enfant et allaite-le pour moi, et je te donnerai ton salaire. » La femme prit l''enfant et l''allaita.'),
(1565, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 10, 'OT', 'L''enfant grandit, et elle l''amena à la fille de Pharaon, et il devint pour elle un fils ; et elle appela son nom Moïse, et dit : C''est que des eaux je l''ai retiré.'),
(1566, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 11, 'OT', 'En ces jours-là, Moïse avait grandi, et il sortit vers ses frères et vit leurs travaux ; et il vit un homme égyptien frappant un homme hébreu, l''un de ses frères.'),
(1567, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 12, 'OT', 'Il se retourna de-ci de-là, vit qu''il n''y avait aucun homme, frappa l''Égyptien et le cacha dans le sable.'),
(1568, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 13, 'OT', 'Il sortit le second jour, et voici deux hommes hébreux qui se querellaient ; et il dit au coupable : Pourquoi frappes-tu ton ami ?'),
(1569, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 14, 'OT', 'Il dit : Qui t''a établi homme, chef et juge sur nous ? Est-ce pour me tuer que tu dis cela, comme tu as tué l''Égyptien ? Moïse eut peur et dit : Certainement, la parole est connue.'),
(1570, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 15, 'OT', 'Pharaon entendit cette parole, et il chercha à tuer Moïse ; mais Moïse s''enfuit de devant la face de Pharaon, et il habita dans la terre de Madian, et il s''assit près du puits.'),
(1571, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 16, 'OT', 'Or, le sacrificateur de Madian avait sept filles. Elles vinrent, puisèrent de l''eau, remplirent les abreuvoirs pour abreuver les brebis de leur père.'),
(1572, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 17, 'OT', 'Les bergers vinrent et les chassèrent ; mais Moïse se leva, les secourut, et abreuva leurs brebis.'),
(1573, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 18, 'OT', 'Elles revinrent vers Réuel, leur père, et il dit : Pourquoi êtes-vous revenues si tôt aujourd''hui ?'),
(1574, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 19, 'OT', 'Elles répondirent : Un homme égyptien nous a délivrées de la main des bergers, et même il a puisé de l''eau pour nous, et il a abreuvé les brebis.'),
(1575, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 20, 'OT', 'Il dit à ses filles : Et où est-il ? Pourquoi avez-vous laissé cet homme ? Appelez-le, et qu''il mange du pain.'),
(1576, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 21, 'OT', 'Moïse consentit à demeurer avec l''homme, et il donna Séphora, sa fille, à Moïse.'),
(1577, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 22, 'OT', 'Elle enfanta un fils, et il appela son nom Guerschom, car il dit : J''ai été un étranger dans une terre étrangère.'),
(1578, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 23, 'OT', 'Il advint en ces nombreux jours que le roi d''Égypte mourut, et les fils d''Israël gémirent à cause du service, et ils crièrent ; et leur cri monta vers Dieu, depuis le service.'),
(1579, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 24, 'OT', 'Dieu entendit leur gémissement, et Dieu se souvint de son alliance avec Abraham, avec Isaac et avec Jacob.'),
(1580, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 2, 25, 'OT', 'Dieu vit les fils d''Israël, et Dieu les connut.'),
(1581, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 1, 'OT', 'Moïse faisait paître les brebis de Jéthro, son beau-père, sacrificateur de Madian ; il mena les brebis derrière le désert et vint à la montagne de Dieu, à Horeb.'),
(1582, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 2, 'OT', 'L''ange de l''Éternel lui apparut dans une flamme de feu, du milieu du buisson ; et il regarda, et voici, le buisson brûlait dans le feu, et le buisson n''était point consumé.'),
(1583, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 3, 'OT', 'Moïse dit : « Je vais me détourner maintenant et voir cette grande apparence, pourquoi le buisson ne se consume pas. »'),
(1584, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 4, 'OT', 'L''Éternel vit qu''il se détournait pour regarder, et Dieu l''appela du milieu du buisson, et dit : Moïse, Moïse ! Et il répondit : Me voici.'),
(1585, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 5, 'OT', 'Il dit : N''approche pas d''ici ; ôte tes chaussures de tes pieds, car le lieu sur lequel tu te tiens est une terre sainte.'),
(1586, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 6, 'OT', 'Il dit : Je suis le Dieu de ton père, le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob. Et Moïse cacha sa face, car il craignait de regarder vers Dieu.'),
(1587, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 7, 'OT', 'L''Éternel dit : J''ai vu, j''ai vu l''affliction de mon peuple qui est en Égypte, et j''ai entendu son cri à cause de la face de ses oppresseurs, car je connais sa douleur.'),
(1588, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 8, 'OT', 'Je suis descendu pour le délivrer de la main des Égyptiens et pour le faire monter de cette terre vers une terre bonne et spacieuse, vers une terre ruisselant de lait et de miel, vers le lieu du Cananéen, du Héthien, de l''Amoréen, du Phérézien, de l''Hévien et du Jébusien.'),
(1589, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 9, 'OT', 'Et maintenant, voici, le cri des fils d''Israël est venu jusqu''à moi, et j''ai aussi vu l''oppression dont les Égyptiens les oppriment.'),
(1590, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 10, 'OT', 'Et maintenant, va, et je t''enverrai vers Pharaon, et fais sortir mon peuple, les fils d''Israël, de l''Égypte.'),
(1591, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 11, 'OT', 'Moïse dit à Dieu : Qui suis-je, moi, pour aller vers Pharaon, et pour faire sortir les fils d''Israël de l''Égypte ?'),
(1592, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 12, 'OT', 'Il dit : « Certainement, je serai avec toi, et ceci sera pour toi le signe que c''est moi qui t''ai envoyé : quand tu feras sortir le peuple d''Égypte, vous servirez Dieu sur cette montagne. »'),
(1593, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 13, 'OT', 'Moïse dit à Dieu : « Voici, je vais vers les fils d''Israël, et je leur dirai : Le Dieu de vos pères m''a envoyé vers vous ; et ils me diront : Quel est son nom ? Que leur dirai-je ? »'),
(1594, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 14, 'OT', 'Dieu dit à Moïse : « Je suis celui qui suis. » Puis il dit : « Tu diras ainsi aux fils d''Israël : "Je suis m''a envoyé vers vous." »'),
(1595, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 15, 'OT', 'Dieu dit encore à Moïse : « Tu diras ainsi aux fils d''Israël : l''Éternel, le Dieu de vos pères, le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob, m''a envoyé vers vous ; c''est là mon nom pour toujours, et c''est là ma mémoire de génération en génération. »'),
(1596, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 16, 'OT', 'Va, rassemble les anciens d''Israël, et dis-leur : L''Éternel, le Dieu de vos pères, le Dieu d''Abraham, d''Isaac et de Jacob, m''est apparu, en disant : Je vous ai certainement visités, et j''ai vu ce qui vous est fait en Égypte.'),
(1597, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 17, 'OT', 'Et j''ai dit : je vous ferai monter de l''affliction de l''Égypte vers la terre du Cananéen, du Héthien, de l''Amoréen, du Phérézien, de l''Hévien et du Jébusien, vers une terre ruisselante de lait et de miel.'),
(1598, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 18, 'OT', 'Ils écouteront ta voix, et tu iras, toi et les anciens d''Israël, auprès du roi d''Égypte, et vous lui direz : l''Éternel, le Dieu des Hébreux, s''est présenté à nous ; et maintenant, nous irons donc un chemin de trois jours dans le désert, et nous sacrifierons à l''Éternel, notre Dieu.'),
(1599, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 19, 'OT', 'Et moi, je sais que le roi d''Égypte ne vous laissera pas aller, ni même par une main forte.'),
(1600, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 20, 'OT', 'J''étendrai ma main et je frapperai l''Égyptien par tous mes prodiges que je ferai au milieu de lui ; et après cela, il vous laissera partir.'),
(1601, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 21, 'OT', 'Je donnerai la grâce de ce peuple aux yeux des Égyptiens, et il arrivera que, quand vous partirez, vous ne partirez pas à vide.'),
(1602, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 3, 22, 'OT', 'La femme demandera à sa voisine et à celle qui habite dans sa maison des ustensiles d''argent, des ustensiles d''or et des vêtements ; vous les mettrez sur vos fils et sur vos filles, et vous dépouillerez les Égyptiens.'),
(1603, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 1, 'OT', 'Moïse répondit et dit : Et voici, ils ne me croiront point, et ils n''écouteront point ma voix ; car ils diront : L''Éternel ne t''est point apparu.'),
(1604, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 2, 'OT', 'L''Éternel lui dit : Qu''est-ce que tu as dans ta main ? Et il répondit : Une tribu.'),
(1605, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 3, 'OT', 'Il dit : « Jette-le à terre », et il le jeta à terre, et cela devint un serpent, et Moïse s''enfuit devant sa face.'),
(1606, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 4, 'OT', 'L''Éternel dit à Moïse : Étends ta main et saisis-le par la queue. Il étendit sa main et le saisit, et cela devint une tribu dans sa main.'),
(1607, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 5, 'OT', 'Afin qu''ils croient que l''Éternel, le Dieu de leurs pères, le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob, t''est apparu.'),
(1608, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 6, 'OT', 'L''Éternel lui dit encore : «Mets ta main dans ton sein.» Il mit sa main dans son sein ; puis il la retira, et voici que sa main était lépreuse comme la neige.'),
(1609, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 7, 'OT', 'Il dit : Remets ta main dans ton sein. Et il remit sa main dans son sein ; puis il la retira de son sein, et voici, elle était redevenue comme sa chair.'),
(1610, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 8, 'OT', 'Et il arrivera que, s''ils ne te croient pas et n''écoutent pas la voix du premier signe, ils croiront à la voix du dernier signe.'),
(1611, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 9, 'OT', 'Et il arrivera que, s''ils ne croient pas même à ces deux signes et n''écoutent pas ta voix, tu prendras des eaux du fleuve et tu les verseras sur le sec ; et les eaux que tu auras prises du fleuve deviendront du sang sur la terre sèche.'),
(1612, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 10, 'OT', 'Moïse dit à l''Éternel : « Ah ! Seigneur, je ne suis pas un homme de parole, ni depuis hier ni depuis avant-hier, ni depuis que tu parles à ton serviteur, car j''ai la bouche lourde et la langue lourde. »'),
(1613, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 11, 'OT', 'L''Éternel lui dit : Qui a fait la bouche de l''homme, ou qui rend muet, ou sourd, ou voyant, ou aveugle ? N''est-ce pas moi, l''Éternel ?'),
(1614, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 12, 'OT', 'Maintenant donc, va, et je serai avec ta bouche, et je t''enseignerai ce que tu devras dire.'),
(1615, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 13, 'OT', 'Je t''en prie, Seigneur, envoie par la main que tu enverras.'),
(1616, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 14, 'OT', 'La colère de l''Éternel s''enflamma contre Moïse, et il dit : « N''est-ce pas Aaron, ton frère, le Lévite ? Je sais qu''il parlera, lui. Et voici, il sort à ta rencontre, et quand il te verra, il se réjouira dans son cœur. »'),
(1617, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 15, 'OT', 'Tu lui parleras et mettras les paroles dans sa bouche, et je serai avec ta bouche et avec sa bouche, et je vous enseignerai ce que vous devrez faire.'),
(1618, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 16, 'OT', 'Il te parlera au peuple, et il sera pour toi une bouche, et toi, tu seras pour lui un Dieu.'),
(1619, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 17, 'OT', 'Et prends cette tribu dans ta main, avec laquelle tu feras les signes.'),
(1620, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 18, 'OT', 'Moïse s''en alla et retourna vers Jéther, son beau-père, et lui dit : « Laisse-moi aller, je te prie, et revenir vers mes frères qui sont en Égypte, et voir s''ils sont encore en vie. » Et Jéthro dit à Moïse : « Va en paix. »'),
(1621, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 19, 'OT', 'L''Éternel dit à Moïse en Madian : Va, retourne en Égypte, car tous les hommes qui cherchaient ton âme sont morts.'),
(1622, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 20, 'OT', 'Moïse prit sa femme et ses fils, les fit monter sur l''âne, et retourna vers la terre d''Égypte ; et Moïse prit la tribu de Dieu dans sa main.'),
(1623, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 21, 'OT', 'L''Éternel dit à Moïse : Quand tu retourneras en Égypte, vois tous les prodiges que j''ai mis dans ta main, et tu les feras devant la face de Pharaon ; mais moi, j''endurcirai son cœur, et il ne laissera pas partir le peuple.'),
(1624, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 22, 'OT', 'Tu diras à Pharaon : Ainsi parle l''Éternel : Israël est mon fils, mon premier-né.'),
(1625, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 23, 'OT', 'Je t''ai dit : « Laisse partir mon fils, et qu''il me serve », mais tu as refusé de le laisser partir ; voici, je vais faire périr ton fils, ton premier-né.'),
(1626, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 24, 'OT', 'Il arriva en chemin, dans le lieu de campement, que l''Éternel le rencontra et chercha à le faire mourir.'),
(1627, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 25, 'OT', 'Séphora prit une pierre aiguë, coupa le prépuce de son fils, le toucha à ses pieds, et dit : « Tu es pour moi un gendre de sang. »'),
(1628, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 26, 'OT', 'Alors il le laissa. Elle dit : « Gendre de sang, à cause de la circoncision. »'),
(1629, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 27, 'OT', 'L''Éternel dit à Aaron : Va à la rencontre de Moïse dans le désert. Il partit, le rencontra à la montagne de Dieu, et l''embrassa.'),
(1630, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 28, 'OT', 'Moïse rapporta à Aaron toutes les paroles de l''Éternel, qui l''avait envoyé, et tous les signes qu''il lui avait commandés.'),
(1631, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 29, 'OT', 'Moïse et Aaron allèrent, et ils rassemblèrent tous les anciens des fils d''Israël.'),
(1632, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 30, 'OT', 'Aaron rapporta toutes les paroles que l''Éternel avait dites à Moïse, et il fit les signes aux yeux du peuple.'),
(1633, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 4, 31, 'OT', 'Le peuple crut, et ils entendirent que l''Éternel avait visité les fils d''Israël et qu''il avait vu leur affliction ; alors ils s''inclinèrent et se prosternèrent.'),
(1634, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 1, 'OT', 'Ensuite Moïse et Aaron vinrent et dirent à Pharaon : Ainsi parle l''Éternel, le Dieu d''Israël : Laisse aller mon peuple, et qu''ils célèbrent une fête pour moi dans le désert.'),
(1635, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 2, 'OT', 'Pharaon dit : Qui est l''Éternel, pour que j''écoute sa voix et que je laisse partir Israël ? Je ne connais pas l''Éternel, et même je ne laisserai pas partir Israël.'),
(1636, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 3, 'OT', 'Ils dirent : Le Dieu des Hébreux nous a appelés ; nous irons donc, je te prie, un chemin de trois jours dans le désert, et nous sacrifierons à l''Éternel, notre Dieu, de peur qu''il ne nous frappe de la peste ou de l''épée.'),
(1637, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 4, 'OT', 'Le roi d''Égypte leur dit : Pourquoi, Moïse et Aaron, détournez-vous le peuple de ses œuvres ? Allez à vos travaux.'),
(1638, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 5, 'OT', 'Pharaon dit : Voici, le peuple de la terre est maintenant nombreux, et vous les feriez cesser de leurs travaux.'),
(1639, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 6, 'OT', 'Ce jour-là, Pharaon ordonna aux surveillants du peuple et à ses officiers, en disant :'),
(1640, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 7, 'OT', 'Vous ne continuerez plus à donner de la paille au peuple pour faire des briques comme auparavant ; qu''ils aillent eux-mêmes et ramassent de la paille pour eux.'),
(1641, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 8, 'OT', 'Et la proportion des briques qu''ils faisaient hier et avant-hier, vous la mettrez sur eux ; vous n''en retrancherez rien, car ils sont paresseux ; c''est pourquoi ils crient, disant : Allons, sacrifions à notre Dieu.'),
(1642, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 9, 'OT', 'Que le service pèse sur ces hommes, et qu''ils s''y emploient, et qu''ils ne se fient pas à des paroles de mensonge.'),
(1643, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 10, 'OT', 'Les surveillants du peuple et ses officiers sortirent et parlèrent au peuple, en disant : Ainsi dit Pharaon : Je ne vous donne pas de paille.'),
(1644, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 11, 'OT', 'Allez vous-mêmes, prenez de la paille là où vous en trouverez, car rien ne sera retranché de votre service, pas une parole.'),
(1645, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 12, 'OT', 'Le peuple se dispersa dans toute la terre d''Égypte pour ramasser du chaume en guise de paille.'),
(1646, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 13, 'OT', 'Et les exacteurs pressaient, disant : « Achevez vos œuvres, la parole du jour en son jour, comme lorsqu''il y avait de la paille. »'),
(1647, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 14, 'OT', 'Les surveillants des fils d''Israël, que les exacteurs de Pharaon avaient établis sur eux, furent frappés, et on leur dit : Pourquoi n''avez-vous pas accompli votre statut de fabrication de briques, ni hier ni aujourd''hui, comme auparavant ?'),
(1648, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 15, 'OT', 'Les surveillants des fils d''Israël vinrent et crièrent à Pharaon, en disant : « Pourquoi fais-tu cela à tes serviteurs ? »'),
(1649, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 16, 'OT', 'La paille n''est point donnée à tes serviteurs, et l''on nous dit : Faites des briques ; et voici, tes serviteurs sont frappés, et la faute est de ton peuple.'),
(1650, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 17, 'OT', 'Il dit : Vous êtes oisifs, oisifs ; c''est pourquoi vous dites : Allons sacrifier à l''Éternel.'),
(1651, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 18, 'OT', 'Et maintenant, allez, servez ; la paille ne vous sera point donnée, et vous livrerez la mesure de briques.'),
(1652, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 19, 'OT', 'Les surveillants des fils d''Israël se virent en détresse, disant : « Vous ne retrancherez rien de vos briques, la parole du jour en son jour. »'),
(1653, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 20, 'OT', 'Ils rencontrèrent Moïse et Aaron, qui se tenaient debout pour les accueillir, à leur sortie de chez Pharaon.'),
(1654, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 21, 'OT', 'Ils leur dirent : « Que l''Éternel vous voie et qu''il juge, car vous avez rendu notre odeur fétide aux yeux de Pharaon et aux yeux de ses serviteurs, en mettant une épée dans leur main pour nous tuer. »'),
(1655, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 22, 'OT', 'Moïse retourna vers l''Éternel et dit : Seigneur, pourquoi as-tu fait du mal à ce peuple ? Pourquoi m''as-tu envoyé ?'),
(1656, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 5, 23, 'OT', 'Et depuis que je suis venu vers Pharaon pour parler en ton nom, il a fait du mal à ce peuple, et tu n''as point délivré ton peuple.'),
(1657, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 1, 'OT', 'L''Éternel dit à Moïse : Maintenant tu verras ce que je ferai à Pharaon, car par une main forte il les renverra, et par une main forte il les chassera de sa terre.'),
(1658, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 2, 'OT', 'Dieu parla à Moïse et lui dit : Je suis l''Éternel.'),
(1659, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 3, 'OT', 'Je me suis révélé à Abraham, à Isaac et à Jacob comme Dieu Tout-Puissant, mais mon nom, l''Éternel, je ne me suis pas fait connaître d''eux.'),
(1660, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 4, 'OT', 'Et j''ai aussi établi mon alliance avec eux, pour leur donner la terre de Canaan, la terre de leur séjour, où ils ont séjourné.'),
(1661, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 5, 'OT', 'Et moi aussi, j''ai entendu le gémissement des fils d''Israël, que les Égyptiens font servir, et je me suis souvenu de mon alliance.'),
(1662, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 6, 'OT', 'C''est pourquoi dis aux fils d''Israël : Je suis l''Éternel, et je vous ferai sortir de dessous les travaux de l''Égypte, et je vous délivrerai de leur service, et je vous rachèterai à bras étendu et par de grands jugements.'),
(1663, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 7, 'OT', 'Je vous prendrai pour mon peuple, et je serai pour vous un Dieu ; et vous saurez que je suis l''Éternel, votre Dieu, qui vous fait sortir de dessous les travaux de l''Égypte.'),
(1664, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 8, 'OT', 'Je vous ferai entrer dans la terre que j''ai levé ma main pour la donner à Abraham, à Isaac et à Jacob ; et je vous la donnerai en possession : moi, l''Éternel.'),
(1665, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 9, 'OT', 'Moïse parla ainsi aux fils d''Israël, mais ils n''écoutèrent pas Moïse, à cause de l''angoisse de l''esprit et du service dur.'),
(1666, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 10, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(1667, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 11, 'OT', 'Va, parle à Pharaon, roi d''Égypte, et qu''il laisse partir les fils d''Israël de sa terre.'),
(1668, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 12, 'OT', 'Moïse parla devant l''Éternel, en disant : Voici, les fils d''Israël ne m''ont pas écouté ; et comment Pharaon m''écouterait-il, moi qui ai les lèvres incirconcises ?'),
(1669, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 13, 'OT', 'L''Éternel parla à Moïse et à Aaron, et leur donna des ordres pour les fils d''Israël et pour Pharaon, roi d''Égypte, afin de faire sortir les fils d''Israël de la terre d''Égypte.'),
(1670, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 14, 'OT', 'Voici les chefs de la maison de leurs pères : les fils de Ruben, premier-né d''Israël : Hénoc, Pallu, Hetsron et Carmi. Ce sont les familles de Ruben.'),
(1671, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 15, 'OT', 'Les fils de Siméon : Jemuel, Jamin, Ohad, Jakin, Tsochar et Saül, fils de la Cananéenne ; ce sont là les familles de Siméon.'),
(1672, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 16, 'OT', 'Et voici les noms des fils de Lévi selon leurs générations : Guerschon, Kehath et Merari ; et la vie de Lévi fut de cent trente-sept années.'),
(1673, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 17, 'OT', 'Les fils de Guerschon : Libni et Schimeï, selon leurs familles.'),
(1674, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 18, 'OT', 'Les fils de Kehath : Amram, Jitsehar, Hébron et Uziel ; et la vie de Kehath fut de cent trente-trois années.'),
(1675, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 19, 'OT', 'Les fils de Merari : Machli et Muschi ; ce sont là les familles de Lévi selon leurs générations.'),
(1676, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 20, 'OT', 'Amram prit Jokébed, sa tante, pour femme, et elle lui enfanta Aaron et Moïse ; et la vie d''Amram fut de cent trente-sept années.'),
(1677, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 21, 'OT', 'Les fils de Jitsehar : Koré, Népheg et Zicri.'),
(1678, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 22, 'OT', 'Les fils d''Uziel : Mischaël, Élitsaphan et Sithri.'),
(1679, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 23, 'OT', 'Aaron prit Élischéba, fille d''Amminadab, sœur de Nachschon, pour lui comme femme, et elle lui enfanta Nadab, Abihu, Éléazar et Ithamar.'),
(1680, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 24, 'OT', 'Et les fils de Koré : Assir, Elkana et Abiasaph. Ce sont là les familles des Korhites.'),
(1681, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 25, 'OT', 'Éléazar, fils d''Aaron, prit pour lui une des filles de Puthiel pour femme, et elle lui enfanta Phinées. Ce sont les têtes des pères des Lévites selon leurs familles.'),
(1682, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 26, 'OT', 'C''est cet Aaron et Moïse, à qui l''Éternel dit : Faites sortir les fils d''Israël de la terre d''Égypte selon leurs armées.'),
(1683, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 27, 'OT', 'Ce sont eux qui parlaient à Pharaon, roi d''Égypte, pour faire sortir les fils d''Israël de l''Égypte ; c''est Moïse et Aaron.'),
(1684, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 28, 'OT', 'Il advint, au jour où l''Éternel parla à Moïse dans la terre d''Égypte :'),
(1685, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 29, 'OT', 'L''Éternel parla à Moïse, en disant : Je suis l''Éternel ; parle à Pharaon, roi d''Égypte, tout ce que je te dis.'),
(1686, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 6, 30, 'OT', 'Moïse dit devant l''Éternel : « Voici, j''ai les lèvres incirconcises, et comment Pharaon m''écoutera-t-il ? »'),
(1687, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 1, 'OT', 'L''Éternel dit à Moïse : Vois, je t''ai établi Dieu pour Pharaon, et Aaron, ton frère, sera ton prophète.'),
(1688, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 2, 'OT', 'Tu parleras tout ce que je te commanderai, et Aaron, ton frère, parlera à Pharaon, et il renverra les fils d''Israël de sa terre.'),
(1689, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 3, 'OT', 'Et moi, je rendrai obstiné le cœur de Pharaon, et je multiplierai mes signes et mes prodiges dans la terre d''Égypte.'),
(1690, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 4, 'OT', 'Pharaon ne vous écoutera point, et je mettrai ma main sur l''Égypte, et je ferai sortir mes armées, mon peuple, les fils d''Israël, de la terre d''Égypte, par de grands jugements.'),
(1691, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 5, 'OT', 'Les Égyptiens sauront que je suis l''Éternel, quand j''étendrai ma main sur l''Égypte, et que je ferai sortir les fils d''Israël du milieu d''eux.'),
(1692, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 6, 'OT', 'Moïse et Aaron firent comme l''Éternel le leur avait commandé ; ainsi firent-ils.'),
(1693, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 7, 'OT', 'Moïse était âgé de quatre-vingts ans, et Aaron âgé de quatre-vingt-trois ans, lorsqu''ils parlèrent à Pharaon.'),
(1694, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 8, 'OT', 'L''Éternel dit à Moïse et à Aaron :'),
(1695, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 9, 'OT', 'Lorsque Pharaon vous parlera en disant : « Donnez pour vous des prodiges », tu diras à Aaron : « Prends ta tribu et jette-la devant la face de Pharaon : elle deviendra un chacal. »'),
(1696, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 10, 'OT', 'Moïse et Aaron vinrent vers Pharaon, et ils firent ainsi comme l''Éternel l''avait commandé ; Aaron jeta sa tribu devant la face de Pharaon et devant la face de ses serviteurs, et elle devint un chacal.'),
(1697, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 11, 'OT', 'Pharaon appela aussi les sages et les enchanteurs, et les magiciens d''Égypte firent de même par leurs enchantements.'),
(1698, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 12, 'OT', 'Chacun jeta sa tribu, et elles devinrent des chacals ; et la tribu d''Aaron engloutit leurs tribus.'),
(1699, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 13, 'OT', 'Le cœur de Pharaon s''endurcit, et il ne les écouta point, comme l''Éternel l''avait dit.'),
(1700, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 14, 'OT', 'L''Éternel dit à Moïse : Le cœur de Pharaon est endurci ; il refuse de laisser partir le peuple.'),
(1701, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 15, 'OT', 'Va vers Pharaon au matin ; voici, il sort vers les eaux, et tu te tiendras devant lui sur la lèvre du fleuve, et tu prendras en ta main la tribu qui a été changée en serpent.'),
(1702, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 16, 'OT', 'Tu lui diras : l''Éternel, le Dieu des Hébreux, m''a envoyé vers toi pour dire : Laisse partir mon peuple, afin qu''ils me servent dans le désert ; et voici, tu n''as pas écouté jusqu''à présent.'),
(1703, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 17, 'OT', 'Ainsi parle l''Éternel : À ceci tu connaîtras que je suis l''Éternel. Voici, je frappe avec la tribu qui est dans ma main les eaux qui sont dans le fleuve, et elles seront changées en sang.'),
(1704, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 18, 'OT', 'Les poissons qui sont dans le fleuve mourront, le fleuve deviendra fétide, et les Égyptiens se lasseront de boire des eaux du fleuve.'),
(1705, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 19, 'OT', 'L''Éternel dit à Moïse : Dis à Aaron : Prends ta tribu et étends ta main sur les eaux de l''Égypte, sur leurs fleuves, sur leurs fleuves, et sur leurs étangs, et sur toute espérance de leurs eaux, et elles deviendront du sang ; et il y aura du sang dans toute la terre d''Égypte, dans les bois et dans les pierres.'),
(1706, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 20, 'OT', 'Moïse et Aaron firent ainsi comme l''Éternel l''avait ordonné : il leva la tribu et frappa les eaux qui étaient dans le fleuve, aux yeux de Pharaon et aux yeux de ses serviteurs, et toutes les eaux qui étaient dans le fleuve se changèrent en sang.'),
(1707, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 21, 'OT', 'Le poisson qui était dans le fleuve mourut, et le fleuve devint fétide, et les Égyptiens ne purent boire les eaux du fleuve, et le sang fut dans toute la terre d''Égypte.'),
(1708, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 22, 'OT', 'Les magiciens d''Égypte firent de même par leurs enchantements, et le cœur de Pharaon s''endurcit, et il ne les écouta point, comme l''Éternel l''avait dit.'),
(1709, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 23, 'OT', 'Pharaon se retourna et rentra dans sa maison, et il ne prit pas cela à cœur.'),
(1710, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 24, 'OT', 'Tous les Égyptiens creusèrent aux alentours du fleuve pour trouver des eaux à boire, car ils ne pouvaient pas boire des eaux du fleuve.'),
(1711, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 7, 25, 'OT', 'Et sept jours s''accomplirent après que l''Éternel eut frappé le fleuve.'),
(1712, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 1, 'OT', 'L''Éternel dit à Moïse : Va vers Pharaon, et dis-lui : Ainsi parle l''Éternel : Laisse aller mon peuple, afin qu''ils me servent.'),
(1713, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 2, 'OT', 'Mais si tu refuses de les laisser partir, voici que je frapperai toute ta frontière de grenouilles.'),
(1714, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 3, 'OT', 'Le fleuve fourmillera de grenouilles, et elles monteront et entreront dans ta maison, dans la chambre de ton lit et sur ton lit, dans la maison de tes serviteurs et parmi ton peuple, dans tes fours et dans tes pétrins.'),
(1715, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 4, 'OT', 'Et sur toi, et sur ton peuple, et sur tous tes serviteurs, les grenouilles monteront.'),
(1716, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 5, 'OT', 'L''Éternel dit à Moïse : Dis à Aaron : Étends ta main avec ta tribu sur les fleuves, sur les fleuves et sur les étangs, et fais monter les grenouilles sur la terre d''Égypte.'),
(1717, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 6, 'OT', 'Aaron étendit sa main sur les eaux de l''Égypte, et la grenouille monta et couvrit la terre d''Égypte.'),
(1718, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 7, 'OT', 'Les magiciens firent de même par leurs enchantements, et ils firent monter les grenouilles sur la terre d''Égypte.'),
(1719, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 8, 'OT', 'Pharaon appela Moïse et Aaron, et dit : Implorez l''Éternel, et qu''il retire les grenouilles de moi et de mon peuple ; et je renverrai le peuple, et ils sacrifieront à l''Éternel.'),
(1720, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 9, 'OT', 'Moïse dit à Pharaon : « Glorifie-toi sur moi : pour quand dois-je prier pour toi, pour tes serviteurs et pour ton peuple, afin de retirer les grenouilles de toi et de tes maisons ? Elles ne resteront que dans le fleuve. »'),
(1721, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 10, 'OT', 'Il dit : Demain. Et il dit : Selon ta parole, afin que tu saches qu''il n''y a personne comme l''Éternel, notre Dieu.'),
(1722, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 11, 'OT', 'Les grenouilles se retireront de toi, de tes maisons, de tes serviteurs et de ton peuple ; elles ne resteront que dans le fleuve.'),
(1723, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 12, 'OT', 'Moïse et Aaron sortirent de chez Pharaon, et Moïse cria à l''Éternel au sujet de la parole des grenouilles qu''il avait imposée à Pharaon.'),
(1724, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 13, 'OT', 'L''Éternel fit selon la parole de Moïse, et les grenouilles moururent, hors des maisons, hors des parvis et hors des champs.'),
(1725, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 14, 'OT', 'Ils les entassèrent en monceaux d''argile, monceaux d''argile, et la terre devint fétide.'),
(1726, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 15, 'OT', 'Pharaon vit qu''il y avait un relâche, et il appesantit son cœur, et il ne les écouta point, comme l''Éternel l''avait dit.'),
(1727, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 16, 'OT', 'L''Éternel dit à Moïse : Dis à Aaron : Étends ta tribu et frappe la poussière de la terre, et elle deviendra des poux dans toute la terre d''Égypte.'),
(1728, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 17, 'OT', 'Ils firent ainsi : Aaron étendit sa main avec son bâton et frappa la poussière de la terre, et elle devint des poux sur l''homme et sur le bétail ; toute la poussière de la terre devint des poux dans tout le pays d''Égypte.'),
(1729, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 18, 'OT', 'Les magiciens firent de même avec leurs enchantements pour faire sortir les poux, mais ils ne le purent pas ; et les poux furent sur l''homme et sur le bétail.'),
(1730, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 19, 'OT', 'Les magiciens dirent à Pharaon : « C''est le doigt de Dieu. » Mais le cœur de Pharaon s''endurcit, et il ne les écouta point, comme l''Éternel l''avait dit.'),
(1731, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 20, 'OT', 'L''Éternel dit à Moïse : Lève-toi de bon matin, tiens-toi devant la face de Pharaon ; voici, il sort vers les eaux ; et tu lui diras : Ainsi parle l''Éternel : Laisse aller mon peuple, afin qu''il me serve.'),
(1732, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 21, 'OT', 'Car si tu ne laisses pas partir mon peuple, voici que je fais venir sur toi, sur tes serviteurs, sur ton peuple et dans tes maisons les mouches ; et les maisons des Égyptiens seront remplies de mouches, et aussi la terre sur laquelle ils se trouvent.'),
(1733, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 22, 'OT', 'Et je distinguerai en ce jour-là la terre de Gosen, où mon peuple demeure, afin qu''il n''y ait point là de mouches, pour que tu saches que je suis l''Éternel au milieu de la terre.'),
(1734, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 23, 'OT', 'Je mettrai une rédemption entre mon peuple et ton peuple ; demain sera ce signe.'),
(1735, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 24, 'OT', 'L''Éternel fit ainsi, et une nuée de mouches pesante vint dans la maison de Pharaon et dans la maison de ses serviteurs, et dans toute la terre d''Égypte ; la terre fut corrompue à cause de la face des mouches.'),
(1736, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 25, 'OT', 'Pharaon appela Moïse et Aaron, et dit : Allez, sacrifiez à votre Dieu dans la terre.'),
(1737, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 26, 'OT', 'Moïse dit : Il n''est pas convenable de faire ainsi, car nous sacrifierions l''abomination des Égyptiens à l''Éternel, notre Dieu ; voici, si nous sacrifions l''abomination des Égyptiens devant leurs yeux, ne nous lapideront-ils pas ?'),
(1738, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 27, 'OT', 'Nous ferons trois jours de chemin dans le désert, et nous sacrifierons à l''Éternel, notre Dieu, comme il nous le dira.'),
(1739, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 28, 'OT', 'Pharaon dit : « Je vous laisserai partir, et vous sacrifierez à l''Éternel, votre Dieu, dans le désert ; seulement, ne vous éloignez pas trop en allant ; intercédez pour moi. »'),
(1740, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 29, 'OT', 'Moïse dit : Voici, je sors de chez toi, et je supplierai l''Éternel, et les mouches se retireront de Pharaon, de ses serviteurs et de son peuple, demain ; seulement, que Pharaon ne continue pas à tromper, en refusant de laisser aller le peuple pour sacrifier à l''Éternel.'),
(1741, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 30, 'OT', 'Moïse sortit de chez Pharaon et implora l''Éternel.'),
(1742, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 31, 'OT', 'L''Éternel fit selon la parole de Moïse, et il retira les mouches de Pharaon, de ses serviteurs et de son peuple ; il n''en resta pas une seule.'),
(1743, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 8, 32, 'OT', 'Pharaon endurcit aussi son cœur cette fois-ci, et il ne laissa point partir le peuple.'),
(1744, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 1, 'OT', 'L''Éternel dit à Moïse : Va vers Pharaon et dis-lui : Ainsi parle l''Éternel, le Dieu des Hébreux : Laisse aller mon peuple, afin qu''ils me servent.'),
(1745, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 2, 'OT', 'Car si tu refuses de les laisser partir, et que tu les retiens encore,'),
(1746, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 3, 'OT', 'Voici, la main de l''Éternel sera sur tes troupeaux qui sont dans le champ, sur les chevaux, sur les ânes, sur les chameaux, sur les bœufs et sur les brebis : une peste très lourde.'),
(1747, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 4, 'OT', 'L''Éternel fera une distinction entre les troupeaux d''Israël et les troupeaux d''Égypte, et il ne mourra rien de tout ce qui appartient aux fils d''Israël, pas une seule parole.'),
(1748, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 5, 'OT', 'L''Éternel fixa une assignation, en disant : Demain, l''Éternel fera cette parole dans la terre.'),
(1749, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 6, 'OT', 'L''Éternel fit cette parole dès le lendemain, et tout le troupeau des Égyptiens mourut ; mais du troupeau des fils d''Israël, pas un seul ne mourut.'),
(1750, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 7, 'OT', 'Pharaon envoya, et voici, il n''était mort aucun des troupeaux d''Israël, pas même un seul ; mais le cœur de Pharaon s''endurcit, et il ne laissa point aller le peuple.'),
(1751, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 8, 'OT', 'L''Éternel dit à Moïse et à Aaron : Prenez pour vous le contenu de vos poignées de cendre de fournaise, et que Moïse la jette vers les cieux aux yeux de Pharaon.'),
(1752, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 9, 'OT', 'Cela deviendra de la poussière sur toute la terre d''Égypte, et cela sera sur l''homme et sur le bétail un ulcère qui éclôt en ulcères sur toute la terre d''Égypte.'),
(1753, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 10, 'OT', 'Ils prirent de la cendre de la fournaise, et se tinrent devant la face de Pharaon ; Moïse la jeta vers les cieux, et il y eut des ulcères, des ulcères bourgeonnants, sur l''homme et sur le bétail.'),
(1754, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 11, 'OT', 'Les magiciens ne purent se tenir devant la face de Moïse à cause de l''ulcère, car l''ulcère était sur les magiciens et sur tout Égyptien.'),
(1755, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 12, 'OT', 'L''Éternel endurcit le cœur de Pharaon, et Pharaon ne les écouta point, selon ce que l''Éternel avait dit à Moïse.'),
(1756, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 13, 'OT', 'L''Éternel dit à Moïse : Lève-toi de bon matin, tiens-toi devant la face de Pharaon, et dis-lui : Ainsi parle l''Éternel, le Dieu des Hébreux : Laisse aller mon peuple, et qu''ils me servent.'),
(1757, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 14, 'OT', 'Car cette fois, je fais venir toutes mes plaies sur ton cœur, sur tes serviteurs et sur ton peuple, à cause de cela tu sauras qu''il n''y a personne comme moi dans toute la terre.'),
(1758, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 15, 'OT', 'Car maintenant, j''ai étendu ma main et je t''ai frappé, toi et ton peuple, par la peste, et tu aurais été retranché de la terre.'),
(1759, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 16, 'OT', 'Mais en vérité, c''est à cause de cela que je t''ai établi : à cause de te montrer ma force, et afin que mon nom soit proclamé dans toute la terre.'),
(1760, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 17, 'OT', 'Toi, tu t''élèves encore contre mon peuple, pour ne pas les laisser partir.'),
(1761, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 18, 'OT', 'Voici, je fais tomber à ce temps demain une grêle très lourde, telle qu''il n''y en a pas eu en Égypte depuis le jour où elle fut fondée jusqu''à maintenant.'),
(1762, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 19, 'OT', 'Et maintenant, envoie rassembler tes troupeaux et tout ce qui est à toi dans le champ ; tout homme et bétail qui se trouvera dans le champ et qui ne sera pas rentré à la maison, la grêle descendra sur eux, et ils mourront.'),
(1763, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 20, 'OT', 'Celui qui craignait la parole de l''Éternel parmi les serviteurs de Pharaon fit fuir ses serviteurs et ses troupeaux dans les maisons.'),
(1764, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 21, 'OT', 'Mais celui qui ne prit pas à cœur la parole de l''Éternel laissa ses serviteurs et ses troupeaux dans le champ.'),
(1765, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 22, 'OT', 'L''Éternel dit à Moïse : Étends ta main vers les cieux, et qu''il y ait de la grêle dans toute la terre d''Égypte, sur l''homme et sur le bétail, et sur toute herbe des champs dans la terre d''Égypte.'),
(1766, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 23, 'OT', 'Moïse étendit sa tribu vers les cieux, et l''Éternel donna des voix et de la grêle, et le feu se répandit sur la terre ; et l''Éternel fit tomber de la grêle sur la terre d''Égypte.'),
(1767, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 24, 'OT', 'Il y eut de la grêle, et un feu qui se mêlait au milieu de la grêle, très lourd, tel qu''il n''y en avait pas eu dans toute la terre d''Égypte depuis qu''elle était devenue une nation.'),
(1768, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 25, 'OT', 'La grêle frappa dans toute la terre d''Égypte tout ce qui était dans le champ, depuis l''homme jusqu''au bétail ; et la grêle frappa toute l''herbe des champs, et elle brisa tout bois des champs.'),
(1769, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 26, 'OT', 'Seulement dans la terre de Gosen, où étaient les fils d''Israël, il n''y eut point de grêle.'),
(1770, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 27, 'OT', 'Pharaon envoya appeler Moïse et Aaron, et leur dit : J''ai péché cette fois ; l''Éternel est juste, et moi et mon peuple nous sommes coupables.'),
(1771, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 28, 'OT', 'Implorez l''Éternel, car il y a beaucoup de voix de Dieu et de grêle ; je vous renverrai, et vous ne continuerez plus à rester.'),
(1772, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 29, 'OT', 'Moïse lui dit : Dès que je sortirai de la ville, j''étendrai mes mains vers l''Éternel ; les voix cesseront, et il n''y aura plus de grêle, afin que tu saches que la terre est à l''Éternel.'),
(1773, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 30, 'OT', 'Mais toi et tes serviteurs, je sais que vous ne craignez pas encore devant la face de l''Éternel Dieu.'),
(1774, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 31, 'OT', 'Le lin et l''orge furent frappés, car l''orge était en épis et le lin en floraison.'),
(1775, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 32, 'OT', 'Le froment et l''épeautre ne furent point frappés, car ils étaient tardifs.'),
(1776, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 33, 'OT', 'Moïse sortit de chez Pharaon, hors de la ville, et étendit ses mains vers l''Éternel ; les voix et la grêle cessèrent, et la pluie ne tomba pas sur la terre.'),
(1777, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 34, 'OT', 'Pharaon vit que la pluie, la grêle et les voix avaient cessé, et il continua de pécher ; il appesantit son cœur, lui et ses serviteurs.'),
(1778, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 9, 35, 'OT', 'Le cœur de Pharaon s''endurcit, et il ne renvoya pas les fils d''Israël, comme l''Éternel l''avait dit par la main de Moïse.'),
(1779, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 1, 'OT', 'L''Éternel dit à Moïse : Va vers Pharaon, car moi, j''ai alourdi son cœur et le cœur de ses serviteurs, afin de mettre ces mes signes au milieu de lui.'),
(1780, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 2, 'OT', 'afin que tu racontes aux oreilles de ton fils et du fils de ton fils ce que j''ai fait en Égypte, et mes signes que j''ai placés au milieu d''eux, et que vous sachiez que je suis l''Éternel.'),
(1781, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 3, 'OT', 'Moïse et Aaron vinrent vers Pharaon et lui dirent : Ainsi parle l''Éternel, le Dieu des Hébreux : Jusqu''à quand refuseras-tu de t''humilier devant ma face ? Laisse aller mon peuple, et qu''ils me servent.'),
(1782, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 4, 'OT', 'Mais si tu refuses de laisser partir mon peuple, voici que je ferai venir demain des sauterelles dans ta frontière.'),
(1783, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 5, 'OT', 'Il couvrira l''œil de la terre, et on ne pourra pas voir la terre ; il dévorera le reste des réchappés qui vous demeure de la grêle, et il dévorera tout le bois qui croît pour vous dans le champ.'),
(1784, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 6, 'OT', 'Tes maisons seront remplies, ainsi que les maisons de tous tes serviteurs et les maisons de tous les Égyptiens, ce que n''ont vu ni tes pères ni les pères de tes pères, depuis le jour où ils furent sur la terre jusqu''à ce jour-ci. Puis il se retourna et sortit de devant Pharaon.'),
(1785, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 7, 'OT', 'Les serviteurs de Pharaon lui dirent : « Jusqu''à quand cela sera-t-il pour nous un piège ? Laisse partir les hommes, et qu''ils servent l''Éternel, leur Dieu. Ne sais-tu pas encore que l''Égypte est perdue ? »'),
(1786, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 8, 'OT', 'Moïse et Aaron furent ramenés vers Pharaon, et il leur dit : Allez, servez l''Éternel, votre Dieu ; qui et qui sont ceux qui iront ?'),
(1787, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 9, 'OT', 'Moïse dit : « Nous irons avec nos jeunes et nos anciens, avec nos fils et nos filles, avec nos brebis et nos bœufs nous irons, car c''est pour nous une fête de l''Éternel. »'),
(1788, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 10, 'OT', 'Il leur dit : « Que l''Éternel soit avec vous, comme je vous laisserai partir, vous et vos petits enfants ; voyez que le mal est devant votre face. »'),
(1789, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 11, 'OT', 'Non pas ainsi ; allez donc, vous les hommes, et servez l''Éternel, car c''est cela que vous demandez. Et on les chassa de devant la face de Pharaon.'),
(1790, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 12, 'OT', 'L''Éternel dit à Moïse : Étends ta main sur la terre d''Égypte pour la sauterelle, et elle montera sur la terre d''Égypte, et elle mangera toute l''herbe de la terre, tout ce que la grêle a laissé.'),
(1791, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 13, 'OT', 'Moïse étendit sa verge sur la terre d''Égypte, et l''Éternel fit souffler un vent d''orient sur la terre tout ce jour-là et toute la nuit ; le matin vint, et le vent d''orient avait porté la sauterelle.'),
(1792, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 14, 'OT', 'La sauterelle monta sur toute la terre d''Égypte et se posa dans toutes les frontières de l''Égypte, très lourdement ; devant elle, il n''y avait pas eu de sauterelle semblable, et après elle, il n''y en aura pas de telle.'),
(1793, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 15, 'OT', 'Et il couvrit l''œil de toute la terre, et la terre s''obscurcit ; et il mangea toute l''herbe de la terre et tout le fruit du bois que la grêle avait laissé, et il ne resta aucune herbe verte dans le bois ni dans l''herbe du champ, dans toute la terre d''Égypte.'),
(1794, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 16, 'OT', 'Pharaon se hâta d''appeler Moïse et Aaron, et dit : J''ai péché contre l''Éternel, votre Dieu, et contre vous.'),
(1795, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 17, 'OT', 'Et maintenant, pardonne, je te prie, mon péché seulement cette fois, et suppliez l''Éternel, votre Dieu, afin qu''il retire de moi seulement cette mort.'),
(1796, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 18, 'OT', 'Il sortit de devant Pharaon et pria l''Éternel.'),
(1797, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 19, 'OT', 'L''Éternel fit souffler un vent de mer très fort, et il emporta les sauterelles et les jeta dans la mer Rouge ; il ne resta pas une seule sauterelle dans toute la frontière de l''Égypte.'),
(1798, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 20, 'OT', 'L''Éternel endurcit le cœur de Pharaon, et il ne laissa pas partir les fils d''Israël.'),
(1799, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 21, 'OT', 'L''Éternel dit à Moïse : Étends ta main vers les cieux, et qu''il y ait des ténèbres sur la terre d''Égypte, et que l''on puisse toucher les ténèbres.'),
(1800, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 22, 'OT', 'Moïse étendit sa main vers les cieux, et il y eut des ténèbres épaisses sur toute la terre d''Égypte, trois jours.'),
(1801, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 23, 'OT', 'Nul homme ne vit son frère, et nul ne se leva de sa place pendant trois jours ; mais pour tous les fils d''Israël, il y avait de la lumière dans leurs habitations.'),
(1802, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 24, 'OT', 'Pharaon appela Moïse et dit : Allez, servez l''Éternel ; seulement vos brebis et vos bœufs resteront ; même vos petits enfants iront avec vous.'),
(1803, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 25, 'OT', 'Moïse dit : « Toi aussi, tu mettras en nos mains des sacrifices et des holocaustes, et nous les offrirons à l''Éternel, notre Dieu. »'),
(1804, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 26, 'OT', 'Et même nos troupeaux iront avec nous ; il n''en restera pas une corne du pied, car c''est d''eux que nous prendrons pour servir l''Éternel, notre Dieu ; et nous ne savons pas avec quoi nous servirons l''Éternel, jusqu''à ce que nous arrivions là.'),
(1805, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 27, 'OT', 'L''Éternel endurcit le cœur de Pharaon, et il ne voulut pas les laisser partir.'),
(1806, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 28, 'OT', 'Pharaon lui dit : Va-t''en de devant moi ; garde-toi de ne plus voir ma face, car au jour où tu verras ma face, tu mourras.'),
(1807, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 10, 29, 'OT', 'Moïse dit : Tu as bien parlé ; je ne verrai plus ta face.'),
(1808, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 1, 'OT', 'L''Éternel dit à Moïse : « Je ferai venir encore une plaie sur Pharaon et sur l''Égypte ; après cela, il vous laissera partir d''ici ; lorsqu''il vous laissera partir, il vous chassera d''ici avec un anéantissement complet. »'),
(1809, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 2, 'OT', 'Parle maintenant aux oreilles du peuple, et que chaque homme demande à son ami, et chaque femme à sa compagne, des ustensiles d''argent et des ustensiles d''or.'),
(1810, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 3, 'OT', 'L''Éternel accorda la grâce du peuple aux yeux des Égyptiens, et l''homme Moïse était très grand dans la terre d''Égypte aux yeux des serviteurs de Pharaon et aux yeux du peuple.'),
(1811, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 4, 'OT', 'Moïse dit : « Ainsi parle l''Éternel : au milieu de la nuit, je sortirai au milieu de l''Égypte. »'),
(1812, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 5, 'OT', 'Et tout premier-né dans la terre d''Égypte mourra, depuis le premier-né de Pharaon qui est assis sur son trône, jusqu''au premier-né de la servante qui est derrière la meule, et tout premier-né du bétail.'),
(1813, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 6, 'OT', 'Il y aura un grand cri dans toute la terre d''Égypte, tel qu''il n''y en a point eu et tel qu''il n''y en aura plus.'),
(1814, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 7, 'OT', 'Et pour tous les fils d''Israël, aucun chien ne remuera sa langue, ni contre un homme ni contre le bétail, afin que vous sachiez que l''Éternel fait une distinction entre l''Égypte et Israël.'),
(1815, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 8, 'OT', 'Tous tes serviteurs que voici descendront vers moi et se prosterneront devant moi, en disant : « Sors, toi et tout le peuple qui est à tes pieds ! » Et après cela, je sortirai. Et il sortit de chez Pharaon dans l''ardeur de la colère.'),
(1816, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 9, 'OT', 'L''Éternel dit à Moïse : Pharaon ne vous écoutera point, afin que mes prodiges se multiplient dans la terre d''Égypte.'),
(1817, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 11, 10, 'OT', 'Moïse et Aaron firent tous ces prodiges devant la face de Pharaon ; et l''Éternel endurcit le cœur de Pharaon, et il ne laissa point partir les fils d''Israël de sa terre.'),
(1818, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 1, 'OT', 'L''Éternel dit à Moïse et à Aaron dans la terre d''Égypte, en disant :'),
(1819, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 2, 'OT', 'Ce mois-ci sera pour vous la tête des mois ; il est pour vous le premier des mois de l''année.'),
(1820, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 3, 'OT', 'Parlez à toute l''assemblée d''Israël, en disant : Au dixième jour de ce mois, que chaque homme prenne pour lui un agneau pour la maison des pères, un agneau pour la maison.'),
(1821, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 4, 'OT', 'Et si la maison est trop petite pour un agneau, il le prendra, lui et son voisin le plus proche de sa maison, selon l''estimation des âmes ; chacun selon sa bouche, selon sa nourriture, vous compterez pour l''agneau.'),
(1822, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 5, 'OT', 'L''agneau sera pour vous sans défaut, un mâle d''un an ; vous le prendrez d''entre les agneaux et d''entre les chèvres.'),
(1823, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 6, 'OT', 'Ce sera pour vous une observance jusqu''au quatorzième jour de ce mois, et toute l''assemblée de l''assemblée d''Israël le sacrifiera entre les deux soirs.'),
(1824, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 7, 'OT', 'Ils prendront du sang et le mettront sur les deux poteaux et sur le linteau, sur les maisons où ils le mangeront.'),
(1825, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 8, 'OT', 'Ils mangeront la chair cette nuit-là, rôtie au feu, et des pains sans levain ; avec des herbes d''amertume ils la mangeront.'),
(1826, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 9, 'OT', 'Ne mangez point de cela cru, ni bouilli dans les eaux, mais seulement rôti au feu, sa tête sur ses jambes et sur son milieu.'),
(1827, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 10, 'OT', 'N''en laisserez rien jusqu''au matin, et ce qui en restera jusqu''au matin, vous le brûlerez au feu.'),
(1828, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 11, 'OT', 'Et vous le mangerez ainsi : vos reins ceints, vos chaussures à vos pieds, et votre bâton en votre main ; et vous le mangerez en hâte : c''est la Pâque de l''Éternel.'),
(1829, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 12, 'OT', 'Je passerai par la terre d''Égypte cette nuit-là, et je frapperai tout premier-né dans la terre d''Égypte, depuis l''homme jusqu''au bétail ; et sur tous les dieux de l''Égypte j''exécuterai des jugements : moi, l''Éternel.'),
(1830, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 13, 'OT', 'Le sang vous servira de signe sur les maisons où vous êtes ; je verrai le sang, et je passerai par-dessus vous, et il n''y aura parmi vous aucune plaie de destruction quand je frapperai la terre d''Égypte.'),
(1831, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 14, 'OT', 'Ce jour sera pour vous un mémorial, et vous le célébrerez comme une fête en l''honneur de l''Éternel ; vous le célébrerez comme une loi perpétuelle pour vos générations, à toujours.'),
(1832, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 15, 'OT', 'Pendant sept jours vous mangerez des pains sans levain ; mais au premier jour vous ôterez le levain de vos maisons, car quiconque mangera du levain, cette âme-là sera retranchée d''Israël, depuis le premier jour jusqu''au septième jour.'),
(1833, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 16, 'OT', 'Le premier jour sera pour vous une sainte convocation, et le septième jour sera pour vous une sainte convocation ; on ne fera en eux aucun ouvrage, mais seulement ce qui se mangera pour toute âme, cela seul se fera pour vous.'),
(1834, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 17, 'OT', 'Vous garderez les pains sans levain, car en ce jour même, en son os, j''ai fait sortir vos armées de la terre d''Égypte ; et vous garderez ce jour pour vos générations comme une loi pour toujours.'),
(1835, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 18, 'OT', 'Au premier mois, le quatorzième jour du mois, au soir, vous mangerez des pains sans levain, jusqu''au vingt et unième jour du mois, au soir.'),
(1836, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 19, 'OT', 'Pendant sept jours, il ne se trouvera point de levain dans vos maisons; car quiconque mangera du pain levé, cette âme-là sera retranchée de l''assemblée d''Israël, tant l''étranger que l''autochtone de la terre.'),
(1837, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 20, 'OT', 'Vous ne mangerez aucune chose levée ; dans toutes vos habitations, vous mangerez des pains sans levain.'),
(1838, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 21, 'OT', 'Moïse convoqua tous les anciens d''Israël et leur dit : Tirez et prenez pour vous des brebis selon vos familles, et sacrifiez la Pâque.'),
(1839, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 22, 'OT', 'Vous prendrez un faisceau d''Hysope, vous le tremperez dans le sang qui est sur le seuil, et vous toucherez le linteau et les deux poteaux avec le sang qui est sur le seuil ; et vous ne sortirez pas, aucun homme de l''entrée de sa maison, jusqu''au matin.'),
(1840, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 23, 'OT', 'L''Éternel passera pour frapper l''Égypte, et il verra le sang sur le linteau et sur les deux poteaux, et l''Éternel protégera l''entrée, et il ne laissera pas la destruction entrer dans vos maisons pour frapper.'),
(1841, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 24, 'OT', 'Vous garderez cette parole comme un statut pour toi et pour tes fils, jusqu''à toujours.'),
(1842, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 25, 'OT', 'Il arrivera que, lorsque vous entrerez dans la terre que l''Éternel vous donnera, comme il l''a dit, vous observerez ce service.'),
(1843, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 26, 'OT', 'Il arrivera que lorsque vos fils vous diront : « Quel est ce service pour vous ? »'),
(1844, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 27, 'OT', 'Vous direz : c''est le sacrifice de la Pâque pour l''Éternel, qui a passé par-dessus les maisons des fils d''Israël en Égypte, lorsqu''il frappait l''Égypte, et qui a délivré nos maisons. Et le peuple s''inclina et se prosterna.'),
(1845, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 28, 'OT', 'Les fils d''Israël partirent et firent comme l''Éternel l''avait commandé à Moïse et à Aaron ; ainsi ils firent.'),
(1846, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 29, 'OT', 'Il arriva qu''à la moitié de la nuit, l''Éternel frappa tout premier-né dans la terre d''Égypte, depuis le premier-né de Pharaon qui était assis sur son trône, jusqu''au premier-né du captif qui était dans la maison de la citerne, et tout premier-né du bétail.'),
(1847, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 30, 'OT', 'Pharaon se leva de nuit, lui et tous ses serviteurs et toute l''Égypte, et il y eut un grand cri en Égypte, car il n''y avait pas de maison où il n''y eût un mort.'),
(1848, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 31, 'OT', 'Il appela Moïse et Aaron pendant la nuit et dit : Levez-vous, sortez du milieu de mon peuple, vous et les fils d''Israël, et allez servir l''Éternel, comme vous l''avez dit.'),
(1849, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 32, 'OT', 'Prenez aussi vos brebis et aussi vos bœufs, comme vous l''avez dit, et allez-vous-en ; et bénissez-moi aussi.'),
(1850, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 33, 'OT', 'Les Égyptiens pressèrent le peuple, pour les renvoyer en hâte de la terre, car ils disaient : Nous sommes tous morts.'),
(1851, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 34, 'OT', 'Le peuple emporta sa pâte avant qu''elle ne fût levée, leurs pétrins liés dans leurs vêtements sur leurs épaules.'),
(1852, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 35, 'OT', 'Les fils d''Israël firent selon la parole de Moïse, et ils demandèrent aux Égyptiens des ustensiles d''argent, des ustensiles d''or et des vêtements.'),
(1853, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 36, 'OT', 'L''Éternel donna la grâce du peuple aux yeux de l''Égypte, et ils leur prêtèrent ; et ils dépouillèrent l''Égypte.'),
(1854, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 37, 'OT', 'Les fils d''Israël partirent de Ramsès vers Succoth, environ six cent mille hommes de pied, seuls, sans compter les petits enfants.'),
(1855, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 38, 'OT', 'Et aussi une grande trame monta avec eux, et des brebis et des bœufs, des troupeaux très nombreux.'),
(1856, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 39, 'OT', 'Ils firent cuire la pâte qu''ils avaient sortie d''Égypte en galettes de pains sans levain, car elle n''avait pas levé ; parce qu''ils avaient été chassés d''Égypte et ne pouvaient pas s''attarder, et ils ne s''étaient pas non plus préparé de provisions.'),
(1857, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 40, 'OT', 'L''habitation des fils d''Israël, qui demeurèrent en Égypte, fut de trente ans et de quatre cents ans.'),
(1858, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 41, 'OT', 'Il arriva qu''au bout de trente ans et quatre cents ans, en ce jour même, toutes les armées de l''Éternel sortirent de la terre d''Égypte.'),
(1859, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 42, 'OT', 'C''est une nuit de veille pour l''Éternel, pour les faire sortir de la terre d''Égypte ; cette nuit-là est pour l''Éternel une veille pour tous les fils d''Israël, selon leurs générations.'),
(1860, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 43, 'OT', 'L''Éternel dit à Moïse et à Aaron : Voici la loi de la Pâque : tout fils d''étranger n''en mangera point.'),
(1861, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 44, 'OT', 'Tout serviteur d''homme, acquisition d''argent, tu le circonciras ; alors il en mangera.'),
(1862, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 45, 'OT', 'L''étranger et le salarié n''en mangeront point.'),
(1863, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 46, 'OT', 'Dans une seule maison elle sera mangée ; tu ne sortiras point de la maison de la chair au dehors, et vous ne briserez aucun os en elle.'),
(1864, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 47, 'OT', 'Toute l''assemblée d''Israël la fera.'),
(1865, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 48, 'OT', 'Et si un étranger séjourne chez toi et veut faire la Pâque pour l''Éternel, que tout mâle lui soit circoncis, et alors il s''approchera pour la faire, et il sera comme l''autochtone de la terre ; mais aucun incirconcis n''en mangera.'),
(1866, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 49, 'OT', 'Une seule loi sera pour l''autochtone et pour l''étranger qui séjourne au milieu de vous.'),
(1867, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 50, 'OT', 'Tous les fils d''Israël firent comme l''Éternel l''avait commandé à Moïse et à Aaron ; ainsi firent-ils.'),
(1868, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 12, 51, 'OT', 'Il advint, en ce même jour, que l''Éternel fit sortir les fils d''Israël de la terre d''Égypte selon leurs armées.'),
(1869, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(1870, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 2, 'OT', 'Consacre-moi tout premier-né, tout ce qui ouvre la matrice parmi les fils d''Israël, tant de l''homme que du bétail ; c''est à moi.'),
(1871, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 3, 'OT', 'Moïse dit au peuple : Souviens-toi de ce jour où vous êtes sortis d''Égypte, de la maison de servitude, car c''est par la force de la main que l''Éternel vous a fait sortir de là ; et l''on ne mangera point de levain.'),
(1872, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 4, 'OT', 'Aujourd''hui vous sortez au mois des épis.'),
(1873, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 5, 'OT', 'Et il arrivera que, lorsque l''Éternel t''aura fait entrer dans la terre du Cananéen, du Héthien, de l''Amoréen, de l''Hévien et du Jébusien, qu''il a juré à tes pères de te donner, une terre ruisselant de lait et de miel, tu accompliras ce service en ce mois.'),
(1874, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 6, 'OT', 'Pendant sept jours tu mangeras des pains sans levain, et au septième jour il y aura une fête pour l''Éternel.'),
(1875, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 7, 'OT', 'Des pains sans levain seront mangés pendant les sept jours, et il ne sera pas vu chez toi de levain, et il ne sera pas vu chez toi de levain dans toute ta frontière.'),
(1876, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 8, 'OT', 'Tu raconteras à ton fils, en ce jour-là, en disant : À cause de cela, l''Éternel a agi pour moi, quand je suis sorti d''Égypte.'),
(1877, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 9, 'OT', 'Ce sera pour toi un signe sur ta main et un mémorial entre tes yeux, afin que la loi de l''Éternel soit dans ta bouche, car c''est par une main forte que l''Éternel t''a fait sortir d''Égypte.'),
(1878, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 10, 'OT', 'Tu garderas cette loi en son assignation, de jours en jours.'),
(1879, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 11, 'OT', 'Et il arrivera que lorsque l''Éternel t''aura fait entrer dans la terre du Cananéen, comme il te l''a juré, à toi et à tes pères, et qu''il te l''aura donnée,'),
(1880, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 12, 'OT', 'Tu feras passer à l''Éternel tout premier-né de la matrice, et tout premier-né du petit du bétail qui sera à toi : les mâles seront à l''Éternel.'),
(1881, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 13, 'OT', 'Tout premier-né d''âne, tu le rachèteras avec un agneau ; et si tu ne le rachètes pas, tu lui briseras la nuque ; et tout premier-né d''homme parmi tes fils, tu le rachèteras.'),
(1882, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 14, 'OT', 'Et il arrivera que lorsque ton fils te demandera demain, en disant : « Qu''est-ce que cela ? » tu lui diras : « Par la force de la main, l''Éternel nous a fait sortir d''Égypte, de la maison des serviteurs. »'),
(1883, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 15, 'OT', 'Il arriva que, lorsque Pharaon refusa de nous laisser partir, l''Éternel frappa tout premier-né dans la terre d''Égypte, depuis le premier-né de l''homme jusqu''au premier-né du bétail ; c''est pourquoi je sacrifie à l''Éternel tout premier-né de la matrice, les mâles, et je rachète tout premier-né de mes fils.'),
(1884, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 16, 'OT', 'Et ce sera un signe sur ta main et des fronteaux entre tes yeux, car par la force de la main l''Éternel nous a fait sortir d''Égypte.'),
(1885, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 17, 'OT', 'Il advint que, lorsque Pharaon laissa partir le peuple, Dieu ne les conduisit point par le chemin de la terre des Philistins, car il était proche ; car Dieu dit : De peur que le peuple ne se repente en voyant la guerre, et qu''ils ne retournent en Égypte.'),
(1886, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 18, 'OT', 'Dieu fit faire au peuple un détour par le chemin du désert vers la mer Rouge ; et les fils d''Israël montèrent en armes de la terre d''Égypte.'),
(1887, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 19, 'OT', 'Moïse prit avec lui les os de Joseph, car Joseph avait fait jurer les fils d''Israël, en disant : Dieu vous visitera certainement, et vous ferez monter mes os d''ici avec vous.'),
(1888, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 20, 'OT', 'Ils partirent de Succoth et campèrent à Étham, à l''extrémité du désert.'),
(1889, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 21, 'OT', 'L''Éternel allait devant eux, le jour dans un pilier de nuée pour les conduire sur le chemin, et la nuit dans un pilier de feu pour les éclairer, afin qu''ils marchent de jour et de nuit.'),
(1890, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 13, 22, 'OT', 'La colonne de nuée ne s''éloignait pas de devant le peuple, ni le pilier de feu durant la nuit, de devant la face du peuple.'),
(1891, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(1892, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 2, 'OT', 'Parle aux fils d''Israël, et qu''ils se retournent et campent devant Pi-Hahiroth, entre Migdol et la mer, devant Baal-Tsephon ; en face de lui vous camperez près de la mer.'),
(1893, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 3, 'OT', 'Pharaon dira des fils d''Israël : Ils sont égarés dans la terre ; le désert les a enfermés.'),
(1894, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 4, 'OT', 'Je fortifierai le cœur de Pharaon, et il poursuivra après eux, et je serai honoré en Pharaon et en toute sa force, et les Égyptiens sauront que je suis l''Éternel. Et ils firent ainsi.'),
(1895, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 5, 'OT', 'On annonça au roi d''Égypte que le peuple s''était enfui, et le cœur de Pharaon et de ses serviteurs se retourna contre le peuple, et ils dirent : Qu''avons-nous fait, en laissant partir Israël de notre service ?'),
(1896, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 6, 'OT', 'Il attela son char et prit son peuple avec lui.'),
(1897, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 7, 'OT', 'Il prit six cents chars d''élite, et tous les chars de l''Égypte, et des officiers sur chacun d''eux.'),
(1898, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 8, 'OT', 'L''Éternel endurcit le cœur de Pharaon, roi d''Égypte, et il poursuivit les fils d''Israël ; mais les fils d''Israël sortaient à main levée.'),
(1899, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 9, 'OT', 'Les Égyptiens les poursuivirent et les atteignirent campés près de la mer, tous les chevaux, les chars de Pharaon, ses cavaliers et sa force, près de Pi-Hahiroth, devant Baal-Tsephon.'),
(1900, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 10, 'OT', 'Pharaon s''approcha, et les fils d''Israël levèrent leurs yeux, et voici que les Égyptiens marchaient après eux, et ils eurent très peur, et les fils d''Israël crièrent à l''Éternel.'),
(1901, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 11, 'OT', 'Ils dirent à Moïse : « N''y avait-il pas de tombeaux en Égypte, que tu nous a pris pour mourir dans le désert ? Qu''est-ce que tu nous as fait, en nous faisant sortir d''Égypte ? »'),
(1902, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 12, 'OT', 'N''est-ce pas là la parole que nous t''avions dite en Égypte, en disant : Laisse-nous, et nous servirons les Égyptiens ? Car il vaut mieux pour nous servir les Égyptiens que de mourir dans le désert.'),
(1903, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 13, 'OT', 'Moïse dit au peuple : Ne craignez pas ; tenez-vous fermes, et voyez le salut de l''Éternel, qu''il accomplira pour vous aujourd''hui ; car les Égyptiens que vous avez vus aujourd''hui, vous ne les reverrez plus jamais, jusqu''à toujours.'),
(1904, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 14, 'OT', 'L''Éternel combattra pour vous, et vous, vous resterez silencieux.'),
(1905, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 15, 'OT', 'L''Éternel dit à Moïse : Pourquoi cries-tu vers moi ? Parle aux fils d''Israël, et qu''ils se mettent en marche.'),
(1906, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 16, 'OT', 'Et toi, lève ta tribu et étends ta main sur la mer et fends-la ; et les fils d''Israël entreront au milieu de la mer sur le sec.'),
(1907, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 17, 'OT', 'Et moi, voici que je fortifierai le cœur des Égyptiens, et ils viendront après eux, et je serai glorifié en Pharaon et en toute sa force, en son char et en ses cavaliers.'),
(1908, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 18, 'OT', 'Les Égyptiens sauront que je suis l''Éternel, quand je serai glorifié aux dépens de Pharaon, de son char et de ses cavaliers.'),
(1909, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 19, 'OT', 'L''ange de Dieu qui marchait devant le camp d''Israël se déplaça et alla derrière eux, et le pilier de nuée se déplaça de devant eux et se tint derrière eux.'),
(1910, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 20, 'OT', 'Il vint entre le camp de l''Égypte et le camp d''Israël, et la nuée et les ténèbres furent là, et elle éclaira la nuit ; et l''un ne s''approcha point de l''autre pendant toute la nuit.'),
(1911, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 21, 'OT', 'Moïse étendit sa main sur la mer, et l''Éternel fit reculer la mer par un vent d''orient fort toute la nuit, et il mit la mer en terre sèche, et les eaux se fendirent.'),
(1912, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 22, 'OT', 'Les fils d''Israël entrèrent au milieu de la mer sur le sec, et les eaux leur furent une muraille à leur droite et à leur gauche.'),
(1913, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 23, 'OT', 'Les Égyptiens les poursuivirent et entrèrent après eux, tout cheval de Pharaon, ses chars et ses cavaliers, au milieu de la mer.'),
(1914, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 24, 'OT', 'Il advint, à la veille du matin, que l''Éternel regarda vers le camp des Égyptiens depuis un pilier de feu et de nuée, et il troubla le camp des Égyptiens.'),
(1915, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 25, 'OT', 'Il ôta les roues de ses chars et les fit avancer avec une marche difficile, et l''Égypte dit : « Fuyons devant la face d''Israël, car l''Éternel combat pour eux contre l''Égypte. »'),
(1916, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 26, 'OT', 'L''Éternel dit à Moïse : Étends ta main sur la mer, et les eaux reviendront sur l''Égypte, sur son char et sur ses cavaliers.'),
(1917, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 27, 'OT', 'Moïse étendit sa main sur la mer, et la mer revint à sa force vers le matin, et l''Égypte fuyait à sa rencontre, et l''Éternel secoua l''Égypte au milieu de la mer.'),
(1918, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 28, 'OT', 'Les eaux revinrent et couvrirent le char et les cavaliers, toute la force de Pharaon qui était venue après eux dans la mer ; il n''en resta pas un seul.'),
(1919, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 29, 'OT', 'Les fils d''Israël marchèrent sur le sec au milieu de la mer, et les eaux leur furent une muraille à leur droite et à leur gauche.'),
(1920, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 30, 'OT', 'L''Éternel sauva en ce jour-là Israël de la main de l''Égypte, et Israël vit l''Égypte morte sur la lèvre de la mer.'),
(1921, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 14, 31, 'OT', 'Israël vit la grande main que l''Éternel avait exercée contre l''Égypte, et le peuple craignit l''Éternel, et ils crurent en l''Éternel et en Moïse, son serviteur.'),
(1922, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 1, 'OT', 'Alors Moïse et les fils d''Israël chantèrent ce cantique à l''Éternel, et ils dirent en parlant : Je chanterai à l''Éternel, car il s''est hautement élevé ; le cheval et son cavalier, il les a jetés dans la mer.'),
(1923, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 2, 'OT', 'Ma force et mes louanges, c''est l''Éternel, et il est devenu mon salut ; c''est mon Dieu, et je le glorifierai, le Dieu de mon père, et je l''exalterai.'),
(1924, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 3, 'OT', 'L''Éternel est un homme de guerre ; l''Éternel est son nom.'),
(1925, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 4, 'OT', 'Les chars de Pharaon et sa force, il les a jetés dans la mer, et l''élite de ses officiers a été engloutie dans la mer Rouge.'),
(1926, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 5, 'OT', 'Les abîmes les couvrent ; ils descendent dans les profondeurs comme une pierre.'),
(1927, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 6, 'OT', 'Ta droite, ô Éternel, est majestueuse en force ; ta droite, ô Éternel, écrase l''ennemi.'),
(1928, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 7, 'OT', 'Et dans la multitude de ton orgueil, tu renverses tes adversaires ; tu envoies ta fureur, elle les consume comme le chaume.'),
(1929, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 8, 'OT', 'Par le souffle de ton esprit, les eaux se sont amoncelées, les courants se sont dressés comme un monceau, les abîmes ont gelé au cœur de la mer, par ta colère.'),
(1930, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 9, 'OT', 'L''ennemi a dit : Je poursuivrai, j''atteindrai, je partagerai le butin ; mon âme se rassasiera d''eux ; je tirerai mon épée, ma main les détruira.'),
(1931, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 10, 'OT', 'Tu as soufflé de ton esprit, la mer les a couverts ; ils ont sombré comme du plomb dans les eaux puissantes.'),
(1932, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 11, 'OT', 'Qui est comme toi parmi les dieux, ô Éternel ? Qui est comme toi, majestueux dans le saint, redoutable en louanges, auteur de prodiges ?'),
(1933, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 12, 'OT', 'Tu as étendu ta droite ; la terre les a engloutis.'),
(1934, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 13, 'OT', 'Tu as conduit par ta bonté ce peuple que tu as racheté ; tu l''as guidé par ta force vers la demeure de ton saint.'),
(1935, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 14, 'OT', 'Les peuples l''ont entendu, ils tremblent ; la douleur a saisi les habitants de la Philistie.'),
(1936, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 15, 'OT', 'Alors les chefs d''Édom furent épouvantés ; les béliers de Moab furent saisis de tremblement ; tous les habitants de Canaan se fondirent.'),
(1937, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 16, 'OT', 'La terreur et la frayeur tomberont sur eux ; par la grandeur de ton bras, ils seront muets comme une pierre, jusqu''à ce que ton peuple passe, ô Éternel, jusqu''à ce que passe le peuple que tu as acquis.'),
(1938, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 17, 'OT', 'Tu les feras entrer et les planteras sur la montagne de ton héritage, demeure que tu as faite, ô Éternel, sanctuaire, ô Seigneur, que tes mains ont établi.'),
(1939, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 18, 'OT', 'L''Éternel régnera pour toujours et pour l''éternité.'),
(1940, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 19, 'OT', 'Car le cheval de Pharaon entra dans la mer avec son char et ses cavaliers, et l''Éternel ramena sur eux les eaux de la mer ; mais les fils d''Israël marchèrent sur le sec au milieu de la mer.'),
(1941, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 20, 'OT', 'Marie, la prophétesse, sœur d''Aaron, prit le tambourin dans sa main, et toutes les femmes sortirent après elle avec des tambourins et des danses.'),
(1942, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 21, 'OT', 'Et Marie leur répondit : Chantez à l''Éternel, car il s''est hautement élevé ; le cheval et son cavalier, il les a jetés dans la mer.'),
(1943, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 22, 'OT', 'Moïse fit partir Israël de la mer Rouge, et ils sortirent vers le désert de Schur ; ils marchèrent trois jours dans le désert, et ils ne trouvèrent point d''eaux.'),
(1944, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 23, 'OT', 'Ils arrivèrent à Mara, et ils ne purent boire des eaux de Mara, car elles étaient amères ; c''est pourquoi on appela son nom Mara.'),
(1945, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 24, 'OT', 'Le peuple murmura contre Moïse, en disant : Que boirons-nous ?'),
(1946, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 25, 'OT', 'Il cria à l''Éternel, et l''Éternel lui montra un bois, qu''il jeta dans les eaux, et les eaux devinrent douces. Là, il établit pour lui un statut et un jugement, et là il le mit à l''épreuve.'),
(1947, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 26, 'OT', 'Il dit : Si tu écoutes attentivement la voix de l''Éternel, ton Dieu, et que tu fais ce qui est droit à ses yeux, et que tu prêtes l''oreille à ses commandements, et que tu gardes tous ses statuts, je ne mettrai sur toi aucune des maladies que j''ai mises sur l''Égypte, car je suis l''Éternel, ton guérisseur.'),
(1948, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 15, 27, 'OT', 'Ils arrivèrent à Élim, et là il y avait douze yeux d''eaux et soixante-dix palmiers, et ils campèrent là près des eaux.'),
(1949, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 1, 'OT', 'Ils partirent d''Élim, et toute l''assemblée des fils d''Israël arriva au désert de Sin, qui est entre Élim et Sinaï, le quinzième jour du second mois, après leur sortie de la terre d''Égypte.'),
(1950, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 2, 'OT', 'Toute l''assemblée des fils d''Israël murmura contre Moïse et contre Aaron dans le désert.'),
(1951, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 3, 'OT', 'Les fils d''Israël leur dirent : Que ne sommes-nous morts par la main de l''Éternel dans la terre d''Égypte, quand nous étions assis près du chaudron de chair, quand nous mangions du pain à rassasiement ! Car vous nous avez fait sortir vers ce désert pour faire mourir par la famine toute cette assemblée.'),
(1952, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 4, 'OT', 'L''Éternel dit à Moïse : Voici, je fais pleuvoir pour vous du pain des cieux, et le peuple sortira et recueillera la parole d''un jour pour chaque jour, afin que je l''éprouve, pour voir s''il marchera dans ma loi ou non.'),
(1953, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 5, 'OT', 'Il arrivera, le sixième jour, qu''ils prépareront ce qu''ils auront apporté, et il y aura le second par-dessus ce qu''ils ramasseront jour après jour.'),
(1954, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 6, 'OT', 'Moïse et Aaron dirent à tous les fils d''Israël : Au soir, vous saurez que l''Éternel vous a fait sortir de la terre d''Égypte.'),
(1955, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 7, 'OT', 'Et au matin, vous verrez la gloire de l''Éternel, lorsqu''il aura entendu vos murmures contre l''Éternel ; et nous, que sommes-nous, que vous murmuriez contre nous ?'),
(1956, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 8, 'OT', 'Moïse dit : Quand l''Éternel vous donnera le soir de la chair à manger, et du pain au matin pour vous rassasier, parce que l''Éternel entend vos murmures que vous murmurez contre lui, et nous, que sommes-nous ? Ce n''est pas contre nous que sont vos murmures, mais contre l''Éternel.'),
(1957, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 9, 'OT', 'Moïse dit à Aaron : « Dis à toute l''assemblée des fils d''Israël : Approchez-vous devant la face de l''Éternel, car il a entendu vos murmures. »'),
(1958, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 10, 'OT', 'Il arriva, comme Aaron parlait à toute l''assemblée des fils d''Israël, qu''ils se tournèrent vers le désert, et voici, la gloire de l''Éternel apparut dans la nuée.'),
(1959, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 11, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(1960, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 12, 'OT', 'J''ai entendu les murmures des fils d''Israël ; parle-leur, en disant : Entre les deux soirs vous mangerez de la chair, et au matin vous serez rassasiés de pain, et vous saurez que je suis l''Éternel, votre Dieu.'),
(1961, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 13, 'OT', 'Le soir, les cailles montèrent et couvrirent le camp, et au matin il y avait une couche de rosée tout alentour du camp.'),
(1962, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 14, 'OT', 'La couche de rosée se leva, et voici, sur la face du désert, une fine substance écailleuse, fine comme la coupe sur la terre.'),
(1963, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 15, 'OT', 'Les fils d''Israël virent, et ils se dirent l''un à l''autre, chaque homme à son frère : « Qu''est-ce que cela ? » car ils ne savaient pas ce que c''était. Et Moïse leur dit : « C''est le pain que l''Éternel vous a donné pour nourriture. »'),
(1964, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 16, 'OT', 'Voici la parole que l''Éternel a commandée : recueillez-en, chaque homme selon sa bouche, selon sa nourriture ; une gerbe par tête, selon le nombre de vos âmes, chaque homme pour ceux qui sont dans sa tente, vous prendrez.'),
(1965, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 17, 'OT', 'Les fils d''Israël firent ainsi, et ils recueillirent, l''un plus, l''autre moins.'),
(1966, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 18, 'OT', 'Ils mesurèrent avec la gerbe, et celui qui avait beaucoup n''eut pas de surplus, et celui qui avait peu ne manqua de rien ; chaque homme, selon sa bouche, pour sa nourriture, ils recueillirent.'),
(1967, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 19, 'OT', 'Moïse leur dit : qu''aucun homme n''en laisse rien jusqu''au matin.'),
(1968, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 20, 'OT', 'Ils n''écoutèrent pas Moïse, et des hommes en gardèrent une partie jusqu''au matin ; cela produisit des vers cramoisis et cela devint fétide, et Moïse s''irrita contre eux.'),
(1969, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 21, 'OT', 'Ils le ramassaient chaque matin, chaque matin, chacun selon sa bouche de nourriture ; et quand le soleil devenait chaud, il fondait.'),
(1970, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 22, 'OT', 'Le sixième jour, ils ramassèrent du pain en double, deux omers pour chacun ; et tous les princes de l''assemblée vinrent et le rapportèrent à Moïse.'),
(1971, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 23, 'OT', 'Il leur dit : « C''est ce que l''Éternel a déclaré : demain est un repos solennel, un sabbat saint pour l''Éternel ; ce que vous devez cuire, cuisez-le, et ce que vous devez faire bouillir, faites-le bouillir, et tout ce qui reste, déposez-le pour vous en observance jusqu''au matin. »'),
(1972, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 24, 'OT', 'Ils le laissèrent jusqu''au matin, comme Moïse l''avait commandé, et il ne devint pas fétide, et il n''y avait point de ver en lui.'),
(1973, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 25, 'OT', 'Moïse dit : Mangez-le aujourd''hui, car aujourd''hui est un sabbat pour l''Éternel ; aujourd''hui vous ne le trouverez pas dans le champ.'),
(1974, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 26, 'OT', 'Six jours vous le ramasserez, et au septième jour, c''est un sabbat ; il n''y en aura point en ce jour-là.'),
(1975, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 27, 'OT', 'Le septième jour, des gens du peuple sortirent pour ramasser, mais ils n''en trouvèrent point.'),
(1976, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 28, 'OT', 'L''Éternel dit à Moïse : Jusqu''à quand refuserez-vous de garder mes commandements et mes lois ?'),
(1977, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 29, 'OT', 'Voyez que l''Éternel vous a donné le sabbat ; c''est pourquoi il vous donne au sixième jour du pain pour deux jours ; demeurez chacun chez vous, que personne ne sorte de son lieu au septième jour.'),
(1978, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 30, 'OT', 'Le peuple se reposa le septième jour.'),
(1979, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 31, 'OT', 'La maison d''Israël appela son nom manne, et elle était comme de la postérité de coriandre, blanche, et son goût était comme une galette au miel.'),
(1980, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 32, 'OT', 'Moïse dit : Voici la parole que l''Éternel a commandée : un contenu de gerbe de lui, pour observance pour vos générations, afin qu''ils voient le pain que je vous ai fait manger dans le désert, quand je vous ai fait sortir de la terre d''Égypte.'),
(1981, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 33, 'OT', 'Moïse dit à Aaron : Prends un vase, mets-y un contenu de gerbe de manne, et dépose-le devant la face de l''Éternel, en observance pour vos générations.'),
(1982, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 34, 'OT', 'Comme l''Éternel l''avait commandé à Moïse, Aaron le déposa devant le témoignage, pour l''observance.'),
(1983, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 35, 'OT', 'Les fils d''Israël mangèrent la manne quarante ans, jusqu''à leur arrivée dans une terre habitée ; ils mangèrent la manne jusqu''à leur arrivée à l''extrémité de la terre de Canaan.'),
(1984, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 16, 36, 'OT', 'La gerbe est le dixième de l''épha.'),
(1985, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 1, 'OT', 'Toute l''assemblée des fils d''Israël partit du désert de Sin, selon leurs marches, sur la bouche de l''Éternel, et ils campèrent à Rephidim, et il n''y avait pas d''eaux pour que le peuple boive.'),
(1986, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 2, 'OT', 'Le peuple querella avec Moïse et dit : Donne-nous des eaux, et nous boirons. Et Moïse leur dit : Pourquoi me querellez-vous ? Pourquoi tentez-vous l''Éternel ?'),
(1987, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 3, 'OT', 'Le peuple eut soif là, des eaux, et le peuple murmura contre Moïse, et dit : Pourquoi cela nous as-tu fait monter d''Égypte, pour me faire mourir, moi, mes fils et mes troupeaux, par la soif ?'),
(1988, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 4, 'OT', 'Moïse cria à l''Éternel, en disant : Que ferai-je à ce peuple ? Encore un peu, et ils me lapideront.'),
(1989, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 5, 'OT', 'L''Éternel dit à Moïse : Passe devant la face du peuple, et prends avec toi des anciens d''Israël ; et ta tribu, avec laquelle tu as frappé le fleuve, prends-la dans ta main et va.'),
(1990, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 6, 'OT', 'Me voici, je me tiens devant toi, là, sur le rocher, à Horeb ; tu frapperas le rocher, et il en sortira des eaux, et le peuple boira. Et Moïse fit ainsi aux yeux des anciens d''Israël.'),
(1991, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 7, 'OT', 'Il appela le nom du lieu Massa et Meriba, à cause du procès des fils d''Israël et parce qu''ils avaient mis l''Éternel à l''épreuve, en disant : « L''Éternel est-il au milieu de nous, ou non ? »'),
(1992, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 8, 'OT', 'Amalek vint et combattit contre Israël à Rephidim.'),
(1993, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 9, 'OT', 'Moïse dit à Josué : Choisis-nous des hommes, et sors, combats contre Amalek ; demain, je me tiendrai sur le sommet de la colline, et la tribu de Dieu sera dans ma main.'),
(1994, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 10, 'OT', 'Josué fit comme Moïse lui avait dit, pour combattre contre Amalek ; et Moïse, Aaron et Hur montèrent au sommet de la colline.'),
(1995, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 11, 'OT', 'Et il arrivait que lorsque Moïse levait sa main, Israël était le plus fort ; et lorsqu''il laissait retomber sa main, Amalek était le plus fort.'),
(1996, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 12, 'OT', 'Les mains de Moïse étaient pesantes, et ils prirent une pierre et la placèrent sous lui, et il s''assit dessus ; et Aaron et Hur soutenaient ses mains, l''un d''un côté et l''autre de l''autre côté, et ses mains furent en fidélité jusqu''au coucher du soleil.'),
(1997, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 13, 'OT', 'Josué défit Amalek et son peuple par la bouche de l''épée.'),
(1998, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 14, 'OT', 'L''Éternel dit à Moïse : Écris cela comme mémorial dans le livre, et mets-le dans les oreilles de Josué, car j''effacerai entièrement la mémoire d''Amalek de dessous les cieux.'),
(1999, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 15, 'OT', 'Moïse bâtit un autel et lui donna pour nom : l''Éternel-ma-bannière.'),
(2000, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 17, 16, 'OT', 'Il dit : « La main sur le trône de l''Éternel : guerre de l''Éternel contre Amalek, de génération en génération. »'),
(2001, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 1, 'OT', 'Jéthro, sacrificateur de Madian, beau-père de Moïse, apprit tout ce que Dieu avait fait pour Moïse et pour Israël, son peuple, et que l''Éternel avait fait sortir Israël d''Égypte.'),
(2002, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 2, 'OT', 'Jéthro, beau-père de Moïse, prit Séphora, femme de Moïse, après son présent de mariage.'),
(2003, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 3, 'OT', 'et ses deux fils, dont le nom de l''un était Guerschom, car il dit : « J''ai été un étranger dans une terre étrangère. »'),
(2004, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 4, 'OT', 'Et le nom de l''autre était Éliézer, car le Dieu de mon père a été mon secours, et il m''a délivré de l''épée de Pharaon.'),
(2005, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 5, 'OT', 'Jéthro, beau-père de Moïse, vint avec ses fils et sa femme auprès de Moïse, au désert où il campait, à la montagne de Dieu.'),
(2006, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 6, 'OT', 'Il dit à Moïse : Moi, Jéthro, ton beau-père, je viens vers toi, avec ta femme et ses deux fils avec elle.'),
(2007, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 7, 'OT', 'Moïse sortit à la rencontre de son beau-père, se prosterna et l''embrassa, et ils se demandèrent l''un à l''autre, chaque homme à son ami, des nouvelles de leur paix, puis ils entrèrent dans la tente.'),
(2008, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 8, 'OT', 'Moïse raconta à son beau-père tout ce que l''Éternel avait fait à Pharaon et à l''Égypte à cause d''Israël, toute la peine qui les avait atteints sur le chemin, et comment l''Éternel les avait délivrés.'),
(2009, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 9, 'OT', 'Jéthro se réjouit de tout le bien que l''Éternel avait fait à Israël, de ce qu''il l''avait délivré de la main de l''Égypte.'),
(2010, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 10, 'OT', 'Jéthro dit : « Béni soit l''Éternel, qui vous a délivrés de la main de l''Égypte et de la main de Pharaon, qui a délivré le peuple de dessous la main de l''Égypte. »'),
(2011, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 11, 'OT', 'Maintenant je sais que l''Éternel est plus grand que tous les dieux, car dans la parole par laquelle ils ont agi avec arrogance contre eux.'),
(2012, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 12, 'OT', 'Jéthro, beau-père de Moïse, offrit un holocauste et des sacrifices à Dieu ; puis Aaron et tous les anciens d''Israël vinrent manger du pain avec le beau-père de Moïse devant Dieu.'),
(2013, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 13, 'OT', 'Le lendemain, Moïse s''assit pour juger le peuple, et le peuple se tint devant Moïse depuis le matin jusqu''au soir.'),
(2014, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 14, 'OT', 'Le beau-père de Moïse vit tout ce qu''il faisait pour le peuple, et il dit : « Quelle est cette parole que tu fais pour le peuple ? Pourquoi es-tu assis seul, et tout le peuple se tient devant toi, depuis le matin jusqu''au soir ? »'),
(2015, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 15, 'OT', 'Moïse dit à son beau-père : « Parce que le peuple vient à moi pour consulter Dieu. »'),
(2016, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 16, 'OT', 'Quand ils ont une parole, elle vient à moi, et je juge entre un homme et son ami, et je fais connaître les statuts de Dieu et ses lois.'),
(2017, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 17, 'OT', 'Le beau-père de Moïse lui dit : Ce n''est pas une bonne parole que celle que tu fais.'),
(2018, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 18, 'OT', 'Tu t''épuiseras certainement, toi aussi, et ce peuple aussi qui est avec toi, car la parole est trop lourde pour toi ; tu ne pourras pas la faire seul.'),
(2019, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 19, 'OT', 'Écoute maintenant ma voix, je te conseillerai, et que Dieu soit avec toi ; sois toi-même pour le peuple devant Dieu, et porte toi-même les paroles à Dieu.'),
(2020, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 20, 'OT', 'Tu les avertiras des statuts et des lois, et tu leur feras connaître le chemin par lequel ils doivent marcher et l''œuvre qu''ils doivent accomplir.'),
(2021, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 21, 'OT', 'Et toi, choisis parmi tout le peuple des hommes de force, craignant Dieu, des hommes de vérité, haïssant le gain, et établis-les sur eux comme chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines.'),
(2022, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 22, 'OT', 'Ils jugeront le peuple en tout temps ; et il arrivera que toute grande parole ils t''apporteront, et toute petite parole ils la jugeront eux-mêmes ; et ils allégeront ce qui pèse sur toi, et ils le porteront avec toi.'),
(2023, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 23, 'OT', 'Si tu fais cette parole, et que Dieu te le commande, tu pourras subsister, et aussi tout ce peuple arrivera en paix à son lieu.'),
(2024, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 24, 'OT', 'Moïse écouta la voix de son beau-père et fit tout ce qu''il avait dit.'),
(2025, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 25, 'OT', 'Moïse choisit des hommes de force parmi tout Israël, et les établit comme têtes sur le peuple : chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines.'),
(2026, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 26, 'OT', 'Ils jugeaient le peuple en tout temps ; la parole difficile, ils la portaient à Moïse, et toute parole petite, ils la jugeaient eux-mêmes.'),
(2027, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 18, 27, 'OT', 'Moïse renvoya son beau-père, et il s''en alla vers sa terre.'),
(2028, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 1, 'OT', 'Au troisième mois de la sortie des fils d''Israël de la terre d''Égypte, en ce jour-là, ils arrivèrent au désert de Sinaï.'),
(2029, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 2, 'OT', 'Ils partirent de Rephidim, arrivèrent au désert de Sinaï, et campèrent dans le désert ; et Israël campa là, en face de la montagne.'),
(2030, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 3, 'OT', 'Moïse monta vers Dieu, et l''Éternel l''appela du haut de la montagne, en disant : Tu diras ainsi à la maison de Jacob, et tu annonceras aux fils d''Israël.'),
(2031, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 4, 'OT', 'Vous avez vu ce que j''ai fait à l''Égypte, et je vous ai portés sur des ailes d''aigles, et je vous ai amenés à moi.'),
(2032, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 5, 'OT', 'Et maintenant, si vous écoutez attentivement ma voix et gardez mon alliance, vous serez pour moi un peuple particulier parmi tous les peuples, car toute la terre est à moi.'),
(2033, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 6, 'OT', 'Et vous, vous serez pour moi un royaume de sacrificateurs et une nation sainte ; voici les paroles que tu diras aux fils d''Israël.'),
(2034, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 7, 'OT', 'Moïse vint, appela les anciens du peuple, et mit devant leur face toutes ces paroles que l''Éternel lui avait commandées.'),
(2035, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 8, 'OT', 'Tout le peuple répondit ensemble et dit : Tout ce qu''a dit l''Éternel, nous le ferons. Et Moïse rapporta les paroles du peuple à l''Éternel.'),
(2036, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 9, 'OT', 'L''Éternel dit à Moïse : Voici, je viens à toi dans une nuée épaisse, afin que le peuple entende quand je te parlerai, et qu''ils croient aussi en toi pour toujours. Et Moïse rapporta les paroles du peuple à l''Éternel.'),
(2037, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 10, 'OT', 'L''Éternel dit à Moïse : Va vers le peuple, et sanctifie-les aujourd''hui et demain, et qu''ils lavent leurs vêtements.'),
(2038, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 11, 'OT', 'Ils seront prêts pour le troisième jour, car au troisième jour l''Éternel descendra aux yeux de tout le peuple sur la montagne de Sinaï.'),
(2039, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 12, 'OT', 'Tu fixeras des limites au peuple tout alentour, en disant : Gardez-vous de monter sur la montagne et de toucher son extrémité ; tout homme qui touchera la montagne sera mis à mort.'),
(2040, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 13, 'OT', 'Nul n''y touchera de la main, car il sera lapidé ou percé de flèches ; que ce soit bétail ou homme, il ne vivra pas. Quand le jubilé sonnera longuement, ils monteront sur la montagne.'),
(2041, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 14, 'OT', 'Moïse descendit de la montagne vers le peuple, et il sanctifia le peuple, et ils lavèrent leurs vêtements.'),
(2042, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 15, 'OT', 'Il dit au peuple : Soyez prêts pour le troisième jour ; ne vous approchez pas d''une femme.'),
(2043, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 16, 'OT', 'Le troisième jour, au matin, il y eut des voix, des éclairs, une nuée épaisse sur la montagne, et une voix de trompette très forte ; et tout le peuple qui était dans le camp trembla.'),
(2044, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 17, 'OT', 'Moïse fit sortir le peuple du camp à la rencontre de Dieu, et ils se placèrent au bas de la montagne.'),
(2045, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 18, 'OT', 'La montagne de Sinaï fumait tout entière, parce que l''Éternel était descendu sur elle dans le feu ; sa fumée montait comme la fumée d''une fournaise, et toute la montagne tremblait violemment, à cause de la face de l''Éternel.'),
(2046, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 19, 'OT', 'Le son de la trompette allait en croissant et devenait très fort ; Moïse parlait, et Dieu lui répondait par une voix.'),
(2047, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 20, 'OT', 'L''Éternel descendit sur la montagne de Sinaï, au sommet de la montagne ; et l''Éternel appela Moïse au sommet de la montagne, et Moïse monta.'),
(2048, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 21, 'OT', 'L''Éternel dit à Moïse : Descends, avertis le peuple, de peur qu''ils ne se précipitent vers l''Éternel pour voir, et que beaucoup d''entre eux ne tombent.'),
(2049, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 22, 'OT', 'Et aussi les sacrificateurs qui s''approchent de l''Éternel se sanctifieront, de peur que l''Éternel ne fasse une brèche parmi eux.'),
(2050, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 23, 'OT', 'Moïse dit à l''Éternel : Le peuple ne peut pas monter à la montagne de Sinaï, car tu nous as averti en disant : Délimite la montagne et sanctifie-la.'),
(2051, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 24, 'OT', 'L''Éternel dit à Moïse : Descends, et tu monteras, toi et Aaron avec toi ; mais que les sacrificateurs et le peuple ne se précipitent point pour monter vers l''Éternel, de peur qu''il ne fasse une brèche parmi eux.'),
(2052, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 19, 25, 'OT', 'Moïse descendit vers le peuple et leur dit.'),
(2053, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 1, 'OT', 'Dieu parla toutes ces paroles, en disant :'),
(2054, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 2, 'OT', 'Je suis l''Éternel, ton Dieu, qui t''ai fait sortir de la terre d''Égypte, de la maison des serviteurs.'),
(2055, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 3, 'OT', 'Tu n''auras pas d''autres dieux devant ma face.'),
(2056, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 4, 'OT', 'Tu ne te feras point d''idole, ni aucune image de ce qui est dans les cieux en haut, ni de ce qui est sur la terre en bas, ni de ce qui est dans les eaux sous la terre.'),
(2057, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 5, 'OT', 'Tu ne te prosterneras point devant elles, et tu ne les serviras point ; car moi, l''Éternel, ton Dieu, je suis un Dieu jaloux, qui punis l''iniquité des pères sur les fils, jusqu''à la troisième et à la quatrième génération de ceux qui me haïssent.'),
(2058, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 6, 'OT', 'et faisant bonté à des milliers, à ceux qui m''aiment et qui gardent mes commandements.'),
(2059, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 7, 'OT', 'Tu ne porteras pas le nom de l''Éternel, ton Dieu, en vanité, car l''Éternel ne laissera pas impuni celui qui portera son nom en vanité.'),
(2060, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 8, 'OT', 'Souviens-toi du jour du sabbat pour le sanctifier.'),
(2061, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 9, 'OT', 'Six jours tu travailleras, et tu feras tout ton ouvrage.'),
(2062, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 10, 'OT', 'Le septième jour est un sabbat pour l''Éternel, ton Dieu : tu ne feras aucun ouvrage, toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bétail, ni l''étranger qui est dans tes portes.'),
(2063, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 11, 'OT', 'Car en six jours l''Éternel fit les cieux et la terre, la mer et tout ce qui s''y trouve, et il se reposa au septième jour ; c''est pourquoi l''Éternel bénit le jour du sabbat et le sanctifia.'),
(2064, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 12, 'OT', 'Honore ton père et ta mère, afin que tes jours se prolongent sur la terre que l''Éternel, ton Dieu, te donne.'),
(2065, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 13, 'OT', 'Tu ne tueras point.'),
(2066, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 14, 'OT', 'Tu ne commettras point d''adultère.'),
(2067, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 15, 'OT', 'Tu ne voleras point.'),
(2068, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 16, 'OT', 'Tu ne porteras pas contre ton ami un témoignage de mensonge.'),
(2069, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 17, 'OT', 'Tu ne convoiteras point la maison de ton ami ; tu ne convoiteras point la femme de ton ami, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni tout ce qui appartient à ton ami.'),
(2070, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 18, 'OT', 'Tout le peuple voyait les voix, les flambeaux, le son de la trompette et la montagne fumante ; et le peuple, voyant cela, trembla et se tint à distance.'),
(2071, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 19, 'OT', 'Ils dirent à Moïse : Parle toi-même avec nous, et nous écouterons ; mais que Dieu ne parle pas avec nous, de peur que nous mourions.'),
(2072, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 20, 'OT', 'Moïse dit au peuple : Ne craignez point, car c''est pour vous éprouver que Dieu est venu, et c''est pour que sa crainte soit sur vos faces, afin que vous ne péchiez point.'),
(2073, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 21, 'OT', 'Le peuple se tint à distance, et Moïse s''approcha des ténèbres où était Dieu.'),
(2074, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 22, 'OT', 'L''Éternel dit à Moïse : « Ainsi parleras-tu aux fils d''Israël : Vous avez vu que des cieux j''ai parlé avec vous. »'),
(2075, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 23, 'OT', 'Vous ne ferez pas avec moi des dieux d''argent, et des dieux d''or vous n''en ferez point pour vous.'),
(2076, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 24, 'OT', 'Tu feras pour moi un autel de terre, et tu y offriras tes holocaustes et tes sacrifices d''actions de grâces, tes brebis et tes bœufs ; en tout lieu où je rappellerai mon nom, je viendrai à toi et je te bénirai.'),
(2077, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 25, 'OT', 'Si tu me fais un autel de pierres, tu ne le bâtiras pas en pierre de taille, car tu as brandi ton épée dessus et tu l''as profané.'),
(2078, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 20, 26, 'OT', 'Tu ne monteras point par degrés à mon autel, afin que ta nudité n''y soit pas découverte.'),
(2079, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 1, 'OT', 'Voici ces jugements que tu placeras devant leur face.'),
(2080, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 2, 'OT', 'Si tu achètes un serviteur hébreu, il servira six années, et à la septième il sortira libre, sans rien payer.'),
(2081, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 3, 'OT', 'S''il entre seul, il sortira seul ; s''il est maître d''une femme, sa femme sortira avec lui.'),
(2082, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 4, 'OT', 'Si son seigneur lui donne une femme, et qu''elle lui enfante des fils ou des filles, la femme et ses enfants appartiendront à son seigneur, et lui sortira seul.'),
(2083, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 5, 'OT', 'Et si le serviteur dit clairement : « J''aime mon seigneur, ma femme et mes fils ; je ne sortirai pas libre, »'),
(2084, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 6, 'OT', 'Son maître le conduira devant Dieu, et le conduira à la porte ou au poteau, et son maître percera son oreille avec un poinçon, et il le servira pour toujours.'),
(2085, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 7, 'OT', 'Si un homme vend sa fille comme servante, elle ne sortira pas comme sortent les serviteurs.'),
(2086, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 8, 'OT', 'Si elle déplaît aux yeux de son seigneur, qui ne l''avait pas désignée pour lui, il la laissera être rachetée ; il n''aura pas le pouvoir de la vendre à un peuple étranger, parce qu''il a agi avec traîtrise envers elle.'),
(2087, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 9, 'OT', 'Et si c''est pour son fils qu''il la destine, il agira envers elle selon le jugement des filles.'),
(2088, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 10, 'OT', 'S''il prend pour lui une autre femme, il ne retranchera rien à sa chair, à son vêtement, ni à son devoir conjugal.'),
(2089, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 11, 'OT', 'Et s''il ne lui fait pas ces trois choses, elle sortira gratuitement, sans argent.'),
(2090, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 12, 'OT', 'Celui qui frappe un homme et qu''il meure sera mis à mort.'),
(2091, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 13, 'OT', 'Mais celui qui n''a pas dressé d''embûche, et que Dieu a livré entre sa main, je t''établirai un lieu où il pourra fuir.'),
(2092, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 14, 'OT', 'Mais si un homme agit avec audace contre son ami pour le tuer par ruse, tu le prendras de mon autel pour qu''il meure.'),
(2093, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 15, 'OT', 'Celui qui frappe son père ou sa mère sera mis à mort.'),
(2094, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 16, 'OT', 'Celui qui vole un homme et le vend, et qui est trouvé en sa main, sera mis à mort.'),
(2095, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 17, 'OT', 'Celui qui maudit son père et sa mère sera mis à mort.'),
(2096, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 18, 'OT', 'Et si des hommes se querellent, et qu''un homme frappe son ami avec une pierre ou avec un poing, et qu''il ne meure pas, mais tombe au lit,'),
(2097, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 19, 'OT', 'S''il se lève et marche dehors sur son bâton, alors celui qui a frappé sera absous ; seulement il paiera son interruption, et il le fera guérir complètement.'),
(2098, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 20, 'OT', 'Si un homme frappe son serviteur ou sa servante avec une tribu, et qu''il meurt sous sa main, il sera certainement vengé.'),
(2099, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 21, 'OT', 'Mais s''il survit un jour ou deux jours, il ne sera pas vengé, car c''est son argent.'),
(2100, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 22, 'OT', 'Si des hommes se querellent et heurtent une femme enceinte, et que ses enfants sortent, mais qu''il n''y a pas de malheur, il sera certainement puni d''amende selon ce que le maître de la femme lui imposera, et il paiera par les juges.'),
(2101, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 23, 'OT', 'Mais si un malheur arrive, tu donneras une âme pour une âme.'),
(2102, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 24, 'OT', 'Œil pour œil, dent pour dent, main pour main, pied pour pied.'),
(2103, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 25, 'OT', 'Brûlure pour brûlure, plaie pour plaie, meurtrissure pour meurtrissure.'),
(2104, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 26, 'OT', 'Si un homme frappe l''œil de son serviteur ou l''œil de sa servante, et le détruit, il le renverra libre en compensation de son œil.'),
(2105, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 27, 'OT', 'Et s''il fait tomber une dent de son serviteur ou une dent de sa servante, il le renverra libre pour sa dent.'),
(2106, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 28, 'OT', 'Si un bœuf frappe de sa corne un homme ou une femme, et qu''ils meurent, le bœuf sera lapidé, et on ne mangera point sa chair ; mais le maître du bœuf sera quitte.'),
(2107, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 29, 'OT', 'Et si un bœuf est frappeur depuis hier et avant-hier, et que son maître en a été averti, et qu''il ne le garde pas, et qu''il tue un homme ou une femme, le bœuf sera lapidé, et même son maître sera mis à mort.'),
(2108, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 30, 'OT', 'S''il lui est imposé une rançon, il donnera la rançon de son âme selon tout ce qui lui est imposé.'),
(2109, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 31, 'OT', 'Soit un fils qu''il frappe de corne, soit une fille qu''il frappe de corne, selon ce jugement-là il lui sera fait.'),
(2110, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 32, 'OT', 'Si un bœuf frappe de sa corne un serviteur ou une servante, il donnera à leur seigneur trente sicles d''argent, et le bœuf sera lapidé.'),
(2111, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 33, 'OT', 'Et si un homme ouvre une citerne, ou si un homme creuse une citerne et ne la couvre pas, et qu''un bœuf ou un âne y tombe :'),
(2112, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 34, 'OT', 'Le maître de la citerne paiera ; il rendra de l''argent à son maître, et l''animal mort lui appartiendra.'),
(2113, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 35, 'OT', 'Si le bœuf d''un homme frappe le bœuf de son ami, et qu''il meure, ils vendront le bœuf vivant et partageront son argent, et ils partageront aussi le mort.'),
(2114, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 21, 36, 'OT', 'Ou s''il est connu que le bœuf était frappeur dès hier et avant-hier, et que son maître ne l''a pas gardé, il paiera bœuf pour bœuf, et le mort lui appartiendra.'),
(2115, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 1, 'OT', 'Si un homme vole un bœuf ou un agneau, et le tue ou le vend, il restituera cinq bœufs pour le bœuf, et quatre brebis pour l''agneau.'),
(2116, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 2, 'OT', 'Si l''on trouve le voleur en effraction, et qu''il soit frappé et meure, il n''y a pas de sang pour lui.'),
(2117, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 3, 'OT', 'Si le soleil s''est levé sur lui, il y a du sang pour lui ; il devra sûrement restituer ; s''il n''a rien, il sera vendu pour son vol.'),
(2118, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 4, 'OT', 'Si le vol se trouve en sa main, depuis un bœuf jusqu''à un âne, jusqu''à un agneau, vivants, il paiera le double.'),
(2119, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 5, 'OT', 'Si un homme fait paître un champ ou une vigne, et envoie son bétail, et que celui-ci broute dans le champ d''un autre, il restituera du meilleur de son champ et du meilleur de sa vigne.'),
(2120, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 6, 'OT', 'Si un feu se répand et atteint des épines, et que la gerbe, ou le blé sur pied, ou le champ est consumé, celui qui a allumé l''incendie devra le payer pleinement.'),
(2121, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 7, 'OT', 'Si un homme donne à son ami de l''argent ou des ustensiles pour les garder, et qu''un vol soit commis dans la maison de cet homme, si le voleur est trouvé, il paiera le double.'),
(2122, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 8, 'OT', 'Si le voleur n''est pas trouvé, le maître de la maison s''approchera de Dieu, pour savoir s''il n''a pas mis la main sur l''ouvrage de son ami.'),
(2123, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 9, 'OT', 'Sur toute parole de transgression, pour un bœuf, pour un âne, pour un agneau, pour un manteau, pour toute perte dont on dira : « C''est cela », la parole des deux viendra devant Dieu ; celui que Dieu condamnera paiera le double à son ami.'),
(2124, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 10, 'OT', 'Si un homme donne à son ami un âne, ou un bœuf, ou un agneau, ou tout bétail, pour le garder, et qu''il meurt, ou qu''il se brise, ou qu''il soit emporté, sans que personne ne le voie,'),
(2125, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 11, 'OT', 'Le serment de l''Éternel sera entre eux deux, qu''il n''a pas étendu sa main sur l''ouvrage de son ami ; et son maître l''acceptera, et il ne paiera pas.'),
(2126, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 12, 'OT', 'Et s''il est volé de chez lui, il paiera à son maître.'),
(2127, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 13, 'OT', 'Si une bête a été déchirée, qu''il l''amène comme témoin ; il ne paiera pas la bête déchirée.'),
(2128, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 14, 'OT', 'Si un homme emprunte à son ami, et que cela se brise ou meure, son maître n''étant pas avec lui, il devra le rembourser pleinement.'),
(2129, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 15, 'OT', 'Si son maître est avec lui, il ne paiera pas ; s''il est loué, il est venu pour son salaire.'),
(2130, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 16, 'OT', 'Si un homme séduit une vierge qui n''est pas fiancée et couche avec elle, il la dotera certainement pour lui comme femme.'),
(2131, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 17, 'OT', 'Si son père refuse de la lui donner, il pèsera de l''argent selon la dot des vierges.'),
(2132, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 18, 'OT', 'Tu ne laisseras pas vivre une sorcière.'),
(2133, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 19, 'OT', 'Quiconque couche avec du bétail sera mis à mort.'),
(2134, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 20, 'OT', 'Celui qui sacrifie à un dieu sera voué à l''anathème, excepté à l''Éternel seul.'),
(2135, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 21, 'OT', 'Tu ne maltraiteras point l''étranger, et tu ne l''opprimeras point, car vous avez été étrangers dans la terre d''Égypte.'),
(2136, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 22, 'OT', 'Vous n''opprimerez aucune veuve ni orphelin.'),
(2137, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 23, 'OT', 'Si tu l''affliges vraiment, et qu''il crie vers moi, j''entendrai certainement son cri.'),
(2138, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 24, 'OT', 'Ma colère s''embrasera, et je vous tuerai par l''épée, et vos femmes seront veuves, et vos fils orphelins.'),
(2139, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 25, 'OT', 'Si tu prêtes de l''argent à mon peuple, au pauvre qui est avec toi, tu ne seras pas pour lui comme un créancier ; tu ne lui imposeras point d''usure.'),
(2140, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 26, 'OT', 'Si tu prends en gage le manteau de ton ami, tu le lui rendras avant le coucher du soleil.'),
(2141, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 27, 'OT', 'Car c''est là son seul vêtement, c''est le vêtement de sa peau ; en quoi se coucherait-il ? Et s''il crie vers moi, je l''écouterai, car je suis miséricordieux.'),
(2142, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 28, 'OT', 'Tu ne maudiras point Dieu, et tu ne maudiras point le prince de ton peuple.'),
(2143, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 29, 'OT', 'Tes prémices et ta vendange, tu ne les différeras point ; le premier-né de tes fils, tu me le donneras.'),
(2144, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 30, 'OT', 'Tu feras de même pour ton bœuf et pour tes brebis : sept jours il sera avec sa mère ; au huitième jour, tu me le donneras.'),
(2145, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 22, 31, 'OT', 'Vous serez des hommes saints pour moi, et vous ne mangerez point de chair déchirée dans le champ ; vous la jetterez au chien.'),
(2146, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 1, 'OT', 'Tu ne porteras point de bruit de vanité ; ne mets point ta main avec le méchant pour être témoin de violence.'),
(2147, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 2, 'OT', 'Ne te range pas après la multitude pour faire le mal, et ne réponds pas dans un procès en te penchant après la multitude pour faire fléchir le droit.'),
(2148, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 3, 'OT', 'Tu ne favoriseras point le pauvre dans son procès.'),
(2149, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 4, 'OT', 'Si tu rencontres le bœuf de ton ennemi ou son âne égaré, tu le lui ramèneras certainement.'),
(2150, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 5, 'OT', 'Si tu vois l''âne de ton ennemi couché sous son fardeau, et que tu t''abstiens de l''aider, tu l''aideras certainement avec lui.'),
(2151, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 6, 'OT', 'Ne détourne pas le jugement de ton pauvre dans son procès.'),
(2152, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 7, 'OT', 'Éloigne-toi de la parole de mensonge, et ne fais pas mourir l''innocent et le juste, car je ne justifierai pas le méchant.'),
(2153, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 8, 'OT', 'Tu ne prendras point de présent, car le présent aveugle ceux qui voient clair et pervertit les paroles des justes.'),
(2154, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 9, 'OT', 'Tu n''opprimeras point l''étranger, car vous connaissez l''âme de l''étranger, puisque vous avez été étrangers dans la terre d''Égypte.'),
(2155, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 10, 'OT', 'Pendant six années, tu sèmeras ta terre, et tu recueilleras son produit.'),
(2156, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 11, 'OT', 'La septième année, tu la laisseras en repos et tu l''abandonneras, et les pauvres de ton peuple en mangeront, et leur reste, la vie des champs la mangera ; ainsi feras-tu pour ta vigne et pour ton olivier.'),
(2157, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 12, 'OT', 'Six jours tu feras tes œuvres, et au septième jour tu te reposeras, afin que ton bœuf et ton âne se reposent, et que le fils de ta servante et l''étranger reprennent haleine.'),
(2158, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 13, 'OT', 'Et dans tout ce que je vous ai commandé, vous vous garderez ; et le nom d''autres dieux vous ne mentionnerez point ; il ne sera point entendu sur votre bouche.'),
(2159, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 14, 'OT', 'Tu célébreras pour moi une fête trois fois par année, à pied.'),
(2160, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 15, 'OT', 'Tu garderas la fête des pains sans levain : sept jours tu mangeras des pains sans levain, comme je te l''ai commandé, à l''assignation du mois des épis, car c''est en lui que tu es sorti d''Égypte ; et l''on ne paraîtra pas devant ma face les mains vides.'),
(2161, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 16, 'OT', 'Et la fête de la moisson, des premiers fruits de ton œuvre, que tu auras semée dans le champ ; et la fête de la moisson à la sortie de l''année, quand tu recueilleras ton œuvre du champ.'),
(2162, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 17, 'OT', 'Trois fois dans l''année, tout mâle de toi paraîtra devant la face du Seigneur, l''Éternel.'),
(2163, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 18, 'OT', 'Tu n''offriras point avec du levain le sang de mon sacrifice, et la graisse de ma fête ne demeurera point jusqu''au matin.'),
(2164, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 19, 'OT', 'Le commencement des premiers fruits de ta terre, tu l''apporteras dans la maison de l''Éternel, ton Dieu. Tu ne feras pas cuire un chevreau dans le lait de sa mère.'),
(2165, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 20, 'OT', 'Voici, j''envoie un ange devant ta face pour te garder sur le chemin et pour te faire venir au lieu que j''ai préparé.'),
(2166, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 21, 'OT', 'Prends garde à sa face et écoute sa voix ; ne te rebelle pas contre lui, car il ne pardonnera pas votre transgression, parce que mon nom est en son milieu.'),
(2167, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 22, 'OT', 'Car si tu écoutes attentivement sa voix et que tu fais tout ce que je dirai, je serai l''ennemi de tes ennemis et j''affligerai ceux qui t''affligent.'),
(2168, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 23, 'OT', 'Car mon ange ira devant ta face et te fera entrer chez l''Amoréen, le Héthien, le Phérézien, le Cananéen, l''Hévien et le Jébusien, et je les exterminerai.'),
(2169, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 24, 'OT', 'Tu ne te prosterneras pas devant leurs dieux, et tu ne les serviras pas, et tu ne feras pas comme leurs œuvres ; car tu les détruiras entièrement, et tu briseras leurs monuments.'),
(2170, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 25, 'OT', 'Vous servirez l''Éternel, votre Dieu, et il bénira ton pain et tes eaux, et j''ôterai la maladie du milieu de toi.'),
(2171, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 26, 'OT', 'Il n''y aura dans ton pays ni femme qui avorte ni femme stérile ; je remplirai le nombre de tes jours.'),
(2172, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 27, 'OT', 'J''enverrai ma terreur devant ta face, et je mettrai en déroute tout le peuple contre lequel tu viendras, et je ferai que tous tes ennemis te tournent le cou.'),
(2173, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 28, 'OT', 'J''enverrai le frelon devant ta face, et il chassera le Hévien, le Cananéen et le Héthien de devant ta face.'),
(2174, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 29, 'OT', 'Je ne les chasserai pas de devant toi en une seule année, de peur que la terre ne devienne un désert et que la bête des champs ne se multiplie contre toi.'),
(2175, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 30, 'OT', 'Peu à peu, je le chasserai de devant ta face, jusqu''à ce que tu deviennes fécond et que tu hérites de la terre.'),
(2176, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 31, 'OT', 'Je fixerai ta frontière depuis la mer Rouge jusqu''à la mer des Philistins, et depuis le désert jusqu''au fleuve ; car je livrerai en votre main les habitants de la terre, et tu les chasseras de devant ta face.'),
(2177, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 32, 'OT', 'Tu ne concluras pas d''alliance avec eux ni avec leurs dieux.'),
(2178, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 23, 33, 'OT', 'Ils ne demeureront pas dans ta terre, de peur qu''ils ne te fassent pécher contre moi ; car tu servirais leurs dieux, car cela serait pour toi un piège.'),
(2179, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 1, 'OT', 'Et à Moïse il dit : Monte vers l''Éternel, toi et Aaron, Nadab et Abihu, et soixante-dix des anciens d''Israël, et vous vous prosternerez de loin.'),
(2180, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 2, 'OT', 'Moïse s''approchera seul de l''Éternel, mais eux ne s''approcheront pas, et le peuple ne montera pas avec lui.'),
(2181, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 3, 'OT', 'Moïse vint et rapporta au peuple toutes les paroles de l''Éternel et tous les jugements ; et tout le peuple répondit d''une seule voix et dit : Toutes les paroles que l''Éternel a dites, nous les ferons.'),
(2182, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 4, 'OT', 'Moïse écrivit toutes les paroles de l''Éternel, puis il se leva de bon matin et bâtit un autel au pied de la montagne, ainsi que douze monuments pour les douze tribus d''Israël.'),
(2183, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 5, 'OT', 'Il envoya les jeunes gens des fils d''Israël, et ils offrirent des holocaustes, et ils sacrifièrent des sacrifices d''actions de grâces à l''Éternel, des taureaux.'),
(2184, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 6, 'OT', 'Moïse prit la moitié du sang et la mit dans les coupes, et la moitié du sang, il la répandit sur l''autel.'),
(2185, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 7, 'OT', 'Il prit le livre de l''alliance et le lut aux oreilles du peuple, et ils dirent : Tout ce qu''a dit l''Éternel, nous le ferons et nous l''écouterons.'),
(2186, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 8, 'OT', 'Moïse prit le sang, le répandit sur le peuple, et dit : Voici le sang de l''alliance que l''Éternel a conclue avec vous, selon toutes ces paroles.'),
(2187, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 9, 'OT', 'Moïse et Aaron, Nadab et Abihu, et soixante-dix des anciens d''Israël montèrent.'),
(2188, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 10, 'OT', 'Ils virent le Dieu d''Israël, et sous ses pieds, comme une œuvre d''ouvrage de saphir, et comme l''os des cieux en splendeur.'),
(2189, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 11, 'OT', 'Et il n''étendit point sa main sur l''élite des fils d''Israël ; ils virent Dieu, puis ils mangèrent et burent.'),
(2190, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 12, 'OT', 'L''Éternel dit à Moïse : Monte vers moi sur la montagne, et sois là ; je te donnerai les tables de pierre, la loi et le commandement que j''ai écrits pour les instruire.'),
(2191, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 13, 'OT', 'Moïse se leva, avec Josué, son serviteur, et Moïse monta sur la montagne de Dieu.'),
(2192, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 14, 'OT', 'Et aux anciens il dit : Restez ici pour nous jusqu''à ce que nous revenions vers vous ; et voici, Aaron et Hur sont avec vous ; que celui qui est maître d''une parole s''approche d''eux.'),
(2193, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 15, 'OT', 'Moïse monta sur la montagne, et la nuée couvrit la montagne.'),
(2194, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 16, 'OT', 'La gloire de l''Éternel reposa sur la montagne de Sinaï, et la nuée la couvrit pendant six jours ; et il appela Moïse au septième jour du milieu de la nuée.'),
(2195, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 17, 'OT', 'L''apparence de la gloire de l''Éternel était comme un feu dévorant sur le sommet de la montagne, aux yeux des fils d''Israël.'),
(2196, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 24, 18, 'OT', 'Moïse entra au milieu de la nuée et monta sur la montagne, et Moïse fut sur la montagne quarante jours et quarante nuits.'),
(2197, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2198, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 2, 'OT', 'Parle aux fils d''Israël, et qu''ils prennent pour moi une offrande ; de tout homme dont le cœur le pousse, vous prendrez mon offrande.'),
(2199, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 3, 'OT', 'Et voici l''offrande que vous prendrez d''eux : de l''or, de l''argent et de l''airain.'),
(2200, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 4, 'OT', 'du bleu, et du pourpre, et du cramoisi, et du fin lin, et du poil de chèvre.'),
(2201, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 5, 'OT', 'et des peaux de béliers teintes en rouge, et des peaux de dauphin, et du bois d''acacia.'),
(2202, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 6, 'OT', 'De l''huile pour le luminaire, des aromates pour l''huile d''onction et pour l''encens aromatique.'),
(2203, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 7, 'OT', 'Des pierres d''onyx et des pierres de consécration, pour l''éphod et pour le pectoral.'),
(2204, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 8, 'OT', 'Ils me feront un sanctuaire, et je demeurerai au milieu d''eux.'),
(2205, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 9, 'OT', 'Selon tout ce que je te montre, le modèle du tabernacle et le modèle de tous ses ustensiles, ainsi vous ferez.'),
(2206, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 10, 'OT', 'Ils feront une arche de bois d''acacia : deux coudées et demie sa longueur, une coudée et demie sa largeur, et une coudée et demie sa hauteur.'),
(2207, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 11, 'OT', 'Tu la recouvriras d''or pur ; par-dedans la maison et par-dehors tu la recouvriras, et tu feras sur elle une bordure d''or tout alentour.'),
(2208, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 12, 'OT', 'Tu fondras pour lui quatre anneaux d''or, et tu les mettras sur ses quatre fois, et deux anneaux sur un côté, et deux anneaux sur son second côté.'),
(2209, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 13, 'OT', 'Tu feras des barres de bois d''acacia, et tu les recouvriras d''or.'),
(2210, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 14, 'OT', 'Tu introduiras les barres dans les anneaux, sur les côtés de l''arche, pour porter l''arche avec elles.'),
(2211, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 15, 'OT', 'Les barres resteront dans les anneaux de l''arche ; elles n''en seront point retirées.'),
(2212, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 16, 'OT', 'Tu mettras dans l''arche le témoignage que je te donnerai.'),
(2213, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 17, 'OT', 'Tu feras un propitiatoire d''or pur ; sa longueur sera de deux coudées et une moitié, et sa largeur d''une coudée et une moitié.'),
(2214, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 18, 'OT', 'Tu feras deux chérubins d''or ; tu les feras d''or battu, aux deux extrémités du propitiatoire.'),
(2215, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 19, 'OT', 'Tu feras un chérubin à une extrémité, et un chérubin à l''autre extrémité ; c''est du propitiatoire que vous ferez les chérubins, sur ses deux extrémités.'),
(2216, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 20, 'OT', 'Les chérubins étendront leurs ailes vers le haut, couvrant de leurs ailes le propitiatoire, et leurs faces seront l''une vers l''autre ; vers le propitiatoire seront les faces des chérubins, chaque homme regardant son frère.'),
(2217, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 21, 'OT', 'Tu placeras le propitiatoire sur l''arche, par-dessus, et dans l''arche tu mettras le témoignage que je te donnerai.'),
(2218, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 22, 'OT', 'Je me rencontrerai avec toi là, et je te parlerai de dessus le propitiatoire, d''entre les deux chérubins qui sont sur l''arche du témoignage, tout ce que je te commanderai pour les fils d''Israël.'),
(2219, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 23, 'OT', 'Tu feras une table de bois d''acacia ; sa longueur sera de deux coudées, sa largeur d''une coudée, et sa hauteur d''une coudée et demie.'),
(2220, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 24, 'OT', 'Tu la recouvriras d''or pur, et tu lui feras une bordure d''or tout alentour.'),
(2221, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 25, 'OT', 'Tu lui feras un rebord d''une palme tout alentour, et tu feras une bordure d''or pour son rebord, tout alentour.'),
(2222, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 26, 'OT', 'Tu feras pour lui quatre anneaux d''or, et tu mettras les anneaux sur les quatre côtés qui sont à ses quatre pieds.'),
(2223, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 27, 'OT', 'Près du rebord seront les anneaux, comme maisons pour les seuls bâtons, pour porter la table.'),
(2224, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 28, 'OT', 'Tu feras les barres de bois d''acacia, et tu les recouvriras d''or, et l''on portera avec elles la table.'),
(2225, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 29, 'OT', 'Tu feras ses plats, ses mains, ses coupes et ses coupes à libation, avec lesquelles on versera ; tu les feras en or pur.'),
(2226, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 30, 'OT', 'Tu mettras sur la table le pain des faces devant moi, continuellement.'),
(2227, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 31, 'OT', 'Tu feras un chandelier d''or pur ; le chandelier sera fait d''or battu ; son côté, son roseau, ses coupes, ses pommes et ses fleurs seront d''une seule pièce avec lui.'),
(2228, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 32, 'OT', 'Et six roseaux sortant de ses côtés : trois roseaux du chandelier d''un côté, et trois roseaux du chandelier de l''autre côté.'),
(2229, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 33, 'OT', 'Trois coupes en forme de fleur d''amandier sur un roseau, une pomme et une fleur, et trois coupes en forme de fleur d''amandier sur l''autre roseau, une pomme et une fleur ; ainsi pour les six roseaux qui sortent du chandelier.'),
(2230, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 34, 'OT', 'Et sur le chandelier, quatre coupes en forme d''amande, ses pommes et ses fleurs.'),
(2231, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 35, 'OT', 'et une pomme sous deux des roseaux issus d''elle, et une pomme sous deux des roseaux issus d''elle, et une pomme sous deux des roseaux issus d''elle, pour les six roseaux qui sortent du chandelier.'),
(2232, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 36, 'OT', 'Leurs pommes et leurs roseaux seront faits de la même pièce ; le tout sera d''un seul or battu, d''or pur.'),
(2233, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 37, 'OT', 'Tu feras ses sept lampes, et tu feras monter ses lampes, et elles éclaireront au-delà de sa face.'),
(2234, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 38, 'OT', 'Ses mouchettes et ses brasiers, d''or pur.'),
(2235, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 39, 'OT', 'On fera ce chandelier d''un talent d''or pur, avec tous ces ustensiles.'),
(2236, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 25, 40, 'OT', 'Regarde et fais selon leur modèle, qui t''est montré sur la montagne.'),
(2237, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 1, 'OT', 'Tu feras le tabernacle de dix tapis de lin fin retors, de bleu, de pourpre et de cramoisi ; tu les feras avec des chérubins, œuvre d''artisan.'),
(2238, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 2, 'OT', 'La longueur d''un tapis sera de vingt-huit coudées, et la largeur d''un tapis de quatre coudées ; une même mesure pour tous les tapis.'),
(2239, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 3, 'OT', 'Cinq tapis seront joints, une femme à sa sœur, et cinq tapis seront joints, une femme à sa sœur.'),
(2240, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 4, 'OT', 'Tu feras des lacets de bleu sur la lèvre du tapis, à l''extrémité de l''assemblage, et tu feras de même sur la lèvre du tapis extérieur, à la jointure seconde.'),
(2241, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 5, 'OT', 'Tu feras cinquante lacets sur le premier tapis, et tu feras cinquante lacets à l''extrémité du tapis qui est à la seconde jointure ; les lacets se correspondront l''un à l''autre, comme une femme à sa sœur.'),
(2242, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 6, 'OT', 'Tu feras cinquante agrafes d''or, et tu joindras les tapis l''un à l''autre, une femme à sa sœur, avec les agrafes, et le tabernacle sera un seul.'),
(2243, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 7, 'OT', 'Tu feras des tapis de poil de chèvre pour la tente au-dessus du tabernacle ; tu feras onze tapis.'),
(2244, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 8, 'OT', 'La longueur d''un tapis était de trente coudées, et la largeur de quatre coudées pour le même tapis ; une seule mesure pour les onze tapis.'),
(2245, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 9, 'OT', 'Tu joindras les cinq tapis à part, et les six tapis à part, et tu replieras le sixième tapis vers le devant de la face de la tente.'),
(2246, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 10, 'OT', 'Tu feras cinquante lacets sur la lèvre du tapis qui est le plus extérieur dans l''assemblage, et cinquante lacets sur la lèvre du tapis qui est le second dans l''assemblage.'),
(2247, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 11, 'OT', 'Tu feras cinquante agrafes d''airain, et tu feras entrer les agrafes dans les lacets, et tu joindras la tente, et elle sera une.'),
(2248, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 12, 'OT', 'Le surplus des tapis de la tente, la moitié du tapis qui excède, retombera sur le derrière du tabernacle.'),
(2249, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 13, 'OT', 'La coudée d''un côté et la coudée de l''autre côté, dans le surplus de la longueur des tapis de la tente, sera étendue sur les côtés du tabernacle, d''un côté et de l''autre, pour le couvrir.'),
(2250, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 14, 'OT', 'Tu feras une couverture pour la tente, des peaux de béliers teintes en rouge, et une couverture de peaux de dauphin par-dessus.'),
(2251, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 15, 'OT', 'Tu feras les planches pour le tabernacle en bois d''acacia, dressées debout.'),
(2252, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 16, 'OT', 'Dix coudées la longueur de la planche, et une coudée et une moitié de coudée la largeur de la planche, celle-là.'),
(2253, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 17, 'OT', 'Deux mains pour chaque planche, enchevêtrées l''une avec sa sœur ; ainsi tu feras pour toutes les planches du tabernacle.'),
(2254, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 18, 'OT', 'Tu feras les planches pour le tabernacle : vingt planches pour le côté du midi, vers le midi.'),
(2255, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 19, 'OT', 'Tu feras quarante socles d''argent sous les vingt planches : deux socles sous une planche pour ses deux mains, et deux socles sous l''autre planche pour ses deux mains.'),
(2256, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 20, 'OT', 'Et pour le côté du tabernacle, le second, vers le côté du nord, vingt planches.'),
(2257, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 21, 'OT', 'Et leurs quarante socles en argent : deux socles sous une planche, et deux socles sous l''autre planche.'),
(2258, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 22, 'OT', 'Et pour les extrémités du tabernacle, vers la mer, tu feras six planches.'),
(2259, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 23, 'OT', 'Tu feras deux planches pour les extrémités du tabernacle, dans les côtés.'),
(2260, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 24, 'OT', 'Ils seront jumeaux par en bas, et ensemble ils seront parfaits à sa tête, vers l''unique anneau ; ainsi en sera-t-il pour les deux, pour les deux coins ils seront.'),
(2261, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 25, 'OT', 'Il y aura huit planches, avec leurs socles d''argent, seize socles ; deux socles sous une planche, et deux socles sous l''autre planche.'),
(2262, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 26, 'OT', 'Tu feras des verrous de bois d''acacia, cinq pour les planches du côté du tabernacle, celui-là.'),
(2263, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 27, 'OT', 'Cinq verrous pour les planches du côté du second tabernacle, et cinq verrous pour les planches du côté du tabernacle, vers les extrémités, du côté de la mer.'),
(2264, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 28, 'OT', 'Le verrou du milieu, au milieu des planches, traversant d''une extrémité à l''autre extrémité.'),
(2265, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 29, 'OT', 'Tu recouvriras les planches d''or, et tu feras leurs anneaux d''or, comme maisons pour les verrous, et tu recouvriras les verrous d''or.'),
(2266, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 30, 'OT', 'Tu dresseras le tabernacle selon son jugement, tel qu''il t''a été montré sur la montagne.'),
(2267, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 31, 'OT', 'Tu feras un voile de bleu, de pourpre, de cramoisi et de fin lin retors ; ce sera une œuvre d''artisan, on le fera avec des chérubins.'),
(2268, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 32, 'OT', 'Tu la placeras sur quatre piliers de bois d''acacia, recouverts d''or, avec leurs crochets d''or, sur quatre socles d''argent.'),
(2269, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 33, 'OT', 'Tu placeras le voile sous les agrafes, et tu feras entrer là, à l''intérieur de la maison, derrière le voile, l''arche du témoignage ; et le voile vous séparera entre le saint et le saint des saints.'),
(2270, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 34, 'OT', 'Tu mettras le propitiatoire sur l''arche du témoignage dans le saint des saints.'),
(2271, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 35, 'OT', 'Tu placeras la table en dehors du voile, et le chandelier en face de la table, sur le côté du tabernacle vers le midi ; et la table, tu la mettras sur le côté du nord.'),
(2272, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 36, 'OT', 'Tu feras un rideau pour l''entrée de la tente, de bleu, de pourpre, de cramoisi et de lin fin retors, œuvre de brodeur.'),
(2273, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 26, 37, 'OT', 'Tu feras pour le rideau cinq piliers de bois d''acacia, et tu les plaqueras d''or, et leurs crochets d''or, et tu fondras pour eux cinq socles d''airain.'),
(2274, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 1, 'OT', 'Tu feras l''autel en bois d''acacia ; sa longueur sera de cinq coudées, et sa largeur de cinq coudées ; l''autel sera carré, et sa hauteur de trois coudées.'),
(2275, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 2, 'OT', 'Tu feras ses cornes sur ses quatre angles ; ses cornes seront de lui-même, et tu le revêtiras d''airain.'),
(2276, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 3, 'OT', 'Tu feras ses chaudrons pour en ôter les cendres, ses pelles, ses bassins, ses fourchettes et ses brasiers ; pour tous ses ustensiles, tu feras de l''airain.'),
(2277, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 4, 'OT', 'Tu feras pour elle une grille, œuvre de filet d''airain, et tu feras sur le filet quatre anneaux d''airain, à ses quatre extrémités.'),
(2278, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 5, 'OT', 'Tu placeras le filet sous le rebord de l''autel, par en dessous, et le filet s''étendra jusqu''à la moitié de l''autel.'),
(2279, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 6, 'OT', 'Tu feras des barres pour l''autel, des barres de bois d''acacia, et tu les revêtiras d''airain.'),
(2280, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 7, 'OT', 'Ses barres seront introduites dans les anneaux, et les barres seront sur les deux côtés de l''autel lorsqu''on le portera.'),
(2281, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 8, 'OT', 'Tu le feras creux, en tables ; comme il te l''a montré sur la montagne, ainsi ils le feront.'),
(2282, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 9, 'OT', 'Tu feras le parvis du tabernacle : du côté du midi, vers le midi, des toiles pour le parvis, en fin lin retors, de cent coudées de longueur pour ce côté-là.'),
(2283, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 10, 'OT', 'Ses piliers, vingt, et leurs socles, vingt, d''airain ; les crochets des piliers et leurs tringles, d''argent.'),
(2284, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 11, 'OT', 'Et de même pour le côté du nord, dans la longueur, des toiles de cent coudées de longueur, et leurs vingt piliers, et leurs vingt socles d''airain ; les crochets des piliers et leurs tringles, d''argent.'),
(2285, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 12, 'OT', 'La largeur du parvis, du côté de la mer, était de cinquante coudées de toile, leurs piliers dix, et leurs socles dix.'),
(2286, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 13, 'OT', 'La largeur du parvis, du côté de l''orient, vers l''est, sera de cinquante coudées.'),
(2287, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 14, 'OT', 'Quinze coudées de toile pour le côté ; leurs piliers trois, et leurs socles trois.'),
(2288, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 15, 'OT', 'Et pour le second côté, quinze toiles ; leurs piliers, trois, et leurs socles, trois.'),
(2289, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 16, 'OT', 'Pour la porte du parvis, un rideau de vingt coudées, en bleu, pourpre, et cramoisi, et en fin lin retors, œuvre de brodeur ; ses piliers étaient quatre, et leurs socles quatre.'),
(2290, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 17, 'OT', 'Tous les piliers du parvis, alentour, étaient revêtus d''argent, leurs crochets d''argent, et leurs socles d''airain.'),
(2291, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 18, 'OT', 'La longueur du parvis sera de cent coudées, et la largeur de cinquante par cinquante, et la hauteur de cinq coudées, en fin lin retors, et leurs socles d''airain.'),
(2292, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 19, 'OT', 'Pour tous les ustensiles du tabernacle, dans tout son service, et tous ses piquets, et tous les piquets du parvis, en airain.'),
(2293, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 20, 'OT', 'Tu ordonneras aux fils d''Israël, et ils apporteront pour toi de l''huile d''olivier pure, broyée, pour le luminaire, afin de faire monter une lampe continuellement.'),
(2294, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 27, 21, 'OT', 'Dans la tente d''assignation, en dehors du voile qui est devant le témoignage, Aaron et ses fils l''arrangeront, du soir au matin, devant la face de l''Éternel ; c''est une loi perpétuelle pour leurs générations, de la part des fils d''Israël.'),
(2295, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 1, 'OT', 'Et toi, fais approcher de toi Aaron, ton frère, et ses fils avec lui, du milieu des fils d''Israël, pour qu''ils exercent le sacerdoce pour moi : Aaron, Nadab et Abihu, Éléazar et Ithamar, fils d''Aaron.'),
(2296, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 2, 'OT', 'Tu feras des vêtements saints pour Aaron, ton frère, pour la gloire et pour la splendeur.'),
(2297, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 3, 'OT', 'Et toi, tu parleras à tous les sages de cœur, que j''ai remplis d''un esprit de sagesse, et ils feront les vêtements d''Aaron pour le sanctifier, afin qu''il exerce le sacerdoce pour moi.'),
(2298, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 4, 'OT', 'Voici les vêtements qu''ils feront : le pectoral, l''éphod, le manteau, la tunique brodée, la tiare et la ceinture ; ils feront des vêtements saints pour Aaron ton frère et pour ses fils, afin qu''ils exercent le sacerdoce pour moi.'),
(2299, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 5, 'OT', 'Ils prendront l''or, le bleu, le pourpre, le cramoisi et le lin fin.'),
(2300, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 6, 'OT', 'Ils feront l''éphod d''or, de bleu, de pourpre, de cramoisi et de cramoisi, œuvre d''artisan.'),
(2301, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 7, 'OT', 'Deux côtés assemblés seront sur ses deux extrémités, et ils seront joints.'),
(2302, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 8, 'OT', 'La ceinture de l''éphod, qui est sur lui, sera de la même œuvre que lui, faite d''or, de bleu, de pourpre, de cramoisi et de lin fin retors.'),
(2303, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 9, 'OT', 'Tu prendras les deux pierres d''onyx, et tu graveras sur elles les noms des fils d''Israël.'),
(2304, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 10, 'OT', 'Six de leurs noms sur la première pierre, et les noms des six restants sur la seconde pierre, selon leurs générations.'),
(2305, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 11, 'OT', 'Œuvre d''artisan en pierre, gravures de sceau, tu graveras les deux pierres avec les noms des fils d''Israël ; tu les feras entourées de montures d''or.'),
(2306, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 12, 'OT', 'Tu placeras les deux pierres sur les côtés de l''éphod, pierres de mémorial pour les fils d''Israël ; et Aaron portera leurs noms devant l''Éternel sur ses deux côtés, en mémorial.'),
(2307, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 13, 'OT', 'Tu feras des montures d''or.'),
(2308, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 14, 'OT', 'Tu feras deux chaînes d''or pur, aux extrémités, œuvre de corde tressée, et tu mettras les chaînes de corde sur les montures.'),
(2309, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 15, 'OT', 'Tu feras le pectoral de jugement, œuvre d''artisan, comme l''œuvre de l''éphod tu le feras : d''or, de bleu, de pourpre, de cramoisi et de lin fin retors, tu le feras.'),
(2310, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 16, 'OT', 'Il sera carré, double, d''un empan sa longueur et d''un empan sa largeur.'),
(2311, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 17, 'OT', 'Tu le rempliras d''un chaton de pierre, quatre rangées de pierre : une rangée de sardoine, de topaze et d''escarboucle ; la première rangée.'),
(2312, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 18, 'OT', 'La deuxième rangée : émeraude, saphir et diamant.'),
(2313, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 19, 'OT', 'La troisième rangée : une opale, une agate et une améthyste.'),
(2314, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 20, 'OT', 'La quatrième rangée sera de chrysolithe, d''onyx et de jaspe ; elles seront enchâssées dans l''or, dans leurs chatons.'),
(2315, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 21, 'OT', 'Les pierres seront selon les noms des fils d''Israël, douze selon leurs noms ; comme des gravures de sceau, chacune avec son nom, elles seront pour les douze tribus.'),
(2316, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 22, 'OT', 'Tu feras sur le pectoral des chaînes tressées, œuvre de cordes, en or pur.'),
(2317, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 23, 'OT', 'Tu feras sur le pectoral deux anneaux d''or, et tu mettras les deux anneaux aux deux extrémités du pectoral.'),
(2318, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 24, 'OT', 'Tu mettras les deux cordes d''or sur les deux anneaux, aux extrémités du pectoral.'),
(2319, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 25, 'OT', 'Tu mettras les deux extrémités des deux cordes sur les deux montures, et tu les placeras sur les côtés de l''éphod, en face de sa face.'),
(2320, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 26, 'OT', 'Tu feras deux anneaux d''or, et tu les placeras sur les deux extrémités du pectoral, sur sa lèvre qui est vers l''au-delà de l''éphod, du côté de la maison.'),
(2321, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 27, 'OT', 'Tu feras deux anneaux d''or, et tu les mettras sur les deux côtés de l''éphod, en bas, en face de sa face, près de sa jointure, au-dessus de la ceinture de l''éphod.'),
(2322, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 28, 'OT', 'Ils attacheront le pectoral par ses anneaux aux anneaux de l''éphod avec un cordon de bleu, pour qu''il soit sur la ceinture de l''éphod, et le pectoral ne se détachera pas de dessus l''éphod.'),
(2323, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 29, 'OT', 'Aaron portera les noms des fils d''Israël sur le pectoral du jugement, sur son cœur, lorsqu''il entrera dans le lieu saint, en mémorial devant la face de l''Éternel, continuellement.'),
(2324, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 30, 'OT', 'Tu mettras dans le pectoral du jugement l''Urim et le Thummim, et ils seront sur le cœur d''Aaron lorsqu''il entrera devant l''Éternel ; et Aaron portera le jugement des fils d''Israël sur son cœur devant l''Éternel, toujours.'),
(2325, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 31, 'OT', 'Tu feras le manteau de l''éphod entièrement en bleu.'),
(2326, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 32, 'OT', 'Et son ouverture de tête sera en son milieu ; une lèvre sera à son ouverture, tout alentour, une œuvre de tisserand, comme l''ouverture d''une cotte de mailles, elle sera pour lui ; elle ne se déchirera pas.'),
(2327, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 33, 'OT', 'Tu feras sur sa bordure des grenades de bleu, de pourpre et de cramoisi, sur sa bordure, tout alentour ; et des clochettes d''or au milieu d''elles, tout alentour.'),
(2328, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 34, 'OT', 'Une clochette d''or et une grenade, une clochette d''or et une grenade, sur la bordure du manteau, tout alentour.'),
(2329, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 35, 'OT', 'Il sera sur Aaron pour le service, et sa voix sera entendue quand il entrera dans le lieu saint devant la face de l''Éternel, et quand il en sortira, afin qu''il ne meure pas.'),
(2330, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 36, 'OT', 'Tu feras une fleur d''or pur, et tu y graveras des gravures de sceau : saint à l''Éternel.'),
(2331, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 37, 'OT', 'Tu le placeras sur un cordon de bleu, et il sera sur la tiare ; en face de la tiare, il sera.'),
(2332, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 38, 'OT', 'Il sera sur le front d''Aaron, et Aaron portera l''iniquité des choses saintes que les fils d''Israël consacreront dans tous leurs dons saints ; il sera sur son front continuellement, pour leur être une bienveillance devant la face de l''Éternel.'),
(2333, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 39, 'OT', 'Tu tisseras la tunique de lin fin, et tu feras une tiare de lin fin, et tu feras une ceinture, œuvre de brodeur.'),
(2334, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 40, 'OT', 'Et pour les fils d''Aaron tu feras des tuniques, et tu leur feras des ceintures, et tu leur feras des bonnets, pour la gloire et pour l''ornement.'),
(2335, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 41, 'OT', 'Tu revêtiras Aaron, ton frère, et ses fils avec lui ; tu les oindras, tu rempliras leurs mains et tu les sanctifieras, et ils exerceront le sacerdoce pour moi.'),
(2336, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 42, 'OT', 'Fais-leur des caleçons de lin, pour couvrir la chair de leur nudité ; depuis les reins jusqu''au côté, ils seront.'),
(2337, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 28, 43, 'OT', 'Ils seront sur Aaron et sur ses fils lorsqu''ils entreront dans la tente d''assignation, ou lorsqu''ils s''approcheront de l''autel pour servir dans le saint lieu, afin qu''ils ne portent pas d''iniquité et ne meurent pas. C''est une loi perpétuelle pour lui et pour sa postérité après lui.'),
(2338, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 1, 'OT', 'Voici la parole que tu feras pour eux, afin de les sanctifier pour qu''ils me servent comme prêtres : prends un jeune taureau, et deux béliers sans défaut.'),
(2339, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 2, 'OT', 'Du pain sans levain, des gâteaux sans levain pétris à l''huile, et des galettes sans levain ointes d''huile : tu les feras de fleur de farine de froment.'),
(2340, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 3, 'OT', 'Tu les mettras sur une seule corbeille, et tu les présenteras dans la corbeille, avec le taureau et les deux béliers.'),
(2341, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 4, 'OT', 'Tu feras approcher Aaron et ses fils à l''entrée de la tente d''assignation, et tu les laveras avec des eaux.'),
(2342, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 5, 'OT', 'Tu prendras les vêtements, et tu revêtiras Aaron de la tunique, du manteau de l''éphod, de l''éphod et du pectoral, et tu le ceindras avec la ceinture de l''éphod.'),
(2343, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 6, 'OT', 'Tu placeras la tiare sur sa tête, et tu mettras le diadème saint sur la tiare.'),
(2344, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 7, 'OT', 'Tu prendras l''huile de l''onction, tu la verseras sur sa tête, et tu l''oindras.'),
(2345, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 8, 'OT', 'Tu feras approcher ses fils, et tu les revêtiras de tuniques.'),
(2346, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 9, 'OT', 'Tu ceindras Aaron et ses fils de la ceinture, et tu leur attacheras les bonnets ; et ils auront le sacerdoce comme une loi pour toujours ; et tu rempliras la main d''Aaron et la main de ses fils.'),
(2347, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 10, 'OT', 'Tu feras approcher le taureau devant la face de la tente d''assignation, et Aaron et ses fils poseront leurs mains sur la tête du taureau.'),
(2348, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 11, 'OT', 'Tu égorgeras le taureau devant la face de l''Éternel, à l''entrée de la tente d''assignation.'),
(2349, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 12, 'OT', 'Tu prendras du sang du taureau, et tu en mettras sur les cornes de l''autel avec ton doigt, et tout le sang, tu le verseras au fondement de l''autel.'),
(2350, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 13, 'OT', 'Tu prendras toute la graisse qui couvre le milieu, et la graisse qui est sur le foie, et les deux reins, et la graisse qui est sur eux, et tu les feras fumer sur l''autel.'),
(2351, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 14, 'OT', 'Tu brûleras au feu, dehors du camp, la chair du taureau, sa peau et ses excréments : c''est un sacrifice pour le péché.'),
(2352, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 15, 'OT', 'Tu prendras le bélier unique, et Aaron et ses fils poseront leurs mains sur la tête du bélier.'),
(2353, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 16, 'OT', 'Tu égorgeras le bélier, tu prendras son sang, et tu le répandras sur l''autel, tout alentour.'),
(2354, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 17, 'OT', 'Tu couperas le bélier en morceaux, et tu laveras son milieu et ses jambes, et tu les placeras sur ses morceaux et sur sa tête.'),
(2355, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 18, 'OT', 'Tu feras brûler tout le bélier sur l''autel ; c''est un holocauste à l''Éternel, une odeur agréable, un sacrifice consumé par le feu à l''Éternel.'),
(2356, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 19, 'OT', 'Tu prendras le second bélier, et Aaron et ses fils poseront leurs mains sur la tête du bélier.'),
(2357, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 20, 'OT', 'Tu égorgeras le bélier, tu prendras de son sang, et tu en mettras sur le lobe de l''oreille droite d''Aaron et sur le lobe de l''oreille droite de ses fils, sur le pouce de leur main droite et sur le pouce de leur pied droit, et tu répandras le sang sur l''autel, tout alentour.'),
(2358, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 21, 'OT', 'Tu prendras du sang qui est sur l''autel et de l''huile de l''onction, et tu en aspergeras Aaron et ses vêtements, et ses fils et les vêtements de ses fils avec lui ; et il sera sanctifié, lui et ses vêtements, et ses fils et les vêtements de ses fils avec lui.'),
(2359, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 22, 'OT', 'Tu prendras du bélier la graisse, la queue, la graisse qui couvre le milieu, la graisse du foie, les deux reins et la graisse qui est sur eux, et l''épaule droite, car c''est un bélier de consécration.'),
(2360, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 23, 'OT', 'un talent de pain, et un gâteau de pain à l''huile, et une galette, de la corbeille des pains sans levain qui est devant la face de l''Éternel.'),
(2361, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 24, 'OT', 'Tu placeras le tout sur les mains d''Aaron et sur les mains de ses fils, et tu les balanceras en offrande balancée devant la face de l''Éternel.'),
(2362, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 25, 'OT', 'Tu les prendras de leur main, et tu les feras brûler sur l''autel, par-dessus l''holocauste, en odeur agréable devant l''Éternel ; c''est un sacrifice consumé par le feu, pour l''Éternel.'),
(2363, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 26, 'OT', 'Tu prendras la poitrine du bélier de consécration, qui est pour Aaron, et tu la balanceras en offrande devant la face de l''Éternel, et elle sera pour toi comme portion.'),
(2364, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 27, 'OT', 'Tu consacreras la poitrine de l''offrande balancée et l''épaule de l''offrande élevée, ce qui a été balancé et ce qui a été élevé, du bélier de consécration, de ce qui revient à Aaron et de ce qui revient à ses fils.'),
(2365, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 28, 'OT', 'Ce sera pour Aaron et pour ses fils un statut perpétuel, de la part des fils d''Israël, car c''est une offrande ; et ce sera une offrande de la part des fils d''Israël, tirée de leurs sacrifices d''actions de grâces, leur offrande à l''Éternel.'),
(2366, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 29, 'OT', 'Les vêtements saints qui appartiennent à Aaron seront pour ses fils après lui, pour l''onction en eux et pour consacrer leurs mains par eux.'),
(2367, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 30, 'OT', 'Pendant sept jours, le sacrificateur qui sera de ses fils les portera, lorsqu''il entrera dans la tente d''assignation pour servir dans le saint lieu.'),
(2368, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 31, 'OT', 'Tu prendras le bélier de consécration, et tu feras cuire sa chair dans un lieu saint.'),
(2369, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 32, 'OT', 'Aaron et ses fils mangeront la chair du bélier et le pain qui est dans la corbeille, à l''entrée de la tente d''assignation.'),
(2370, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 33, 'OT', 'Ils mangeront ces choses par lesquelles l''expiation a été faite, pour remplir leur main et les sanctifier ; mais l''étranger n''en mangera point, car elles sont saintes.'),
(2371, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 34, 'OT', 'Et s''il reste de la chair de la consécration et du pain jusqu''au matin, tu brûleras au feu ce qui restera ; cela ne sera point mangé, car c''est une chose sainte.'),
(2372, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 35, 'OT', 'Tu feras ainsi pour Aaron et pour ses fils, selon tout ce que je t''ai commandé : pendant sept jours, tu rempliras leurs mains.'),
(2373, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 36, 'OT', 'Et tu feras un taureau de péché pour le jour, sur les expiations, et tu purifieras l''autel en faisant l''expiation sur lui, et tu l''oindras pour le sanctifier.'),
(2374, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 37, 'OT', 'Pendant sept jours tu feras l''expiation sur l''autel, et tu le sanctifieras ; et l''autel sera très saint ; tout ce qui touchera l''autel sera sanctifié.'),
(2375, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 38, 'OT', 'Et voici ce que tu feras sur l''autel : deux agneaux d''un an, par jour, continuellement.'),
(2376, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 39, 'OT', 'Tu feras l''un des agneaux le matin, et l''autre agneau, tu le feras entre les deux soirs.'),
(2377, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 40, 'OT', 'Un dixième d''épha de fleur de farine pétrie avec de l''huile d''olive broyée, un quart de hin, et une libation d''un quart de hin de vin, pour l''agneau, un seul.'),
(2378, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 41, 'OT', 'Tu feras le second agneau entre les deux soirs, comme l''offrande du matin et comme sa libation, tu le feras pour elle, en odeur agréable, un sacrifice consumé par le feu à l''Éternel.'),
(2379, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 42, 'OT', 'Ce sera l''holocauste continuel pour vos générations, à l''entrée de la tente d''assignation, devant la face de l''Éternel, où je me rencontrerai avec vous là, pour te parler là.'),
(2380, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 43, 'OT', 'Et je me rencontrerai là avec les fils d''Israël, et je serai sanctifié dans ma gloire.'),
(2381, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 44, 'OT', 'Je sanctifierai la tente d''assignation et l''autel, et je consacrerai Aaron et ses fils pour qu''ils exercent le sacerdoce devant moi.'),
(2382, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 45, 'OT', 'Je demeurerai au milieu des fils d''Israël, et je serai pour eux Dieu.'),
(2383, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 29, 46, 'OT', 'Et ils sauront que je suis l''Éternel, leur Dieu, qui les ai fait sortir de la terre d''Égypte pour habiter au milieu d''eux ; je suis l''Éternel, leur Dieu.'),
(2384, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 1, 'OT', 'Tu feras un autel des parfums pour brûler de l''encens ; tu le feras en bois d''acacia.'),
(2385, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 2, 'OT', 'Une coudée sa longueur, et une coudée sa largeur ; il sera carré, et deux coudées sa hauteur ; de lui ses cornes.'),
(2386, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 3, 'OT', 'Tu la recouvriras d''or pur : son toit, ses murs tout alentour, et ses cornes ; et tu lui feras une bordure d''or tout alentour.'),
(2387, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 4, 'OT', 'Tu feras pour lui deux anneaux d''or, au-dessous de sa bordure, sur ses deux côtés ; tu les feras sur ses deux flancs, et ils serviront de maisons pour les seuls bâtons, afin de le porter par eux.'),
(2388, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 5, 'OT', 'Tu feras les barres en bois d''acacia, et tu les recouvriras d''or.'),
(2389, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 6, 'OT', 'Tu le placeras devant le voile qui est sur l''arche du témoignage, devant le propitiatoire qui est sur le témoignage, là où je te rencontrerai.'),
(2390, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 7, 'OT', 'Aaron fera brûler sur l''autel un encens d''aromates ; chaque matin, lorsqu''il préparera les lampes, il le fera brûler.'),
(2391, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 8, 'OT', 'Quand Aaron fera monter les lampes entre les deux soirs, il fera brûler l''encens ; un encens continuel devant la face de l''Éternel, pour vos générations.'),
(2392, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 9, 'OT', 'Vous ne ferez point monter sur lui un encens étranger, ni holocauste, ni offrande, et vous ne répandrez point sur lui de libation.'),
(2393, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 10, 'OT', 'Aaron fera l''expiation sur ses cornes une fois par an ; avec le sang du sacrifice pour le péché de l''expiation, il fera l''expiation sur lui une fois par an, pour vos générations ; c''est une chose très sainte pour l''Éternel.'),
(2394, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 11, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2395, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 12, 'OT', 'Quand tu lèveras la tête des fils d''Israël pour leur recensement, chacun donnera une rançon pour son âme à l''Éternel lors de leur dénombrement, et il n''y aura point de plaie parmi eux lors de leur dénombrement.'),
(2396, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 13, 'OT', 'Voici ce que donnera tout homme qui passe au recensement : une moitié de sicle, selon le sicle du sanctuaire, le sicle valant vingt guéras ; une moitié de sicle sera une offrande à l''Éternel.'),
(2397, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 14, 'OT', 'Tout homme qui passe au recensement, depuis l''âge de vingt ans et au-dessus, donnera l''offrande de l''Éternel.'),
(2398, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 15, 'OT', 'Le riche ne donnera pas plus, et le pauvre ne donnera pas moins que la moitié d''un sicle, pour présenter l''offrande à l''Éternel, afin de faire l''expiation pour vos âmes.'),
(2399, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 16, 'OT', 'Tu prendras l''argent du rachat de la part des fils d''Israël, et tu le donneras pour le service de la tente d''assignation ; et il sera pour les fils d''Israël un mémorial devant la face de l''Éternel, pour faire l''expiation sur vos âmes.'),
(2400, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 17, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2401, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 18, 'OT', 'Tu feras un bassin d''airain et sa base d''airain pour se laver, et tu le placeras entre la tente d''assignation et l''autel, et tu mettras là des eaux.'),
(2402, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 19, 'OT', 'Aaron et ses fils s''y laveront les mains et les pieds.'),
(2403, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 20, 'OT', 'En entrant dans la tente d''assignation, ils se laveront avec des eaux, et ils ne mourront pas ; ou en s''approchant de l''autel pour officier, pour faire fumer un sacrifice consumé par le feu à l''Éternel.'),
(2404, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 21, 'OT', 'Ils se laveront les mains et les pieds, et ils ne mourront pas ; et ce sera pour eux un statut perpétuel, pour lui et pour sa postérité, à travers leurs générations.'),
(2405, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 22, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2406, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 23, 'OT', 'Et toi, prends pour toi des aromates de tête : myrrhe de liberté, cinq cents, et cinnamome aromatique, sa moitié, deux cent cinquante, et roseau aromatique, deux cent cinquante.'),
(2407, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 24, 'OT', 'et de la casse, cinq cents sicles, selon le sicle du sanctuaire, et de l''huile d''olivier, un hin.'),
(2408, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 25, 'OT', 'Tu feras de lui une huile d''onction sainte, un onguent composé, œuvre de parfumeur ; ce sera une huile d''onction sainte.'),
(2409, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 26, 'OT', 'Tu en oindras la tente d''assignation et l''arche du témoignage.'),
(2410, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 27, 'OT', 'et la table et tous ses ustensiles, et le chandelier et ses ustensiles, et l''autel de l''encens.'),
(2411, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 28, 'OT', 'et l''autel de l''holocauste et tous ses ustensiles, et le bassin et sa base.'),
(2412, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 29, 'OT', 'Tu les consacreras, et ils seront saints entre les saints ; tout celui qui les touchera sera sanctifié.'),
(2413, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 30, 'OT', 'Tu oindras Aaron et ses fils, et tu les consacreras pour qu''ils exercent le sacerdoce en mon honneur.'),
(2414, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 31, 'OT', 'Tu parleras aux fils d''Israël, en disant : Cette huile d''onction sainte sera pour moi, à travers vos générations.'),
(2415, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 32, 'OT', 'On ne le versera point sur la chair d''un homme, et vous n''en ferez point selon sa proportion ; il est saint, il sera saint pour vous.'),
(2416, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 33, 'OT', 'Quiconque, homme, en composera de semblable, ou en mettra sur un étranger, sera retranché de son peuple.'),
(2417, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 34, 'OT', 'L''Éternel dit à Moïse : Prends pour toi des aromates, du goutte, de l''ongle odorant et du galbanum, des aromates et de l''encens pur ; chaque partie sera égale, seul à seul.'),
(2418, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 35, 'OT', 'Tu feras de cela un encens, un onguent, œuvre de parfumeur, salé, pur, saint.'),
(2419, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 36, 'OT', 'Tu la broieras finement, et tu en mettras devant le témoignage, dans la tente d''assignation, où je me rencontrerai avec toi là ; ce sera pour vous une chose très sainte.'),
(2420, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 37, 'OT', 'L''encens que tu feras selon sa proportion, vous n''en ferez point pour vous-mêmes ; il te sera saint, consacré à l''Éternel.'),
(2421, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 30, 38, 'OT', 'Quiconque, homme, en fera de semblable pour en respirer l''odeur, sera retranché de son peuple.'),
(2422, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2423, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 2, 'OT', 'Vois, j''ai appelé par nom Betsaleel, fils d''Uri, fils de Hur, de la tribu de Juda.'),
(2424, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 3, 'OT', 'Et je l''ai rempli de l''esprit de Dieu, en sagesse, en intelligence, en connaissance, et en toute espèce d''ouvrage.'),
(2425, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 4, 'OT', 'Pour concevoir des pensées, pour travailler l''or, l''argent et l''airain.'),
(2426, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 5, 'OT', 'et dans le graver de pierre pour remplir, et dans le graver de bois, pour faire en tout ouvrage.'),
(2427, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 6, 'OT', 'Et moi, voici que j''ai donné avec lui Oholiab, fils d''Ahisamac, de la tribu de Dan, et dans le cœur de tout homme sage de cœur j''ai mis la sagesse, et ils feront tout ce que je t''ai commandé.'),
(2428, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 7, 'OT', 'La tente d''assignation, l''arche du témoignage, le propitiatoire qui est sur elle, et tous les ustensiles de la tente.'),
(2429, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 8, 'OT', 'et la table et ses ustensiles, et le chandelier pur et tous ses ustensiles, et l''autel de l''encens.'),
(2430, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 9, 'OT', 'et l''autel de l''holocauste et tous ses ustensiles, et le bassin et sa base.'),
(2431, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 10, 'OT', 'et les vêtements du service, et les vêtements saints pour Aaron, le sacrificateur, et les vêtements de ses fils pour exercer le sacerdoce.'),
(2432, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 11, 'OT', 'Et l''huile de l''onction, et l''encens des aromates pour le saint, selon tout ce que je t''ai commandé, ils le feront.'),
(2433, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 12, 'OT', 'L''Éternel dit à Moïse :'),
(2434, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 13, 'OT', 'Et toi, parle aux fils d''Israël, en disant : Certainement, vous garderez mes sabbats, car c''est un signe entre moi et vous, pour vos générations, afin que vous sachiez que je suis l''Éternel qui vous sanctifie.'),
(2435, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 14, 'OT', 'Vous garderez le sabbat, car il est saint pour vous ; celui qui le profanera sera mis à mort, car tout homme qui fera en ce jour un ouvrage, cette âme-là sera retranchée du milieu de son peuple.'),
(2436, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 15, 'OT', 'Six jours on fera un ouvrage, et au septième jour, sabbat de repos solennel, saint à l''Éternel ; tout homme qui fera un ouvrage au jour du sabbat sera mis à mort.'),
(2437, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 16, 'OT', 'Les fils d''Israël garderont le sabbat, pour observer le sabbat à travers leurs générations, comme une alliance pour toujours.'),
(2438, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 17, 'OT', 'C''est entre moi et les fils d''Israël un signe pour toujours ; car en six jours l''Éternel a fait les cieux et la terre, et au septième jour il s''est reposé et a respiré.'),
(2439, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 31, 18, 'OT', 'Il donna à Moïse, lorsqu''il eut achevé de parler avec lui sur la montagne de Sinaï, les deux tables du témoignage, des tables de pierre, écrites du doigt de Dieu.'),
(2440, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 1, 'OT', 'Le peuple vit que Moïse tardait à descendre de la montagne, et le peuple s''assembla auprès d''Aaron, et ils lui dirent : Lève-toi, fais-nous des dieux qui marchent devant nous ; car ce Moïse, l''homme qui nous a fait monter de la terre d''Égypte, nous ne savons pas ce qui lui est arrivé.'),
(2441, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 2, 'OT', 'Aaron leur dit : « Détachez les anneaux d''or qui sont aux oreilles de vos femmes, de vos fils et de vos filles, et apportez-les-moi. »'),
(2442, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 3, 'OT', 'Tout le peuple se détacha les anneaux d''or qui étaient à leurs oreilles, et ils les apportèrent à Aaron.'),
(2443, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 4, 'OT', 'Il le prit de leurs mains, le façonna avec un stylet et en fit un veau d''image taillée ; puis ils dirent : « Voici tes dieux, ô Israël, qui t''ont fait monter de la terre d''Égypte. »'),
(2444, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 5, 'OT', 'Aaron le vit, bâtit un autel devant lui, et Aaron proclama : « Demain, une fête pour l''Éternel. »'),
(2445, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 6, 'OT', 'Le lendemain, ils se levèrent de bon matin, offrirent des holocaustes et présentèrent des sacrifices d''actions de grâces ; puis le peuple s''assit pour manger et boire, et ils se levèrent pour se livrer à la débauche.'),
(2446, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 7, 'OT', 'L''Éternel parla à Moïse : Va, descends, car ton peuple, que tu as fait monter de la terre d''Égypte, s''est corrompu.'),
(2447, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 8, 'OT', 'Ils se sont écartés bien vite du chemin que je leur avais prescrit ; ils se sont fait un veau en image taillée, ils se sont prosternés devant lui, ils lui ont offert des sacrifices, et ils ont dit : « Voici tes dieux, ô Israël, qui t''ont fait monter de la terre d''Égypte. »'),
(2448, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 9, 'OT', 'L''Éternel dit à Moïse : J''ai vu ce peuple, et voici que c''est un peuple au cou raide.'),
(2449, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 10, 'OT', 'Maintenant donc, laisse-moi, et que ma colère s''enflamme contre eux, et je les consumerai, et je ferai de toi une grande nation.'),
(2450, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 11, 'OT', 'Moïse implora la face de l''Éternel, son Dieu, et dit : Pourquoi, ô Éternel, ta colère s''embraserait-elle contre ton peuple, que tu as fait sortir de la terre d''Égypte avec une grande force et une main puissante ?'),
(2451, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 12, 'OT', 'Pourquoi les Égyptiens diraient-ils : « C''est par mal qu''il les a fait sortir, pour les tuer dans les montagnes et pour les consumer de dessus la face de la terre » ? Reviens de la fureur de ta colère, et repens-toi du mal contre ton peuple.'),
(2452, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 13, 'OT', 'Souviens-toi d''Abraham, d''Isaac et d''Israël, tes serviteurs, auxquels tu as juré par toi-même, et tu leur as dit : Je multiplierai votre postérité comme les étoiles des cieux, et toute cette terre dont j''ai dit que je la donnerais à votre postérité, et ils la posséderont pour toujours.'),
(2453, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 14, 'OT', 'L''Éternel se repentit du mal qu''il avait dit qu''il ferait à son peuple.'),
(2454, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 15, 'OT', 'Moïse se retourna et descendit de la montagne, les deux tables du témoignage dans sa main ; tables écrites sur leurs deux au-delà, de ce côté-ci et de ce côté-là elles étaient écrites.'),
(2455, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 16, 'OT', 'Les tables étaient l''œuvre de Dieu, et l''écrit était l''écrit de Dieu, gravé sur les tables.'),
(2456, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 17, 'OT', 'Josué entendit la voix du peuple dans son cri, et il dit à Moïse : Voix de guerre dans le camp.'),
(2457, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 18, 'OT', 'Il dit : Ce n''est pas une voix de cris de puissance, et ce n''est pas une voix de cris de vaincus ; c''est une voix de cris que j''entends.'),
(2458, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 19, 'OT', 'Comme il approchait du camp, il vit le veau et la danse, et la colère de Moïse s''enflamma ; il jeta de sa main les tables, et les brisa au pied de la montagne.'),
(2459, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 20, 'OT', 'Il prit le veau qu''ils avaient fait, le brûla au feu, le moulut jusqu''à ce qu''il fût réduit en poudre, le répandit sur la face des eaux, et en fit boire aux fils d''Israël.'),
(2460, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 21, 'OT', 'Moïse dit à Aaron : Que t''a fait ce peuple, pour que tu aies fait venir sur lui un grand péché ?'),
(2461, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 22, 'OT', 'Aaron dit : Que la colère de mon seigneur ne s''enflamme point ; tu connais ce peuple, qu''il est dans le mal.'),
(2462, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 23, 'OT', 'Ils m''ont dit : Fais-nous des dieux qui marchent devant nous ; car ce Moïse, l''homme qui nous a fait monter de la terre d''Égypte, nous ne savons pas ce qui lui est arrivé.'),
(2463, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 24, 'OT', 'Et je leur dis : « À qui est cet or ? Détachez-le. » Et ils me le donnèrent, et je le jetai au feu, et il en sortit ce veau.'),
(2464, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 25, 'OT', 'Moïse vit que le peuple était sans frein, car Aaron l''avait laissé sans frein, pour l''opprobre au milieu de ses ennemis.'),
(2465, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 26, 'OT', 'Moïse se tint à la porte du camp et dit : Qui est pour l''Éternel ? Qu''il vienne à moi. Et tous les fils de Lévi se rassemblèrent auprès de lui.'),
(2466, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 27, 'OT', 'Il leur dit : Ainsi parle l''Éternel, le Dieu d''Israël : Que chacun mette son épée sur son côté ; passez et revenez de porte en porte dans le camp, et que chacun tue son frère, chacun son ami, et chacun son proche.'),
(2467, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 28, 'OT', 'Les fils de Lévi firent selon la parole de Moïse, et il tomba du peuple, en ce jour-là, environ trois mille hommes.'),
(2468, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 29, 'OT', 'Moïse dit : « Remplissez aujourd''hui vos mains pour l''Éternel, car chacun a été contre son fils et contre son frère, et pour qu''il vous soit donné aujourd''hui une bénédiction. »'),
(2469, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 30, 'OT', 'Le lendemain, Moïse dit au peuple : Vous avez commis un grand péché ; et maintenant je monterai vers l''Éternel, peut-être ferai-je l''expiation pour votre péché.'),
(2470, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 31, 'OT', 'Moïse retourna vers l''Éternel et dit : « Hélas ! ce peuple a commis un grand péché, et ils se sont fait des dieux d''or. »'),
(2471, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 32, 'OT', 'Et maintenant, si tu pardonnes leur péché, et si non, efface-moi, je te prie, de ton livre que tu as écrit.'),
(2472, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 33, 'OT', 'L''Éternel dit à Moïse : Celui qui a péché contre moi, je l''effacerai de mon livre.'),
(2473, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 34, 'OT', 'Et maintenant, va, conduis le peuple vers le lieu dont je t''ai parlé ; voici, mon ange ira devant ta face ; et au jour de ma visite, je ferai payer leur péché sur eux.'),
(2474, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 32, 35, 'OT', 'L''Éternel frappa le peuple, à cause du veau qu''Aaron avait fait.'),
(2475, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 1, 'OT', 'L''Éternel parla à Moïse : Va, monte d''ici, toi et le peuple que tu as fait monter de la terre d''Égypte, vers la terre que j''ai jurée à Abraham, à Isaac et à Jacob, en disant : Je la donnerai à ta postérité.'),
(2476, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 2, 'OT', 'J''enverrai devant ta face un ange, et je chasserai le Cananéen, l''Amoréen, le Héthien, le Phérézien, l''Hévien et le Jébusien.'),
(2477, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 3, 'OT', 'Vers une terre ruisselante de lait et de miel, car je ne monterai pas au milieu de toi, parce que tu es un peuple au cou raide, de peur que je ne te consume en chemin.'),
(2478, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 4, 'OT', 'Le peuple entendit cette mauvaise parole, et ils menèrent deuil, et nul homme ne mit son ornement sur lui.'),
(2479, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 5, 'OT', 'L''Éternel dit à Moïse : Dis aux fils d''Israël : Vous êtes un peuple au cou raide ; si je monte au milieu de toi en un instant, je te consumerai. Maintenant donc, ôte tes ornements de dessus toi, et je saurai ce que je te ferai.'),
(2480, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 6, 'OT', 'Les fils d''Israël se dépouillèrent de leurs ornements depuis la montagne de Horeb.'),
(2481, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 7, 'OT', 'Et Moïse prit la tente et la dressa pour lui dehors du camp, loin du camp, et l''appela tente d''assignation ; et il arrivait que tout chercheur de l''Éternel sortait vers la tente d''assignation, qui était dehors du camp.'),
(2482, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 8, 'OT', 'Et il arrivait que, lorsque Moïse sortait vers la tente, tout le peuple se levait, et chacun se tenait à l''entrée de sa tente, et ils regardaient après Moïse jusqu''à ce qu''il fût entré dans la tente.'),
(2483, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 9, 'OT', 'Et il arrivait que, lorsque Moïse entrait dans la tente, le pilier de nuée descendait et se tenait à l''entrée de la tente, et il parlait avec Moïse.'),
(2484, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 10, 'OT', 'Tout le peuple vit le pilier de la nuée se tenant à l''entrée de la tente, et tout le peuple se leva et se prosterna, chacun à l''entrée de sa tente.'),
(2485, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 11, 'OT', 'L''Éternel parlait à Moïse face à face, comme un homme parle à son ami ; puis il retournait au camp, et son serviteur Josué, fils de Nun, jeune homme, ne quittait pas le milieu de la tente.'),
(2486, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 12, 'OT', 'Moïse dit à l''Éternel : Vois, tu me dis : Fais monter ce peuple, mais tu ne m''as pas fait connaître celui que tu enverras avec moi ; et tu as dit : Je te connais par ton nom, et tu as aussi trouvé grâce à mes yeux.'),
(2487, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 13, 'OT', 'Et maintenant, si j''ai trouvé grâce à tes yeux, fais-moi connaître tes chemins, afin que je te connaisse et que je trouve grâce à tes yeux ; et considère que cette nation est ton peuple.'),
(2488, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 14, 'OT', 'Il dit : Ma face ira, et je te donnerai du repos.'),
(2489, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 15, 'OT', 'Il lui dit : Si ta face ne va pas, ne nous fais pas monter d''ici.'),
(2490, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 16, 'OT', 'Et en quoi sera-t-il connu alors que j''ai trouvé grâce à tes yeux, moi et ton peuple ? N''est-ce pas en ce que tu marches avec nous, et que nous soyons distingués, moi et ton peuple, de tout le peuple qui est sur la face de la terre ?'),
(2491, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 17, 'OT', 'L''Éternel dit à Moïse : Je ferai aussi cette parole que tu as dite, car tu as trouvé grâce à mes yeux, et je te connais par ton nom.'),
(2492, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 18, 'OT', 'Il dit : « Montre-moi, je te prie, ta gloire. »'),
(2493, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 19, 'OT', 'Il dit : Je ferai passer toute ma bonté devant ta face, et je proclamerai le nom de l''Éternel devant toi ; je ferai grâce à qui je ferai grâce, et j''aurai compassion de qui j''aurai compassion.'),
(2494, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 20, 'OT', 'Il dit : Tu ne peux pas voir ma face, car l''homme ne me verra point et vivra.'),
(2495, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 21, 'OT', 'L''Éternel dit : Voici un lieu avec moi, et tu te tiendras sur le rocher.'),
(2496, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 22, 'OT', 'Et il arrivera, quand ma gloire passera, que je te mettrai dans le creux du rocher, et je couvrirai ma main sur toi jusqu''à ce que je sois passé.'),
(2497, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 33, 23, 'OT', 'Et je retirerai ma main, et tu verras mon arrière, mais ma face ne sera pas vue.'),
(2498, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 1, 'OT', 'L''Éternel dit à Moïse : Taille pour toi deux tables de pierre comme les premières, et j''écrirai sur les tables les paroles qui étaient sur les premières tables que tu as brisées.'),
(2499, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 2, 'OT', 'Sois prêt dès le matin, et tu monteras le matin sur la montagne de Sinaï, et tu te tiendras là devant moi au sommet de la montagne.'),
(2500, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 3, 'OT', 'Nul homme ne montera avec toi, et même qu''aucun homme ne soit vu dans toute la montagne ; même les brebis et les bœufs ne paîtront pas en face de cette montagne.'),
(2501, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 4, 'OT', 'Il tailla deux tables de pierre comme les premières ; Moïse se leva de bon matin et monta à la montagne de Sinaï, comme l''Éternel le lui avait commandé, et il prit dans sa main deux tables de pierre.'),
(2502, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 5, 'OT', 'L''Éternel descendit dans la nuée, se tint là avec lui, et proclama le nom de l''Éternel.'),
(2503, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 6, 'OT', 'L''Éternel passa devant sa face et proclama : l''Éternel, l''Éternel, Dieu compatissant et miséricordieux, lent à la colère et abondant en bonté et en vérité.'),
(2504, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 7, 'OT', 'Gardien de bonté pour des milliers, porteur d''iniquité, de transgression et de péché, et qui ne tient pas pour innocent le coupable, visitant l''iniquité des pères sur les fils et sur les fils des fils, sur la troisième génération et sur la quatrième.'),
(2505, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 8, 'OT', 'Moïse se hâta, s''inclina jusqu''à terre et se prosterna.'),
(2506, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 9, 'OT', 'Il dit : Si j''ai trouvé grâce à tes yeux, Seigneur, que le Seigneur marche au milieu de nous, car c''est un peuple au cou raide ; pardonne notre iniquité et notre péché, et fais de nous ton héritage.'),
(2507, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 10, 'OT', 'Il dit : Voici, je conclus une alliance ; devant tout ton peuple je ferai des prodiges qui n''ont pas été créés dans toute la terre ni parmi toutes les nations ; et tout le peuple au milieu duquel tu es verra l''œuvre de l''Éternel, car c''est une chose redoutable que je fais avec toi.'),
(2508, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 11, 'OT', 'Garde pour toi ce que je te commande aujourd''hui : voici, je chasse devant ta face l''Amoréen, le Cananéen, le Héthien, le Phérézien, l''Hévien et le Jébusien.'),
(2509, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 12, 'OT', 'Garde-toi de faire alliance avec l''habitant de la terre sur laquelle tu vas entrer, de peur que cela ne devienne un piège au milieu de toi.'),
(2510, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 13, 'OT', 'Car vous démolirez leurs autels, vous briserez leurs monuments, et vous couperez leurs Astartés.'),
(2511, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 14, 'OT', 'Car tu ne te prosterneras pas devant un autre Dieu, car l''Éternel, dont le nom est Jaloux, est un Dieu jaloux.'),
(2512, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 15, 'OT', 'De peur que tu ne fasses alliance avec l''habitant de la terre, et qu''ils se prostituent après leurs dieux, et qu''ils sacrifient à leurs dieux, et qu''il t''appelle, et que tu manges de son sacrifice.'),
(2513, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 16, 'OT', 'Tu prendras de leurs filles pour tes fils, et leurs filles se prostitueront après leurs dieux, et elles feront se prostituer tes fils après leurs dieux.'),
(2514, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 17, 'OT', 'Tu ne feras pas pour toi d''image taillée de Dieu.'),
(2515, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 18, 'OT', 'Tu garderas la fête des pains sans levain ; sept jours tu mangeras des pains sans levain, comme je te l''ai commandé, à l''assignation du mois des épis ; car c''est au mois des épis que tu es sorti d''Égypte.'),
(2516, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 19, 'OT', 'Tout premier-né de la matrice est à moi ; et tout ton troupeau, le premier-né du bœuf et de l''agneau.'),
(2517, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 20, 'OT', 'Tu rachèteras le premier-né de l''âne avec un agneau ; et si tu ne le rachètes pas, tu lui briseras la nuque. Tu rachèteras tout premier-né de tes fils, et ils ne paraîtront pas devant ma face les mains vides.'),
(2518, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 21, 'OT', 'Six jours tu travailleras, et au septième jour tu te reposeras ; au labourage et à la moisson tu te reposeras.'),
(2519, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 22, 'OT', 'Tu feras pour toi la fête des semaines, les premiers fruits de la moisson du froment, et la fête de la moisson au retour de l''année.'),
(2520, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 23, 'OT', 'Trois fois dans l''année, tout mâle de toi paraîtra devant la face du Seigneur, l''Éternel, Dieu d''Israël.'),
(2521, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 24, 'OT', 'Car je chasserai les nations devant ta face, et j''élargirai ta frontière ; et nul homme ne convoitera ta terre, quand tu monteras pour paraître devant la face de l''Éternel, ton Dieu, trois fois dans l''année.'),
(2522, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 25, 'OT', 'Tu ne sacrifieras pas sur du levain le sang de mon sacrifice, et le sacrifice de la fête de la Pâque ne demeurera pas jusqu''au matin.'),
(2523, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 26, 'OT', 'Le commencement des premiers fruits de ta terre, tu l''apporteras dans la maison de l''Éternel, ton Dieu. Tu ne feras pas cuire un chevreau dans le lait de sa mère.'),
(2524, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 27, 'OT', 'L''Éternel dit à Moïse : Écris pour toi ces paroles, car c''est selon la bouche de ces paroles que j''ai fait alliance avec toi et avec Israël.'),
(2525, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 28, 'OT', 'Il fut là avec l''Éternel quarante jours et quarante nuits ; il ne mangea point de pain et ne but point d''eaux ; et il écrivit sur les tables les paroles de l''alliance, les dix paroles.'),
(2526, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 29, 'OT', 'Et il advint, lorsque Moïse descendit de la montagne de Sinaï, ayant les deux tables du témoignage dans la main de Moïse, en descendant de la montagne, que Moïse ne savait pas que la peau de sa face rayonnait, parce qu''il avait parlé avec lui.'),
(2527, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 30, 'OT', 'Aaron et tous les fils d''Israël virent Moïse, et voici que la peau de sa face rayonnait, et ils craignirent de s''approcher de lui.'),
(2528, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 31, 'OT', 'Moïse les appela, et Aaron et tous les princes de l''assemblée revinrent vers lui, et Moïse leur parla.'),
(2529, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 32, 'OT', 'Et après cela, tous les fils d''Israël s''approchèrent, et il leur commanda tout ce que l''Éternel avait dit avec lui sur la montagne de Sinaï.'),
(2530, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 33, 'OT', 'Moïse acheva de leur parler, et il mit un voile sur son visage.'),
(2531, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 34, 'OT', 'Et lorsque Moïse entrait devant la face de l''Éternel pour parler avec lui, il ôtait le voile jusqu''à sa sortie ; puis il sortait et parlait aux fils d''Israël de tout ce qui lui était commandé.'),
(2532, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 34, 35, 'OT', 'Les fils d''Israël virent la face de Moïse, car la peau de la face de Moïse rayonnait ; et Moïse remit le voile sur sa face, jusqu''à ce qu''il entrât pour parler avec lui.'),
(2533, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 1, 'OT', 'Moïse assembla toute l''assemblée des fils d''Israël et leur dit : Voici les paroles que l''Éternel a commandé de faire.'),
(2534, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 2, 'OT', 'Pendant six jours, on fera un ouvrage, et au septième jour, il sera pour vous saint, un sabbat de repos solennel pour l''Éternel ; tout homme qui fera un ouvrage en ce jour-là sera mis à mort.'),
(2535, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 3, 'OT', 'Vous n''allumerez pas de feu dans toutes vos habitations, le jour du sabbat.'),
(2536, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 4, 'OT', 'Moïse dit à toute l''assemblée des fils d''Israël : Voici la parole que l''Éternel a commandée, en disant :'),
(2537, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 5, 'OT', 'Prenez de chez vous une offrande pour l''Éternel ; tout homme dont le cœur est généreux apportera l''offrande de l''Éternel : de l''or, de l''argent et de l''airain.'),
(2538, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 6, 'OT', 'du bleu, et de la pourpre, et du cramoisi, et du lin, et du poil de chèvre'),
(2539, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 7, 'OT', 'et des peaux de béliers teintes en rouge, et des peaux de dauphin, et du bois d''acacia.'),
(2540, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 8, 'OT', 'de l''huile pour le luminaire, des aromates pour l''huile de l''onction, et de l''encens pour les aromates.'),
(2541, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 9, 'OT', 'Et des pierres d''onyx, et des pierres de consécration, pour l''éphod et pour le pectoral.'),
(2542, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 10, 'OT', 'Et tout homme sage de cœur parmi vous viendra et fera tout ce que l''Éternel a commandé.'),
(2543, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 11, 'OT', 'Le tabernacle, sa tente et sa couverture, ses agrafes et ses planches, ses verrous, ses piliers et ses socles.'),
(2544, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 12, 'OT', 'l''arche et ses barres, le propitiatoire, et le voile du rideau'),
(2545, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 13, 'OT', 'La table et ses barres, et tous ses ustensiles, et le pain des faces.'),
(2546, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 14, 'OT', 'Et le chandelier du luminaire, et ses ustensiles, et ses lampes, et l''huile du luminaire.'),
(2547, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 15, 'OT', 'et l''autel de l''encens et ses barres, et l''huile de l''onction et l''encens des aromates, et le rideau de l''entrée pour l''entrée du tabernacle.'),
(2548, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 16, 'OT', 'L''autel de l''holocauste, et sa grille d''airain, ses barres et tous ses ustensiles, le bassin et sa base.'),
(2549, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 17, 'OT', 'Les toiles du parvis, ses piliers et ses socles, et le rideau de la porte du parvis.'),
(2550, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 18, 'OT', 'les piquets du tabernacle, les piquets du parvis, et leurs cordes'),
(2551, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 19, 'OT', 'les vêtements du service pour officier dans le saint lieu, les vêtements saints d''Aaron, le sacrificateur, et les vêtements de ses fils pour exercer la sacrificature.'),
(2552, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 20, 'OT', 'Toute l''assemblée des fils d''Israël sortit de devant la face de Moïse.'),
(2553, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 21, 'OT', 'Tout homme dont le cœur fut porté vint, et tous ceux dont l''esprit fut disposé volontairement apportèrent l''offrande de l''Éternel pour l''ouvrage de la tente d''assignation, et pour tout son service, et pour les vêtements saints.'),
(2554, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 22, 'OT', 'Les hommes vinrent avec les femmes ; tous ceux dont le cœur était généreux apportèrent des boucles, des anneaux, des anneaux et des colliers, tout ustensile d''or, et tout homme qui fit une offrande d''or à l''Éternel.'),
(2555, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 23, 'OT', 'Et tout homme chez qui se trouvaient du bleu, de la pourpre, du cramoisi, du fin lin, du poil de chèvre, des peaux de béliers teintes en rouge, et des peaux de dauphin, les apportèrent.'),
(2556, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 24, 'OT', 'Tous ceux qui offraient une offrande d''argent et d''airain apportèrent l''offrande de l''Éternel ; et tous ceux chez qui se trouvait du bois d''acacia pour tout ouvrage du service l''apportèrent.'),
(2557, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 25, 'OT', 'Et toute femme habile de cœur filait de ses mains, et elles apportaient l''ouvrage filé : le bleu, le pourpre, le cramoisi, et le lin fin.'),
(2558, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 26, 'OT', 'Et toutes les femmes dont le cœur les avait portées avec sagesse filèrent les chèvres.'),
(2559, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 27, 'OT', 'Les princes apportèrent les pierres d''onyx et les pierres de consécration, pour l''éphod et pour le pectoral.'),
(2560, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 28, 'OT', 'et l''aromate et l''huile, pour le luminaire, et pour l''huile d''onction, et pour l''encens des aromates.'),
(2561, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 29, 'OT', 'Tout homme et femme dont le cœur les poussait à apporter pour tout l''ouvrage que l''Éternel avait commandé de faire par la main de Moïse, les fils d''Israël apportèrent une offrande volontaire à l''Éternel.'),
(2562, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 30, 'OT', 'Moïse dit aux fils d''Israël : Voyez, l''Éternel a appelé par nom Betsaleel, fils d''Uri, fils de Hur, de la tribu de Juda.'),
(2563, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 31, 'OT', 'Il le remplit de l''esprit de Dieu, de sagesse, d''intelligence, de connaissance et de toute espèce d''ouvrage.'),
(2564, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 32, 'OT', 'Et pour concevoir des pensées, pour travailler l''or, l''argent et l''airain.'),
(2565, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 33, 'OT', 'et dans le travail de graver la pierre pour enchâsser, et dans le travail de graver le bois, pour faire en tout ouvrage de pensée.'),
(2566, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 34, 'OT', 'Et pour enseigner, il a mis dans son cœur, lui et Oholiab, fils d''Ahisamac, de la tribu de Dan.'),
(2567, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 35, 35, 'OT', 'Il les a remplis de sagesse de cœur, pour faire tout ouvrage d''artisan, de dessinateur, et de brodeur en bleu, en pourpre, en cramoisi et en lin fin, et de tisserand, ceux qui font tout ouvrage et qui conçoivent des pensées.'),
(2568, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 1, 'OT', 'Betsaleel et Oholiab et tout homme sage de cœur, à qui l''Éternel a donné sagesse et intelligence, pour savoir faire tout l''ouvrage du service du saint, selon tout ce que l''Éternel a commandé.'),
(2569, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 2, 'OT', 'Moïse appela Betsaleel et Oholiab, et tout homme sage de cœur, à qui l''Éternel avait donné de la sagesse dans son cœur, tout homme que son cœur portait à s''approcher de l''ouvrage pour le faire.'),
(2570, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 3, 'OT', 'Ils prirent de devant la face de Moïse toute l''offrande que les fils d''Israël avaient apportée pour l''ouvrage du service du saint, afin de l''exécuter ; et ils lui apportaient encore une offrande volontaire chaque matin, chaque matin.'),
(2571, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 4, 'OT', 'Alors tous les hommes habiles qui faisaient tout l''ouvrage du sanctuaire vinrent, chacun de son ouvrage qu''ils faisaient.'),
(2572, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 5, 'OT', 'Ils dirent à Moïse : Le peuple apporte plus que la suffisance du service pour l''ouvrage que l''Éternel a commandé de faire.'),
(2573, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 6, 'OT', 'Moïse commanda, et l''on fit passer une voix dans le camp, en disant : Que ni homme ni femme ne fasse plus d''ouvrage pour l''offrande du saint. Et le peuple fut retenu d''apporter.'),
(2574, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 7, 'OT', 'L''ouvrage était une suffisance pour tout l''ouvrage à faire, et il y avait du surplus.'),
(2575, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 8, 'OT', 'Tous les hommes au cœur habile, parmi ceux qui faisaient l''ouvrage, firent le tabernacle de dix tapis de fin lin retors, de bleu, de pourpre et de cramoisi, avec des chérubins, œuvre d''artisan.'),
(2576, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 9, 'OT', 'La longueur du tapis était de vingt-huit coudées, et la largeur de quatre coudées pour le tapis ; une même mesure pour tous les tapis.'),
(2577, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 10, 'OT', 'Il joignit les cinq tapis l''un à l''autre, et il joignit les cinq autres tapis l''un à l''autre.'),
(2578, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 11, 'OT', 'Il fit des lacets de bleu sur la lèvre du tapis, à l''extrémité, dans la jointure ; il fit de même sur la lèvre du tapis extérieur, dans la seconde jointure.'),
(2579, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 12, 'OT', 'Il fit cinquante lacets dans le premier tapis, et il fit cinquante lacets à l''extrémité du tapis qui est dans la seconde jointure, les lacets se correspondant l''un à l''autre.'),
(2580, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 13, 'OT', 'Il fit cinquante agrafes d''or, et il joignit les tapis l''un à l''autre avec les agrafes, et le tabernacle fut un.'),
(2581, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 14, 'OT', 'Il fit des tapis de poil de chèvre pour la tente sur le tabernacle ; il fit onze tapis.'),
(2582, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 15, 'OT', 'La longueur d''un tapis était de trente coudées, et la largeur d''un tapis était de quatre coudées ; une même mesure pour les onze tapis.'),
(2583, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 16, 'OT', 'Il joignit les cinq tapis seuls, et les six tapis seuls.'),
(2584, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 17, 'OT', 'Il fit cinquante lacets sur la lèvre du tapis extrême à la jointure, et cinquante lacets il fit sur la lèvre du tapis de l''assemblage second.'),
(2585, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 18, 'OT', 'Il fit cinquante agrafes d''airain pour joindre la tente, afin qu''elle fût une.'),
(2586, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 19, 'OT', 'Il fit une couverture pour la tente, en peaux de béliers teintes en rouge, et une couverture de peaux de dauphin par-dessus.'),
(2587, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 20, 'OT', 'Il fit les planches pour le tabernacle en bois d''acacia, dressées debout.'),
(2588, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 21, 'OT', 'Dix coudées la longueur de la planche, et une coudée et une moitié de coudée la largeur de la planche, celle-là.'),
(2589, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 22, 'OT', 'Deux mains pour chaque planche, assemblées l''une contre l''autre ; ainsi fit-il pour toutes les planches du tabernacle.'),
(2590, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 23, 'OT', 'Il fit les planches pour le tabernacle : vingt planches pour le côté du midi, vers le midi.'),
(2591, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 24, 'OT', 'Et il fit quarante socles d''argent sous les vingt planches : deux socles sous une planche pour ses deux mains, et deux socles sous l''autre planche pour ses deux mains.'),
(2592, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 25, 'OT', 'Et pour le côté du tabernacle, le second, vers le côté du nord, il fit vingt planches.'),
(2593, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 26, 'OT', 'Et leurs quarante socles étaient d''argent, deux socles sous une planche, et deux socles sous l''autre planche.'),
(2594, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 27, 'OT', 'Et pour les extrémités du tabernacle, vers la mer, il fit six planches.'),
(2595, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 28, 'OT', 'Et il fit deux planches pour les extrémités du tabernacle, aux deux côtés.'),
(2596, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 29, 'OT', 'Ils étaient jumeaux par en bas, et ensemble ils étaient parfaits jusqu''à sa tête, jusqu''à l''anneau unique ; ainsi fit-il pour les deux, pour les deux coins.'),
(2597, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 30, 'OT', 'Il y avait huit planches, et leurs socles d''argent, seize socles ; deux socles sous chaque planche.'),
(2598, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 31, 'OT', 'Il fit des verrous de bois d''acacia, cinq pour les planches du côté du tabernacle, celui-là.'),
(2599, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 32, 'OT', 'Et cinq verrous pour les planches du côté du second tabernacle, et cinq verrous pour les planches du tabernacle, pour les extrémités vers la mer.'),
(2600, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 33, 'OT', 'Il fit le verrou du milieu, pour passer au milieu des planches, d''une extrémité à l''autre extrémité.'),
(2601, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 34, 'OT', 'Il recouvrit les planches d''or, fit leurs anneaux d''or comme maisons pour les verrous, et recouvrit les verrous d''or.'),
(2602, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 35, 'OT', 'Il fit le voile de bleu, de pourpre, de cramoisi et de cramoisi, et de fin lin retors ; il le fit en œuvre de brodeur, avec des chérubins.'),
(2603, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 36, 'OT', 'Il fit pour elle quatre piliers de bois d''acacia, et les plaqua d''or ; leurs crochets étaient d''or, et il fondit pour eux quatre socles d''argent.'),
(2604, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 37, 'OT', 'Il fit un rideau pour l''entrée de la tente, de bleu, de pourpre, de cramoisi et de lin retors, œuvre de brodeur.'),
(2605, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 36, 38, 'OT', 'et ses cinq piliers, et leurs crochets, et il recouvrit d''or leurs têtes et leurs tringles, et leurs cinq socles d''airain.'),
(2606, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 1, 'OT', 'Betsaleel fit l''arche de bois d''acacia ; sa longueur était de deux coudées et une moitié, sa largeur d''une coudée et une moitié, et sa hauteur d''une coudée et une moitié.'),
(2607, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 2, 'OT', 'Il la recouvrit d''or pur, à l''intérieur de la maison et au dehors, et il lui fit une bordure d''or tout alentour.'),
(2608, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 3, 'OT', 'Il fondit pour lui quatre anneaux d''or sur ses quatre fois, et deux anneaux sur son premier côté, et deux anneaux sur son second côté.'),
(2609, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 4, 'OT', 'Il fit des barres de bois d''acacia, et il les recouvrit d''or.'),
(2610, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 5, 'OT', 'Il inséra les barres dans les anneaux sur les côtés de l''arche, pour porter l''arche.'),
(2611, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 6, 'OT', 'Il fit le propitiatoire d''or pur : deux coudées et une moitié sa longueur, et une coudée et une moitié sa largeur.'),
(2612, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 7, 'OT', 'Il fit deux chérubins d''or ; il les fit d''or battu, aux deux extrémités du propitiatoire.'),
(2613, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 8, 'OT', 'Un chérubin à une extrémité, et un chérubin à l''autre extrémité ; c''est du propitiatoire qu''il fit les chérubins, des deux extrémités.'),
(2614, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 9, 'OT', 'Les chérubins étendaient leurs ailes vers le haut, couvrant de leurs ailes le propitiatoire, et leurs faces étaient l''une vers l''autre ; vers le propitiatoire étaient les faces des chérubins, chacun regardant son frère.'),
(2615, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 10, 'OT', 'Il fit la table de bois d''acacia ; sa longueur était de deux coudées, sa largeur d''une coudée, et sa hauteur d''une coudée et demie.'),
(2616, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 11, 'OT', 'Il la recouvrit d''or pur, et il lui fit une bordure d''or tout alentour.'),
(2617, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 12, 'OT', 'Il fit pour lui un rebord d''une palme, tout alentour, et il fit une bordure d''or pour son rebord, tout alentour.'),
(2618, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 13, 'OT', 'Il fondit pour elle quatre anneaux d''or, et il mit les anneaux sur les quatre côtés qui étaient aux quatre pieds de la table.'),
(2619, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 14, 'OT', 'Près du rebord étaient les anneaux, comme maisons pour les barres, afin de porter la table.'),
(2620, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 15, 'OT', 'Il fit les barres de bois d''acacia, et les recouvrit d''or, pour porter la table.'),
(2621, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 16, 'OT', 'Il fit les ustensiles qui étaient sur la table : ses plats, ses mains, ses coupes, et les coupes avec lesquelles on versait les libations, en or pur.'),
(2622, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 17, 'OT', 'Il fit le chandelier d''or pur ; en or battu il fit le chandelier, son côté et son roseau, ses coupes, ses pommes et ses fleurs étaient tirés de lui.'),
(2623, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 18, 'OT', 'Et six roseaux sortant de ses côtés : trois roseaux du chandelier d''un côté, et trois roseaux du chandelier de l''autre côté.'),
(2624, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 19, 'OT', 'Trois coupes en forme d''amande sur le premier roseau, avec une pomme et une fleur ; et trois coupes en forme d''amande sur l''autre roseau, avec une pomme et une fleur ; ainsi pour les six roseaux sortant du chandelier.'),
(2625, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 20, 'OT', 'Sur le chandelier, quatre coupes en forme de fleurs d''amandier, avec ses pommes et ses fleurs.'),
(2626, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 21, 'OT', 'une pomme sous deux des roseaux sortant d''elle, et une pomme sous deux des roseaux sortant d''elle, et une pomme sous deux des roseaux sortant d''elle, pour les six roseaux qui sortent d''elle.'),
(2627, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 22, 'OT', 'Leurs pommes et leurs roseaux étaient d''une seule pièce avec elle ; le tout était un seul or battu, d''or pur.'),
(2628, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 23, 'OT', 'Il fit ses sept lampes, et ses mouchettes et ses brasiers d''or pur.'),
(2629, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 24, 'OT', 'D''un talent d''or pur il la fit, et tous ses ustensiles.'),
(2630, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 25, 'OT', 'Il fit l''autel de l''encens en bois d''acacia ; sa longueur était d''une coudée, et sa largeur d''une coudée, carré, et sa hauteur de deux coudées ; ses cornes étaient d''une seule pièce avec lui.'),
(2631, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 26, 'OT', 'Il la recouvrit d''or pur, son toit, ses murs tout alentour et ses cornes, et il lui fit une bordure d''or tout alentour.'),
(2632, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 27, 'OT', 'Et deux anneaux d''or il fit pour lui, sous sa bordure, sur ses deux côtés, sur ses deux flancs, comme maisons pour les seuls, afin de le porter par eux.'),
(2633, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 28, 'OT', 'Il fit les barres en bois d''acacia, et il les recouvrit d''or.'),
(2634, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 37, 29, 'OT', 'Il fit l''huile de l''onction sainte, et l''encens pur des aromates, œuvre de parfumeur.'),
(2635, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 1, 'OT', 'Il fit l''autel de l''holocauste en bois d''acacia ; sa longueur était de cinq coudées, et sa largeur de cinq coudées, carré, et sa hauteur de trois coudées.'),
(2636, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 2, 'OT', 'Il fit ses cornes sur ses quatre angles ; ses cornes étaient d''une seule pièce avec lui, et il le revêtit d''airain.'),
(2637, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 3, 'OT', 'Il fit tous les ustensiles de l''autel : les chaudrons, les pelles, les bassins, les fourchettes et les brasiers ; il fit tous ses ustensiles d''airain.'),
(2638, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 4, 'OT', 'Il fit pour l''autel une grille, œuvre de filet d''airain, sous son rebord, en bas jusqu''à sa moitié.'),
(2639, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 5, 'OT', 'Il fondit quatre anneaux aux quatre extrémités de la grille d''airain, comme maisons pour les barres.'),
(2640, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 6, 'OT', 'Il fit les barres de bois d''acacia, et les recouvrit d''airain.'),
(2641, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 7, 'OT', 'Il inséra les barres dans les anneaux sur les côtés de l''autel, pour le porter avec eux ; il le fit creux, en tables.'),
(2642, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 8, 'OT', 'Il fit le bassin d''airain et sa base d''airain, avec les visions des femmes qui se rassemblaient à l''entrée de la tente d''assignation.'),
(2643, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 9, 'OT', 'Il fit le parvis, du côté du midi, vers le midi : les toiles du parvis étaient de lin retors, de cent coudées.'),
(2644, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 10, 'OT', 'Leurs piliers étaient vingt, et leurs socles vingt, en airain ; les crochets des piliers et leurs tringles étaient en argent.'),
(2645, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 11, 'OT', 'Pour le côté du nord, cent coudées, leurs piliers vingt, et leurs socles vingt, d''airain ; les crochets des piliers et leurs tringles, d''argent.'),
(2646, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 12, 'OT', 'Et pour le côté de la mer, des toiles de cinquante coudées, leurs piliers dix, et leurs socles dix ; les crochets des piliers et leurs tringles, en argent.'),
(2647, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 13, 'OT', 'Et pour le côté de l''orient, vers l''est, cinquante coudées.'),
(2648, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 14, 'OT', 'Des toiles de quinze coudées pour le côté ; leurs piliers, trois, et leurs socles, trois.'),
(2649, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 15, 'OT', 'Et pour le second côté, de part et d''autre de la porte du parvis, des toiles de quinze coudées ; leurs piliers, trois, et leurs socles, trois.'),
(2650, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 16, 'OT', 'Toutes les toiles du parvis, tout alentour, étaient de fin lin retors.'),
(2651, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 17, 'OT', 'Les socles des piliers étaient d''airain, les crochets des piliers et leurs tringles d''argent, le revêtement de leurs têtes d''argent, et ils étaient garnis de tringles d''argent ; tous les piliers du parvis étaient ainsi.'),
(2652, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 18, 'OT', 'Le rideau de la porte du parvis était une œuvre de brodeur, en bleu, en pourpre, en cramoisi et en fin lin retors, de vingt coudées de longueur, et sa hauteur, dans la largeur, était de cinq coudées, près des toiles du parvis.'),
(2653, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 19, 'OT', 'Leurs piliers étaient quatre, et leurs socles étaient quatre, d''airain ; leurs crochets étaient d''argent, et le revêtement de leurs têtes et leurs tringles étaient d''argent.'),
(2654, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 20, 'OT', 'Tous les piquets du tabernacle et du parvis, tout alentour, étaient d''airain.'),
(2655, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 21, 'OT', 'Voici les comptes du tabernacle, du tabernacle du témoignage, qui fut dressé selon la bouche de Moïse, le service des Lévites, par la main d''Ithamar, fils d''Aaron, le sacrificateur.'),
(2656, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 22, 'OT', 'Betsaleel, fils d''Uri, fils de Hur, de la tribu de Juda, fit tout ce que l''Éternel avait commandé à Moïse.'),
(2657, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 23, 'OT', 'Et avec lui Oholiab, fils d''Ahisamac, de la tribu de Dan, artisan et ouvrier habile, et brodeur en bleu, en pourpre, en cramoisi et en lin fin.'),
(2658, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 24, 'OT', 'Tout l''or employé pour l''ouvrage, dans tout l''ouvrage du saint, et l''or de l''offrande fut de vingt-neuf talents et sept cent trente sicles, selon le sicle du sanctuaire.'),
(2659, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 25, 'OT', 'L''argent des recensés de l''assemblée fut de cent talents, et mille sept cent soixante-quinze sicles, selon le sicle du sanctuaire.'),
(2660, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 26, 'OT', 'Un demi-sicle par tête, la moitié d''un sicle, selon le sicle du sanctuaire, pour tout homme passant parmi les recensés, depuis l''âge de vingt ans et au-dessus, six cent mille et trois mille et cinq cent cinquante.'),
(2661, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 27, 'OT', 'Il y eut cent talents d''argent pour fondre les socles du sanctuaire et les socles du voile : cent socles pour cent talents, un talent par socle.'),
(2662, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 28, 'OT', 'Et des mille sept cent soixante-quinze, il fit des crochets pour les piliers, et il plaqua leurs têtes, et il les cercla.'),
(2663, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 29, 'OT', 'L''airain de l''offrande était de soixante-dix talents, et deux mille quatre cents sicles.'),
(2664, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 30, 'OT', 'Il en fit les socles de l''entrée de la tente d''assignation, l''autel d''airain, sa grille d''airain, et tous les ustensiles de l''autel.'),
(2665, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 38, 31, 'OT', 'et les socles du parvis, tout alentour, et les socles de la porte du parvis, et tous les piquets du tabernacle, et tous les piquets du parvis, tout alentour.'),
(2666, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 1, 'OT', 'Et du bleu, du pourpre et du cramoisi, ils firent des vêtements de service pour officier dans le lieu saint, et ils firent les vêtements sacrés qui étaient pour Aaron, comme l''Éternel l''avait commandé à Moïse.'),
(2667, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 2, 'OT', 'Il fit l''éphod d''or, de bleu, de pourpre et de cramoisi, et de fin lin retors.'),
(2668, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 3, 'OT', 'Ils martelèrent les pièges d''or et coupèrent des cordons, pour faire au milieu du bleu, au milieu du pourpre, au milieu du cramoisi et au milieu du lin fin, une œuvre de dessinateur.'),
(2669, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 4, 'OT', 'Ils firent pour lui des côtés, joints ensemble, sur ses deux extrémités, il fut uni.'),
(2670, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 5, 'OT', 'La ceinture de son éphod, qui était sur lui, était de la même œuvre : or, bleu, pourpre, cramoisi, et cramoisi de lin retors, comme l''Éternel l''avait commandé à Moïse.'),
(2671, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 6, 'OT', 'Ils firent les pierres d''onyx, montées en montures d''or, gravées de gravures de sceau, avec les noms des fils d''Israël.'),
(2672, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 7, 'OT', 'Il les plaça sur les côtés de l''éphod, comme pierres de mémorial pour les fils d''Israël, selon ce que l''Éternel avait commandé à Moïse.'),
(2673, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 8, 'OT', 'Il fit le pectoral, œuvre d''artisan, comme l''œuvre de l''éphod : or, bleu, pourpre, et cramoisi, et cramoisi de lin retors.'),
(2674, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 9, 'OT', 'Le pectoral était carré, double ; ils le firent double : un empan sa longueur et un empan sa largeur, double.'),
(2675, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 10, 'OT', 'Ils y enchâssèrent quatre rangées de pierres : une rangée de sardoine, de topaze et d''escarboucle, la première rangée.'),
(2676, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 11, 'OT', 'Et la seconde rangée : émeraude, saphir et diamant.'),
(2677, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 12, 'OT', 'La troisième rangée : une opale, une agate et une améthyste.'),
(2678, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 13, 'OT', 'La quatrième rangée : chrysolithe, onyx et jaspe, montées dans des montures d''or avec leurs chatons.'),
(2679, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 14, 'OT', 'Et les pierres étaient selon les noms des fils d''Israël, douze selon leurs noms ; comme des gravures de sceau, chacune avec son nom, pour les douze tribus.'),
(2680, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 15, 'OT', 'Ils firent sur le pectoral des chaînes tressées, œuvre de corde, en or pur.'),
(2681, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 16, 'OT', 'Ils firent deux montures d''or et deux anneaux d''or, et ils mirent les deux anneaux aux deux extrémités du pectoral.'),
(2682, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 17, 'OT', 'Ils mirent les deux cordes d''or sur les deux anneaux, aux extrémités du pectoral.'),
(2683, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 18, 'OT', 'Et ils mirent les deux extrémités des deux cordes sur les deux montures, et ils les placèrent sur les côtés de l''éphod, en face de sa face.'),
(2684, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 19, 'OT', 'Ils firent deux anneaux d''or et les mirent aux deux extrémités du pectoral, sur sa lèvre qui est vers l''au-delà de l''éphod, du côté de la maison.'),
(2685, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 20, 'OT', 'Ils firent deux anneaux d''or, et les mirent sur les deux côtés de l''éphod, en dessous, devant sa face, près de sa jointure, au-dessus de la ceinture de l''éphod.'),
(2686, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 21, 'OT', 'Ils attachèrent le pectoral par ses anneaux aux anneaux de l''éphod avec un cordon de bleu, afin qu''il fût sur la ceinture de l''éphod, et que le pectoral ne se détachât point de dessus l''éphod, comme l''Éternel l''avait commandé à Moïse.'),
(2687, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 22, 'OT', 'Il fit le manteau de l''éphod, œuvre de tissage, tout en bleu.'),
(2688, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 23, 'OT', 'L''ouverture du manteau, en son milieu, était comme l''ouverture d''une cotte de mailles, avec une lèvre autour de son ouverture, tout alentour, afin qu''elle ne se déchire pas.'),
(2689, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 24, 'OT', 'Ils firent sur la bordure du manteau des grenades de bleu, de pourpre et de cramoisi, en fil retors.'),
(2690, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 25, 'OT', 'Ils firent des clochettes d''or pur, et ils mirent les clochettes au milieu des grenades, sur la bordure du manteau, tout alentour, au milieu des grenades.'),
(2691, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 26, 'OT', 'Une clochette et une grenade, une clochette et une grenade, sur la bordure du manteau, tout alentour, pour le service, comme l''Éternel l''avait commandé à Moïse.'),
(2692, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 27, 'OT', 'Ils firent les tuniques de lin, œuvre de tisserand, pour Aaron et pour ses fils.'),
(2693, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 28, 'OT', 'Et la tiare de lin, et les diadèmes des bonnets de lin, et les caleçons de lin, en lin fin retors.'),
(2694, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 29, 'OT', 'Et la ceinture de fin lin retors, et de bleu, et de pourpre, et de cramoisi, œuvre de tisserand, comme l''Éternel l''avait commandé à Moïse.'),
(2695, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 30, 'OT', 'Ils firent la fleur du diadème saint en or pur, et ils écrivirent dessus un écrit de gravure de sceau : Saint à l''Éternel.'),
(2696, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 31, 'OT', 'Ils mirent sur lui un cordon de bleu, pour le poser sur la tiare par-dessus, comme l''Éternel l''avait commandé à Moïse.'),
(2697, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 32, 'OT', 'Ainsi fut achevé tout le service du tabernacle de la tente d''assignation ; et les fils d''Israël firent selon tout ce que l''Éternel avait commandé à Moïse ; ainsi ils firent.'),
(2698, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 33, 'OT', 'Ils apportèrent le tabernacle à Moïse, la tente et tout son ustensile, ses agrafes, ses planches, ses verrous, ses piliers et ses socles.'),
(2699, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 34, 'OT', 'et la couverture de peaux de béliers teintes en rouge, et la couverture de peaux de dauphin, et le voile du rideau.'),
(2700, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 35, 'OT', 'l''arche du témoignage et ses barres, et le propitiatoire.'),
(2701, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 36, 'OT', 'la table, tous ses ustensiles, et le pain des faces'),
(2702, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 37, 'OT', 'le chandelier pur, ses lampes, les lampes du rang, et tous ses ustensiles, et l''huile du luminaire.'),
(2703, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 38, 'OT', 'et l''autel d''or, et l''huile d''onction, et l''encens des aromates, et le rideau de l''entrée de la tente.'),
(2704, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 39, 'OT', 'L''autel d''airain, et sa grille d''airain, ses barres et tous ses ustensiles, le bassin et sa base.'),
(2705, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 40, 'OT', 'Les toiles du parvis, ses piliers et ses socles, le rideau pour la porte du parvis, ses cordes et ses piquets, et tous les ustensiles du service du tabernacle, pour la tente d''assignation.'),
(2706, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 41, 'OT', 'Les vêtements du service pour officier dans le saint lieu, les vêtements sacrés pour Aaron le sacrificateur, et les vêtements de ses fils pour exercer la sacrificature.'),
(2707, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 42, 'OT', 'Selon tout ce que l''Éternel avait commandé à Moïse, ainsi les fils d''Israël firent tout le service.'),
(2708, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 39, 43, 'OT', 'Moïse vit tout l''ouvrage, et voici, ils l''avaient fait comme l''Éternel l''avait commandé ; ainsi ils le firent, et Moïse les bénit.'),
(2709, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2710, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 2, 'OT', 'Le premier jour du mois, le premier du mois, tu dresseras le tabernacle, la tente d''assignation.'),
(2711, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 3, 'OT', 'Tu placeras là l''arche du témoignage, et tu couvriras l''arche avec le voile.'),
(2712, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 4, 'OT', 'Tu apporteras la table et tu disposeras son estimation, et tu apporteras le chandelier et tu allumeras ses lampes.'),
(2713, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 5, 'OT', 'Tu placeras l''autel d''or pour l''encens devant l''arche du témoignage, et tu mettras le rideau de l''entrée du tabernacle.'),
(2714, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 6, 'OT', 'Tu placeras l''autel de l''holocauste devant l''entrée du tabernacle de la tente d''assignation.'),
(2715, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 7, 'OT', 'Tu placeras le bassin entre la tente d''assignation et l''autel, et tu y mettras des eaux.'),
(2716, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 8, 'OT', 'Tu placeras le parvis tout alentour, et tu mettras le rideau de la porte du parvis.'),
(2717, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 9, 'OT', 'Tu prendras l''huile de l''onction, et tu oindras le tabernacle et tout ce qui s''y trouve, et tu le sanctifieras, lui et tous ses ustensiles, et il sera saint.'),
(2718, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 10, 'OT', 'Tu oindras l''autel de l''holocauste et tous ses ustensiles, et tu consacreras l''autel, et l''autel sera très saint.'),
(2719, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 11, 'OT', 'Tu oindras le bassin et sa base, et tu le sanctifieras.'),
(2720, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 12, 'OT', 'Tu feras approcher Aaron et ses fils à l''entrée de la tente d''assignation, et tu les laveras avec des eaux.'),
(2721, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 13, 'OT', 'Tu revêtiras Aaron des vêtements saints, tu l''oindras et tu le consacreras, et il exercera le sacerdoce pour moi.'),
(2722, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 14, 'OT', 'Tu feras approcher ses fils, et tu les revêtiras de tuniques.'),
(2723, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 15, 'OT', 'Tu les oindras comme tu as oint leur père, et ils seront prêtres pour moi ; et leur onction sera pour eux un sacerdoce perpétuel, pour leurs générations.'),
(2724, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 16, 'OT', 'Moïse fit tout ce que l''Éternel lui avait commandé ; ainsi il le fit.'),
(2725, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 17, 'OT', 'Il advint, au premier mois de la deuxième année, le premier jour du mois, que le tabernacle fut dressé.'),
(2726, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 18, 'OT', 'Moïse dressa le tabernacle, et il plaça ses socles, et il mit ses planches, et il posa ses verrous, et il dressa ses piliers.'),
(2727, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 19, 'OT', 'Il étendit la tente sur le tabernacle, et il mit la couverture de la tente par-dessus, au-dessus, comme l''Éternel l''avait commandé à Moïse.'),
(2728, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 20, 'OT', 'Il prit et mit le témoignage dans l''arche, plaça les barres sur l''arche, et mit le propitiatoire sur l''arche, par-dessus.'),
(2729, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 21, 'OT', 'Il fit entrer l''arche dans le tabernacle, plaça le voile du rideau, et couvrit l''arche du témoignage, comme l''Éternel l''avait commandé à Moïse.'),
(2730, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 22, 'OT', 'Il plaça la table dans la tente d''assignation, sur le côté nord du tabernacle, en dehors du voile.'),
(2731, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 23, 'OT', 'Il disposa sur elle l''estimation du pain devant la face de l''Éternel, comme l''Éternel l''avait commandé à Moïse.'),
(2732, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 24, 'OT', 'Il plaça le chandelier dans la tente d''assignation, en face de la table, sur le côté du tabernacle vers le midi.'),
(2733, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 25, 'OT', 'Il alluma les lampes devant la face de l''Éternel, comme l''Éternel l''avait commandé à Moïse.'),
(2734, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 26, 'OT', 'Il plaça l''autel d''or dans la tente d''assignation, devant le voile.'),
(2735, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 27, 'OT', 'Il fit monter sur lui un encens d''aromates, comme l''Éternel l''avait commandé à Moïse.'),
(2736, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 28, 'OT', 'Il plaça le rideau de l''entrée du tabernacle.'),
(2737, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 29, 'OT', 'Il plaça l''autel de l''holocauste à l''entrée du tabernacle de la tente d''assignation, et il offrit sur lui l''holocauste et l''offrande, comme l''Éternel l''avait commandé à Moïse.'),
(2738, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 30, 'OT', 'Il plaça le bassin entre la tente d''assignation et l''autel, et y mit des eaux pour le lavage.'),
(2739, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 31, 'OT', 'Moïse, Aaron et ses fils s''y lavaient les mains et les pieds.'),
(2740, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 32, 'OT', 'Lorsqu''ils entraient dans la tente d''assignation et qu''ils s''approchaient de l''autel, ils se lavaient, comme l''Éternel l''avait commandé à Moïse.'),
(2741, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 33, 'OT', 'Il dressa le parvis tout alentour du tabernacle et de l''autel, et il mit le rideau de la porte du parvis. Et Moïse acheva l''ouvrage.'),
(2742, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 34, 'OT', 'La nuée couvrit la tente d''assignation, et la gloire de l''Éternel remplit le tabernacle.'),
(2743, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 35, 'OT', 'Moïse ne pouvait pas entrer dans la tente d''assignation, car la nuée s''était posée sur elle, et la gloire de l''Éternel remplissait le tabernacle.'),
(2744, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 36, 'OT', 'Et lorsque la nuée s''élevait de dessus le tabernacle, les fils d''Israël partaient en toutes leurs marches.'),
(2745, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 37, 'OT', 'Et si la nuée ne s''élevait pas, ils ne partaient pas jusqu''au jour où elle s''élevait.'),
(2746, 2, 'GOI_Fr', 'GOI_Fr', 'fr', 'EXO', 40, 38, 'OT', 'Car la nuée de l''Éternel était sur le tabernacle pendant le jour, et un feu y était pendant la nuit, aux yeux de toute la maison d''Israël, dans toutes leurs marches.'),
(2747, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 1, 'OT', 'L''Éternel appela Moïse et lui parla depuis la tente d''assignation, en disant :'),
(2748, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 2, 'OT', 'Parle aux fils d''Israël et dis-leur : Si un homme d''entre vous présente une offrande à l''Éternel, vous présenterez votre offrande parmi le bétail, parmi les bœufs et parmi les brebis.'),
(2749, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 3, 'OT', 'Si son offrande est un holocauste pris du bœuf, il l''offrira, un mâle sans défaut ; il le présentera à l''entrée de la tente d''assignation, pour sa bienveillance, devant la face de l''Éternel.'),
(2750, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 4, 'OT', 'Il posera sa main sur la tête de l''holocauste, et il lui sera agréé pour faire l''expiation pour lui.'),
(2751, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 5, 'OT', 'Il égorgera le fils du bœuf devant l''Éternel, et les fils d''Aaron, les sacrificateurs, offriront le sang, et ils répandront le sang sur l''autel tout autour, qui est à l''entrée de la tente d''assignation.'),
(2752, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 6, 'OT', 'Il dépouillera le holocauste, et le découpera en ses morceaux.'),
(2753, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 7, 'OT', 'Les fils d''Aaron, le sacrificateur, mettront du feu sur l''autel, et disposeront du bois sur le feu.'),
(2754, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 8, 'OT', 'Les fils d''Aaron, les sacrificateurs, disposeront les morceaux, la tête et la graisse, sur le bois qui est sur le feu, qui est sur l''autel.'),
(2755, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 9, 'OT', 'Il lavera avec les eaux son milieu et ses jambes, et le sacrificateur fera fumer tout sur l''autel : un holocauste, un sacrifice consumé par le feu, une odeur agréable à l''Éternel.'),
(2756, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 10, 'OT', 'Et si son offrande est du troupeau, des agneaux ou des chèvres, pour un holocauste, il l''offrira, un mâle sans défaut.'),
(2757, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 11, 'OT', 'Il l''égorgera sur le côté de l''autel, vers le nord, devant l''Éternel ; et les fils d''Aaron, les sacrificateurs, répandront son sang sur l''autel, tout alentour.'),
(2758, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 12, 'OT', 'On le coupera en ses morceaux, avec sa tête et sa graisse ; et le sacrificateur les arrangera sur le bois qui est sur le feu, qui est sur l''autel.'),
(2759, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 13, 'OT', 'Il lavera le milieu et les jambes avec les eaux, et le sacrificateur offrira tout et le fera brûler sur l''autel : c''est un holocauste, un sacrifice consumé par le feu, une odeur agréable à l''Éternel.'),
(2760, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 14, 'OT', 'Et si son offrande à l''Éternel est un holocauste d''oiseau, il présentera son offrande de tourterelles ou de jeunes pigeons.'),
(2761, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 15, 'OT', 'Le sacrificateur l''offrira à l''autel, lui rompra la tête, et la fera brûler sur l''autel ; et son sang sera exprimé contre le mur de l''autel.'),
(2762, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 16, 'OT', 'Il ôtera son jabot avec ses plumes, et le jettera à côté de l''autel, vers l''orient, au lieu des cendres.'),
(2763, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 1, 17, 'OT', 'Il la déchirera par ses ailes, sans la diviser ; et le sacrificateur la fera fumer sur l''autel, sur le bois qui est sur le feu ; c''est un holocauste, un sacrifice consumé par le feu, une odeur agréable à l''Éternel.'),
(2764, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 1, 'OT', 'Si une âme présente une offrande de minchah à l''Éternel, son offrande sera de fleur de farine, et il versera de l''huile dessus, et il mettra de l''encens dessus.'),
(2765, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 2, 'OT', 'Il l''apportera aux fils d''Aaron, les sacrificateurs ; et il prendra de là une pleine poignée de sa fleur de farine et de son huile, avec tout son encens ; et le sacrificateur fera fumer son mémorial sur l''autel, sacrifice consumé par le feu, d''une odeur agréable à l''Éternel.'),
(2766, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 3, 'OT', 'Et le reste de l''offrande sera pour Aaron et pour ses fils ; c''est une chose très sainte, parmi les sacrifices consumés par le feu, offerts à l''Éternel.'),
(2767, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 4, 'OT', 'Et si tu présentes une offrande de grain en cuisson au four, ce sera de la fleur de farine : des gâteaux de pains sans levain mêlés à l''huile, et des galettes de pains sans levain ointes d''huile.'),
(2768, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 5, 'OT', 'Et si ton offrande est une offrande sur le poêle, ce sera de la fleur de farine pétrie à l''huile, des pains sans levain.'),
(2769, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 6, 'OT', 'Tu la briseras en morceaux, et tu verseras de l''huile dessus ; c''est une offrande.'),
(2770, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 7, 'OT', 'Si ton offrande est une offrande de poêle, elle sera faite de fleur de farine avec de l''huile.'),
(2771, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 8, 'OT', 'Tu apporteras l''offrande qui sera faite de ces choses à l''Éternel, et tu la présenteras au sacrificateur, et il la déposera sur l''autel.'),
(2772, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 9, 'OT', 'Le sacrificateur prélèvera de l''offrande son mémorial, et il le fera brûler sur l''autel : un sacrifice consumé par le feu, une odeur agréable à l''Éternel.'),
(2773, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 10, 'OT', 'Et le reste de l''offrande sera pour Aaron et pour ses fils : c''est une chose très sainte, parmi les sacrifices consumés par le feu de l''Éternel.'),
(2774, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 11, 'OT', 'Toute offrande que vous offrirez à l''Éternel ne sera point faite avec du levain ; car vous ne ferez brûler de rien de cela, ni levain ni miel, comme sacrifice consumé par le feu à l''Éternel.'),
(2775, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 12, 'OT', 'Vous offrirez l''offrande de commencement à l''Éternel, mais elles ne monteront pas sur l''autel pour une odeur agréable.'),
(2776, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 13, 'OT', 'Tu saleras avec du sel toute offrande de ton offrande de farine ; tu ne laisseras pas manquer le sel de l''alliance de ton Dieu sur ton offrande de farine ; sur toute offrande que tu présenteras, tu offriras du sel.'),
(2777, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 14, 'OT', 'Et si tu présentes une offrande de premiers fruits à l''Éternel, tu présenteras des épis rôtis au feu, du grain broyé de verger, comme offrande de tes premiers fruits.'),
(2778, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 15, 'OT', 'Tu mettras de l''huile dessus, et tu placeras de l''encens dessus ; c''est une offrande.'),
(2779, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 2, 16, 'OT', 'Le sacrificateur fera fumer son mémorial, de son grain broyé et de son huile, avec tout son encens : c''est un sacrifice consumé par le feu à l''Éternel.'),
(2780, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 1, 'OT', 'Si son offrande est un sacrifice d''actions de grâces, s''il l''offre du bœuf, que ce soit un mâle ou une femelle, il l''offrira sans défaut devant la face de l''Éternel.'),
(2781, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 2, 'OT', 'Il posera sa main sur la tête de son offrande et l''égorgera à l''entrée de la tente d''assignation ; et les fils d''Aaron, les sacrificateurs, répandront le sang sur l''autel, tout alentour.'),
(2782, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 3, 'OT', 'Il offrira du sacrifice d''actions de grâces un sacrifice consumé par le feu à l''Éternel : la graisse qui couvre le milieu, et toute la graisse qui est sur le milieu.'),
(2783, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 4, 'OT', 'Et les deux reins, et la graisse qui est sur eux, qui est sur la confiance, et la graisse qui est sur le foie, sur les reins, il la retirera.'),
(2784, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 5, 'OT', 'Les fils d''Aaron feront fumer cela sur l''autel, par-dessus l''holocauste qui est sur le bois qui est sur le feu : c''est un sacrifice consumé par le feu, une odeur agréable à l''Éternel.'),
(2785, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 6, 'OT', 'Si son offrande pour un sacrifice d''actions de grâces à l''Éternel est de brebis, mâle ou femelle, il l''offrira sans défaut.'),
(2786, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 7, 'OT', 'S''il offre un agneau comme son offrande, il le présentera devant la face de l''Éternel.'),
(2787, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 8, 'OT', 'Il posera sa main sur la tête de son offrande, et l''égorgera devant la tente d''assignation ; et les fils d''Aaron répandront son sang sur l''autel, tout alentour.'),
(2788, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 9, 'OT', 'Il offrira du sacrifice d''actions de grâces un sacrifice consumé par le feu à l''Éternel : sa graisse, la queue entière, qu''il retirera près de l''échine, et la graisse qui couvre le milieu, et toute la graisse qui est sur le milieu.'),
(2789, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 10, 'OT', 'Et les deux reins, et la graisse qui est sur eux, qui est sur la confiance, et la graisse qui est sur le foie, sur les reins, il l''ôtera.'),
(2790, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 11, 'OT', 'Le sacrificateur le fera brûler sur l''autel, comme pain d''un sacrifice consumé par le feu pour l''Éternel.'),
(2791, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 12, 'OT', 'Et si son offrande est une chèvre, il la présentera devant la face de l''Éternel.'),
(2792, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 13, 'OT', 'Il posera sa main sur sa tête, et l''égorgera devant la tente d''assignation ; et les fils d''Aaron répandront son sang sur l''autel, tout alentour.'),
(2793, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 14, 'OT', 'Il offrira de son offrande un sacrifice consumé par le feu à l''Éternel : la graisse qui couvre le milieu, et toute la graisse qui est sur le milieu.'),
(2794, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 15, 'OT', 'Et les deux reins, et la graisse qui est sur eux, qui est sur la confiance, et la graisse qui est sur le foie, sur les reins, il la retirera.'),
(2795, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 16, 'OT', 'Le sacrificateur les fera fumer sur l''autel, comme pain d''un sacrifice consumé par le feu, d''une odeur agréable à l''Éternel ; toute la graisse est à l''Éternel.'),
(2796, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 3, 17, 'OT', 'Loi perpétuelle pour vos générations, dans toutes vos habitations : toute graisse et tout sang, vous n''en mangerez point.'),
(2797, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2798, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 2, 'OT', 'Parle aux fils d''Israël, en disant : Si une âme pèche involontairement, contre l''un de tous les commandements de l''Éternel, qui ne doivent pas être faits, et qu''elle fasse l''une de ces choses,'),
(2799, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 3, 'OT', 'Si le sacrificateur oint pèche, entraînant la culpabilité du peuple, il offrira pour son péché qu''il a commis un jeune taureau, sans défaut, à l''Éternel, en sacrifice pour le péché.'),
(2800, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 4, 'OT', 'Il amènera le taureau à l''entrée de la tente d''assignation, devant l''Éternel, et il posera sa main sur la tête du taureau, et il égorgera le taureau devant l''Éternel.'),
(2801, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 5, 'OT', 'Le sacrificateur oint prendra du sang du taureau et l''apportera à la tente d''assignation.'),
(2802, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 6, 'OT', 'Le sacrificateur trempera son doigt dans le sang, et il fera aspersion du sang sept fois devant l''Éternel, vers la face du voile du saint.'),
(2803, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 7, 'OT', 'Le sacrificateur mettra du sang sur les cornes de l''autel de l''encens des aromates, devant l''Éternel, qui est dans la tente d''assignation ; et tout le sang du taureau, il le versera au fondement de l''autel de l''holocauste, qui est à l''entrée de la tente d''assignation.'),
(2804, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 8, 'OT', 'Et il prélèvera de lui toute la graisse du taureau du sacrifice pour le péché : la graisse qui recouvre le milieu, et toute la graisse qui est sur le milieu.'),
(2805, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 9, 'OT', 'Et les deux reins, et la graisse qui est sur eux, qui est sur la confiance, et la graisse qui est sur le foie, sur les reins, il la retirera.'),
(2806, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 10, 'OT', 'Comme on lève du bœuf du sacrifice d''actions de grâces, le sacrificateur les fera fumer sur l''autel de l''holocauste.'),
(2807, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 11, 'OT', 'Et la peau du taureau, et toute sa chair, avec sa tête et ses jambes, et son milieu et ses excréments.'),
(2808, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 12, 'OT', 'Il fera sortir tout le taureau en dehors du camp, vers un lieu pur, vers le tas de cendres, et il le brûlera sur du bois au feu ; c''est sur le tas de cendres qu''il sera brûlé.'),
(2809, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 13, 'OT', 'Et si toute l''assemblée d''Israël s''égare, et que la parole soit cachée aux yeux de l''assemblée, et qu''ils fassent une de toutes les commandements de l''Éternel, lesquelles ne doivent pas être faites, et qu''ils se rendent coupables,'),
(2810, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 14, 'OT', 'Quand le péché qu''ils ont commis contre elle sera connu, l''assemblée offrira un jeune taureau, en sacrifice pour le péché, et ils l''amèneront devant la face de la tente d''assignation.'),
(2811, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 15, 'OT', 'Les anciens de l''assemblée poseront leurs mains sur la tête du taureau devant l''Éternel, et on égorgera le taureau devant l''Éternel.'),
(2812, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 16, 'OT', 'Le sacrificateur oint apportera du sang du taureau à la tente d''assignation.'),
(2813, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 17, 'OT', 'Le sacrificateur trempera son doigt dans le sang, et il fera sept fois aspersion devant l''Éternel, vers la face du voile.'),
(2814, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 18, 'OT', 'Et du sang il mettra sur les cornes de l''autel qui est devant l''Éternel, qui est dans la tente d''assignation, et tout le sang il versera contre le fondement de l''autel de l''holocauste, qui est à l''entrée de la tente d''assignation.'),
(2815, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 19, 'OT', 'Il ôtera toute sa graisse de dessus lui, et il la fera brûler sur l''autel.'),
(2816, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 20, 'OT', 'Il fera au taureau comme il a fait au taureau du sacrifice pour le péché ; ainsi fera-t-il pour lui. Le sacrificateur fera l''expiation pour eux, et il leur sera pardonné.'),
(2817, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 21, 'OT', 'Il fera sortir le taureau dehors, hors du camp, et le brûlera comme il a brûlé le premier taureau ; c''est le péché de l''assemblée.'),
(2818, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 22, 'OT', 'Lorsqu''un prince pèche et fait l''une de toutes les choses que l''Éternel, son Dieu, a commandées de ne pas faire, involontairement, et se rend coupable,'),
(2819, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 23, 'OT', 'Ou si son péché qu''il a commis lui est révélé, il apportera son offrande : un bouc mâle sans défaut, pris parmi les chèvres.'),
(2820, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 24, 'OT', 'Il posera sa main sur la tête du bouc et le sacrifiera dans le lieu où l''on sacrifie l''holocauste devant l''Éternel ; c''est un sacrifice pour le péché.'),
(2821, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 25, 'OT', 'Le sacrificateur prendra du sang du sacrifice pour le péché avec son doigt, et en mettra sur les cornes de l''autel de l''holocauste, et il versera son sang au fondement de l''autel de l''holocauste.'),
(2822, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 26, 'OT', 'Et il fera fumer toute sa graisse sur l''autel, comme la graisse du sacrifice d''actions de grâces ; et le sacrificateur fera propitiation pour lui à cause de son péché, et il lui sera pardonné.'),
(2823, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 27, 'OT', 'Et si une âme du peuple de la terre pèche involontairement, en faisant l''une des choses qui sont parmi les commandements de l''Éternel, lesquelles ne doivent pas se faire, et qu''elle se rende coupable,'),
(2824, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 28, 'OT', 'Ou si l''on lui fait connaître son péché qu''il a commis, il apportera son offrande : une chèvre femelle sans défaut, pour son péché qu''il a commis.'),
(2825, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 29, 'OT', 'Il posera sa main sur la tête du sacrifice pour le péché, et égorgera le sacrifice pour le péché au lieu de l''holocauste.'),
(2826, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 30, 'OT', 'Le sacrificateur prendra de son sang avec son doigt, et le mettra sur les cornes de l''autel de l''holocauste, et il répandra tout son sang au fondement de l''autel.'),
(2827, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 31, 'OT', 'Il ôtera toute sa graisse, comme on ôte la graisse de dessus le sacrifice d''actions de grâces ; et le sacrificateur la fera fumer sur l''autel, en odeur agréable à l''Éternel ; et le sacrificateur fera l''expiation pour lui, et il lui sera pardonné.'),
(2828, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 32, 'OT', 'Et si un agneau est son offrande pour le péché, il l''amènera femelle sans défaut.'),
(2829, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 33, 'OT', 'Il posera sa main sur la tête du sacrifice pour le péché, et l''égorgera comme sacrifice pour le péché dans le lieu où l''on égorge l''holocauste.'),
(2830, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 34, 'OT', 'Le sacrificateur prendra avec son doigt du sang du sacrifice pour le péché, et il en mettra sur les cornes de l''autel de l''holocauste ; et tout son sang, il le versera sur le fondement de l''autel.'),
(2831, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 4, 35, 'OT', 'Et il enlèvera toute sa graisse, comme on enlève la graisse de l''agneau du sacrifice d''actions de grâces ; et le sacrificateur les fera fumer sur l''autel, sur les sacrifices consumés par le feu de l''Éternel ; et le sacrificateur fera l''expiation pour lui, à cause de son péché qu''il a commis, et il lui sera pardonné.'),
(2832, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 1, 'OT', 'Si une âme pèche, et qu''elle entende la voix d''une malédiction, et qu''elle soit témoin, soit qu''elle ait vu, soit qu''elle ait connu, si elle ne le déclare pas, elle portera son iniquité.'),
(2833, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 2, 'OT', 'Ou bien une âme qui touche à toute parole impure, soit la carcasse d''une vie impure, soit la carcasse d''un bétail impur, soit la carcasse d''un reptile impur, et que cela lui soit caché, et qu''il soit impur, et qu''il soit coupable.'),
(2834, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 3, 'OT', 'Ou s''il touche l''impureté d''un homme, selon toute son impureté par laquelle il se rend impur, et que cela lui soit caché, puis qu''il le sache, il sera coupable.'),
(2835, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 4, 'OT', 'Ou bien une âme qui jure, en proférant avec ses lèvres, pour faire du mal ou pour faire du bien, en tout ce que l''homme profère par serment, et que cela lui soit caché, et qu''il le sache, et qu''il soit coupable pour l''une de ces choses.'),
(2836, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 5, 'OT', 'Et il arrivera que, lorsqu''il sera coupable de l''une de ces choses, il confessera le péché qu''il a commis en elle.'),
(2837, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 6, 'OT', 'Il amènera son sacrifice de culpabilité à l''Éternel pour son péché qu''il a commis : une femelle du troupeau, une agnelle ou une chèvre, en sacrifice pour le péché ; et le sacrificateur fera l''expiation pour lui, à cause de son péché.'),
(2838, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 7, 'OT', 'Et si sa main n''atteint pas la suffisance d''un agneau, il apportera son sacrifice de culpabilité pour ce qu''il a commis : deux tourterelles ou deux jeunes pigeons à l''Éternel, l''un pour le péché et l''autre pour l''holocauste.'),
(2839, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 8, 'OT', 'Il les apportera au sacrificateur, et il offrira d''abord celui qui est pour le péché ; il lui brisera la tête près du cou, sans la séparer.'),
(2840, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 9, 'OT', 'Il aspergera du sang du sacrifice pour le péché sur le mur de l''autel, et le reste du sang sera pressé contre le fondement de l''autel ; c''est un sacrifice pour le péché.'),
(2841, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 10, 'OT', 'Il fera le second en holocauste, selon le jugement ; et le sacrificateur fera l''expiation pour lui, à cause de son péché qu''il a commis, et il lui sera pardonné.'),
(2842, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 11, 'OT', 'Et si sa main n''atteint pas deux tourterelles ou deux jeunes pigeons, il apportera son offrande pour ce qu''il a péché : un dixième d''épha de fleur de farine pour le péché ; il ne mettra pas d''huile dessus, et il ne mettra pas d''encens dessus, car c''est un péché.'),
(2843, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 12, 'OT', 'Il l''apportera au sacrificateur, et le sacrificateur prendra de son contenu une pleine poignée, son mémorial, et le fera fumer sur l''autel, sur les sacrifices consumés par le feu de l''Éternel ; c''est un sacrifice pour le péché.'),
(2844, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 13, 'OT', 'Le sacrificateur fera l''expiation pour lui, à cause de son péché qu''il a commis dans l''une de ces choses, et il lui sera pardonné ; et cela appartiendra au sacrificateur, comme l''offrande.'),
(2845, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 14, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2846, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 15, 'OT', 'Si une âme commet une perfidie et pèche involontairement à l''égard des choses saintes de l''Éternel, elle apportera à l''Éternel, comme sacrifice de culpabilité, un bélier sans défaut pris du troupeau, selon ton estimation, en argent, en sicles, selon le sicle du sanctuaire, pour un sacrifice de culpabilité.'),
(2847, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 16, 'OT', 'Et ce qu''il a péché contre le saint, il le restituera, et il y ajoutera son cinquième, et le donnera au sacrificateur ; et le sacrificateur fera l''expiation pour lui avec le bélier du sacrifice de culpabilité, et il lui sera pardonné.'),
(2848, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 17, 'OT', 'Et si une âme pèche et fait l''une de toutes les choses qui, parmi les commandements de l''Éternel, ne doivent pas être faites, sans le savoir, elle est coupable et portera son iniquité.'),
(2849, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 18, 'OT', 'Il amènera un bélier sans défaut du troupeau, selon ton estimation, en sacrifice de culpabilité, au sacrificateur ; et le sacrificateur fera l''expiation pour lui au sujet de son péché commis involontairement, qu''il a commis sans le savoir, et il lui sera pardonné.'),
(2850, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 5, 19, 'OT', 'C''est un sacrifice de culpabilité ; il a certainement commis une faute envers l''Éternel.'),
(2851, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2852, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 2, 'OT', 'Si une âme pèche et commet une perfidie envers l''Éternel, et qu''elle mente à son prochain au sujet d''un dépôt, ou d''un dépôt remis en main, ou d''une rapine, ou qu''elle opprime son prochain,'),
(2853, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 3, 'OT', 'ou bien il trouve une perte et la nie, et jure sur un mensonge, au sujet de l''une de toutes les choses que l''homme fait pour pécher en elles.'),
(2854, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 4, 'OT', 'Et il arrivera que, s''il pèche et se rend coupable, il restituera la rapine qu''il a ravie, ou l''oppression qu''il a commise, ou le dépôt qui lui avait été confié, ou la perte qu''il a trouvée.'),
(2855, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 5, 'OT', 'ou de tout ce sur quoi il a juré faussement pour un mensonge, il le restituera en sa tête, et il y ajoutera ses cinquièmes ; à celui à qui cela appartient, il le donnera au jour de sa culpabilité.'),
(2856, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 6, 'OT', 'Et il amènera son sacrifice de culpabilité à l''Éternel : un bélier sans défaut, pris du troupeau de brebis, selon ton estimation, pour un sacrifice de culpabilité, au sacrificateur.'),
(2857, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 7, 'OT', 'Le sacrificateur fera l''expiation pour lui devant la face de l''Éternel, et il lui sera pardonné, pour toute chose qu''il aura faite en vue d''une culpabilité.'),
(2858, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 8, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2859, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 9, 'OT', 'Ordonne à Aaron et à ses fils, en disant : Voici la loi de l''holocauste : c''est l''holocauste sur son foyer, sur l''autel, toute la nuit jusqu''au matin, et le feu de l''autel y brûlera.'),
(2860, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 10, 'OT', 'Le sacrificateur revêtira son vêtement de lin, et il mettra des caleçons de lin sur sa chair ; il enlèvera la cendre que le feu a consumée de l''holocauste sur l''autel, et il la déposera à côté de l''autel.'),
(2861, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 11, 'OT', 'Il ôtera ses vêtements, et revêtira d''autres vêtements, et il emportera les cendres dehors, hors du camp, vers un lieu pur.'),
(2862, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 12, 'OT', 'Le feu sur l''autel y sera entretenu, il ne s''éteindra pas ; le sacrificateur y brûlera du bois chaque matin, chaque matin, il y arrangera l''holocauste, et il y fera fumer la graisse des sacrifices d''actions de grâces.'),
(2863, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 13, 'OT', 'Un feu toujours brûlera sur l''autel ; il ne s''éteindra pas.'),
(2864, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 14, 'OT', 'Et telle est la loi de l''offrande : les fils d''Aaron la présenteront devant l''Éternel, devant la face de l''autel.'),
(2865, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 15, 'OT', 'Il prélèvera de sa poignée de la fleur de farine de l''offrande et de son huile, ainsi que tout l''encens qui est sur l''offrande, et il le fera fumer sur l''autel comme une odeur agréable, son mémorial, à l''Éternel.'),
(2866, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 16, 'OT', 'Le reste de ce qui en restera, Aaron et ses fils le mangeront ; on le mangera en pains sans levain dans un lieu saint ; dans le parvis de la tente d''assignation, ils le mangeront.'),
(2867, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 17, 'OT', 'Elle ne sera point cuite avec du levain ; c''est leur part que je leur ai donnée de mes sacrifices consumés par le feu ; c''est une chose très sainte, comme le sacrifice pour le péché et comme le sacrifice de culpabilité.'),
(2868, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 18, 'OT', 'Tout mâle parmi les fils d''Aaron la mangera ; c''est un statut perpétuel pour vos générations, tiré des sacrifices consumés par le feu de l''Éternel ; tout ce qui les touchera sera saint.'),
(2869, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 19, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2870, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 20, 'OT', 'Voici l''offrande d''Aaron et de ses fils, qu''ils offriront à l''Éternel, au jour de son onction : un dixième d''épha de fleur de farine, comme offrande perpétuelle, la moitié le matin et la moitié le soir.'),
(2871, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 21, 'OT', 'Sur une poêle, à l''huile, elle sera faite, pétrie ; tu l''apporteras ; en morceaux cuits, l''offrande de morceaux, tu l''offriras en odeur agréable à l''Éternel.'),
(2872, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 22, 'OT', 'Le sacrificateur oint, qui sera à sa place parmi ses fils, fera cette offrande : c''est un statut pour toujours devant l''Éternel ; elle sera entièrement consumée par le feu.'),
(2873, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 23, 'OT', 'Et toute offrande de sacrificateur sera entièrement consumée ; elle ne sera point mangée.'),
(2874, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 24, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2875, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 25, 'OT', 'Parle à Aaron et à ses fils, en disant : Voici la loi du sacrifice pour le péché : dans le lieu où l''holocauste est immolé, le sacrifice pour le péché sera immolé devant l''Éternel ; c''est une chose très sainte.'),
(2876, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 26, 'OT', 'Le sacrificateur qui fait l''expiation pour elle la mangera ; c''est dans un lieu saint qu''elle sera mangée, dans le parvis de la tente d''assignation.'),
(2877, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 27, 'OT', 'Tout ce qui touchera sa chair sera saint, et ce qui sera aspergé de son sang sur le vêtement, ce sur quoi il sera aspergé, tu le laveras dans un lieu saint.'),
(2878, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 28, 'OT', 'Et l''ustensile de vase de terre dans lequel elle sera cuite sera brisé ; mais si c''est dans un ustensile d''airain qu''elle a été cuite, il sera récuré et rincé dans les eaux.'),
(2879, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 29, 'OT', 'Tout mâle parmi les sacrificateurs la mangera ; c''est une chose très sainte.'),
(2880, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 6, 30, 'OT', 'Et tout péché dont on apportera de son sang dans la tente d''assignation pour faire l''expiation dans le lieu saint ne sera point mangé ; il sera brûlé au feu.'),
(2881, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 1, 'OT', 'Et c''est ici la loi du sacrifice de culpabilité : il est très saint.'),
(2882, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 2, 'OT', 'Au lieu où l''on égorge l''holocauste, on égorgera le sacrifice de culpabilité, et l''on répandra son sang sur l''autel, tout alentour.'),
(2883, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 3, 'OT', 'Il offrira de lui toute sa graisse : la queue et la graisse qui couvre le milieu.'),
(2884, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 4, 'OT', 'Et les deux reins, et la graisse qui est sur eux, qui est sur la confiance, et la graisse qui est sur le foie, sur les reins, il la retirera.'),
(2885, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 5, 'OT', 'Le sacrificateur les fera brûler sur l''autel comme sacrifice consumé par le feu à l''Éternel ; c''est un sacrifice de culpabilité.'),
(2886, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 6, 'OT', 'Tout mâle parmi les sacrificateurs le mangera ; dans un lieu saint il sera mangé ; c''est une chose très sainte.'),
(2887, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 7, 'OT', 'Comme le sacrifice pour le péché, ainsi le sacrifice de culpabilité : une même loi leur sera ; le sacrificateur qui fera l''expiation avec elle, à lui elle appartiendra.'),
(2888, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 8, 'OT', 'Le sacrificateur qui offre l''holocauste d''un homme, la peau de l''holocauste qu''il a offert sera pour le sacrificateur, à lui.'),
(2889, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 9, 'OT', 'Toute offrande cuite au four, et tout ce qui est préparé dans le poêle ou sur le poêle, appartiendra au sacrificateur qui la présente.'),
(2890, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 10, 'OT', 'Toute offrande mêlée d''huile et sèche sera pour tous les fils d''Aaron, chaque homme comme son frère.'),
(2891, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 11, 'OT', 'Et telle est la loi du sacrifice d''actions de grâces, qu''on offrira à l''Éternel.'),
(2892, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 12, 'OT', 'S''il l''offre en sacrifice d''actions de grâces, il offrira avec le sacrifice d''actions de grâces des gâteaux de pains sans levain pétris à l''huile, et des galettes de pains sans levain ointes d''huile, et de la fleur de farine pétrie en gâteaux mêlés d''huile.'),
(2893, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 13, 'OT', 'Avec des gâteaux de pain levé, il présentera son offrande, sur le sacrifice d''actions de grâces de ses sacrifices d''actions de grâces.'),
(2894, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 14, 'OT', 'Il offrira de chaque offrande une part en offrande élevée à l''Éternel ; elle appartiendra au sacrificateur qui répand le sang du sacrifice d''actions de grâces.'),
(2895, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 15, 'OT', 'La chair du sacrifice d''actions de grâces de ses sacrifices de paix sera mangée le jour de son offrande ; on n''en laissera rien jusqu''au matin.'),
(2896, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 16, 'OT', 'Et si c''est un vœu ou une offrande volontaire, son sacrifice, son offrande, le jour où il offrira son sacrifice, il sera mangé ; et le lendemain, ce qui en restera sera mangé.'),
(2897, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 17, 'OT', 'Et ce qui restera de la chair du sacrifice, au troisième jour, sera brûlé au feu.'),
(2898, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 18, 'OT', 'Et si l''on mange de la chair de son sacrifice d''actions de grâces le troisième jour, cela ne sera point agréé ; celui qui l''offre n''en recevra point de compte ; ce sera une chose impure, et l''âme qui en mangera portera son iniquité.'),
(2899, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 19, 'OT', 'La chair qui touche à tout impur ne sera pas mangée ; elle sera brûlée au feu ; et la chair, tout homme pur en mangera.'),
(2900, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 20, 'OT', 'L''âme qui mangera de la chair du sacrifice d''actions de grâces qui appartient à l''Éternel, ayant son impureté sur elle, cette âme-là sera retranchée de son peuple.'),
(2901, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 21, 'OT', 'Et toute âme qui touchera quelque chose d''impur, soit une impureté d''homme, soit un bétail impur, soit quelque abomination impure, et qui mangera de la chair du sacrifice d''actions de grâces qui appartient à l''Éternel, cette âme-là sera retranchée de son peuple.'),
(2902, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 22, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2903, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 23, 'OT', 'Parle aux fils d''Israël, en disant : Toute graisse de bœuf, d''agneau et de chèvre, vous n''en mangerez point.'),
(2904, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 24, 'OT', 'La graisse d''une carcasse et la graisse d''une bête déchirée sera employée pour tout ouvrage, mais vous n''en mangerez point.'),
(2905, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 25, 'OT', 'Car quiconque mange de la graisse du bétail dont on présente un sacrifice consumé par le feu à l''Éternel, l''âme qui mange sera retranchée de son peuple.'),
(2906, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 26, 'OT', 'Vous ne mangerez aucun sang, dans toutes vos habitations, tant des oiseaux que du bétail.'),
(2907, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 27, 'OT', 'Toute âme qui mangera tout sang, cette âme-là sera retranchée de son peuple.'),
(2908, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 28, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2909, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 29, 'OT', 'Parle aux fils d''Israël, et dis-leur : Celui qui présente le sacrifice de ses sacrifices d''actions de grâces à l''Éternel apportera son offrande à l''Éternel, prise du sacrifice de ses sacrifices d''actions de grâces.'),
(2910, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 30, 'OT', 'Ses mains apporteront les sacrifices consumés par le feu à l''Éternel : la graisse sur la poitrine, il l''apportera, la poitrine pour la présenter en offrande devant l''Éternel.'),
(2911, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 31, 'OT', 'Le sacrificateur fera fumer la graisse sur l''autel, et la poitrine sera pour Aaron et pour ses fils.'),
(2912, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 32, 'OT', 'Et l''épaule droite, vous la donnerez en offrande au sacrificateur, de vos sacrifices d''actions de grâces.'),
(2913, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 33, 'OT', 'Celui qui présente le sang du sacrifice d''actions de grâces et la graisse, d''entre les fils d''Aaron, aura l''épaule droite pour portion.'),
(2914, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 34, 'OT', 'Car j''ai pris la poitrine de l''offrande et l''épaule de l''offrande élevée des fils d''Israël, de leurs sacrifices d''actions de grâces, et je les ai donnés à Aaron le sacrificateur et à ses fils comme statut perpétuel de la part des fils d''Israël.'),
(2915, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 35, 'OT', 'C''est l''onction d''Aaron et l''onction de ses fils, des sacrifices consumés par le feu de l''Éternel, au jour où il les fit approcher pour exercer le sacerdoce devant l''Éternel.'),
(2916, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 36, 'OT', 'que l''Éternel commanda de leur donner au jour de son onction, de la part des fils d''Israël, comme loi perpétuelle pour leurs générations.'),
(2917, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 37, 'OT', 'Voici la loi pour l''holocauste, pour l''offrande, pour le péché, pour le sacrifice de culpabilité, pour les consécrations, et pour le sacrifice d''actions de grâces.'),
(2918, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 7, 38, 'OT', 'ce que l''Éternel commanda à Moïse sur la montagne de Sinaï, le jour où il commanda aux fils d''Israël de présenter leurs offrandes à l''Éternel dans le désert de Sinaï.'),
(2919, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(2920, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 2, 'OT', 'Prends Aaron et ses fils avec lui, et les vêtements, et l''huile de l''onction, et le taureau du sacrifice pour le péché, et les deux béliers, et la corbeille des pains sans levain.'),
(2921, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 3, 'OT', 'Et toute l''assemblée, il la réunit à l''entrée de la tente d''assignation.'),
(2922, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 4, 'OT', 'Moïse fit comme l''Éternel le lui avait commandé, et l''assemblée se rassembla à l''entrée de la tente d''assignation.'),
(2923, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 5, 'OT', 'Moïse dit à l''assemblée : Voici la parole que l''Éternel a commandé de faire.'),
(2924, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 6, 'OT', 'Moïse fit approcher Aaron et ses fils, et les lava avec des eaux.'),
(2925, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 7, 'OT', 'Il mit sur lui la tunique, le ceignit de la ceinture, le revêtit du manteau, plaça sur lui l''éphod, le ceignit avec la ceinture de l''éphod, et l''en attacha.'),
(2926, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 8, 'OT', 'Il posa sur lui le pectoral, et il mit dans le pectoral l''Urim et le Thummim.'),
(2927, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 9, 'OT', 'Il posa la tiare sur sa tête, et il posa sur la tiare, en face de son visage, la fleur d''or, le diadème saint, comme l''Éternel l''avait commandé à Moïse.'),
(2928, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 10, 'OT', 'Moïse prit l''huile de l''onction, oignit le tabernacle et tout ce qui s''y trouvait, et les sanctifia.'),
(2929, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 11, 'OT', 'Il fit aspersion de ce sang sur l''autel sept fois, et il oignit l''autel et tous ses ustensiles, ainsi que le bassin et sa base, pour les sanctifier.'),
(2930, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 12, 'OT', 'Il versa de l''huile de l''onction sur la tête d''Aaron, et l''oignit pour le sanctifier.'),
(2931, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 13, 'OT', 'Moïse fit approcher les fils d''Aaron, les revêtit de tuniques, les ceignit de ceintures, et leur attacha des bonnets, comme l''Éternel l''avait commandé à Moïse.'),
(2932, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 14, 'OT', 'Il fit approcher le taureau du sacrifice pour le péché, et Aaron et ses fils posèrent leurs mains sur la tête du taureau du sacrifice pour le péché.'),
(2933, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 15, 'OT', 'Il l''égorgea ; Moïse prit le sang et en mit avec son doigt sur les cornes de l''autel tout alentour, et il purifia l''autel ; puis il versa le sang au fondement de l''autel et le sanctifia pour faire l''expiation sur lui.'),
(2934, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 16, 'OT', 'Moïse prit toute la graisse qui était sur le milieu, et la graisse du foie, et les deux reins, et leur graisse, et Moïse les fit brûler sur l''autel.'),
(2935, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 17, 'OT', 'Et le taureau, avec sa peau, sa chair et ses excréments, il les brûla au feu dehors du camp, comme l''Éternel l''avait commandé à Moïse.'),
(2936, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 18, 'OT', 'Il fit approcher le bélier de l''holocauste, et Aaron et ses fils posèrent leurs mains sur la tête du bélier.'),
(2937, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 19, 'OT', 'Il l''égorgea, et Moïse répandit le sang sur l''autel, tout alentour.'),
(2938, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 20, 'OT', 'Et le bélier, il le coupa en ses morceaux ; et Moïse fit brûler la tête, les morceaux et la graisse.'),
(2939, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 21, 'OT', 'Il lava le milieu et les jambes avec les eaux, et Moïse fit fumer tout le bélier sur l''autel : c''est un holocauste, c''est une odeur agréable, c''est un sacrifice consumé par le feu pour l''Éternel, comme l''Éternel l''avait commandé à Moïse.'),
(2940, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 22, 'OT', 'Il fit approcher le second bélier, le bélier de consécration, et Aaron et ses fils posèrent leurs mains sur la tête du bélier.'),
(2941, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 23, 'OT', 'Il l''égorgea, et Moïse prit de son sang, et il en mit sur le lobe de l''oreille droite d''Aaron, sur le pouce de sa main droite, et sur le pouce de son pied droit.'),
(2942, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 24, 'OT', 'Il fit approcher les fils d''Aaron, et Moïse prit du sang et le mit sur le lobe de leur oreille droite, sur le pouce de leur main droite et sur le pouce de leur pied droit ; puis Moïse aspergea le sang sur l''autel tout autour, alentour.'),
(2943, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 25, 'OT', 'Il prit la graisse, et la queue, et toute la graisse qui est sur le milieu, et la graisse du foie, et les deux reins avec leur graisse, et l''épaule droite.'),
(2944, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 26, 'OT', 'De la corbeille des pains sans levain qui était devant la face de l''Éternel, il prit un gâteau de pains sans levain, un gâteau de pain à l''huile, et une galette, et il les posa sur les graisses et sur l''épaule droite.'),
(2945, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 27, 'OT', 'Il mit le tout sur les mains d''Aaron et sur les mains de ses fils, et il les agita en offrande devant la face de l''Éternel.'),
(2946, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 28, 'OT', 'Moïse les prit de leurs mains et les fit brûler sur l''autel, par-dessus l''holocauste ; c''étaient des offrandes de consécration, d''une odeur agréable, un sacrifice consumé par le feu à l''Éternel.'),
(2947, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 29, 'OT', 'Moïse prit la poitrine et la présenta en offrande balancée devant la face de l''Éternel, du bélier de consécration ; elle fut pour Moïse une portion, comme l''Éternel l''avait commandé à Moïse.'),
(2948, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 30, 'OT', 'Moïse prit de l''huile de l''onction et du sang qui était sur l''autel, et il en aspergea Aaron, ses vêtements, ses fils, et les vêtements de ses fils avec lui ; et il sanctifia Aaron, ses vêtements, ses fils, et les vêtements de ses fils avec lui.'),
(2949, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 31, 'OT', 'Moïse dit à Aaron et à ses fils : Faites cuire la chair à l''entrée de la tente d''assignation, et là vous la mangerez, ainsi que le pain qui est dans la corbeille de consécration, comme je l''ai commandé, en disant : Aaron et ses fils le mangeront.'),
(2950, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 32, 'OT', 'Et le reste de la chair et du pain, vous le brûlerez au feu.'),
(2951, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 33, 'OT', 'Et de l''entrée de la tente d''assignation vous ne sortirez pas sept jours, jusqu''au jour où seront accomplis les jours de votre consécration ; car sept jours il remplira vos mains.'),
(2952, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 34, 'OT', 'Comme il a été fait en ce jour, l''Éternel a commandé de faire, afin de faire propitiation pour vous.'),
(2953, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 35, 'OT', 'À l''entrée de la tente d''assignation vous demeurerez jour et nuit sept jours, et vous garderez l''observance de l''Éternel, et vous ne mourrez point, car ainsi il m''a été commandé.'),
(2954, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 8, 36, 'OT', 'Aaron et ses fils firent toutes les paroles que l''Éternel avait commandées par la main de Moïse.'),
(2955, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 1, 'OT', 'Il advint, au huitième jour, que Moïse appela Aaron et ses fils, et les anciens d''Israël.'),
(2956, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 2, 'OT', 'Il dit à Aaron : Prends pour toi un jeune veau, pour le péché, et un bélier sans défaut pour l''holocauste, et présente-les devant la face de l''Éternel.'),
(2957, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 3, 'OT', 'Et tu parleras aux fils d''Israël, en disant : Prenez un bouc de chèvres pour le péché, et un veau et un agneau d''un an, sans défaut, pour l''holocauste.'),
(2958, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 4, 'OT', 'un bœuf et un bélier pour le sacrifice d''actions de grâces, à sacrifier devant la face de l''Éternel, et une offrande pétrie à l''huile ; car aujourd''hui l''Éternel se montrera à vous.'),
(2959, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 5, 'OT', 'Ils prirent ce que Moïse avait ordonné, devant la face de la tente d''assignation ; et toute l''assemblée s''approcha, et ils se tinrent devant la face de l''Éternel.'),
(2960, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 6, 'OT', 'Moïse dit : Voici la parole que l''Éternel a commandée ; faites-la, et la gloire de l''Éternel vous apparaîtra.'),
(2961, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 7, 'OT', 'Moïse dit à Aaron : Approche-toi de l''autel, fais ton sacrifice pour le péché et ton holocauste, et fais l''expiation pour toi et pour le peuple ; puis fais l''offrande du peuple et fais l''expiation pour eux, comme l''Éternel l''a commandé.'),
(2962, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 8, 'OT', 'Aaron s''approcha de l''autel et égorgea le veau du péché qui lui appartenait.'),
(2963, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 9, 'OT', 'Les fils d''Aaron lui apportèrent le sang, et il trempa son doigt dans le sang, et il en mit sur les cornes de l''autel, et il répandit le sang au fondement de l''autel.'),
(2964, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 10, 'OT', 'Et la graisse, et les reins, et la graisse du foie, de l''offrande pour le péché, il les fit brûler sur l''autel, comme l''Éternel l''avait commandé à Moïse.'),
(2965, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 11, 'OT', 'Et la chair et la peau, il les brûla au feu, dehors du camp.'),
(2966, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 12, 'OT', 'Il égorgea l''holocauste, et les fils d''Aaron lui présentèrent le sang, et il le répandit sur l''autel, tout alentour.'),
(2967, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 13, 'OT', 'Ils lui présentèrent l''holocauste en ses morceaux, ainsi que la tête, et il fit fumer sur l''autel.'),
(2968, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 14, 'OT', 'Il lava le milieu et les jambes, et il fit fumer l''holocauste sur l''autel.'),
(2969, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 15, 'OT', 'Il offrit l''offrande du peuple, prit le bouc du sacrifice pour le péché qui était pour le peuple, le tua et fit l''expiation avec lui comme la première fois.'),
(2970, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 16, 'OT', 'Il offrit l''holocauste et le fit selon le jugement.'),
(2971, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 17, 'OT', 'Il offrit l''offrande, remplit sa main de ce qu''elle contenait, et la fit fumer sur l''autel, en plus de l''holocauste du matin seul.'),
(2972, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 18, 'OT', 'Il égorgea le bœuf et le bélier, le sacrifice d''actions de grâces qui était pour le peuple ; et les fils d''Aaron lui apportèrent le sang, et il le répandit sur l''autel, tout alentour.'),
(2973, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 19, 'OT', 'et les graisses du bœuf et du bélier : la queue, le vêtement, les reins, et la graisse du foie.'),
(2974, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 20, 'OT', 'Ils placèrent les graisses sur les poitrines, et il fit brûler les graisses sur l''autel.'),
(2975, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 21, 'OT', 'Aaron agita la poitrine et l''épaule droite en offrande devant l''Éternel, comme Moïse l''avait commandé.'),
(2976, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 22, 'OT', 'Aaron leva sa main vers le peuple et les bénit ; puis il descendit après avoir offert le sacrifice pour le péché, l''holocauste et le sacrifice d''actions de grâces.'),
(2977, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 23, 'OT', 'Moïse et Aaron entrèrent dans la tente d''assignation, puis ils sortirent et bénirent le peuple, et la gloire de l''Éternel apparut à tout le peuple.'),
(2978, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 9, 24, 'OT', 'Un feu sortit de devant l''Éternel, et il consuma sur l''autel l''holocauste et les graisses ; et tout le peuple vit, et ils poussèrent des cris de joie, et ils tombèrent sur leur face.'),
(2979, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 1, 'OT', 'Les fils d''Aaron, Nadab et Abihu, prirent chacun leur brasier, y mirent du feu, et placèrent de l''encens dessus ; ils offrirent devant l''Éternel un feu étranger, qu''il ne leur avait point commandé.'),
(2980, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 2, 'OT', 'Un feu sortit de devant la face de l''Éternel, et il les dévora, et ils moururent devant la face de l''Éternel.'),
(2981, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 3, 'OT', 'Moïse dit à Aaron : « C''est là ce que l''Éternel a déclaré, en disant : Je serai sanctifié dans ceux qui s''approchent de moi, et devant la face de tout le peuple je serai glorifié. » Et Aaron se tut.'),
(2982, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 4, 'OT', 'Moïse appela Mischaël et Élitsaphan, fils d''Uziel, bien-aimé d''Aaron, et leur dit : Approchez-vous, portez vos frères de devant la face du saint lieu, dehors du camp.'),
(2983, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 5, 'OT', 'Ils s''approchèrent et les portèrent dans leurs tuniques dehors du camp, comme Moïse l''avait dit.'),
(2984, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 6, 'OT', 'Moïse dit à Aaron et à Éléazar et à Ithamar, ses fils : Ne découvrez pas vos têtes et ne déchirez pas vos vêtements, afin que vous ne mouriez pas et que la colère ne vienne pas sur toute l''assemblée ; mais vos frères, toute la maison d''Israël, pleureront la brûlure que l''Éternel a allumée.'),
(2985, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 7, 'OT', 'Ne sortez pas de l''entrée de la tente d''assignation, de peur que vous ne mouriez, car l''huile de l''onction de l''Éternel est sur vous. Et ils firent selon la parole de Moïse.'),
(2986, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 8, 'OT', 'L''Éternel parla à Aaron, en disant :'),
(2987, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 9, 'OT', 'Ne bois ni vin ni boisson forte, toi et tes fils avec toi, quand vous entrerez dans la tente d''assignation, afin que vous ne mouriez point ; c''est une loi perpétuelle pour vos générations.'),
(2988, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 10, 'OT', 'afin de distinguer entre le saint et le profane, et entre l''impur et le pur.'),
(2989, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 11, 'OT', 'Et pour enseigner aux fils d''Israël tous les statuts que l''Éternel leur a dits par la main de Moïse.'),
(2990, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 12, 'OT', 'Moïse parla à Aaron, et à Éléazar et à Ithamar, ses fils qui restaient : Prenez l''offrande qui reste des sacrifices consumés par le feu de l''Éternel, et mangez-la en pains sans levain près de l''autel, car elle est très sainte.'),
(2991, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 13, 'OT', 'Vous la mangerez dans un lieu saint, car c''est votre statut et le statut de vos fils, provenant des sacrifices consumés par le feu de l''Éternel, car ainsi il m''a été commandé.'),
(2992, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 14, 'OT', 'Et la poitrine de l''offrande balancée et l''épaule de l''offrande élevée, vous les mangerez dans un lieu pur, toi et tes fils et tes filles avec toi ; car c''est ton statut et le statut de tes fils, qui vous sont donnés des sacrifices d''actions de grâces des fils d''Israël.'),
(2993, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 15, 'OT', 'Ils apporteront l''épaule de l''offrande et la poitrine de l''offrande, sur les sacrifices consumés par le feu des graisses, pour les offrir en offrande devant la face de l''Éternel ; et cela sera pour toi et pour tes fils avec toi comme un statut pour toujours, comme l''Éternel l''a commandé.'),
(2994, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 16, 'OT', 'Moïse chercha avec soin le bouc du sacrifice pour le péché, et voici qu''il avait été brûlé ; alors il s''irrita contre Éléazar et contre Ithamar, les fils d''Aaron qui restaient, en disant :'),
(2995, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 17, 'OT', 'Pourquoi n''avez-vous pas mangé le péché dans le lieu saint, car c''est une chose très sainte, et il vous l''a donnée pour porter l''iniquité de l''assemblée, afin de faire l''expiation pour eux devant la face de l''Éternel.'),
(2996, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 18, 'OT', 'Voici que son sang n''a pas été apporté dans le lieu saint, à l''intérieur ; vous la mangerez certainement dans le lieu saint, comme je l''ai commandé.'),
(2997, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 19, 'OT', 'Aaron parla à Moïse : Voici, aujourd''hui ils ont présenté leur péché et leur holocauste devant la face de l''Éternel, et ces choses m''ont atteint ; si j''avais mangé le péché aujourd''hui, cela aurait-il été agréable aux yeux de l''Éternel ?'),
(2998, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 10, 20, 'OT', 'Moïse entendit, et cela fut bon à ses yeux.'),
(2999, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 1, 'OT', 'L''Éternel parla à Moïse et à Aaron, en leur disant :'),
(3000, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 2, 'OT', 'Parlez aux fils d''Israël, en disant : Voici la vie que vous mangerez, de tout le bétail qui est sur la terre.'),
(3001, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 3, 'OT', 'Tout animal qui a la corne du pied fendue et qui fend la fente des cornes du pied, qui rumine parmi le bétail, vous le mangerez.'),
(3002, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 4, 'OT', 'Mais vous ne mangerez pas de ceux qui ruminent seulement, ou qui ont seulement la corne du pied fendue : le chameau, parce qu''il rumine, mais n''a pas la corne du pied fendue ; il est impur pour vous.'),
(3003, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 5, 'OT', 'Et le daman, parce qu''il rumine, mais ne fend pas la corne du pied : il est impur pour vous.'),
(3004, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 6, 'OT', 'Et le lièvre, parce qu''il rumine, mais ne fend pas la corne du pied, il est impur pour vous.'),
(3005, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 7, 'OT', 'Et le pourceau, parce qu''il fend la corne du pied et qu''il a une fente dans la corne du pied, mais qu''il ne rumine pas, il est impur pour vous.'),
(3006, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 8, 'OT', 'Vous ne mangerez point de leur chair, et vous ne toucherez point leur carcasse ; ils sont impurs pour vous.'),
(3007, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 9, 'OT', 'Vous mangerez de tout ce qui est dans les eaux : tout ce qui a des nageoires et des écailles, dans les eaux, dans les mers et dans les torrents, vous en mangerez.'),
(3008, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 10, 'OT', 'Et tout ce qui n''a pas de nageoires ni d''écaille, dans les mers et dans les torrents, de tout reptile des eaux et de toute âme vivante qui est dans les eaux, ils sont une abomination pour vous.'),
(3009, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 11, 'OT', 'Ils seront pour vous une abomination ; vous ne mangerez pas de leur chair, et vous aurez en abomination leur carcasse.'),
(3010, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 12, 'OT', 'Tout ce qui n''a pas de nageoires et d''écaille dans les eaux est une abomination pour vous.'),
(3011, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 13, 'OT', 'Et ceux-ci, vous les tiendrez pour abominables parmi les oiseaux ; on ne les mangera point, ils sont une abomination : l''aigle, l''orfraie et l''orfraie.'),
(3012, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 14, 'OT', 'et le milan, et le milane selon son espèce.'),
(3013, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 15, 'OT', 'tout corbeau selon son espèce'),
(3014, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 16, 'OT', 'et la fille de l''autruche, et le hibou, et la mouette, et l''épervier selon son espèce.'),
(3015, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 17, 'OT', 'et la coupe, et le cormoran, et la chouette.'),
(3016, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 18, 'OT', 'le cygne, le cormoran, et le cormoran'),
(3017, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 19, 'OT', 'et la cigogne, le héron selon son espèce, et la huppe, et la chauve-souris.'),
(3018, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 20, 'OT', 'Tout reptile volant qui marche sur quatre pattes est une abomination pour vous.'),
(3019, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 21, 'OT', 'Seulement ceci vous pourrez manger de tout reptile volant qui marche sur quatre pieds, qui a des jambes au-dessus de ses pieds pour sauter avec elles sur la terre.'),
(3020, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 22, 'OT', 'Vous mangerez ceux-ci d''entre eux : la sauterelle selon son espèce, et la sauterelle selon son espèce, et le hargol selon son espèce, et la sauterelle selon son espèce.'),
(3021, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 23, 'OT', 'Et tout reptile de l''oiseau qui a quatre pieds est une abomination pour vous.'),
(3022, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 24, 'OT', 'Et par ceux-là vous serez rendus impurs : tout homme qui touche leur carcasse sera impur jusqu''au soir.'),
(3023, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 25, 'OT', 'Et tout homme qui portera de leur carcasse lavera ses vêtements, et il sera impur jusqu''au soir.'),
(3024, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 26, 'OT', 'Tout bétail qui a la corne du pied fendue, mais qui ne divise pas la fente, et qui ne rumine pas, est impur pour vous ; quiconque les touche sera impur.'),
(3025, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 27, 'OT', 'Et tout ce qui marche sur ses mains, parmi toute vie qui marche sur quatre, ils sont impurs pour vous : tout celui qui touche leur carcasse sera impur jusqu''au soir.'),
(3026, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 28, 'OT', 'Celui qui portera leur carcasse lavera ses vêtements et sera impur jusqu''au soir ; ils sont impurs pour vous.'),
(3027, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 29, 'OT', 'Voici ce qui est impur pour vous parmi les reptiles qui rampent sur la terre : la taupe, la souris et la litière selon son espèce.'),
(3028, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 30, 'OT', 'le lézard, la force, le caméléon, le limaçon et le cygne.'),
(3029, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 31, 'OT', 'Voici ceux qui sont impurs pour vous parmi tout reptile : quiconque les touchera à leur mort sera impur jusqu''au soir.'),
(3030, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 32, 'OT', 'Tout ce qui tombera sur eux, quand ils seront morts, sera impur : tout ustensile de bois, ou vêtement, ou peau, ou sac, tout ustensile qui sert à un ouvrage, sera plongé dans les eaux, et il sera impur jusqu''au soir, puis il sera pur.'),
(3031, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 33, 'OT', 'Et tout ustensile de vase de terre dans le milieu duquel il en tombera, tout ce qui est dans son milieu sera impur, et vous le briserez.'),
(3032, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 34, 'OT', 'De toute nourriture qui se mange, sur laquelle des eaux viennent, elle sera impure ; et tout échanson qui se boit dans tout ustensile sera impur.'),
(3033, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 35, 'OT', 'Et tout ce sur quoi tombera quelque chose de leur carcasse sera impur ; le four et le foyer seront démolis ; ils sont impurs, et ils seront impurs pour vous.'),
(3034, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 36, 'OT', 'Toutefois, une source et une citerne, espérance d''eaux, sera pure ; mais celui qui touche leur carcasse sera impur.'),
(3035, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 37, 'OT', 'Et si quelque chose de leur carcasse tombe sur toute postérité de semence qui doit être semée, elle est pure.'),
(3036, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 38, 'OT', 'Et si l''on verse des eaux sur de la postérité, et qu''il tombe de leur carcasse sur elle, elle est impure pour vous.'),
(3037, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 39, 'OT', 'Et si meurt du bétail qui est pour vous en nourriture, celui qui touche sa carcasse sera impur jusqu''au soir.'),
(3038, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 40, 'OT', 'Celui qui mange de sa carcasse lavera ses vêtements et sera impur jusqu''au soir, et celui qui porte sa carcasse lavera ses vêtements et sera impur jusqu''au soir.'),
(3039, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 41, 'OT', 'Et tout reptile qui rampe sur la terre est une abomination ; il ne sera point mangé.'),
(3040, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 42, 'OT', 'Tout ce qui marche sur le ventre, et tout ce qui marche sur quatre pieds, jusqu''à tout ce qui a beaucoup de pieds, parmi tous les reptiles qui rampent sur la terre, vous ne les mangerez point, car ils sont une abomination.'),
(3041, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 43, 'OT', 'Ne rendez point vos âmes abominables par tout reptile qui rampe, et ne vous souillez point par eux, et vous seriez souillés par eux.'),
(3042, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 44, 'OT', 'Car je suis l''Éternel, votre Dieu ; vous vous sanctifierez et vous serez saints, car je suis saint ; et vous ne souillerez point vos âmes par tout reptile qui rampe sur la terre.'),
(3043, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 45, 'OT', 'Car je suis l''Éternel, qui vous ai fait monter de la terre d''Égypte pour être votre Dieu ; et vous serez saints, car je suis saint.'),
(3044, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 46, 'OT', 'C''est la loi du bétail et de l''oiseau, et de toute âme vivante qui se meut dans les eaux, et de toute âme qui rampe sur la terre.'),
(3045, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 11, 47, 'OT', 'pour distinguer entre l''impur et le pur, et entre la vie qui se mange et la vie qui ne se mange pas.'),
(3046, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3047, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 2, 'OT', 'Parle aux fils d''Israël, en disant : Lorsqu''une femme conçoit et enfante un mâle, elle sera impure sept jours ; comme les jours de l''impureté de sa menstruation, elle sera impure.'),
(3048, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 3, 'OT', 'Et au huitième jour, la chair de son prépuce sera circoncise.'),
(3049, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 4, 'OT', 'Elle restera trente-trois jours dans le sang de sa purification ; elle ne touchera aucune chose sainte, et elle n''entrera pas dans le sanctuaire, jusqu''à ce que soient accomplis les jours de sa purification.'),
(3050, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 5, 'OT', 'Et si elle enfante une femelle, elle sera impure deux semaines, comme lors de son impureté ; et elle restera soixante-six jours dans le sang de sa purification.'),
(3051, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 6, 'OT', 'Lorsque les jours de sa purification seront accomplis, pour un fils ou pour une fille, elle apportera un agneau d''un an pour holocauste, et un jeune pigeon ou une tourterelle pour le péché, à l''entrée de la tente d''assignation, vers le sacrificateur.'),
(3052, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 7, 'OT', 'Il l''offrira devant l''Éternel, et il fera l''expiation pour elle, et elle sera pure de la source de son sang. Telle est la loi de celle qui enfante, pour un mâle ou pour une femelle.'),
(3053, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 12, 8, 'OT', 'Et si sa main ne trouve pas de quoi suffire pour un agneau, elle prendra deux tourterelles ou deux jeunes pigeons, l''un pour holocauste et l''autre pour le péché ; le sacrificateur fera l''expiation pour elle, et elle sera pure.'),
(3054, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 1, 'OT', 'L''Éternel parla à Moïse et à Aaron, en disant :'),
(3055, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 2, 'OT', 'Lorsqu''un homme aura sur la peau de sa chair une tumeur, ou une tache, ou une tache blanche, et que cela devienne sur la peau de sa chair une plaie de lèpre, il sera amené à Aaron le sacrificateur, ou à l''un de ses fils les sacrificateurs.'),
(3056, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 3, 'OT', 'Le sacrificateur examinera la plaie dans la peau de la chair ; et si les cheveux dans la plaie sont devenus blancs, et que l''apparence de la plaie est plus profonde que la peau de sa chair, c''est une plaie de lèpre ; le sacrificateur l''examinera et le déclarera impur.'),
(3057, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 4, 'OT', 'Et si la tache blanche est sur la peau de sa chair, et que son apparence n''est pas plus profonde que la peau, et que les cheveux ne sont pas devenus blancs, le sacrificateur enfermera la plaie pendant sept jours.'),
(3058, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 5, 'OT', 'Le sacrificateur l''examinera au septième jour, et voici que la plaie est restée à ses yeux, la plaie ne s''est pas étendue sur la peau ; alors le sacrificateur l''enfermera sept jours une seconde fois.'),
(3059, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 6, 'OT', 'Le sacrificateur l''examinera de nouveau le septième jour, et voici, la plaie est devenue terne, et la plaie ne s''est pas étendue sur la peau ; alors le sacrificateur le déclarera pur : c''est une dartre ; il lavera ses vêtements, et il sera pur.'),
(3060, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 7, 'OT', 'Et si la dartre s''étend sur la peau, après qu''il s''est montré au sacrificateur pour sa purification, il sera vu de nouveau par le sacrificateur.'),
(3061, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 8, 'OT', 'Le sacrificateur l''examinera, et voici que la dartre s''est étendue sur la peau ; alors le sacrificateur le déclarera impur : c''est une lèpre.'),
(3062, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 9, 'OT', 'Quand une plaie de lèpre sera dans un homme, il sera amené au sacrificateur.'),
(3063, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 10, 'OT', 'Le sacrificateur regardera, et voici une tumeur blanche sur la peau, et elle a fait tourner les cheveux en blanc, et une subsistance de chair vive est dans la tumeur.'),
(3064, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 11, 'OT', 'C''est une lèpre chronique dans la peau de sa chair ; le sacrificateur le déclarera impur ; il ne l''enfermera pas, car il est impur.'),
(3065, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 12, 'OT', 'Et si la lèpre fait éruption sur la peau, et que la lèpre couvre toute la peau de la plaie, depuis sa tête jusqu''à ses pieds, selon toute l''apparence qu''en voient les yeux du sacrificateur,'),
(3066, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 13, 'OT', 'Le sacrificateur la verra, et voici que la lèpre a couvert toute sa chair ; il déclarera la plaie pure : tout est devenu blanc, il est pur.'),
(3067, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 14, 'OT', 'Et le jour où paraîtra en lui de la chair vive, il sera impur.'),
(3068, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 15, 'OT', 'Le sacrificateur verra la chair vive et la déclarera impure ; la chair vive est impure, c''est une lèpre.'),
(3069, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 16, 'OT', 'Ou si la chair vive revient et se change en blanc, il viendra vers le sacrificateur.'),
(3070, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 17, 'OT', 'Le sacrificateur le verra, et voici que la plaie s''est changée en blanc ; et le sacrificateur déclarera la plaie pure : elle est pure.'),
(3071, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 18, 'OT', 'Et si une chair a dans sa peau un ulcère, et qu''il est guéri,'),
(3072, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 19, 'OT', 'Et il arrivera qu''à la place de l''ulcère il y aura une tumeur blanche, ou une tache blanche rougeâtre, et elle sera montrée au sacrificateur.'),
(3073, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 20, 'OT', 'Le sacrificateur la verra, et voici que son apparence est plus basse que la peau, et ses cheveux sont devenus blancs ; le sacrificateur le déclarera impur : c''est une plaie de lèpre qui a éclaté dans l''ulcère.'),
(3074, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 21, 'OT', 'Et si le sacrificateur la voit, et voici qu''il n''y a en elle point de cheveux blancs, et qu''elle n''est pas plus basse que la peau, et qu''elle est terne, le sacrificateur l''enfermera sept jours.'),
(3075, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 22, 'OT', 'Et si la plaie s''étend sur la peau, le sacrificateur le déclarera impur : c''est une plaie.'),
(3076, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 23, 'OT', 'Mais si la tache blanche demeure en sa place et ne s''est pas étendue, c''est la cicatrice de l''ulcère ; et le sacrificateur le déclarera pur.'),
(3077, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 24, 'OT', 'Ou si la chair a sur sa peau une brûlure de feu, et que la subsistance de la brûlure devienne une tache blanche rougeâtre ou blanche,'),
(3078, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 25, 'OT', 'Le sacrificateur la verra, et voici que les cheveux sont devenus blancs dans la tache blanche, et son apparence est plus profonde que la peau : c''est la lèpre qui a poussé dans la brûlure ; et le sacrificateur le déclarera impur, c''est une plaie de lèpre.'),
(3079, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 26, 'OT', 'Et si le sacrificateur la voit, et voici qu''il n''y a point de cheveux blancs dans la tache blanche, et qu''elle ne soit pas plus basse que la peau, et qu''elle soit terne, le sacrificateur l''enfermera sept jours.'),
(3080, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 27, 'OT', 'Le sacrificateur l''examinera le septième jour ; si la plaie s''est étendue sur la peau, le sacrificateur le déclarera impur : c''est une plaie de lèpre.'),
(3081, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 28, 'OT', 'Et si la tache blanche demeure en place, ne s''est pas étendue dans la peau, et qu''elle est devenue terne, c''est une tumeur de la brûlure ; le sacrificateur le déclarera pur, car c''est une cicatrice de la brûlure.'),
(3082, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 29, 'OT', 'Et un homme ou une femme, lorsqu''il y aura en lui une plaie à la tête ou à la barbe.'),
(3083, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 30, 'OT', 'Le sacrificateur verra la plaie, et voici que son apparence est plus profonde que la peau, et qu''il y a en elle des cheveux jaunes et fins ; alors le sacrificateur le déclarera impur : c''est une teigne, c''est une lèpre de la tête ou de la barbe.'),
(3084, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 31, 'OT', 'Si le sacrificateur voit la plaie de la teigne, et voici que son apparence n''est pas plus profonde que la peau, et qu''il n''y a pas de cheveux noirs en elle, le sacrificateur enfermera la plaie de la teigne pendant sept jours.'),
(3085, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 32, 'OT', 'Le sacrificateur examinera la plaie au septième jour, et voici que la teigne ne s''est pas étendue, et qu''il n''y a pas en elle de cheveux jaunes, et l''apparence de la teigne n''est pas plus profonde que la peau.'),
(3086, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 33, 'OT', 'Il se rasera, mais il ne rasera pas la teigne ; et le sacrificateur enfermera la teigne sept jours une seconde fois.'),
(3087, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 34, 'OT', 'Le sacrificateur examinera la teigne au septième jour, et voici que la teigne ne s''est pas étendue sur la peau, et son apparence n''est pas plus profonde que la peau ; alors le sacrificateur le déclarera pur, et il lavera ses vêtements, et il sera pur.'),
(3088, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 35, 'OT', 'Et si la teigne s''étend sur la peau après sa purification,'),
(3089, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 36, 'OT', 'Le sacrificateur le verra, et voici que la teigne s''est étendue dans la peau ; le sacrificateur ne recherchera pas les cheveux jaunes ; il est impur.'),
(3090, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 37, 'OT', 'Et si, à ses yeux, la teigne est demeurée, et que des cheveux noirs y ont poussé, la teigne est guérie ; il est pur, et le sacrificateur le déclarera pur.'),
(3091, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 38, 'OT', 'Et un homme ou une femme, quand il y aura sur la peau de leur chair des taches blanches, des taches blanches,'),
(3092, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 39, 'OT', 'Le sacrificateur la verra, et voici, sur la peau de leur chair il y a des taches blanches ternes ; c''est une tache blanchâtre qui a poussé sur la peau ; il est pur.'),
(3093, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 40, 'OT', 'Et un homme, quand sa tête se dépouille, il est chauve ; il est pur.'),
(3094, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 41, 'OT', 'Et si c''est du côté de sa face que sa tête se dégarnit, il est chauve par-devant, il est pur.'),
(3095, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 42, 'OT', 'Et s''il y a sur la partie chauve ou sur la partie chauve de devant une plaie blanche rougeâtre, c''est une lèpre qui pousse sur sa partie chauve ou sur sa partie chauve de devant.'),
(3096, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 43, 'OT', 'Le sacrificateur l''examinera, et voici, la tumeur de la plaie est blanche et rougeâtre sur sa partie chauve ou sur sa partie chauve de devant, comme l''apparence de la lèpre sur la peau de la chair.'),
(3097, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 44, 'OT', 'C''est un homme lépreux, il est impur ; le sacrificateur le déclarera impur ; sa plaie est sur sa tête.'),
(3098, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 45, 'OT', 'Et le lépreux chez qui se trouve la plaie, ses vêtements seront déchirés, sa tête sera découverte, il se couvrira la barbe, et il criera : Impur ! Impur !'),
(3099, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 46, 'OT', 'Tout les jours où la plaie sera en lui, il sera impur ; il est impur ; il habitera isolé ; sa habitation sera dehors du camp.'),
(3100, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 47, 'OT', 'Et le vêtement, quand il y aura en lui une plaie de lèpre, dans un vêtement de laine ou dans un vêtement de lin.'),
(3101, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 48, 'OT', 'soit dans la chaîne, soit dans la trame, pour le lin ou pour la laine, soit dans une peau, soit dans tout ouvrage de peau.'),
(3102, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 49, 'OT', 'Et si la plaie est verdâtre ou rougeâtre dans le vêtement, ou dans la peau, ou dans la chaîne, ou dans la trame, ou dans tout ustensile de peau, c''est une plaie de lèpre ; et on la montrera au sacrificateur.'),
(3103, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 50, 'OT', 'Le sacrificateur examinera la plaie, et il enfermera la plaie pendant sept jours.'),
(3104, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 51, 'OT', 'Et il examinera la plaie au septième jour : si la plaie s''est étendue dans le vêtement, ou dans la chaîne, ou dans la trame, ou dans la peau, pour tout ouvrage que l''on fait de peau pour le travail, c''est une lèpre maligne ; la plaie est impure.'),
(3105, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 52, 'OT', 'Il brûlera le vêtement, ou la chaîne, ou la trame, en laine ou en lin, ou tout ustensile de peau dans lequel se trouve la plaie, car c''est une lèpre rongeante ; au feu, il sera brûlé.'),
(3106, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 53, 'OT', 'Et si le sacrificateur voit que voici, la plaie ne s''est pas étendue dans le vêtement, ou dans la chaîne, ou dans la trame, ou dans tout ustensile de peau,'),
(3107, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 54, 'OT', 'Le sacrificateur ordonnera qu''on lave ce qui est atteint de la plaie, et il le confinera sept jours une seconde fois.'),
(3108, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 55, 'OT', 'Le sacrificateur examinera, après que la plaie aura été lavée, et voici que la plaie n''a pas changé son œil, et la plaie ne s''est pas étendue ; elle est impure ; tu la brûleras au feu ; c''est une partie rongée, qu''elle soit dans sa partie chauve ou dans sa partie chauve de devant.'),
(3109, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 56, 'OT', 'Et si le sacrificateur voit que la plaie est devenue pâle après qu''elle a été lavée, il la déchirera du vêtement, ou de la peau, ou de la chaîne, ou de la trame.'),
(3110, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 57, 'OT', 'Et si la plaie réapparaît dans le vêtement, ou dans la chaîne, ou dans la trame, ou dans tout ustensile de peau, c''est une plaie qui s''étend ; tu le brûleras au feu, ce qui porte la plaie.'),
(3111, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 58, 'OT', 'Et le vêtement, ou la chaîne, ou la trame, ou tout ustensile de peau que tu laveras, et la plaie se sera retirée d''eux, sera lavé une seconde fois, et il sera pur.'),
(3112, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 13, 59, 'OT', 'Telle est la loi de la plaie de la lèpre sur le vêtement de laine ou de lin, sur la chaîne ou sur la trame, ou sur tout ustensile de peau, pour le déclarer pur ou pour le déclarer impur.'),
(3113, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3114, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 2, 'OT', 'Celle-ci sera la loi du lépreux au jour de sa purification : il sera amené au sacrificateur.'),
(3115, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 3, 'OT', 'Le sacrificateur sortira dehors du camp, et le sacrificateur regardera, et voici, la plaie de la lèpre est guérie de celui qui est atteint de la lèpre.'),
(3116, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 4, 'OT', 'Le sacrificateur donnera l''ordre, et l''on prendra pour celui qui se purifie deux oiseaux vivants et purs, du bois de cèdre, du cramoisi écarlate, et de l''hysope.'),
(3117, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 5, 'OT', 'Le sacrificateur donnera l''ordre, et on égorgera l''oiseau, l''un, dans un ustensile de vase de terre sur des eaux vives.'),
(3118, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 6, 'OT', 'Il prendra l''oiseau vivant, le bois de cèdre, le cramoisi écarlate, et l''hysope, et il les trempera, ainsi que l''oiseau vivant, dans le sang de l''oiseau égorgé sur les eaux vives.'),
(3119, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 7, 'OT', 'Il aspergera sept fois celui qui se purifie de la lèpre, et il le déclarera pur, puis il lâchera l''oiseau vivant sur la face du champ.'),
(3120, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 8, 'OT', 'Celui qui se purifie lavera ses vêtements, rasera tous ses cheveux, se lavera dans les eaux, et sera pur ; ensuite, il entrera dans le camp, et il demeurera dehors, hors de sa tente, sept jours.'),
(3121, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 9, 'OT', 'Le septième jour, il rasera tous ses cheveux, sa tête, sa barbe, les bords de ses yeux, et tout son poil il rasera ; il lavera ses vêtements, il baignera sa chair dans les eaux, et il sera pur.'),
(3122, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 10, 'OT', 'Au huitième jour, il prendra deux agneaux sans défaut, une agnelle d''un an, fille de son année, sans défaut, et trois dixièmes d''épha de fleur de farine en offrande, pétrie à l''huile, et un log d''huile.'),
(3123, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 11, 'OT', 'Le sacrificateur qui purifie présentera l''homme qui se purifie, et ces choses, devant l''Éternel, à l''entrée de la tente d''assignation.'),
(3124, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 12, 'OT', 'Le sacrificateur prendra l''agneau, et l''offrira en sacrifice de culpabilité, avec le log d''huile, et il les agitera en offrande devant la face de l''Éternel.'),
(3125, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 13, 'OT', 'Il égorgera l''agneau dans le lieu où l''on égorge le sacrifice pour le péché et l''holocauste, dans le lieu saint, car, comme le sacrifice pour le péché, le sacrifice de culpabilité appartient au sacrificateur ; c''est une chose très sainte.'),
(3126, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 14, 'OT', 'Le sacrificateur prendra du sang du sacrifice de culpabilité, et le sacrificateur en mettra sur le lobe de l''oreille droite de celui qui se purifie, sur le pouce de sa main droite, et sur le pouce de son pied droit.'),
(3127, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 15, 'OT', 'Le sacrificateur prendra du log d''huile, et versera sur la main gauche du sacrificateur.'),
(3128, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 16, 'OT', 'Le sacrificateur trempera son doigt droit dans l''huile qui est sur sa main gauche, et il fera aspersion de l''huile avec son doigt sept fois devant l''Éternel.'),
(3129, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 17, 'OT', 'Et du reste de l''huile qui est sur sa main, le sacrificateur en mettra sur le lobe de l''oreille droite de celui qui se purifie, et sur le pouce de sa main droite, et sur le pouce de son pied droit, sur le sang du sacrifice de culpabilité.'),
(3130, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 18, 'OT', 'Le reste de l''huile qui est sur la main du sacrificateur, il le mettra sur la tête de celui qui se purifie, et le sacrificateur fera l''expiation pour lui devant l''Éternel.'),
(3131, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 19, 'OT', 'Le sacrificateur offrira le sacrifice pour le péché, et il fera l''expiation pour celui qui se purifie de son impureté ; ensuite, il égorgera l''holocauste.'),
(3132, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 20, 'OT', 'Le sacrificateur fera monter l''holocauste et l''offrande sur l''autel, et le sacrificateur fera l''expiation pour lui, et il sera pur.'),
(3133, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 21, 'OT', 'Et s''il est pauvre, et que sa main n''atteint pas, il prendra un agneau, un sacrifice de culpabilité, pour offrande, afin de faire propitiation pour lui, et un dixième d''épha de fleur de farine mêlée d''huile, pour offrande, et un log d''huile.'),
(3134, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 22, 'OT', 'et deux tourterelles ou deux jeunes pigeons, que sa main peut atteindre ; et l''un sera pour le péché, et l''autre pour l''holocauste.'),
(3135, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 23, 'OT', 'Il les amènera le huitième jour pour sa purification au sacrificateur, à l''entrée de la tente d''assignation, devant la face de l''Éternel.'),
(3136, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 24, 'OT', 'Le sacrificateur prendra l''agneau du sacrifice de culpabilité et le log d''huile, et le sacrificateur les élèvera en offrande devant la face de l''Éternel.'),
(3137, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 25, 'OT', 'Il égorgera l''agneau du sacrifice de culpabilité, et le sacrificateur prendra du sang du sacrifice de culpabilité, et il le mettra sur le lobe de l''oreille droite de celui qui se purifie, et sur le pouce de sa main droite, et sur le pouce de son pied droit.'),
(3138, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 26, 'OT', 'Et de l''huile, le sacrificateur versera sur la main gauche du sacrificateur.'),
(3139, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 27, 'OT', 'Le sacrificateur fera aspersion avec son doigt droit de l''huile qui est sur sa main gauche, sept fois devant la face de l''Éternel.'),
(3140, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 28, 'OT', 'Le sacrificateur mettra de l''huile qui est sur sa main sur le lobe de l''oreille droite de celui qui se purifie, sur le pouce de sa main droite, sur le pouce de son pied droit, au lieu du sang du sacrifice de culpabilité.'),
(3141, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 29, 'OT', 'Le reste de l''huile qui est sur la main du sacrificateur, il le mettra sur la tête de celui qui se purifie, pour faire l''expiation pour lui devant l''Éternel.'),
(3142, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 30, 'OT', 'Il offrira l''un des tourterelles ou l''un des fils de la colombe, selon ce que sa main peut atteindre.'),
(3143, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 31, 'OT', 'Ce que sa main pourra atteindre, l''un en sacrifice pour le péché et l''autre en holocauste, avec l''offrande ; et le sacrificateur fera l''expiation pour celui qui se purifie, devant la face de l''Éternel.'),
(3144, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 32, 'OT', 'C''est la loi de celui qui a en lui la plaie de la lèpre, dont la main n''atteint pas à sa purification.'),
(3145, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 33, 'OT', 'L''Éternel parla à Moïse et à Aaron, en disant :'),
(3146, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 34, 'OT', 'Quand vous entrerez dans la terre de Canaan, que je vous donne en possession, et que je mettrai une plaie de lèpre dans une maison de la terre de votre possession,'),
(3147, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 35, 'OT', 'Celui à qui appartient la maison viendra et dira au sacrificateur : « Une plaie m''est apparue dans la maison. »'),
(3148, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 36, 'OT', 'Le sacrificateur ordonnera que l''on vide la maison avant que le sacrificateur entre pour examiner la plaie, afin que tout ce qui est dans la maison ne devienne pas impur ; ensuite, le sacrificateur entrera pour examiner la maison.'),
(3149, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 37, 'OT', 'Il examinera la plaie, et voici que la plaie se trouve dans les murs de la maison : des creux verdâtres ou rougeâtres, et leur apparence est plus enfoncée que le mur.'),
(3150, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 38, 'OT', 'Le sacrificateur sortira de la maison, vers l''entrée de la maison, et il fermera la maison pendant sept jours.'),
(3151, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 39, 'OT', 'Le sacrificateur reviendra le septième jour, et il verra que la plaie s''est étendue sur les murs de la maison.'),
(3152, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 40, 'OT', 'Le sacrificateur commandera, et ils retireront les pierres dans lesquelles est la plaie, et ils les jetteront dehors de la ville, vers un lieu impur.'),
(3153, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 41, 'OT', 'Et il fera racler la maison à l''intérieur, tout alentour, et ils verseront la poussière qu''ils auront raclée dehors, hors de la ville, dans un lieu impur.'),
(3154, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 42, 'OT', 'Ils prendront d''autres pierres et les apporteront à la place des pierres, et il prendra une autre poussière et enduira la maison.'),
(3155, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 43, 'OT', 'Et si la plaie revient et fait éruption dans la maison, après qu''on a ôté les pierres, et après qu''on a raclé la maison, et après qu''on l''a enduite,'),
(3156, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 44, 'OT', 'Le sacrificateur entrera et regardera, et voici que la plaie s''est étendue dans la maison : c''est une lèpre rongeante dans la maison ; elle est impure.'),
(3157, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 45, 'OT', 'Il démolira la maison, ses pierres et son bois, et toute la poussière de la maison, et il les portera dehors de la ville, vers un lieu impur.'),
(3158, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 46, 'OT', 'Quiconque entrera dans la maison, tous les jours où il l''aura fermée, sera impur jusqu''au soir.'),
(3159, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 47, 'OT', 'Celui qui couche dans la maison lavera ses vêtements, et celui qui mange dans la maison lavera ses vêtements.'),
(3160, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 48, 'OT', 'Et si le sacrificateur entre et voit, et voici que la plaie ne s''est pas étendue dans la maison après que la maison a été recrépie, le sacrificateur déclarera la maison pure, car la plaie est guérie.'),
(3161, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 49, 'OT', 'Et il prendra, pour purifier la maison, deux oiseaux, du bois de cèdre, du cramoisi écarlate, et de l''hysope.'),
(3162, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 50, 'OT', 'Il égorgera l''oiseau sur un ustensile de vase de terre, au-dessus d''eaux vives.'),
(3163, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 51, 'OT', 'Il prendra le bois de cèdre, l''hysope, le cramoisi, et l''oiseau vivant, et les trempera dans le sang de l''oiseau égorgé et dans les eaux vives, et il aspergera la maison sept fois.'),
(3164, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 52, 'OT', 'Il purifiera la maison avec le sang de l''oiseau, avec les eaux vives, avec l''oiseau vivant, avec le bois de cèdre, avec l''hysope et avec le cramoisi.'),
(3165, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 53, 'OT', 'Et il lâchera l''oiseau vivant dehors, hors de la ville, vers la face du champ, et il fera l''expiation pour la maison, et elle sera pure.'),
(3166, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 54, 'OT', 'Voici la loi pour toute plaie de lèpre et pour la teigne.'),
(3167, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 55, 'OT', 'et pour la lèpre du vêtement et de la maison.'),
(3168, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 56, 'OT', 'et pour la tumeur, et pour la tache, et pour la tache blanche.'),
(3169, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 14, 57, 'OT', 'Pour enseigner au jour de l''impureté et au jour de la pureté, telle est la loi de la lèpre.'),
(3170, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 1, 'OT', 'L''Éternel parla à Moïse et à Aaron, en disant :'),
(3171, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 2, 'OT', 'Parlez aux fils d''Israël et dites-leur : Tout homme qui aura un écoulement de sa chair, son écoulement est impur.'),
(3172, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 3, 'OT', 'Et voici quelle sera son impureté dans son écoulement : lorsque sa chair émet son écoulement, ou que sa chair se retient de son écoulement, c''est là son impureté.'),
(3173, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 4, 'OT', 'Tout lit sur lequel couchera celui qui a un écoulement sera impur, et tout ustensile sur lequel il s''assiéra sera impur.'),
(3174, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 5, 'OT', 'Et l''homme qui touchera son lit lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3175, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 6, 'OT', 'Celui qui s''assoit sur l''ustensile sur lequel s''est assis celui qui a un écoulement lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3176, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 7, 'OT', 'Et celui qui touche la chair de l''homme ayant un écoulement lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3177, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 8, 'OT', 'Et si celui qui a un écoulement crache sur celui qui est pur, il lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3178, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 9, 'OT', 'Et tout char sur lequel montera celui qui a un écoulement sera impur.'),
(3179, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 10, 'OT', 'Et tout homme qui touche à quoi que ce soit qui soit sous lui sera impur jusqu''au soir, et celui qui les porte lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3180, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 11, 'OT', 'Et tout ce que touchera celui qui a un écoulement, sans s''être lavé les mains dans les eaux, il lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3181, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 12, 'OT', 'Et l''ustensile de vase de terre que touchera celui qui a un écoulement sera brisé, et tout ustensile de bois sera lavé dans les eaux.'),
(3182, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 13, 'OT', 'Et quand celui qui a un écoulement sera purifié de son écoulement, il comptera pour lui sept jours pour sa purification, et il lavera ses vêtements, et il baignera sa chair dans des eaux vives, et il sera pur.'),
(3183, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 14, 'OT', 'Et au huitième jour, il prendra pour lui deux tourterelles ou deux jeunes pigeons, et il viendra devant l''Éternel, à l''entrée de la tente d''assignation, et il les donnera au sacrificateur.'),
(3184, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 15, 'OT', 'Le sacrificateur fera l''un comme sacrifice pour le péché, et l''autre comme holocauste ; et le sacrificateur fera l''expiation pour lui devant l''Éternel, à cause de son écoulement.'),
(3185, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 16, 'OT', 'Et si un homme a une couche de postérité qui sort de lui, il lavera dans les eaux toute sa chair, et il sera impur jusqu''au soir.'),
(3186, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 17, 'OT', 'Et tout vêtement et toute peau sur lesquels il y aura une couche de postérité seront lavés dans les eaux, et ils seront impurs jusqu''au soir.'),
(3187, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 18, 'OT', 'Et une femme avec laquelle un homme couchera d''une couche de postérité, ils se laveront dans les eaux, et ils seront impurs jusqu''au soir.'),
(3188, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 19, 'OT', 'Et une femme, lorsqu''elle aura un flux, que son flux soit du sang dans sa chair, elle sera sept jours dans son impureté, et tout celui qui la touchera sera impur jusqu''au soir.'),
(3189, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 20, 'OT', 'Tout ce sur quoi elle couchera pendant son impureté sera impur, et tout ce sur quoi elle s''assiéra sera impur.'),
(3190, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 21, 'OT', 'Et quiconque touche à son lit lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3191, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 22, 'OT', 'Et quiconque touche à tout ustensile sur lequel elle s''assiéra lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3192, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 23, 'OT', 'Et s''il est sur le lit, ou sur l''ustensile sur lequel elle est assise, lorsqu''il le touche, il sera impur jusqu''au soir.'),
(3193, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 24, 'OT', 'Et si un homme couche avec elle, et que son impureté soit sur lui, il sera impur sept jours, et tout lit sur lequel il couchera sera impur.'),
(3194, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 25, 'OT', 'Et si une femme a un écoulement de sang pendant de nombreux jours, hors du temps de son impureté, ou si elle a un écoulement au-delà de son impureté, tous les jours de l''écoulement de son impureté seront comme les jours de son impureté ; elle est impure.'),
(3195, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 26, 'OT', 'Tout lit sur lequel elle couchera tous les jours de son écoulement lui sera comme le lit de son impureté, et tout ustensile sur lequel elle s''assiéra sera impur, comme l''impureté de son impureté.'),
(3196, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 27, 'OT', 'Et tout celui qui les touche sera impur ; il lavera ses vêtements, se baignera dans les eaux, et sera impur jusqu''au soir.'),
(3197, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 28, 'OT', 'Mais si elle est purifiée de son écoulement, elle comptera pour elle sept jours, et après cela elle sera pure.'),
(3198, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 29, 'OT', 'Et au huitième jour, elle prendra pour elle deux tourterelles ou deux jeunes pigeons, et elle les apportera au sacrificateur, à l''entrée de la tente d''assignation.'),
(3199, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 30, 'OT', 'Le sacrificateur offrira l''un en sacrifice pour le péché, et l''autre en holocauste ; et le sacrificateur fera l''expiation pour elle devant l''Éternel, à cause de l''écoulement de son impureté.'),
(3200, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 31, 'OT', 'Vous séparerez les fils d''Israël de leur impureté, afin qu''ils ne meurent pas dans leur impureté, en souillant mon tabernacle qui est au milieu d''eux.'),
(3201, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 32, 'OT', 'C''est ici la loi de celui qui a un écoulement, et de celui de qui sort une couche de postérité, pour se souiller par elle.'),
(3202, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 15, 33, 'OT', 'Et la femme dans son impureté, et l''homme qui a un écoulement, son écoulement, pour le mâle et pour la femelle, et pour l''homme qui couche avec une femme impure.'),
(3203, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 1, 'OT', 'L''Éternel parla à Moïse après la mort des deux fils d''Aaron, lorsqu''ils s''approchèrent devant l''Éternel et moururent.'),
(3204, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 2, 'OT', 'L''Éternel dit à Moïse : Parle à Aaron, ton frère, et qu''il n''entre pas en tout temps dans le lieu saint, au-dedans du voile, devant le propitiatoire qui est sur l''arche, afin qu''il ne meure pas ; car c''est dans la nuée que j''apparaîtrai sur le propitiatoire.'),
(3205, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 3, 'OT', 'C''est avec cela qu''Aaron entrera dans le lieu saint : avec un jeune taureau, pour le péché, et un bélier pour l''holocauste.'),
(3206, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 4, 'OT', 'Il revêtira la tunique de lin saint, et des caleçons de lin seront sur sa chair, et il se ceindra d''une ceinture de lin, et il se coiffera d''une tiare de lin ; ce sont des vêtements saints. Il lavera sa chair dans les eaux, puis il les mettra.'),
(3207, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 5, 'OT', 'De l''assemblée des fils d''Israël, il prendra deux boucs de chèvres pour le péché, et un bélier pour l''holocauste.'),
(3208, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 6, 'OT', 'Aaron offrira le taureau du sacrifice pour le péché qui lui appartient, et il fera l''expiation pour lui-même et pour sa maison.'),
(3209, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 7, 'OT', 'Il prendra les deux boucs et les placera devant la face de l''Éternel, à l''entrée de la tente d''assignation.'),
(3210, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 8, 'OT', 'Aaron mettra les deux sorts sur les deux boucs : un sort pour l''Éternel, et un sort pour l''azazel.'),
(3211, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 9, 'OT', 'Aaron offrira le bouc sur lequel est tombé le sort pour l''Éternel, et il en fera un sacrifice pour le péché.'),
(3212, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 10, 'OT', 'Le bouc sur lequel est tombé le sort pour Azazel sera placé vivant devant l''Éternel, pour faire l''expiation sur lui, afin de l''envoyer pour Azazel dans le désert.'),
(3213, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 11, 'OT', 'Aaron offrira le taureau du sacrifice pour le péché qui est pour lui, et il fera l''expiation pour lui-même et pour sa maison ; puis il égorgera le taureau du sacrifice pour le péché qui est pour lui.'),
(3214, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 12, 'OT', 'Il prendra un plein contenu du brasier, des charbons de feu de dessus l''autel, de devant l''Éternel, et deux pleines poignées d''encens d''aromates finement pilés, et il l''apportera de l''intérieur de la maison, derrière le voile.'),
(3215, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 13, 'OT', 'Il mettra l''encens sur le feu devant l''Éternel, et la nuée de l''encens couvrira le propitiatoire qui est sur le témoignage, et il ne mourra pas.'),
(3216, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 14, 'OT', 'Il prendra du sang du taureau, et il en fera l''aspersion avec son doigt sur la face du propitiatoire, vers l''orient ; et devant le propitiatoire, il fera l''aspersion sept fois du sang avec son doigt.'),
(3217, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 15, 'OT', 'Il égorgera le bouc du sacrifice pour le péché qui est pour le peuple, et il apportera son sang à l''intérieur de la maison, derrière le voile, et il fera avec son sang comme il a fait avec le sang du taureau, et il en aspergera le propitiatoire et devant le propitiatoire.'),
(3218, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 16, 'OT', 'Il fera l''expiation pour le saint lieu, à cause des impuretés des fils d''Israël et de leurs transgressions, pour tous leurs péchés ; et il fera de même pour la tente d''assignation qui demeure avec eux, au milieu de leurs impuretés.'),
(3219, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 17, 'OT', 'Aucun homme ne sera dans la tente d''assignation lorsqu''il entrera pour faire l''expiation dans le saint, jusqu''à ce qu''il en sorte ; et il fera l''expiation pour lui-même, pour sa maison, et pour toute l''assemblée d''Israël.'),
(3220, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 18, 'OT', 'Il sortira vers l''autel qui est devant l''Éternel, et il fera l''expiation sur lui ; il prendra du sang du taureau et du sang du bouc, et il en mettra sur les cornes de l''autel, tout alentour.'),
(3221, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 19, 'OT', 'Il fera aspersion sur lui du sang avec son doigt sept fois, et il le purifiera et le sanctifiera des impuretés des fils d''Israël.'),
(3222, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 20, 'OT', 'Quand il aura fini d''expier le saint, la tente d''assignation et l''autel, il présentera le bouc vivant.'),
(3223, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 21, 'OT', 'Aaron posera ses deux mains sur la tête du bouc vivant, et confessera sur lui toutes les iniquités des fils d''Israël et toutes leurs transgressions, pour tous leurs péchés ; il les mettra sur la tête du bouc, et l''enverra au désert par la main d''un homme désigné.'),
(3224, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 22, 'OT', 'Le bouc portera sur lui toutes leurs iniquités vers une terre de séparation, et l''on enverra le bouc dans le désert.'),
(3225, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 23, 'OT', 'Aaron entrera dans la tente d''assignation, et il ôtera les vêtements de lin qu''il avait revêtus en entrant dans le lieu saint, et il les déposera là.'),
(3226, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 24, 'OT', 'Il lavera sa chair dans les eaux, en un lieu saint, et revêtira ses vêtements ; puis il sortira, offrira son holocauste et l''holocauste du peuple, et fera l''expiation pour lui-même et pour le peuple.'),
(3227, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 25, 'OT', 'Il fera fumer la graisse du péché sur l''autel.'),
(3228, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 26, 'OT', 'Celui qui envoie le bouc pour Azazel lavera ses vêtements, et lavera sa chair dans les eaux ; et après cela, il entrera dans le camp.'),
(3229, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 27, 'OT', 'Et le taureau du péché et le bouc du péché, dont le sang a été apporté pour faire l''expiation dans le saint lieu, on les emportera hors du camp, et on brûlera au feu leurs peaux, leur chair et leurs excréments.'),
(3230, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 28, 'OT', 'Celui qui les brûlera lavera ses vêtements, et baignera sa chair dans les eaux, et après cela il entrera dans le camp.'),
(3231, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 29, 'OT', 'Ce sera pour vous une loi perpétuelle : au septième mois, le dixième jour du mois, vous humilierez vos âmes, et vous ne ferez aucun ouvrage, ni l''autochtone ni l''étranger qui séjourne au milieu de vous.'),
(3232, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 30, 'OT', 'Car en ce jour-là, on fera l''expiation pour vous, afin de vous purifier de tous vos péchés ; devant l''Éternel, vous serez purifiés.'),
(3233, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 31, 'OT', 'C''est un sabbat de repos solennel pour vous, et vous affligerez vos âmes ; c''est une loi pour toujours.'),
(3234, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 32, 'OT', 'Le sacrificateur qui sera oint et dont la main sera remplie pour exercer la sacrificature à la place de son père fera l''expiation, et il revêtira les vêtements de lin, les vêtements saints.'),
(3235, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 33, 'OT', 'Il fera l''expiation pour le sanctuaire saint, et pour la tente d''assignation, et pour l''autel il fera l''expiation ; et pour les sacrificateurs et pour tout le peuple de l''assemblée il fera l''expiation.'),
(3236, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 16, 34, 'OT', 'Cela sera pour vous une loi perpétuelle, pour faire l''expiation sur les fils d''Israël de tous leurs péchés, une fois par année ; et il fit comme l''Éternel l''avait commandé à Moïse.'),
(3237, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3238, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 2, 'OT', 'Parle à Aaron et à ses fils, et à tous les fils d''Israël, et dis-leur : Voici la parole que l''Éternel a commandée, en disant :'),
(3239, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 3, 'OT', 'Tout homme de la maison d''Israël qui égorge un bœuf, ou un agneau, ou une chèvre dans le camp, ou qui l''égorge dehors du camp,'),
(3240, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 4, 'OT', 'Et à l''entrée de la tente d''assignation il ne l''a pas apporté, pour offrir une offrande à l''Éternel devant la face du tabernacle de l''Éternel, du sang sera imputé à cet homme ; il a versé du sang, et cet homme sera retranché du milieu de son peuple.'),
(3241, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 5, 'OT', 'afin que les fils d''Israël apportent leurs sacrifices qu''ils sacrifient sur la face du champ, et qu''ils les amènent à l''Éternel, à l''entrée de la tente d''assignation, au sacrificateur, et qu''ils les sacrifient en sacrifices d''actions de grâces à l''Éternel.'),
(3242, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 6, 'OT', 'Le sacrificateur répandra le sang sur l''autel de l''Éternel, à l''entrée de la tente d''assignation, et il fera fumer la graisse en odeur agréable à l''Éternel.'),
(3243, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 7, 'OT', 'Ils n''offriront plus leurs sacrifices aux boucs, après lesquels ils se prostituent ; ce sera pour eux une loi perpétuelle, pour leurs générations.'),
(3244, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 8, 'OT', 'Et tu leur diras : Tout homme, homme de la maison d''Israël, ou de l''étranger qui séjourne au milieu d''eux, qui offrira un holocauste ou un sacrifice.'),
(3245, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 9, 'OT', 'Et ne l''apportera point à l''entrée de la tente d''assignation pour le faire à l''Éternel, cet homme-là sera retranché du milieu de son peuple.'),
(3246, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 10, 'OT', 'Tout homme, homme de la maison d''Israël, et de l''étranger qui séjourne au milieu d''eux, qui mange quelque sang que ce soit, je tournerai ma face contre cette âme qui mange le sang, et je la retrancherai du milieu de son peuple.'),
(3247, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 11, 'OT', 'Car l''âme de la chair est dans le sang, et je vous l''ai donné sur l''autel pour faire l''expiation pour vos âmes ; car c''est le sang qui, par l''âme, fait l''expiation.'),
(3248, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 12, 'OT', 'C''est pourquoi j''ai dit aux fils d''Israël : Toute âme d''entre vous ne mangera pas de sang, et l''étranger qui séjourne au milieu de vous ne mangera pas de sang.'),
(3249, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 13, 'OT', 'Tout homme, tant d''entre les fils d''Israël que d''entre l''étranger qui séjourne au milieu d''eux, qui chasse du gibier, bête ou oiseau qui se mange, répandra son sang et le couvrira de poussière.'),
(3250, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 14, 'OT', 'Car l''âme de toute chair, c''est son sang qui est en son âme ; et j''ai dit aux fils d''Israël : Vous ne mangerez le sang d''aucune chair, car l''âme de toute chair, c''est son sang ; quiconque le mangera sera retranché.'),
(3251, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 15, 'OT', 'Toute âme qui mangera une carcasse ou une bête déchirée, tant chez l''autochtone que chez l''étranger, lavera ses vêtements, se baignera dans les eaux, et sera impure jusqu''au soir ; puis elle sera pure.'),
(3252, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 17, 16, 'OT', 'Et s''il ne lave pas ses vêtements et ne lave pas sa chair, il portera son iniquité.'),
(3253, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3254, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 2, 'OT', 'Parle aux fils d''Israël et dis-leur : Je suis l''Éternel, votre Dieu.'),
(3255, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 3, 'OT', 'Ne faites point selon les œuvres de la terre d''Égypte, où vous avez habité, et ne faites point selon les œuvres de la terre de Canaan, où je vous mène, et ne marchez point dans leurs lois.'),
(3256, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 4, 'OT', 'Vous pratiquerez mes jugements, et vous garderez mes lois, pour marcher en elles : je suis l''Éternel, votre Dieu.'),
(3257, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 5, 'OT', 'Vous garderez mes lois et mes jugements, que l''homme accomplira et par lesquels il vivra ; je suis l''Éternel.'),
(3258, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 6, 'OT', 'Nul homme ne s''approchera d''aucune chair de sa propre chair pour découvrir la nudité ; je suis l''Éternel.'),
(3259, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 7, 'OT', 'Tu ne découvriras point la nudité de ton père ni la nudité de ta mère : elle est ta mère, tu ne découvriras point sa nudité.'),
(3260, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 8, 'OT', 'La nudité de la femme de ton père, tu ne la découvriras pas ; c''est la nudité de ton père.'),
(3261, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 9, 'OT', 'La nudité de ta sœur, fille de ton père ou fille de ta mère, née dans la maison ou née dehors, tu ne découvriras pas leur nudité.'),
(3262, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 10, 'OT', 'La nudité de la fille de ton fils ou de la fille de ta fille, tu ne découvriras pas leur nudité, car c''est ta propre nudité.'),
(3263, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 11, 'OT', 'La nudité de la fille de la femme de ton père, née de ton père, est ta sœur ; tu ne découvriras pas sa nudité.'),
(3264, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 12, 'OT', 'Tu ne découvriras point la nudité de la sœur de ton père ; elle est la chair de ton père.'),
(3265, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 13, 'OT', 'Tu ne découvriras point la nudité de la sœur de ta mère ; car elle est la chair de ta mère.'),
(3266, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 14, 'OT', 'Tu ne découvriras point la nudité du frère de ton père ; tu ne t''approcheras point de sa femme : elle est ta tante.'),
(3267, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 15, 'OT', 'Tu ne découvriras point la nudité de ta fiancée ; elle est la femme de ton fils ; tu ne découvriras point sa nudité.'),
(3268, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 16, 'OT', 'Tu ne découvriras point la nudité de la femme de ton frère ; c''est la nudité de ton frère.'),
(3269, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 17, 'OT', 'Tu ne découvriras point la nudité d''une femme et de sa fille ; tu ne prendras point la fille de son fils ni la fille de sa fille pour découvrir leur nudité : elles sont proches parentes ; c''est un crime.'),
(3270, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 18, 'OT', 'Tu ne prendras point une femme avec sa sœur, pour la rendre rivale, en découvrant sa nudité sur elle, pendant sa vie.'),
(3271, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 19, 'OT', 'Et tu ne t''approcheras point d''une femme pendant son impureté menstruelle, pour découvrir sa nudité.'),
(3272, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 20, 'OT', 'Et tu ne donneras pas ton coucher à la femme de ton prochain, pour une postérité, afin de te souiller avec elle.'),
(3273, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 21, 'OT', 'Tu ne donneras point de ta postérité pour la faire passer à Moloc, et tu ne profaneras point le nom de ton Dieu : je suis l''Éternel.'),
(3274, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 22, 'OT', 'Tu ne coucheras point avec un mâle comme on couche avec une femme ; c''est une abomination.'),
(3275, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 23, 'OT', 'Et avec tout bétail tu ne donneras pas ton coucher pour te souiller avec lui, et une femme ne se tiendra pas devant la face d''un bétail pour s''accoupler avec lui : c''est une confusion.'),
(3276, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 24, 'OT', 'Ne vous souillez pas dans toutes ces choses, car c''est dans toutes ces choses que se sont souillées les nations que je chasse devant votre face.'),
(3277, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 25, 'OT', 'La terre fut souillée, et je punis son iniquité sur elle, et la terre vomit ses habitants.'),
(3278, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 26, 'OT', 'Vous garderez mes lois et mes jugements, et vous ne ferez aucune de toutes ces abominations, ni l''autochtone ni l''étranger qui séjourne au milieu de vous.'),
(3279, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 27, 'OT', 'Car ils ont commis toutes ces abominations, les hommes de la terre qui étaient devant vous, et la terre en a été souillée.'),
(3280, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 28, 'OT', 'Et la terre ne vous vomira point, parce que vous l''aurez souillée, comme elle a vomi la nation qui était devant vous.'),
(3281, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 29, 'OT', 'Car quiconque fera l''une de toutes ces abominations, les âmes qui les feront seront retranchées du milieu de leur peuple.'),
(3282, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 18, 30, 'OT', 'Vous garderez mon observance, pour ne pas faire des lois des abominations qui ont été faites devant votre face, et vous ne vous souillerez pas par elles ; je suis l''Éternel, votre Dieu.'),
(3283, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3284, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 2, 'OT', 'Parle à toute l''assemblée des fils d''Israël, et dis-leur : Vous serez saints, car je suis saint, moi, l''Éternel, votre Dieu.'),
(3285, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 3, 'OT', 'Chaque homme craindra sa mère et son père, et vous garderez mes sabbats ; je suis l''Éternel, votre Dieu.'),
(3286, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 4, 'OT', 'Ne vous tournez point vers les idoles, et ne faites point pour vous des dieux en image taillée ; je suis l''Éternel, votre Dieu.'),
(3287, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 5, 'OT', 'Et quand vous offrirez un sacrifice d''actions de grâces à l''Éternel, vous l''offrirez pour votre bienveillance.'),
(3288, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 6, 'OT', 'Le jour de votre sacrifice, on le mangera, et le lendemain ; et ce qui restera jusqu''au troisième jour sera brûlé au feu.'),
(3289, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 7, 'OT', 'Et si l''on en mange le troisième jour, c''est une chose impure ; cela ne sera point agréé.'),
(3290, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 8, 'OT', 'Celui qui en mange portera son iniquité, car il a profané le saint de l''Éternel ; et cette âme sera retranchée du milieu de son peuple.'),
(3291, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 9, 'OT', 'Quand vous moissonnerez la moisson de votre terre, tu n''achèveras pas le côté de ton champ pour le moissonner, et tu ne ramasseras pas le glanage de ta moisson.'),
(3292, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 10, 'OT', 'Tu ne grappilleras pas ta vigne, et tu ne ramasseras pas les grappes tombées de ta vigne ; tu les laisseras pour le pauvre et pour l''étranger : je suis l''Éternel, votre Dieu.'),
(3293, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 11, 'OT', 'Vous ne volerez point, et vous ne tromperez point, et vous ne mentirez point, un homme à son prochain.'),
(3294, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 12, 'OT', 'Vous ne jurerez point par mon nom pour le mensonge, et tu ne profaneras point le nom de ton Dieu : je suis l''Éternel.'),
(3295, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 13, 'OT', 'Tu n''opprimeras point ton ami, et tu ne déroberas point ; tu ne retiendras point le salaire du mercenaire avec toi jusqu''au matin.'),
(3296, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 14, 'OT', 'Tu ne maudiras point le sourd, et devant l''aveugle tu ne mettras point d''obstacle, et tu craindras ton Dieu : je suis l''Éternel.'),
(3297, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 15, 'OT', 'Ne commettez point d''iniquité dans le jugement ; ne favorisez point la face du pauvre, et n''honorez point la face du grand ; mais jugez votre prochain avec justice.'),
(3298, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 16, 'OT', 'Tu ne te feras pas calomniateur parmi ton peuple ; tu ne te tiendras pas contre le sang de ton ami. Je suis l''Éternel.'),
(3299, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 17, 'OT', 'Tu ne haïras point ton frère dans ton cœur ; tu reprendras certainement ton prochain, et tu ne porteras point de péché à cause de lui.'),
(3300, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 18, 'OT', 'Tu ne te vengeras point, et tu ne garderas point de rancune envers les fils de ton peuple, mais tu aimeras ton ami comme toi-même ; je suis l''Éternel.'),
(3301, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 19, 'OT', 'Vous garderez mes lois : tu ne feras pas accoupler ton bétail avec des espèces différentes ; tu ne sèmeras pas ton champ avec des espèces différentes ; et un vêtement d''étoffe mélangée ne montera pas sur toi.'),
(3302, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 20, 'OT', 'Si un homme couche avec une femme, ayant une couche de postérité, et qu''elle est une servante fiancée à un homme, et qu''elle n''a pas été rachetée, ni que la liberté ne lui a été donnée, il y aura un châtiment ; ils ne seront pas mis à mort, car elle n''était pas libre.'),
(3303, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 21, 'OT', 'Il amènera son sacrifice de culpabilité à l''Éternel, à l''entrée de la tente d''assignation, un bélier en sacrifice de culpabilité.'),
(3304, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 22, 'OT', 'Le sacrificateur fera l''expiation pour lui avec le bélier du sacrifice de culpabilité devant la face de l''Éternel, pour son péché qu''il a commis, et il lui sera pardonné, pour le péché qu''il a commis.'),
(3305, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 23, 'OT', 'Et quand vous entrerez dans la terre et que vous planterez tout bois de nourriture, vous tiendrez son fruit pour incirconcis, son prépuce ; trois années il sera pour vous incirconcis, on n''en mangera point.'),
(3306, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 24, 'OT', 'Et en la quatrième année, tout son fruit sera une chose sainte, des fêtes de louanges à l''Éternel.'),
(3307, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 25, 'OT', 'Et la cinquième année, vous mangerez son fruit, pour ajouter à votre produit ; je suis l''Éternel, votre Dieu.'),
(3308, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 26, 'OT', 'Vous ne mangerez point avec le sang ; vous ne pratiquerez point la divination, et vous ne vous adonnerez point aux augures.'),
(3309, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 27, 'OT', 'Vous ne couperez point le côté de votre tête, et vous ne détruirez point le côté de votre barbe.'),
(3310, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 28, 'OT', 'Vous ne ferez point d''incision dans votre chair pour une âme, et vous ne ferez point de tatouage sur vous : je suis l''Éternel.'),
(3311, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 29, 'OT', 'Ne profane pas ta fille en la livrant à la prostitution, et que la terre ne se prostitue pas, et que la terre ne se remplisse de crime.'),
(3312, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 30, 'OT', 'Vous garderez mes sabbats, et vous révérerez mon sanctuaire. Je suis l''Éternel.'),
(3313, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 31, 'OT', 'Ne vous tournez point vers les esprits évoqués ni vers les esprits qui prédisent ; ne les recherchez pas pour vous souiller par eux. Je suis l''Éternel, votre Dieu.'),
(3314, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 32, 'OT', 'Tu te lèveras devant la face de la vieillesse, et tu honoreras la face du vieillard, et tu craindras ton Dieu : je suis l''Éternel.'),
(3315, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 33, 'OT', 'Si un étranger séjourne avec toi dans votre terre, vous ne l''opprimerez point.'),
(3316, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 34, 'OT', 'L''étranger qui séjourne parmi vous sera pour vous comme un autochtone parmi vous, et tu l''aimeras comme toi-même, car vous avez été étrangers dans la terre d''Égypte ; je suis l''Éternel, votre Dieu.'),
(3317, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 35, 'OT', 'Ne commettez point d''iniquité dans le jugement, dans la mesure, dans le poids, et dans la mesure.'),
(3318, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 36, 'OT', 'Des balances de justice, des pierres de justice, un épha de justice, et un hin de justice seront à vous ; je suis l''Éternel, votre Dieu, qui vous ai fait sortir de la terre d''Égypte.'),
(3319, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 19, 37, 'OT', 'Vous garderez toutes mes lois et tous mes jugements, et vous les accomplirez ; je suis l''Éternel.'),
(3320, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3321, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 2, 'OT', 'Tu diras aux fils d''Israël : Tout homme, parmi les fils d''Israël ou parmi l''étranger qui séjourne en Israël, qui donnera de sa postérité à Moloc, sera mis à mort ; le peuple de la terre le lapidera avec des pierres.'),
(3322, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 3, 'OT', 'Et moi, je tournerai ma face contre cet homme, et je le retrancherai du milieu de son peuple, parce qu''il a donné de sa postérité à Moloc, afin de souiller mon sanctuaire et de profaner mon saint nom.'),
(3323, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 4, 'OT', 'Et si le peuple de la terre détourne ses yeux de cet homme, lorsqu''il donne de sa postérité à Moloc, pour ne pas le faire mourir,'),
(3324, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 5, 'OT', 'Et je tournerai ma face contre cet homme-là et contre sa famille, et je retrancherai du milieu de leur peuple lui et tous ceux qui se prostituent après lui, en se prostituant après Moloc.'),
(3325, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 6, 'OT', 'L''âme qui se tourne vers les esprits évoqués et vers les esprits, pour se prostituer après eux, je tournerai ma face contre cette âme, et je la retrancherai du milieu de son peuple.'),
(3326, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 7, 'OT', 'Sanctifiez-vous et soyez saints, car je suis l''Éternel, votre Dieu.'),
(3327, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 8, 'OT', 'Vous garderez mes lois et vous les mettrez en pratique. Je suis l''Éternel qui vous sanctifie.'),
(3328, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 9, 'OT', 'Car tout homme qui maudit son père ou sa mère sera mis à mort; il a maudit son père et sa mère, son sang est sur lui.'),
(3329, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 10, 'OT', 'Et l''homme qui commet un adultère avec la femme d''un homme, qui commet un adultère avec la femme de son ami, le coupable d''adultère et la coupable d''adultère seront mis à mort.'),
(3330, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 11, 'OT', 'L''homme qui couche avec la femme de son père a découvert la nudité de son père ; ils seront mis à mort tous les deux, leur sang est sur eux.'),
(3331, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 12, 'OT', 'L''homme qui couche avec sa fiancée, tous deux seront mis à mort ; ils ont commis une confusion ; leur sang est sur eux.'),
(3332, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 13, 'OT', 'Un homme qui couche avec un mâle comme on couche avec une femme, ils ont fait une abomination, tous deux ; ils seront mis à mort, leur sang est sur eux.'),
(3333, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 14, 'OT', 'Si un homme prend une femme et sa mère, c''est un crime ; on les brûlera au feu, lui et elles, et il n''y aura pas de crime au milieu de vous.'),
(3334, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 15, 'OT', 'Si un homme donne son coucher à un bétail, il sera mis à mort, et vous tuerez le bétail.'),
(3335, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 16, 'OT', 'Et la femme qui s''approchera de tout bétail pour s''accoupler avec lui, tu tueras la femme et le bétail ; ils seront mis à mort, leur sang sera sur eux.'),
(3336, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 17, 'OT', 'Et un homme qui prend sa sœur, fille de son père ou fille de sa mère, et voit sa nudité, et qu''elle voie sa nudité, c''est une bonté ; ils seront retranchés aux yeux des fils de leur peuple ; il a découvert la nudité de sa sœur, il portera son iniquité.'),
(3337, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 18, 'OT', 'Si un homme couche avec une femme pendant son impureté menstruelle et découvre sa nudité, exposant sa source, et qu''elle découvre la source de son sang, tous deux seront retranchés du milieu de leur peuple.'),
(3338, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 19, 'OT', 'Tu ne découvriras point la nudité de la sœur de ta mère ni la sœur de ton père, car c''est leur chair qu''ils ont découverte ; ils porteront leur iniquité.'),
(3339, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 20, 'OT', 'Un homme qui couche avec sa tante découvre la nudité de son bien-aimé ; ils porteront leur péché, ils mourront sans enfants.'),
(3340, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 21, 'OT', 'Et un homme qui prend la femme de son frère, c''est une impureté ; il a découvert la nudité de son frère ; ils seront sans enfants.'),
(3341, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 22, 'OT', 'Vous garderez toutes mes lois et tous mes jugements, et vous les accomplirez ; et la terre où je vous fais entrer pour y habiter ne vous vomira point.'),
(3342, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 23, 'OT', 'Et vous ne marcherez point dans les lois de la nation que je chasse devant votre face, car ils ont fait toutes ces choses, et je les ai pris en dégoût.'),
(3343, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 24, 'OT', 'Je vous ai dit : vous posséderez leur terre, et je vous la donnerai pour la posséder, une terre ruisselante de lait et de miel ; je suis l''Éternel, votre Dieu, qui vous ai séparés des peuples.'),
(3344, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 25, 'OT', 'Vous distinguerez entre le bétail pur et l''impur, et entre l''oiseau impur et le pur ; et vous ne rendrez pas vos âmes abominables par le bétail, par l''oiseau, et par tout ce qui rampe sur la terre, que j''ai séparé pour vous comme impur.'),
(3345, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 26, 'OT', 'Vous serez saints pour moi, car je suis saint, moi l''Éternel, et je vous ai séparés des peuples pour que vous soyez à moi.'),
(3346, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 20, 27, 'OT', 'Si un homme ou une femme a en eux un esprit évoqué ou un esprit de divination, ils seront mis à mort ; on les lapidera avec des pierres ; leur sang sera sur eux.'),
(3347, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 1, 'OT', 'L''Éternel dit à Moïse : Parle aux sacrificateurs, fils d''Aaron, et dis-leur : Qu''aucun d''eux ne se rende impur pour une âme morte parmi son peuple.'),
(3348, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 2, 'OT', 'mais seulement pour sa chair, son proche parent, pour sa mère, pour son père, pour son fils, pour sa fille et pour son frère.'),
(3349, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 3, 'OT', 'et pour sa sœur vierge, qui lui est proche, qui n''a pas été à un homme, pour elle il se rendra impur.'),
(3350, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 4, 'OT', 'Le maître ne se rendra pas impur parmi son peuple, au point de se profaner.'),
(3351, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 5, 'OT', 'Ils ne feront point de calvitie sur leur tête, et ils ne raseront point le côté de leur barbe, et ils ne feront point d''incision dans leur chair.'),
(3352, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 6, 'OT', 'Ils seront saints pour leur Dieu, et ils ne profaneront pas le nom de leur Dieu, car ils présentent les sacrifices consumés par le feu de l''Éternel, le pain de leur Dieu, et ils seront saints.'),
(3353, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 7, 'OT', 'Ils ne prendront point une femme prostituée ni une femme profanée, et ils ne prendront point une femme répudiée de son homme, car il est saint pour son Dieu.'),
(3354, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 8, 'OT', 'Tu le sanctifieras, car il offre le pain de ton Dieu ; il sera saint pour toi, car je suis saint, moi l''Éternel, qui vous sanctifie.'),
(3355, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 9, 'OT', 'Et la fille d''un homme sacrificateur, si elle commence à se prostituer, elle profane son père ; elle sera brûlée au feu.'),
(3356, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 10, 'OT', 'Le sacrificateur, le plus grand parmi ses frères, sur la tête duquel l''huile de l''onction a été versée, et dont la main a été remplie pour revêtir les vêtements, ne laissera pas sa tête découverte, et ne déchirera pas ses vêtements.'),
(3357, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 11, 'OT', 'Il n''entrera auprès d''aucune âme morte ; pour son père et pour sa mère, il ne se rendra pas impur.'),
(3358, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 12, 'OT', 'Et du sanctuaire il ne sortira point, et il ne profanera point le sanctuaire de son Dieu, car le diadème de l''huile de l''onction de son Dieu est sur lui : je suis l''Éternel.'),
(3359, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 13, 'OT', 'Et il prendra une femme dans sa virginité.'),
(3360, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 14, 'OT', 'Il ne prendra ni veuve, ni répudiée, ni profanée, ni prostituée ; mais il prendra pour femme une vierge de son peuple.'),
(3361, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 15, 'OT', 'Il ne profanera pas sa postérité parmi son peuple, car moi, l''Éternel, je le sanctifie.'),
(3362, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 16, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3363, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 17, 'OT', 'Parle à Aaron et dis-lui : Tout homme de ta postérité, dans leurs générations, qui aura un défaut, ne s''approchera pas pour offrir le pain de son Dieu.'),
(3364, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 18, 'OT', 'Car tout homme qui a en lui un défaut ne s''approchera point : un homme aveugle, ou boiteux, ou au nez camus, ou ayant un membre trop long.'),
(3365, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 19, 'OT', 'ou un homme qui aura une ruine du pied ou une ruine de la main.'),
(3366, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 20, 'OT', 'ou bossu, ou nain, ou ayant une tache dans son œil, ou gale, ou gale, ou testicule froissé.'),
(3367, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 21, 'OT', 'Tout homme de la postérité d''Aaron, le sacrificateur, qui a un défaut, ne s''approchera pas pour offrir les sacrifices consumés par le feu de l''Éternel ; ayant un défaut, il ne s''approchera pas pour présenter le pain de son Dieu.'),
(3368, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 22, 'OT', 'Le pain de son Dieu, des choses très saintes et des choses saintes, il en mangera.'),
(3369, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 23, 'OT', 'Mais il n''entrera pas vers le voile, et il ne s''approchera pas de l''autel, car il a un défaut ; et il ne profanera pas mon sanctuaire, car je suis l''Éternel qui les sanctifie.'),
(3370, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 21, 24, 'OT', 'Moïse parla à Aaron et à ses fils, et à tous les fils d''Israël.'),
(3371, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3372, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 2, 'OT', 'Parle à Aaron et à ses fils, et qu''ils se séparent des choses saintes des fils d''Israël, et qu''ils ne profanent pas mon saint nom, qu''ils sanctifient pour moi : je suis l''Éternel.'),
(3373, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 3, 'OT', 'Dis-leur, de génération en génération : tout homme qui, parmi toute votre postérité, s''approchera des choses saintes que les fils d''Israël consacrent à l''Éternel, ayant son impureté sur lui, cette âme-là sera retranchée de devant ma face : moi, je suis l''Éternel.'),
(3374, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 4, 'OT', 'Tout homme de la postérité d''Aaron, s''il est lépreux ou atteint d''un écoulement, ne mangera pas des choses saintes jusqu''à ce qu''il soit pur ; et celui qui touche à tout ce qui est impur par une âme, ou un homme de qui est sortie une couche de postérité, ne mangera pas des choses saintes.'),
(3375, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 5, 'OT', 'ou un homme qui touche à tout reptile qui le rend impur, ou un homme qui le rend impur par toute son impureté.'),
(3376, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 6, 'OT', 'L''âme qui le touchera sera impure jusqu''au soir, et ne mangera pas des choses saintes, à moins qu''il n''ait lavé sa chair dans les eaux.'),
(3377, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 7, 'OT', 'Quand le soleil sera couché, il sera pur, et ensuite il mangera des choses saintes, car c''est son pain.'),
(3378, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 8, 'OT', 'Il ne mangera ni carcasse ni bête déchirée, pour se rendre impur par elle : je suis l''Éternel.'),
(3379, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 9, 'OT', 'Ils garderont mon observance, et ne porteront pas de péché à son sujet, et ils mourront à cause d''elle, car ils la profaneront : je suis l''Éternel qui les sanctifie.'),
(3380, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 10, 'OT', 'Aucun étranger ne mangera d''une chose sainte ; l''étranger demeurant chez un sacrificateur, ni le mercenaire, ne mangeront d''une chose sainte.'),
(3381, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 11, 'OT', 'Et le sacrificateur, s''il acquiert une âme comme biens de son argent, celui-là en mangera ; et l''enfant de sa maison, eux mangeront de son pain.'),
(3382, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 12, 'OT', 'Et la fille d''un sacrificateur, si elle devient femme d''un homme étranger, elle ne mangera point de l''offrande des choses saintes.'),
(3383, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 13, 'OT', 'Si la fille d''un sacrificateur devient veuve ou répudiée, sans avoir de postérité, et qu''elle retourne à la maison de son père comme dans sa jeunesse, elle mangera du pain de son père ; mais tout étranger n''en mangera point.'),
(3384, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 14, 'OT', 'Si un homme mange une chose sainte involontairement, il ajoutera son cinquième par-dessus, et donnera au sacrificateur la chose sainte.'),
(3385, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 15, 'OT', 'Ils ne profaneront pas les choses saintes des fils d''Israël, celles qu''ils prélèvent pour l''Éternel.'),
(3386, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 16, 'OT', 'Et ils porteront l''iniquité de leur culpabilité en mangeant leurs choses saintes, car je suis l''Éternel qui les sanctifie.'),
(3387, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 17, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3388, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 18, 'OT', 'Parle à Aaron et à ses fils, et à tous les fils d''Israël, et dis-leur : Tout homme, tout homme de la maison d''Israël, ou de l''étranger en Israël, qui présentera son offrande pour tous leurs vœux et pour toutes leurs offrandes volontaires, qu''ils offriront à l''Éternel en holocauste.'),
(3389, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 19, 'OT', 'Pour votre bienveillance, un mâle sans défaut parmi les bœufs, parmi les agneaux et parmi les chèvres.'),
(3390, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 20, 'OT', 'Tout ce qui a un défaut, vous ne l''offrirez pas, car cela ne sera pas pour votre bienveillance.'),
(3391, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 21, 'OT', 'Et un homme, lorsqu''il offrira un sacrifice d''actions de grâces à l''Éternel, pour accomplir un vœu ou comme offrande volontaire, soit en bœufs, soit en brebis, il sera sans défaut pour être agréé ; tout défaut ne sera point en lui.'),
(3392, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 22, 'OT', 'Aveuglement, ou estropiée, ou fracturée, ou ulcère, ou gale, ou gale, vous n''offrirez pas ces choses à l''Éternel, et vous ne donnerez pas de sacrifice consumé par le feu, pris d''elles, sur l''autel, à l''Éternel.'),
(3393, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 23, 'OT', 'Un bœuf ou un agneau qui a un membre trop long ou trop court, tu pourras l''offrir en offrande volontaire, mais pour un vœu il ne sera pas agréé.'),
(3394, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 24, 'OT', 'Et meurtri, ou écrasé, ou déchiré, ou coupé, vous n''en offrirez point à l''Éternel ; et dans votre terre vous ne le ferez point.'),
(3395, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 25, 'OT', 'Et de la main du fils de l''étranger vous n''offrirez pas le pain de votre Dieu, d''aucun de tous ceux-là, car leur défiguration est en eux ; ils ont un défaut ; ils ne seront pas agréés pour vous.'),
(3396, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 26, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3397, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 27, 'OT', 'Un bœuf, ou un agneau, ou une chèvre, quand il naîtra, sera sept jours sous sa mère ; et dès le huitième jour et au-delà, il sera agréé comme offrande, sacrifice consumé par le feu, pour l''Éternel.'),
(3398, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 28, 'OT', 'Tu ne sacrifieras point un bœuf ou un agneau, lui et son fils, en un même jour.'),
(3399, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 29, 'OT', 'Et quand vous offrirez un sacrifice d''actions de grâces à l''Éternel, vous l''offrirez pour votre bienveillance.'),
(3400, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 30, 'OT', 'On ce jour-là, il sera mangé ; vous n''en laisserez rien jusqu''au matin ; je suis l''Éternel.'),
(3401, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 31, 'OT', 'Vous garderez mes commandements et vous les accomplirez ; je suis l''Éternel.'),
(3402, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 32, 'OT', 'Vous ne profanerez point mon saint nom, et je serai sanctifié au milieu des fils d''Israël ; je suis l''Éternel qui vous sanctifie.'),
(3403, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 22, 33, 'OT', 'Celui qui vous fait sortir de la terre d''Égypte pour être votre Dieu, moi, l''Éternel.'),
(3404, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3405, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 2, 'OT', 'Parle aux fils d''Israël, et dis-leur : Les assignations de l''Éternel, que vous proclamerez comme convocations saintes, ce sont là mes assignations.'),
(3406, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 3, 'OT', 'Six jours, on fera un ouvrage ; mais au septième jour, il y aura un sabbat de repos solennel, une convocation sainte ; vous ne ferez aucun ouvrage ; c''est un sabbat pour l''Éternel dans toutes vos habitations.'),
(3407, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 4, 'OT', 'Voici les assignations de l''Éternel, les convocations saintes, que vous proclamerez en leur assignation.'),
(3408, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 5, 'OT', 'Au premier mois, le quatorzième jour du mois, entre les deux soirs, c''est la Pâque de l''Éternel.'),
(3409, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 6, 'OT', 'Dix‑huit jours de ce mois, la fête des pains sans levain pour l''Éternel ; sept jours vous mangerez des pains sans levain.'),
(3410, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 7, 'OT', 'Le premier jour, il y aura pour vous une sainte convocation ; vous ne ferez aucun ouvrage de service.'),
(3411, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 8, 'OT', 'Vous offrirez un sacrifice consumé par le feu à l''Éternel pendant sept jours ; au septième jour, il y aura une convocation sainte ; vous ne ferez aucun ouvrage de service.'),
(3412, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 9, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3413, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 10, 'OT', 'Parle aux fils d''Israël et dis-leur : Quand vous entrerez dans la terre que je vous donne, et que vous moissonnerez sa moisson, vous apporterez la gerbe du commencement de votre moisson au sacrificateur.'),
(3414, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 11, 'OT', 'Il agitera la gerbe devant la face de l''Éternel, pour votre bienveillance ; le lendemain du sabbat, le sacrificateur l''agitera.'),
(3415, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 12, 'OT', 'Et en ce jour où vous élèverez la gerbe, vous offrirez un agneau sans défaut d''un an, en holocauste à l''Éternel.'),
(3416, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 13, 'OT', 'Son offrande sera de deux dixièmes d''épha de fleur de farine pétrie à l''huile, un sacrifice consumé par le feu à l''Éternel, une odeur agréable ; et sa libation sera du vin, un quart de hin.'),
(3417, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 14, 'OT', 'Vous ne mangerez ni pain, ni grain rôti, ni épis frais, jusqu''à ce même jour, jusqu''à ce que vous ayez apporté l''offrande de votre Dieu ; c''est une loi perpétuelle pour vos générations, dans toutes vos habitations.'),
(3418, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 15, 'OT', 'Et vous compterez pour vous, depuis le lendemain du sabbat, depuis le jour où vous apporterez la gerbe de l''offrande, sept sabbats complets ; ils seront.'),
(3419, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 16, 'OT', 'Jusqu''au lendemain du septième sabbat, vous compterez cinquante jours, et vous présenterez une offrande nouvelle à l''Éternel.'),
(3420, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 17, 'OT', 'De vos habitations vous apporterez un pain d''offrande, deux dixièmes d''épha ; ce sera de la fleur de farine, cuite avec du levain, comme premiers fruits à l''Éternel.'),
(3421, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 18, 'OT', 'Vous offrirez avec le pain sept agneaux sans défaut d''un an, un jeune taureau, et deux béliers ; ils seront un holocauste à l''Éternel, avec leur offrande et leurs libations, un sacrifice consumé par le feu, une odeur agréable à l''Éternel.'),
(3422, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 19, 'OT', 'Vous offrirez un bouc, un mâle parmi les chèvres, pour le péché, et deux agneaux d''un an, pour le sacrifice d''actions de grâces.'),
(3423, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 20, 'OT', 'Le sacrificateur les balancera en offrande balancée devant l''Éternel, avec le pain des premiers fruits et les deux agneaux ; ils seront saints pour l''Éternel, pour le sacrificateur.'),
(3424, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 21, 'OT', 'Et vous proclamerez en ce jour même : une sainte convocation sera pour vous ; vous ne ferez aucun ouvrage de service ; c''est une loi perpétuelle dans toutes vos habitations, pour vos générations.'),
(3425, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 22, 'OT', 'Et quand vous moissonnerez la moisson de votre terre, tu n''achèveras pas le côté de ton champ en le moissonnant, et tu ne glaneras pas le glanage de ta moisson ; tu les laisseras pour le pauvre et pour l''étranger. Je suis l''Éternel, votre Dieu.'),
(3426, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 23, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3427, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 24, 'OT', 'Parle aux fils d''Israël, en disant : Au septième mois, au premier jour du mois, il y aura pour vous un repos solennel, un mémorial de cri de guerre, une convocation sainte.'),
(3428, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 25, 'OT', 'Vous ne ferez aucun ouvrage de service, et vous offrirez un sacrifice consumé par le feu à l''Éternel.'),
(3429, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 26, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3430, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 27, 'OT', 'Mais le dixième jour de ce septième mois, c''est le jour de l''expiation ; ce sera pour vous une sainte convocation, et vous affligerez vos âmes, et vous offrirez un sacrifice consumé par le feu à l''Éternel.'),
(3431, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 28, 'OT', 'Vous ne ferez aucun ouvrage en ce jour même, car c''est un jour d''expiation, pour faire l''expiation pour vous devant l''Éternel, votre Dieu.'),
(3432, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 29, 'OT', 'Car toute âme qui ne s''humiliera pas en ce jour même sera retranchée de son peuple.'),
(3433, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 30, 'OT', 'Et toute âme qui fera tout ouvrage en ce jour même, je détruirai cette âme du milieu de son peuple.'),
(3434, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 31, 'OT', 'Vous ne ferez aucun ouvrage ; c''est une loi perpétuelle pour vos générations, dans toutes vos habitations.'),
(3435, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 32, 'OT', 'C''est un sabbat de repos solennel pour vous, et vous affligerez vos âmes ; le neuvième du mois, au soir, d''un soir à l''autre, vous observerez votre sabbat.'),
(3436, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 33, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3437, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 34, 'OT', 'Parle aux fils d''Israël, en disant : Le quinzième jour de ce septième mois, la fête des tabernacles sera pour l''Éternel, sept jours.'),
(3438, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 35, 'OT', 'Le premier jour, une sainte convocation : vous ne ferez aucun ouvrage de service.'),
(3439, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 36, 'OT', 'Pendant sept jours, vous offrirez un sacrifice consumé par le feu à l''Éternel ; le huitième jour, il y aura pour vous une convocation sainte, et vous offrirez un sacrifice consumé par le feu à l''Éternel ; c''est une assemblée solennelle ; vous ne ferez aucun ouvrage de service.'),
(3440, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 37, 'OT', 'Voici les assignations de l''Éternel, que vous proclamerez comme convocations saintes, pour offrir un sacrifice consumé par le feu à l''Éternel : un holocauste et une offrande, un sacrifice et des libations, la parole de chaque jour en son jour.'),
(3441, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 38, 'OT', 'Outre les sabbats de l''Éternel, et outre vos dons, et outre tous vos vœux, et outre toutes vos offrandes volontaires, que vous donnerez à l''Éternel.'),
(3442, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 39, 'OT', 'Mais le quinzième jour du septième mois, quand vous aurez recueilli le produit de la terre, vous célébrerez la fête de l''Éternel pendant sept jours ; le premier jour sera un repos solennel, et le huitième jour sera un repos solennel.'),
(3443, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 40, 'OT', 'Et vous prendrez pour vous, au premier jour, du fruit de l''arbre de beauté, des palmes de palmiers, et des branches d''arbres touffus, et des saules du torrent, et vous vous réjouirez devant la face de l''Éternel, votre Dieu, sept jours.'),
(3444, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 41, 'OT', 'Et vous célébrerez cela comme une fête pour l''Éternel, sept jours dans l''année ; c''est une loi perpétuelle pour vos générations ; au septième mois, vous célébrerez cela.'),
(3445, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 42, 'OT', 'Vous habiterez dans des tabernacles sept jours ; tout autochtone en Israël habitera dans des tabernacles.'),
(3446, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 43, 'OT', 'afin que vos générations sachent que j''ai fait habiter les fils d''Israël dans des tabernacles, quand je les ai fait sortir de la terre d''Égypte : je suis l''Éternel, votre Dieu.'),
(3447, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 23, 44, 'OT', 'Moïse parla des assignations de l''Éternel aux fils d''Israël.'),
(3448, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3449, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 2, 'OT', 'Ordonne aux fils d''Israël de t''apporter de l''huile d''olivier pure, battue, pour le luminaire, afin de faire monter une lampe continuellement.'),
(3450, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 3, 'OT', 'En dehors du voile du témoignage, dans la tente d''assignation, Aaron l''arrangera depuis le soir jusqu''au matin, devant la face de l''Éternel, continuellement ; c''est une loi perpétuelle pour vos générations.'),
(3451, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 4, 'OT', 'Sur le chandelier pur, il disposera les lampes devant la face de l''Éternel, continuellement, pour toujours.'),
(3452, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 5, 'OT', 'Tu prendras de la fleur de farine, et tu la cuiras en douze gâteaux ; chaque gâteau sera de deux dixièmes d''épha.'),
(3453, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 6, 'OT', 'Tu les placeras en deux rangs, six par pile, sur la table pure, devant la face de l''Éternel.'),
(3454, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 7, 'OT', 'Tu mettras sur la pile de l''encens pur, et cela sera pour le pain un mémorial, un sacrifice consumé par le feu à l''Éternel.'),
(3455, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 8, 'OT', 'Le jour du sabbat, le jour du sabbat, on le disposera devant la face de l''Éternel, continuellement, de la part des fils d''Israël, une alliance pour toujours.'),
(3456, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 9, 'OT', 'Ce sera pour Aaron et pour ses fils, et ils le mangeront dans un lieu saint, car c''est une chose très sainte pour lui, provenant des sacrifices consumés par le feu de l''Éternel : un statut perpétuel.'),
(3457, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 10, 'OT', 'Le fils d''une femme israélite, qui était fils d''un homme égyptien, sortit au milieu des fils d''Israël, et le fils de l''Israélite et un homme israélite se battirent dans le camp.'),
(3458, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 11, 'OT', 'Le fils de la femme israélite proféra le nom et maudit, et ils l''amenèrent à Moïse ; et le nom de sa mère était Schelomith, fille de Dibri, de la tribu de Dan.'),
(3459, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 12, 'OT', 'Et ils le mirent en garde, pour leur déclarer selon la bouche de l''Éternel.'),
(3460, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 13, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3461, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 14, 'OT', 'Fais sortir le blasphémateur dehors, hors du camp, et que tous ceux qui ont entendu posent leurs mains sur sa tête, et que toute l''assemblée le lapide.'),
(3462, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 15, 'OT', 'Et tu parleras aux fils d''Israël, en disant : Tout homme, chaque homme qui maudira son Dieu, portera son péché.'),
(3463, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 16, 'OT', 'Celui qui profane le nom de l''Éternel sera mis à mort ; toute l''assemblée le lapidera ; tant l''étranger que l''autochtone, lorsqu''il profane le nom, sera mis à mort.'),
(3464, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 17, 'OT', 'Et tout homme qui frappe mortellement une âme humaine sera mis à mort.'),
(3465, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 18, 'OT', 'Celui qui frappe une âme de bétail la paiera : âme pour âme.'),
(3466, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 19, 'OT', 'Et si un homme donne un défaut à son prochain, comme il a fait, ainsi lui sera fait.'),
(3467, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 20, 'OT', 'Ruine pour ruine, œil pour œil, dent pour dent ; comme il fait un défaut à un homme, ainsi il lui sera fait.'),
(3468, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 21, 'OT', 'Celui qui frappe du bétail en fera restitution, et celui qui frappe un homme sera mis à mort.'),
(3469, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 22, 'OT', 'Un même jugement sera pour vous, comme l''étranger, ainsi l''autochtone ; car je suis l''Éternel, votre Dieu.'),
(3470, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 24, 23, 'OT', 'Moïse parla aux fils d''Israël, et ils firent sortir le blasphémateur dehors, hors du camp, et ils le lapidèrent avec des pierres. Et les fils d''Israël firent comme l''Éternel l''avait commandé à Moïse.'),
(3471, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 1, 'OT', 'L''Éternel parla à Moïse sur la montagne de Sinaï, en disant :'),
(3472, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 2, 'OT', 'Parle aux fils d''Israël et dis-leur : Quand vous entrerez dans la terre que je vous donne, la terre observera un sabbat pour l''Éternel.'),
(3473, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 3, 'OT', 'Pendant six années tu ensemenceras ton champ, et pendant six années tu tailleras ta vigne, et tu recueilleras son produit.'),
(3474, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 4, 'OT', 'Et dans la septième année, il y aura un sabbat de repos solennel pour la terre, un sabbat pour l''Éternel : tu ne sèmeras pas ton champ, et tu ne tailleras pas ta vigne.'),
(3475, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 5, 'OT', 'Tu ne moissonneras point le produit du grain tombé de ta moisson, et tu ne cueilleras point le raisin de ton naziréen ; ce sera une année de repos solennel pour la terre.'),
(3476, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 6, 'OT', 'Le sabbat de la terre sera pour vous une nourriture : pour toi, pour ton serviteur, pour ta servante, pour ton ouvrier salarié et pour l''étranger qui réside avec toi.'),
(3477, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 7, 'OT', 'Et pour ton bétail et pour la vie qui est dans ta terre, tout son produit sera pour nourriture.'),
(3478, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 8, 'OT', 'Tu compteras pour toi sept sabbats d''années, sept années sept fois, et les jours des sept sabbats d''années seront pour toi quarante-neuf années.'),
(3479, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 9, 'OT', 'Tu feras passer la trompette au cri de guerre au septième mois, le dixième jour du mois, au jour de l''expiation ; vous ferez passer la trompette dans toute votre terre.'),
(3480, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 10, 'OT', 'Vous sanctifierez l''année de cinquante ans, et vous proclamerez la liberté dans la terre pour tous ses habitants ; ce sera pour vous un jubilé, et chacun de vous retournera à sa possession, et chacun de vous retournera à sa famille.'),
(3481, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 11, 'OT', 'Ce sera pour vous un jubilé, l''année de la cinquantième année ; vous ne sèmerez pas, vous ne moissonnerez pas son produit du grain tombé, et vous ne vendangerez pas ses naziréens.'),
(3482, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 12, 'OT', 'Car c''est un jubilé, cela sera saint pour vous ; vous mangerez son produit du champ.'),
(3483, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 13, 'OT', 'En cette année de jubilé, vous retournerez, chaque homme, à sa possession.'),
(3484, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 14, 'OT', 'Et si vous vendez une vente à votre prochain, ou si vous achetez de la main de votre prochain, qu''aucun homme ne trompe son frère.'),
(3485, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 15, 'OT', 'Selon le nombre d''années après le jubilé, tu achèteras de ton prochain ; selon le nombre des produits, il te vendra.'),
(3486, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 16, 'OT', 'Selon la bouche de la multitude des années, tu augmenteras son acquisition, et selon la bouche du peu des années, tu diminueras son acquisition, car c''est le nombre des produits qu''il te vend.'),
(3487, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 17, 'OT', 'Ne trompe point un homme son prochain, et tu craindras ton Dieu ; car je suis l''Éternel, votre Dieu.'),
(3488, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 18, 'OT', 'Vous pratiquerez mes lois, et vous garderez mes jugements et les accomplirez, et vous habiterez en sécurité sur la terre.'),
(3489, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 19, 'OT', 'La terre donnera son fruit, et vous mangerez à rassasiement, et vous habiterez en sécurité sur elle.'),
(3490, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 20, 'OT', 'Et si vous dites : « Que mangerons-nous en la septième année ? Voici, nous ne sèmerons pas et nous ne recueillerons pas notre produit, »'),
(3491, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 21, 'OT', 'Et je commanderai à ma bénédiction pour vous en la sixième année, et elle produira le produit pour trois années.'),
(3492, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 22, 'OT', 'Et vous sèmerez en la huitième année, et vous mangerez de l''ancien produit jusqu''à la neuvième année ; jusqu''à ce que vienne son produit, vous mangerez de l''ancien.'),
(3493, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 23, 'OT', 'La terre ne sera point vendue à perpétuité, car la terre est à moi ; car vous êtes des étrangers et des hôtes avec moi.'),
(3494, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 24, 'OT', 'Et dans toute la terre de votre possession, vous donnerez un rachat à la terre.'),
(3495, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 25, 'OT', 'Si ton frère devient pauvre et vend une partie de sa possession, alors son rédempteur, le plus proche de lui, viendra et rachètera ce que son frère a vendu.'),
(3496, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 26, 'OT', 'Et si un homme n''a point de rédempteur, mais que sa main atteigne et trouve la suffisance de son rachat,'),
(3497, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 27, 'OT', 'Il comptera les années de sa vente, et il restituera le surplus à l''homme à qui il l''avait vendu, puis il retournera à sa possession.'),
(3498, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 28, 'OT', 'Mais si sa main n''a pas trouvé de quoi lui rendre suffisance, sa vente restera en la main de celui qui l''a achetée jusqu''à l''année du jubilé ; et il sortira au jubilé, et il retournera à sa possession.'),
(3499, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 29, 'OT', 'Et si un homme vend une maison d''habitation dans une ville entourée de murailles, son rachat sera jusqu''à la fin de l''année de sa vente ; pendant des jours son rachat sera.'),
(3500, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 30, 'OT', 'Et si elle n''est pas rachetée jusqu''à ce qu''une année entière lui soit accomplie, alors la maison qui est dans la ville qui a une muraille sera à perpétuité pour celui qui l''a achetée, pour ses générations ; elle ne sortira pas au jubilé.'),
(3501, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 31, 'OT', 'Les maisons des parvis qui n''ont point de muraille à l''alentour seront comptées comme le champ de la terre ; le rachat lui appartiendra, et au jubilé elle sortira.'),
(3502, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 32, 'OT', 'Les villes des Lévites, les maisons des villes de leur possession, seront un rachat perpétuel pour les Lévites.'),
(3503, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 33, 'OT', 'Et celui qui rachète d''entre les Lévites, la vente d''une maison et d''une ville de sa possession sortira au jubilé, car les maisons des villes des Lévites sont leur possession au milieu des fils d''Israël.'),
(3504, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 34, 'OT', 'Le champ de la banlieue de leurs villes ne sera pas vendu, car c''est pour eux une possession pour toujours.'),
(3505, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 35, 'OT', 'Si ton frère devient pauvre et que sa main chancelle auprès de toi, tu le soutiendras, comme étranger et comme résident étranger, et il vivra avec toi.'),
(3506, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 36, 'OT', 'Ne prends de lui ni usure ni usure, et crains ton Dieu, afin que ton frère vive avec toi.'),
(3507, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 37, 'OT', 'Tu ne lui donneras point ton argent à usure, et tu ne donneras point ta nourriture à plus grande partie.'),
(3508, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 38, 'OT', 'Je suis l''Éternel, votre Dieu, qui vous ai fait sortir de la terre d''Égypte pour vous donner la terre de Canaan, afin d''être pour vous un Dieu.'),
(3509, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 39, 'OT', 'Si ton frère devient pauvre auprès de toi et se vend à toi, tu ne lui imposeras pas un service de serviteur.'),
(3510, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 40, 'OT', 'Comme un salarié, comme un étranger, il sera avec toi ; jusqu''à l''année du jubilé, il servira avec toi.'),
(3511, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 41, 'OT', 'Il sortira de chez toi, lui et ses fils avec lui, et il retournera à sa famille et à la possession de ses pères il reviendra.'),
(3512, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 42, 'OT', 'Car ils sont mes serviteurs, que j''ai fait sortir de la terre d''Égypte ; ils ne seront pas vendus d''une vente de serviteur.'),
(3513, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 43, 'OT', 'Tu ne domineras pas sur lui avec dureté, et tu craindras ton Dieu.'),
(3514, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 44, 'OT', 'Tes serviteurs et tes servantes qui seront à toi, des nations qui sont autour de vous, c''est d''eux que vous achèterez serviteur et servante.'),
(3515, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 45, 'OT', 'Et même des fils des étrangers qui demeurent avec vous, vous en achèterez, et de leur famille qui est avec vous, qu''ils ont engendrée dans votre terre, et ils seront pour vous une possession.'),
(3516, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 46, 'OT', 'Vous les laisserez en héritage à vos fils après vous, comme une possession pour toujours ; c''est sur eux que vous travaillerez. Mais sur vos frères, les fils d''Israël, un homme ne dominera pas sur son frère avec dureté.'),
(3517, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 47, 'OT', 'Si la main d''un étranger ou d''un résident parmi toi s''enrichit, et que ton frère s''appauvrisse auprès de lui, et qu''il se vende à l''étranger résident parmi toi, ou à la famille de la famille d''un étranger,'),
(3518, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 48, 'OT', 'Après qu''il aura été vendu, le rachat lui appartiendra ; un de ses frères le rachètera.'),
(3519, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 49, 'OT', 'Ou son bien-aimé, ou un fils de son bien-aimé le rachètera ; ou quelqu''un de sa chair, de sa famille, le rachètera ; ou si sa main atteint, il sera racheté.'),
(3520, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 50, 'OT', 'Il comptera avec celui qui l''a acheté, depuis l''année de sa vente à lui jusqu''à l''année du jubilé ; et l''argent de sa vente sera selon le nombre des années, comme les jours d''un ouvrier salarié il sera avec lui.'),
(3521, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 51, 'OT', 'S''il reste encore beaucoup d''années, selon leur bouche il rendra son rachat, de l''argent de son acquisition.'),
(3522, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 52, 'OT', 'Et s''il ne reste que peu d''années jusqu''à l''année du jubilé, il fera le compte avec lui ; selon ses années, il rendra son rachat.'),
(3523, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 53, 'OT', 'Comme un ouvrier à l''année, d''année en année, il sera avec lui ; tu ne le domineras pas avec dureté sous tes yeux.'),
(3524, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 54, 'OT', 'Et s''il n''est pas racheté par ces moyens, il sortira dans l''année du jubilé, lui et ses fils avec lui.'),
(3525, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 25, 55, 'OT', 'Car les fils d''Israël sont mes serviteurs ; ils sont mes serviteurs, que j''ai fait sortir de la terre d''Égypte. Je suis l''Éternel, votre Dieu.'),
(3526, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 1, 'OT', 'Vous ne vous ferez point d''idoles, ni d''idole taillée, ni de monument dressé ; vous ne placerez point dans votre terre de pierre ornée d''images pour vous prosterner dessus ; car je suis l''Éternel, votre Dieu.'),
(3527, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 2, 'OT', 'Vous garderez mes sabbats et vous révérerez mon sanctuaire. Je suis l''Éternel.'),
(3528, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 3, 'OT', 'Si vous marchez dans mes lois, et si vous gardez mes commandements et les mettez en pratique,'),
(3529, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 4, 'OT', 'Je donnerai vos pluies en leur temps, et la terre donnera son produit, et le bois du champ donnera son fruit.'),
(3530, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 5, 'OT', 'Le battage vous atteindra jusqu''à la vendange, et la vendange atteindra la postérité, et vous mangerez votre pain à rassasiement, et vous habiterez en sécurité dans votre terre.'),
(3531, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 6, 'OT', 'Je donnerai la paix dans le pays, et vous vous coucherez sans que personne ne vous effraie ; je ferai disparaître du pays les bêtes nuisibles, et l''épée ne passera point dans votre terre.'),
(3532, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 7, 'OT', 'Vous poursuivrez vos ennemis, et ils tomberont devant votre face par l''épée.'),
(3533, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 8, 'OT', 'Cinq d''entre vous poursuivront cent, et cent d''entre vous poursuivront dix mille, et vos ennemis tomberont devant vous par l''épée.'),
(3534, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 9, 'OT', 'Je me tournerai vers vous, je vous rendrai féconds et je vous multiplierai, et j''établirai mon alliance avec vous.'),
(3535, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 10, 'OT', 'Vous mangerez le vieux grain conservé, et vous sortirez le vieux devant la face du nouveau.'),
(3536, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 11, 'OT', 'Je mettrai mon tabernacle au milieu de vous, et mon âme ne vous aura pas en dégoût.'),
(3537, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 12, 'OT', 'Je marcherai au milieu de vous, je serai pour vous un Dieu, et vous, vous serez pour moi un peuple.'),
(3538, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 13, 'OT', 'Je suis l''Éternel, votre Dieu, qui vous ai fait sortir de la terre d''Égypte, pour que vous ne soyez plus leurs serviteurs ; j''ai brisé les barres de votre joug et je vous ai fait marcher la tête haute.'),
(3539, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 14, 'OT', 'Mais si vous ne m''écoutez pas et ne faites pas tous ces commandements,'),
(3540, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 15, 'OT', 'Mais si vous méprisez mes lois, et si votre âme rejette mes jugements, au point de ne pas faire tous mes commandements, en violant mon alliance,'),
(3541, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 16, 'OT', 'Moi aussi, je ferai ceci contre vous : je ferai venir sur vous la terreur, la consomption et la fièvre, qui consumeront les yeux et feront languir l''âme ; vous sèmerez votre postérité en vanité, et vos ennemis la mangeront.'),
(3542, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 17, 'OT', 'Je tournerai ma face contre vous, et vous serez frappés devant vos ennemis ; ceux qui vous haïssent domineront sur vous, et vous fuirez sans que personne vous poursuive.'),
(3543, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 18, 'OT', 'Et si, malgré cela, vous ne m''écoutez pas, je vous châtierai sept fois davantage pour vos péchés.'),
(3544, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 19, 'OT', 'Je briserai l''orgueil de votre force, et je ferai vos cieux comme du fer, et votre terre comme de l''airain.'),
(3545, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 20, 'OT', 'Votre force s''épuisera en vanité, votre terre ne donnera pas son produit, et le bois de la terre ne donnera pas son fruit.'),
(3546, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 21, 'OT', 'Et si vous marchez avec moi en opposition, et que vous ne vouliez pas m''écouter, j''ajouterai sur vous une plaie septuple, selon vos péchés.'),
(3547, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 22, 'OT', 'J''enverrai contre vous les bêtes sauvages des champs, qui vous priveront de vos enfants, détruiront votre bétail, et vous réduiront à un petit nombre, et vos chemins seront désolés.'),
(3548, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 23, 'OT', 'Mais si, par ces choses, vous n''êtes pas corrigés par moi, et que vous marchiez avec moi en opposition.'),
(3549, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 24, 'OT', 'Et je marcherai aussi, moi, avec vous en opposition, et je vous frapperai, moi aussi, sept fois pour vos péchés.'),
(3550, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 25, 'OT', 'Je ferai venir sur vous l''épée, vengeant la vengeance de l''alliance ; vous serez rassemblés dans vos villes, et j''enverrai la peste au milieu de vous, et vous serez livrés en la main de l''ennemi.'),
(3551, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 26, 'OT', 'Quand je briserai pour vous le bâton de pain, dix femmes cuiront votre pain dans un seul four, et elles rendront votre pain au poids, et vous mangerez, et vous ne serez pas rassasiés.'),
(3552, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 27, 'OT', 'Et si, malgré cela, vous ne m''écoutez pas, et que vous marchiez avec moi en opposition,'),
(3553, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 28, 'OT', 'Je marcherai avec vous dans la fureur de l''opposition, et je vous châtierai, moi aussi, sept fois pour vos péchés.'),
(3554, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 29, 'OT', 'Vous mangerez la chair de vos fils, et la chair de vos filles vous mangerez.'),
(3555, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 30, 'OT', 'Je détruirai vos hauts lieux, je retrancherai vos idoles, je mettrai vos cadavres sur les cadavres de vos idoles, et mon âme vous aura en horreur.'),
(3556, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 31, 'OT', 'Je ferai de vos villes une ruine, je dévasterai vos sanctuaires, et je ne respirerai plus l''odeur de vos agréables odeurs.'),
(3557, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 32, 'OT', 'Et moi, je dévasterai la terre, et vos ennemis qui y habitent seront consternés à son sujet.'),
(3558, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 33, 'OT', 'Je vous disperserai parmi les nations, et je tirerai l''épée après vous ; votre terre deviendra un désert, et vos villes seront une ruine.'),
(3559, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 34, 'OT', 'Alors la terre jouira de ses sabbats tous les jours de sa désolation, tandis que vous serez dans la terre de vos ennemis ; alors la terre se reposera et jouira de ses sabbats.'),
(3560, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 35, 'OT', 'Tous les jours de sa désolation elle se reposera, ce qu''elle n''a pas reposé durant vos sabbats, lorsque vous habitiez sur elle.'),
(3561, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 36, 'OT', 'Et ceux d''entre vous qui resteront, je ferai venir la faiblesse dans leur cœur dans les terres de leurs ennemis ; la voix d''une feuille chassée les poursuivra, et ils fuiront d''une fuite d''épée, et ils tomberont sans qu''il y ait de poursuivant.'),
(3562, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 37, 'OT', 'Chaque homme trébuchera contre son frère, comme devant une épée, sans que personne ne poursuive, et vous n''aurez aucune force de vous tenir devant vos ennemis.'),
(3563, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 38, 'OT', 'Vous périrez parmi les nations, et la terre de vos ennemis vous dévorera.'),
(3564, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 39, 'OT', 'Et ceux d''entre vous qui resteront se consumeront dans leur iniquité, dans les terres de vos ennemis ; et même dans les iniquités de leurs pères, avec eux, ils se consumeront.'),
(3565, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 40, 'OT', 'Ils confesseront leur iniquité et l''iniquité de leurs pères, dans leur perfidie qu''ils ont commise contre moi, et aussi pour avoir marché avec moi en opposition.'),
(3566, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 41, 'OT', 'Moi aussi, je marcherai avec eux en opposition, et je les amènerai dans la terre de leurs ennemis ; alors leur cœur incirconcis s''humiliera, et alors ils accepteront leur iniquité.'),
(3567, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 42, 'OT', 'Je me souviendrai de mon alliance avec Jacob, et aussi de mon alliance avec Isaac, et aussi de mon alliance avec Abraham je me souviendrai, et de la terre je me souviendrai.'),
(3568, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 43, 'OT', 'La terre sera abandonnée par eux, et elle jouira de ses sabbats dans sa désolation, loin d''eux ; et eux, ils porteront leur iniquité, parce qu''ils ont méprisé mes jugements, et que leur âme a abhorré mes lois.'),
(3569, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 44, 'OT', 'Et même alors, lorsqu''ils seront dans la terre de leurs ennemis, je ne les rejetterai pas et je ne les aurai pas en horreur pour les détruire, pour rompre mon alliance avec eux ; car je suis l''Éternel, leur Dieu.'),
(3570, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 45, 'OT', 'Et je me souviendrai pour eux de l''alliance des premiers, par laquelle je les ai fait sortir de la terre d''Égypte aux yeux des nations, pour être leur Dieu : moi, l''Éternel.'),
(3571, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 26, 46, 'OT', 'Voici les statuts, les jugements et les lois que l''Éternel donna entre lui et les fils d''Israël, sur la montagne de Sinaï, par la main de Moïse.'),
(3572, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3573, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 2, 'OT', 'Parle aux fils d''Israël et dis-leur : lorsqu''un homme fera un vœu, selon ton estimation des âmes, à l''Éternel.'),
(3574, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 3, 'OT', 'Ton estimation sera pour un mâle, depuis l''âge de vingt ans jusqu''à l''âge de soixante ans ; et ton estimation sera de cinquante sicles d''argent, selon le sicle du sanctuaire.'),
(3575, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 4, 'OT', 'Et si c''est une femelle, ton estimation sera de trente sicles.'),
(3576, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 5, 'OT', 'Et si c''est depuis l''âge de cinq ans jusqu''à vingt ans, ton estimation sera pour le mâle vingt sicles, et pour la femelle dix sicles.'),
(3577, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 6, 'OT', 'Et si c''est depuis l''âge d''un mois jusqu''à cinq ans, alors ton estimation pour le mâle sera de cinq sicles d''argent, et pour la femelle ton estimation sera de trois sicles d''argent.'),
(3578, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 7, 'OT', 'Et si c''est de soixante ans et au-dessus, si c''est un mâle, ton estimation sera de quinze sicles, et pour la femelle, dix sicles.'),
(3579, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 8, 'OT', 'S''il est trop pauvre pour ton estimation, on le présentera devant le sacrificateur, et le sacrificateur fera son estimation ; selon ce que peut atteindre la main de celui qui a fait le vœu, le sacrificateur l''estimera.'),
(3580, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 9, 'OT', 'Et si c''est du bétail dont on présente une offrande à l''Éternel, tout ce qu''on en donnera à l''Éternel sera saint.'),
(3581, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 10, 'OT', 'Il ne l''échangera point, et ne le remplacera point, bon par mauvais, ou mauvais par bon ; et s''il remplace bétail par bétail, alors lui et son échange seront saints.'),
(3582, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 11, 'OT', 'Et si c''est tout bétail impur, dont on ne présente pas d''offrande à l''Éternel, il placera le bétail devant la face du sacrificateur.'),
(3583, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 12, 'OT', 'Le sacrificateur en fera l''estimation, entre bon et mauvais ; selon ton estimation, ô sacrificateur, ainsi en sera-t-il.'),
(3584, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 13, 'OT', 'Et s''il est racheté par un racheteur, il ajoutera son cinquième à ton estimation.'),
(3585, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 14, 'OT', 'Si un homme consacre sa maison comme sainte à l''Éternel, le sacrificateur l''estimera, qu''elle soit bonne ou mauvaise ; comme le sacrificateur l''estimera, ainsi elle restera.'),
(3586, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 15, 'OT', 'Mais si celui qui consacre rachète sa maison, il ajoutera un cinquième de l''argent de ton estimation sur elle, et elle sera à lui.'),
(3587, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 16, 'OT', 'Si un homme consacre à l''Éternel une partie du champ de sa possession, ton estimation sera selon sa postérité : une postérité d''un argile d''orge, à cinquante sicles d''argent, selon la bouche.'),
(3588, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 17, 'OT', 'S''il sanctifie son champ dès l''année du jubilé, il sera établi selon ton estimation.'),
(3589, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 18, 'OT', 'Mais si c''est après le jubilé qu''il consacre son champ, le sacrificateur lui comptera l''argent selon la bouche des années qui restent jusqu''à l''année du jubilé, et il sera retranché de ton estimation.'),
(3590, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 19, 'OT', 'Et si celui qui a consacré le champ le rachète, il ajoutera un cinquième de l''argent de ton estimation par-dessus, et il lui appartiendra.'),
(3591, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 20, 'OT', 'Et s''il ne rachète pas le champ, et s''il vend le champ à un autre homme, il ne sera plus racheté.'),
(3592, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 21, 'OT', 'Et le champ, lorsqu''il sortira au jubilé, sera saint à l''Éternel, comme le champ de l''interdit ; la possession en appartiendra au sacrificateur.'),
(3593, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 22, 'OT', 'Et s''il consacre à l''Éternel le champ de son acquisition, qui n''est pas du champ de sa possession,'),
(3594, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 23, 'OT', 'Le sacrificateur lui comptera l''estimation de ton estimation jusqu''à l''année du jubilé, et il donnera ton estimation en ce jour-là comme chose sainte à l''Éternel.'),
(3595, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 24, 'OT', 'À l''année du jubilé, le champ retournera à celui qui l''avait acheté de lui, à celui à qui appartient la possession de la terre.'),
(3596, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 25, 'OT', 'Toute ton estimation sera selon le sicle du sanctuaire : vingt guéras seront le sicle.'),
(3597, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 26, 'OT', 'Toutefois, le premier-né qui doit être consacré à l''Éternel parmi le bétail, nul homme ne le sanctifiera ; si c''est un bœuf ou si c''est un agneau, il appartient à l''Éternel.'),
(3598, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 27, 'OT', 'Et si c''est du bétail impur, il le rachètera selon ton estimation, et il y ajoutera son cinquième ; et s''il n''est pas racheté, il sera vendu selon ton estimation.'),
(3599, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 28, 'OT', 'Toutefois, tout interdit qu''un homme consacrera à l''Éternel, de tout ce qui lui appartient, d''homme et de bétail et du champ de sa possession, ne sera ni vendu ni racheté ; tout interdit est très saint à l''Éternel.'),
(3600, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 29, 'OT', 'Tout interdit qui sera voué à l''Éternel parmi les hommes ne sera point racheté ; il sera mis à mort.'),
(3601, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 30, 'OT', 'Et toute dîme de la terre, de la postérité de la terre et du fruit du bois, appartient à l''Éternel ; c''est une chose sainte pour l''Éternel.'),
(3602, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 31, 'OT', 'Et si un homme rachète quelque chose de sa dîme, il y ajoutera son cinquième.'),
(3603, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 32, 'OT', 'Et toute dîme de bœuf et de brebis, tout ce qui passe sous la tribu, le dixième sera saint à l''Éternel.'),
(3604, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 33, 'OT', 'Il ne fera pas de distinction entre le bon et le mauvais, et il ne l''échangera pas ; et s''il l''échange, lui et son échange seront saints, il ne sera pas racheté.'),
(3605, 3, 'GOI_Fr', 'GOI_Fr', 'fr', 'LEV', 27, 34, 'OT', 'Voici les commandements que l''Éternel donna à Moïse pour les fils d''Israël, sur la montagne de Sinaï.'),
(3606, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 1, 'OT', 'L''Éternel parla à Moïse dans le désert de Sinaï, dans la tente d''assignation, le premier jour du second mois, en la seconde année de leur sortie de la terre d''Égypte, en disant :'),
(3607, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 2, 'OT', 'Faites le dénombrement de toute l''assemblée des fils d''Israël, selon leurs familles, selon la maison de leurs pères, en comptant les noms, tout mâle par leurs têtes.'),
(3608, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 3, 'OT', 'Depuis l''âge de vingt ans et au-dessus, tout homme apte à sortir en armée en Israël, vous les recenserez selon leurs armées, toi et Aaron.'),
(3609, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 4, 'OT', 'Et avec vous seront des hommes, un homme par tribu, un homme qui est tête de la maison de ses pères.'),
(3610, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 5, 'OT', 'Et voici les noms des hommes qui se tiendront avec vous : pour Ruben, Élitsur, fils de Schedéur.'),
(3611, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 6, 'OT', 'Pour Siméon, Schelumiel, fils de Tsurischaddaï.'),
(3612, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 7, 'OT', 'Pour Juda : Nachschon, fils d''Amminadab.'),
(3613, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 8, 'OT', 'Pour Issacar : Nethaneel, fils de Tsuar.'),
(3614, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 9, 'OT', 'Pour Zabulon : Éliab, fils d''Hélon.'),
(3615, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 10, 'OT', 'Pour les fils de Joseph : pour Éphraïm, Élischama, fils d''Ammihud ; pour Manassé, Gamliel, fils de Pedahtsur.'),
(3616, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 11, 'OT', 'Pour Benjamin : Abidan, fils de Guideoni.'),
(3617, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 12, 'OT', 'Pour Dan : Ahiézer, fils d''Ammischaddaï.'),
(3618, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 13, 'OT', 'Pour Aser, Paguiel, fils d''Ocran.'),
(3619, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 14, 'OT', 'Pour Gad, Éliasaph, fils de Déuel.'),
(3620, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 15, 'OT', 'De Nephthali, Ahira fils d''Énan.'),
(3621, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 16, 'OT', 'Ce sont ceux de l''assemblée, les princes des tribus de leurs pères, les têtes des milliers d''Israël.'),
(3622, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 17, 'OT', 'Moïse et Aaron prirent ces hommes qui avaient été désignés par leurs noms.'),
(3623, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 18, 'OT', 'Et ils assemblèrent toute l''assemblée le premier jour du second mois, et ils se firent enregistrer selon leurs familles, selon la maison de leurs pères, par le nombre des noms, depuis l''âge de vingt ans et au-dessus, par leurs têtes.'),
(3624, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 19, 'OT', 'Comme l''Éternel l''avait commandé à Moïse, il les dénombra dans le désert de Sinaï.'),
(3625, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 20, 'OT', 'Les fils de Ruben, premier-né d''Israël, leurs générations selon leurs familles, selon la maison de leurs pères, selon le nombre des noms, par leurs têtes, tout mâle depuis l''âge de vingt ans et au-dessus, tout homme sortant en armée.'),
(3626, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 21, 'OT', 'Leurs recensés, pour la tribu de Ruben, furent quarante-six mille cinq cents.'),
(3627, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 22, 'OT', 'Pour les fils de Siméon, selon leurs générations, par leurs familles, par la maison de leurs pères, ses dénombrés, selon le nombre des noms, par leurs têtes, tout mâle depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3628, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 23, 'OT', 'Leurs recensés, selon la tribu de Siméon : cinquante-neuf mille trois cents.'),
(3629, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 24, 'OT', 'Pour les fils de Gad, leurs générations selon leurs familles, selon la maison de leurs pères, selon le nombre des noms, depuis l''âge de vingt ans et au-dessus, tout homme qui sort à l''armée.'),
(3630, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 25, 'OT', 'Leurs recensés, pour la tribu de Gad : quarante-cinq mille six cent cinquante.'),
(3631, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 26, 'OT', 'Pour les fils de Juda, selon leurs générations, selon leurs familles, selon la maison de leurs pères, selon le nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3632, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 27, 'OT', 'Leurs recensés, de la tribu de Juda, étaient soixante-quatorze mille six cents.'),
(3633, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 28, 'OT', 'Pour les fils d''Issacar, selon leurs générations, selon leurs familles, selon la maison de leurs pères, selon le nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortaient pour l''armée.'),
(3634, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 29, 'OT', 'Leurs recensés, selon la tribu d''Issacar : cinquante-quatre mille quatre cents.'),
(3635, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 30, 'OT', 'Pour les fils de Zabulon, leurs générations selon leurs familles, selon la maison de leurs pères, selon le nombre des noms, depuis l''âge de vingt ans et au-dessus, tout homme qui sort à l''armée.'),
(3636, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 31, 'OT', 'Leurs recensés, selon la tribu de Zabulon : cinquante-sept mille quatre cents.'),
(3637, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 32, 'OT', 'Pour les fils de Joseph, pour les fils d''Éphraïm, leurs générations selon leurs familles, selon la maison de leurs pères, au nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3638, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 33, 'OT', 'Leurs recensés, selon la tribu d''Éphraïm : quarante mille cinq cents.'),
(3639, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 34, 'OT', 'Pour les fils de Manassé, selon leurs générations, selon leurs familles, selon la maison de leurs pères, au nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3640, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 35, 'OT', 'Leurs recensés, selon la tribu de Manassé : trente-deux mille deux cents.'),
(3641, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 36, 'OT', 'Pour les fils de Benjamin, selon leurs générations, par leurs familles, par la maison de leurs pères, selon le nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3642, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 37, 'OT', 'Leurs recensés, de la tribu de Benjamin : trente-cinq mille quatre cents.'),
(3643, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 38, 'OT', 'Pour les fils de Dan, selon leurs générations, par leurs familles, selon la maison de leurs pères, par le nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3644, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 39, 'OT', 'Leurs recensés, selon la tribu de Dan : soixante-deux mille sept cents.'),
(3645, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 40, 'OT', 'Pour les fils d''Aser, leurs générations selon leurs familles, selon la maison de leurs pères, selon le nombre des noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortaient pour l''armée.'),
(3646, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 41, 'OT', 'Leurs recensés, selon la tribu d''Aser : quarante et un mille cinq cents.'),
(3647, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 42, 'OT', 'Les fils de Nephthali, selon leurs générations, par leurs familles, selon la maison de leurs pères, en nombre de noms, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortent pour l''armée.'),
(3648, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 43, 'OT', 'Leurs recensés, selon la tribu de Nephthali : cinquante-trois mille quatre cents.'),
(3649, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 44, 'OT', 'Voici ceux qui furent recensés, que Moïse et Aaron et les princes d''Israël recensèrent : douze hommes, un homme pour chaque maison de ses pères.'),
(3650, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 45, 'OT', 'Tous les recensés des fils d''Israël, selon leur maison de leurs pères, depuis l''âge de vingt ans et au-dessus, tous ceux qui sortaient en armée en Israël, furent donc.'),
(3651, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 46, 'OT', 'Tous les recensés furent six cent trois mille cinq cent cinquante.'),
(3652, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 47, 'OT', 'Les Lévites, selon la tribu de leurs pères, ne furent pas comptés au milieu d''eux.'),
(3653, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 48, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3654, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 49, 'OT', 'Seulement la tribu de Lévi tu ne recenseras point, et leur tête tu ne lèveras point au milieu des fils d''Israël.'),
(3655, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 50, 'OT', 'Toi donc, établis les Lévites sur le tabernacle du témoignage, sur tous ses ustensiles et sur tout ce qui lui appartient : eux porteront le tabernacle et tous ses ustensiles, et eux le serviront, et ils camperont à l''alentour du tabernacle.'),
(3656, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 51, 'OT', 'Quand le tabernacle partira, les Lévites le démonteront, et quand le tabernacle campera, les Lévites le monteront ; et l''étranger qui s''approchera sera mis à mort.'),
(3657, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 52, 'OT', 'Les fils d''Israël camperont, chacun près de son camp et chacun près de sa bannière, selon leurs armées.'),
(3658, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 53, 'OT', 'Les Lévites camperont alentour du tabernacle du témoignage, afin qu''il n''y ait point de colère sur l''assemblée des fils d''Israël, et les Lévites garderont l''observance du tabernacle du témoignage.'),
(3659, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 1, 54, 'OT', 'Les fils d''Israël firent selon tout ce que l''Éternel avait commandé à Moïse ; ainsi firent-ils.'),
(3660, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 1, 'OT', 'L''Éternel parla à Moïse et à Aaron, en disant :'),
(3661, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 2, 'OT', 'Chaque homme campera près de sa bannière, selon les signes de la maison de ses pères ; les fils d''Israël camperont en face, tout alentour de la tente d''assignation, ils camperont.'),
(3662, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 3, 'OT', 'Ceux qui campent à l''orient, vers le levant, la bannière du camp de Juda, selon leurs armées ; et le prince des fils de Juda : Nachschon, fils d''Amminadab.'),
(3663, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 4, 'OT', 'Et son armée, et leurs recensés : soixante-quatorze mille six cents.'),
(3664, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 5, 'OT', 'Et ceux qui campaient auprès de lui étaient la tribu d''Issacar ; et le prince des fils d''Issacar était Nethaneel, fils de Tsuar.'),
(3665, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 6, 'OT', 'et son armée et ses recensés : cinquante-quatre mille quatre cents.'),
(3666, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 7, 'OT', 'La tribu de Zabulon, et le prince des fils de Zabulon, Éliab, fils de Hélon.'),
(3667, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 8, 'OT', 'et son armée, et ses recensés : cinquante-sept mille quatre cents.'),
(3668, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 9, 'OT', 'Tous les recensés du camp de Juda, cent quatre-vingt-six mille quatre cents, selon leurs armées, partiront les premiers.'),
(3669, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 10, 'OT', 'La bannière du camp de Ruben, vers le midi, selon leurs armées ; et le prince des fils de Ruben, Élitsur, fils de Schedéur.'),
(3670, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 11, 'OT', 'Et son armée, et ses recensés : quarante-six mille cinq cents.'),
(3671, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 12, 'OT', 'Et ceux qui campent auprès de lui, la tribu de Siméon ; et le prince des fils de Siméon, Schelumiel, fils de Tsurischaddaï.'),
(3672, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 13, 'OT', 'Et son armée, et leurs recensés : cinquante-neuf mille trois cents.'),
(3673, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 14, 'OT', 'Et la tribu de Gad, et le prince des fils de Gad, Éliasaph, fils de Réuel.'),
(3674, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 15, 'OT', 'Son armée et ses recensés, quarante-cinq mille six cent cinquante.'),
(3675, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 16, 'OT', 'Tous les recensés du camp de Ruben, cent cinquante et un mille quatre cent cinquante, selon leurs armées, partiront en second.'),
(3676, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 17, 'OT', 'La tente d''assignation partira, avec le camp des Lévites au milieu des camps ; comme ils campent, ainsi ils partiront, chaque homme à sa main, selon leurs bannières.'),
(3677, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 18, 'OT', 'La bannière du camp d''Éphraïm, selon leurs armées, vers la mer ; et le prince des fils d''Éphraïm, Élischama, fils d''Ammihud.'),
(3678, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 19, 'OT', 'et son armée et leurs recensés : quarante mille cinq cents.'),
(3679, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 20, 'OT', 'Auprès de lui, la tribu de Manassé ; et le prince des fils de Manassé, Gamliel, fils de Pedahtsur.'),
(3680, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 21, 'OT', 'Et son armée, et leurs recensés : trente-deux mille deux cents.'),
(3681, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 22, 'OT', 'Et la tribu de Benjamin ; et le prince des fils de Benjamin, Abidan, fils de Guideoni.'),
(3682, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 23, 'OT', 'et son armée, et leurs dénombrés, trente-cinq mille quatre cents.'),
(3683, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 24, 'OT', 'Tous les recensés du camp d''Éphraïm : cent huit mille cent, selon leurs armées ; et ils partiront en troisième.'),
(3684, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 25, 'OT', 'La bannière du camp de Dan, au nord, selon leurs armées ; et le prince des fils de Dan, Ahiézer, fils d''Ammischaddaï.'),
(3685, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 26, 'OT', 'Et son armée, et ceux qui en étaient dénombrés : soixante-deux mille sept cents.'),
(3686, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 27, 'OT', 'Et ceux qui campent auprès de lui, la tribu d''Aser ; et le prince des fils d''Aser, Paguiel, fils d''Ocran.'),
(3687, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 28, 'OT', 'Son armée et leurs recensés : quarante et un mille cinq cents.'),
(3688, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 29, 'OT', 'Et la tribu de Nephthali, et le prince des fils de Nephthali, Ahira, fils d''Énan.'),
(3689, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 30, 'OT', 'et son armée, et leurs dénombrés : cinquante-trois mille quatre cents.'),
(3690, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 31, 'OT', 'Tous les recensés du camp de Dan : cent cinquante-sept mille six cents ; ils partiront les derniers, selon leurs bannières.'),
(3691, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 32, 'OT', 'Voici les recensements des fils d''Israël, selon leur maison de leurs pères : tous les recensements des camps, selon leurs armées, six cent trois mille cinq cent cinquante.'),
(3692, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 33, 'OT', 'Les Lévites ne furent pas recensés au milieu des fils d''Israël, comme l''Éternel l''avait commandé à Moïse.'),
(3693, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 2, 34, 'OT', 'Les fils d''Israël firent selon tout ce que l''Éternel avait commandé à Moïse : ainsi ils campèrent selon leurs bannières, et ainsi ils partirent, chaque homme selon sa famille, selon la maison de ses pères.'),
(3694, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 1, 'OT', 'Voici les générations d''Aaron et de Moïse, au jour où l''Éternel parla à Moïse sur la montagne de Sinaï.'),
(3695, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 2, 'OT', 'Voici les noms des fils d''Aaron : le premier-né, Nadab ; et Abihu, Éléazar et Ithamar.'),
(3696, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 3, 'OT', 'Voici les noms des fils d''Aaron, les sacrificateurs oints, dont les mains ont été remplies pour exercer la sacrificature.'),
(3697, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 4, 'OT', 'Nadab et Abihu moururent devant l''Éternel, lorsqu''ils offrirent un feu étranger devant l''Éternel dans le désert de Sinaï, et ils n''eurent point de fils ; et Éléazar et Ithamar exercèrent le sacerdoce devant Aaron, leur père.'),
(3698, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 5, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3699, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 6, 'OT', 'Fais approcher la tribu de Lévi, et tu la placeras devant la face d''Aaron, le sacrificateur, et ils le serviront.'),
(3700, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 7, 'OT', 'Ils garderont son observance et l''observance de toute l''assemblée, devant la face de la tente d''assignation, pour accomplir le service du tabernacle.'),
(3701, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 8, 'OT', 'Ils garderont tous les ustensiles de la tente d''assignation et l''observance des fils d''Israël, pour accomplir le service du tabernacle.'),
(3702, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 9, 'OT', 'Tu donneras les Lévites à Aaron et à ses fils ; ils lui sont entièrement donnés, de la part des fils d''Israël.'),
(3703, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 10, 'OT', 'Tu établiras Aaron et ses fils, et ils garderont leur sacerdoce ; mais l''étranger qui s''approchera sera mis à mort.'),
(3704, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 11, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3705, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 12, 'OT', 'Et moi, voici, j''ai pris les Lévites du milieu des fils d''Israël, à la place de tout premier-né qui ouvre la matrice parmi les fils d''Israël ; et les Lévites seront à moi.'),
(3706, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 13, 'OT', 'Car tout premier-né m''appartient : au jour où j''ai frappé tout premier-né dans la terre d''Égypte, j''ai consacré pour moi tout premier-né en Israël, depuis l''homme jusqu''au bétail ; ils seront à moi. Je suis l''Éternel.'),
(3707, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 14, 'OT', 'L''Éternel parla à Moïse dans le désert de Sinaï, en disant :'),
(3708, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 15, 'OT', 'Recense les fils de Lévi selon la maison de leurs pères, selon leurs familles ; tout mâle depuis l''âge d''un mois et au-dessus, tu les recenseras.'),
(3709, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 16, 'OT', 'Moïse les recensa selon la bouche de l''Éternel, comme il avait été commandé.'),
(3710, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 17, 'OT', 'Voici les fils de Lévi, selon leurs noms : Guerschon, Kehath et Merari.'),
(3711, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 18, 'OT', 'Et voici les noms des fils de Guerschon, selon leurs familles : Libni et Schimeï.'),
(3712, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 19, 'OT', 'Les fils de Kehath, selon leurs familles : Amram, Jitsehar, Hébron et Uziel.'),
(3713, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 20, 'OT', 'Les fils de Merari, selon leurs familles : Machli et Muschi. Ce sont là les familles des Lévites, selon la maison de leurs pères.'),
(3714, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 21, 'OT', 'Pour Guerschon : la famille des Libnites et la famille des Schimeï ; ce sont là les familles des Guerschonites.'),
(3715, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 22, 'OT', 'Leurs recensés, selon le nombre de tout mâle, depuis le fils d''un mois et au-dessus, leurs recensés : sept mille cinq cents.'),
(3716, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 23, 'OT', 'Les familles des Guerschonites camperont derrière le tabernacle, vers la mer.'),
(3717, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 24, 'OT', 'Le prince de la maison du père des Guerschonites, Éliasaph, fils de Laël.'),
(3718, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 25, 'OT', 'La charge des fils de Guerschon dans la tente d''assignation : le tabernacle et la tente, sa couverture, et le rideau de l''entrée de la tente d''assignation.'),
(3719, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 26, 'OT', 'les toiles du parvis, et le rideau de l''entrée du parvis, qui est autour du tabernacle et autour de l''autel, alentour, et ses cordes, pour tout son service.'),
(3720, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 27, 'OT', 'À Kehath : la famille des Amramites, la famille des Jitseharites, la famille des Hébronites et la famille des Uziélites ; ce sont là les familles des Kohathites.'),
(3721, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 28, 'OT', 'Selon le nombre de tout mâle, depuis un fils d''un mois et au-dessus, huit mille six cents gardiens de l''observance du saint.'),
(3722, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 29, 'OT', 'Les familles des fils de Kehath camperont sur le côté du tabernacle, vers le midi.'),
(3723, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 30, 'OT', 'Le prince de la maison du père des familles des Kohathites, Élitsaphan, fils d''Uziel.'),
(3724, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 31, 'OT', 'Leur observance était l''arche, la table, le chandelier, les autels, les ustensiles du saint lieu avec lesquels ils officiaient, le rideau, et tout son service.'),
(3725, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 32, 'OT', 'Le prince des princes des Lévites, Éléazar, fils d''Aaron le sacrificateur, avait le châtiment de l''observance des gardiens du saint.'),
(3726, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 33, 'OT', 'De Merari, la famille des Machlites et la famille des Muschites : ce sont là les familles de Merari.'),
(3727, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 34, 'OT', 'Leur recensement, selon le nombre de tout mâle depuis un fils d''un mois et au-dessus, était de six mille deux cents.'),
(3728, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 35, 'OT', 'Le prince de la maison du père des familles de Merari, Tsuriel, fils d''Abichaïl, campera au côté du tabernacle, vers le nord.'),
(3729, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 36, 'OT', 'Et le châtiment de l''observance des fils de Merari : les planches du tabernacle, ses verrous, ses piliers, ses socles, et tous ses ustensiles, et tout son service.'),
(3730, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 37, 'OT', 'Les piliers du parvis, tout alentour, leurs socles, leurs piquets et leurs cordes.'),
(3731, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 38, 'OT', 'Et ceux qui campent devant le tabernacle, vers l''orient, devant la tente d''assignation, du côté du levant, sont Moïse et Aaron et ses fils, gardant l''observance du sanctuaire pour l''observance des fils d''Israël ; et l''étranger qui s''approche sera mis à mort.'),
(3732, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 39, 'OT', 'Tous les Lévites recensés, que Moïse et Aaron recensèrent sur l''ordre de l''Éternel, selon leurs familles, tout mâle depuis l''âge d''un mois et au-dessus, furent vingt-deux mille.'),
(3733, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 40, 'OT', 'L''Éternel dit à Moïse : Recense tout premier-né mâle parmi les fils d''Israël, depuis l''âge d''un mois et au-dessus, et fais le compte du nombre de leurs noms.'),
(3734, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 41, 'OT', 'Tu prendras les Lévites pour moi, moi l''Éternel, à la place de tout premier-né parmi les fils d''Israël, et le bétail des Lévites à la place de tout premier-né parmi le bétail des fils d''Israël.'),
(3735, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 42, 'OT', 'Moïse fit le recensement, comme l''Éternel le lui avait commandé, de tout premier-né parmi les fils d''Israël.'),
(3736, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 43, 'OT', 'Tout premier-né mâle, selon le nombre des noms, depuis l''âge d''un fils de mois et au-dessus, d''après leur recensement, fut vingt-deux mille trois cent soixante-treize.'),
(3737, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 44, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3738, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 45, 'OT', 'Prends les Lévites à la place de tout premier-né parmi les fils d''Israël, et le bétail des Lévites à la place de leur bétail ; et les Lévites seront à moi : je suis l''Éternel.'),
(3739, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 46, 'OT', 'Et le rachat des deux cent soixante-treize, qui excèdent les Lévites, parmi les premiers-nés des fils d''Israël.'),
(3740, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 47, 'OT', 'Tu prendras cinq sicles par tête, selon le sicle du sanctuaire ; tu prendras vingt guéras pour le sicle.'),
(3741, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 48, 'OT', 'Tu donneras l''argent à Aaron et à ses fils, comme rachat de ceux qui sont en surplus parmi eux.'),
(3742, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 49, 'OT', 'Moïse prit l''argent de la rançon de ceux qui restaient en trop sur le rachat des Lévites.'),
(3743, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 50, 'OT', 'Des premiers-nés des fils d''Israël, il prit l''argent : mille trois cent soixante-cinq sicles, selon le sicle du sanctuaire.'),
(3744, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 3, 51, 'OT', 'Moïse donna l''argent du rachat à Aaron et à ses fils, sur la bouche de l''Éternel, comme l''Éternel l''avait commandé à Moïse.'),
(3745, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 1, 'OT', 'L''Éternel parla à Moïse et à Aaron, en disant :'),
(3746, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 2, 'OT', 'Fais le recensement des fils de Kehath, du milieu des fils de Lévi, selon leurs familles, selon la maison de leurs pères, en levant la tête.'),
(3747, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 3, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tout homme qui entre dans l''armée pour faire l''ouvrage dans la tente d''assignation.'),
(3748, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 4, 'OT', 'Voici le service des fils de Kehath dans la tente d''assignation : le lieu très saint.'),
(3749, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 5, 'OT', 'Lorsque le camp se mettra en marche, Aaron et ses fils viendront, et ils descendront le voile du rideau, et ils en couvriront l''arche du témoignage.'),
(3750, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 6, 'OT', 'On déposera sur elle une couverture de peau de dauphin, et on étendra par-dessus un vêtement tout de bleu, et on mettra ses barres.'),
(3751, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 7, 'OT', 'On la table des faces, ils étendront un vêtement bleu, et ils placeront dessus les plats, les mains, les coupes et les coupes de la libation ; et le pain continuel sera dessus.'),
(3752, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 8, 'OT', 'Ils étendront sur eux un vêtement de cramoisi, et le couvriront d''une couverture de peau de dauphin, et ils placeront ses barres.'),
(3753, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 9, 'OT', 'Ils prendront un vêtement bleu et couvriront le chandelier du luminaire, ses lampes, ses mouchettes, ses brasiers, et tous les ustensiles de son huile avec lesquels on le sert.'),
(3754, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 10, 'OT', 'Ils la mettront, elle et tous ses ustensiles, sur une couverture de peau de dauphin, et ils la placeront sur la perche.'),
(3755, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 11, 'OT', 'On l''autel d''or, ils étendront un vêtement bleu, et ils le couvriront d''une couverture de peau de dauphin, et ils placeront ses seuls.'),
(3756, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 12, 'OT', 'Ils prendront tous les ustensiles du service avec lesquels on sert dans le saint lieu, et les mettront sur un vêtement bleu, les couvriront d''une couverture de peau de dauphin, et les placeront sur la perche.'),
(3757, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 13, 'OT', 'Ils ôteront les cendres de l''autel, et étendront dessus un vêtement de pourpre.'),
(3758, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 14, 'OT', 'Ils placeront sur lui tous ses ustensiles avec lesquels on le sert : les brasiers, les fourchettes, les pelles et les bassins, tous les ustensiles de l''autel ; puis ils étendront sur lui une couverture de peau de dauphin, et ils mettront ses seuls.'),
(3759, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 15, 'OT', 'Quand Aaron et ses fils auront achevé de couvrir le saint et tous les ustensiles du saint, au départ du camp, après cela, les fils de Kehath viendront pour porter, et ils ne toucheront pas au saint, sinon ils mourront. Ce sont là les fardeaux des fils de Kehath dans la tente d''assignation.'),
(3760, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 16, 'OT', 'Le châtiment d''Éléazar, fils d''Aaron le sacrificateur, était l''huile du luminaire, l''encens des aromates, l''offrande de toujours et l''huile de l''onction ; le châtiment de tout le tabernacle et de tout ce qui s''y trouve, dans le saint et dans ses ustensiles.'),
(3761, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 17, 'OT', 'L''Éternel parla à Moïse et à Aaron, en disant :'),
(3762, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 18, 'OT', 'Ne coupez pas la tribu des familles des Kohathites du milieu des Lévites.'),
(3763, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 19, 'OT', 'Et voici ce que vous leur ferez, afin qu''ils vivent et ne meurent pas lorsqu''ils s''approchent du saint des saints : Aaron et ses fils viendront, et ils les placeront, chaque homme à son service et à son fardeau.'),
(3764, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 20, 'OT', 'Et ils ne viendront pas pour voir lorsqu''on engloutit le saint, et ils mourront.'),
(3765, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 21, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3766, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 22, 'OT', 'Fais le recensement de la tête des fils de Guerschon, eux aussi, selon la maison de leurs pères, selon leurs familles.'),
(3767, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 23, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tu les recenseras, tous ceux qui viennent pour l''armée du service, pour faire le service dans la tente de l''assignation.'),
(3768, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 24, 'OT', 'C''est le service des familles du Guerschonite, pour servir et pour porter le fardeau.'),
(3769, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 25, 'OT', 'Ils porteront les tapis du tabernacle, et la tente de l''assignation, sa couverture, et la couverture de peau de dauphin qui est au-dessus, et le rideau de l''entrée de la tente de l''assignation.'),
(3770, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 26, 'OT', 'et les toiles du parvis, et le rideau de l''entrée de la porte du parvis, qui est sur le tabernacle et sur l''autel, tout alentour, et leurs cordes, et tous les ustensiles de leur service, et tout ce qui sera fait pour eux, et ils serviront.'),
(3771, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 27, 'OT', 'Selon la bouche d''Aaron et de ses fils sera tout le service des fils du Guerschonite, pour tout leur fardeau et pour tout leur service ; et vous leur confierez en observance tout leur fardeau.'),
(3772, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 28, 'OT', 'Tel est le service des familles des fils des Guerschonites dans la tente d''assignation, et leur observance est sous la main d''Ithamar, fils d''Aaron, le sacrificateur.'),
(3773, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 29, 'OT', 'Les fils de Merari, selon leurs familles, par la maison de leurs pères, tu les compteras.'),
(3774, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 30, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tu les recenseras, tous ceux qui viennent à l''armée, pour accomplir le service de la tente d''assignation.'),
(3775, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 31, 'OT', 'Et voici l''observance de leur fardeau, pour tout leur service dans la tente d''assignation : les planches du tabernacle, ses verrous, ses piliers et ses socles.'),
(3776, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 32, 'OT', 'Et les piliers du parvis, tout alentour, et leurs socles, et leurs piquets, et leurs cordes, pour tous leurs ustensiles et pour tout leur service ; et par nom vous compterez les ustensiles de l''observance de leur fardeau.'),
(3777, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 33, 'OT', 'C''est le service des familles des fils de Merari, pour tout leur service dans la tente d''assignation, par la main d''Ithamar, fils d''Aaron, le sacrificateur.'),
(3778, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 34, 'OT', 'Moïse, Aaron et les princes de l''assemblée firent le recensement des fils des Kohathites, selon leurs familles et selon la maison de leurs pères.'),
(3779, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 35, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tous ceux qui entrent dans l''armée pour le service dans la tente d''assignation.'),
(3780, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 36, 'OT', 'Leurs recensés, selon leurs familles, furent deux mille sept cent cinquante.'),
(3781, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 37, 'OT', 'Voici les familles des Kohathites, tous ceux qui servaient dans la tente d''assignation, que Moïse et Aaron recensèrent sur l''ordre de l''Éternel par la main de Moïse.'),
(3782, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 38, 'OT', 'Et les recensés des fils de Guerschon, selon leurs familles et selon la maison de leurs pères.'),
(3783, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 39, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tous ceux qui viennent à l''armée pour le service dans la tente d''assignation.'),
(3784, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 40, 'OT', 'Leurs recensés, selon leurs familles, selon la maison de leurs pères, furent deux mille six cent trente.'),
(3785, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 41, 'OT', 'Voici les recensements des familles des fils de Guerschon, tous ceux qui servent dans la tente d''assignation, que Moïse et Aaron recensèrent sur l''ordre de la bouche de l''Éternel.'),
(3786, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 42, 'OT', 'Et les recensés des familles des fils de Merari, selon leurs familles, selon la maison de leurs pères :'),
(3787, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 43, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tous ceux qui viennent pour l''armée, pour le service dans la tente d''assignation.'),
(3788, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 44, 'OT', 'Leurs recensés, selon leurs familles, étaient trois mille deux cents.'),
(3789, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 45, 'OT', 'Voici les recensements des familles des fils de Merari, que Moïse et Aaron dénombrèrent sur l''ordre de l''Éternel, par la main de Moïse.'),
(3790, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 46, 'OT', 'Tous les recensés que Moïse et Aaron et les princes d''Israël recensèrent parmi les Lévites, selon leurs familles et selon la maison de leurs pères.'),
(3791, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 47, 'OT', 'Depuis l''âge de trente ans et au-dessus, jusqu''à l''âge de cinquante ans, tous ceux qui viennent pour accomplir le service du service et le service du fardeau dans la tente d''assignation.'),
(3792, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 48, 'OT', 'Leur recensement fut de huit mille cinq cent quatre-vingts.'),
(3793, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 4, 49, 'OT', 'Selon la bouche de l''Éternel, ils furent recensés par la main de Moïse, chaque homme selon son service et selon son fardeau ; et ses recensements, que l''Éternel avait commandés à Moïse.'),
(3794, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3795, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 2, 'OT', 'Ordonne aux fils d''Israël de renvoyer hors du camp tout lépreux, et tout homme atteint d''écoulement, et tout homme impur à cause d''une âme.'),
(3796, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 3, 'OT', 'Du mâle jusqu''à la femelle, vous les renverrez ; c''est dehors du camp que vous les renverrez, et ils ne souilleront pas leur camp, au milieu duquel je demeure.'),
(3797, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 4, 'OT', 'Les fils d''Israël firent ainsi, et ils les renvoyèrent dehors, hors du camp ; comme l''Éternel avait parlé à Moïse, ainsi firent les fils d''Israël.'),
(3798, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 5, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3799, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 6, 'OT', 'Parle aux fils d''Israël : si un homme ou une femme commet l''un de tous les péchés des hommes, en agissant avec perfidie envers l''Éternel, cette âme-là sera coupable.'),
(3800, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 7, 'OT', 'Ils confesseront leur péché qu''ils ont commis, et il restituera son sacrifice de culpabilité en sa tête, et il y ajoutera son cinquième, et il le donnera à celui envers qui il a été coupable.'),
(3801, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 8, 'OT', 'Et s''il n''y a pas d''homme à qui restituer le sacrifice de culpabilité, le sacrifice de culpabilité restitué sera pour l''Éternel, pour le sacrificateur, en plus du bélier d''expiation par lequel on fera l''expiation pour lui.'),
(3802, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 9, 'OT', 'Et toute offrande de toutes les choses saintes des fils d''Israël, qu''ils présenteront au sacrificateur, lui appartiendra.'),
(3803, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 10, 'OT', 'Et un homme, ses choses saintes seront à lui ; ce qu''un homme donnera au sacrificateur sera à lui.'),
(3804, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 11, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3805, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 12, 'OT', 'Parle aux fils d''Israël et dis-leur : Si un homme dont la femme s''égare et commet une perfidie contre lui,'),
(3806, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 13, 'OT', 'Un homme couche avec elle en couche de postérité, et cela est caché aux yeux de son mari, et elle se dissimule, et elle est souillée, et il n''y a pas de témoin contre elle, et elle n''a pas été surprise.'),
(3807, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 14, 'OT', 'Et un esprit de jalousie passe sur lui, et il est jaloux de sa femme, et elle est souillée ; ou un esprit de jalousie passe sur lui, et il est jaloux de sa femme, et elle n''est pas souillée.'),
(3808, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 15, 'OT', 'L''homme amènera sa femme au sacrificateur, et il apportera son offrande pour elle : un dixième d''épha de farine d''orge ; il ne versera pas d''huile dessus, et il ne mettra pas d''encens dessus, car c''est une offrande de jalousie, une offrande de mémorial qui rappelle l''iniquité.'),
(3809, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 16, 'OT', 'Le sacrificateur la fera approcher et la fera se tenir devant la face de l''Éternel.'),
(3810, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 17, 'OT', 'Le sacrificateur prendra des eaux saintes dans un ustensile de vase de terre, et de la poussière qui sera sur le sol du tabernacle, le sacrificateur la prendra et la mettra dans les eaux.'),
(3811, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 18, 'OT', 'Le sacrificateur fera tenir la femme devant la face de l''Éternel, et il découvrira la tête de la femme, et il mettra sur ses mains l''offrande de mémorial, l''offrande de jalousie, et dans la main du sacrificateur seront les eaux amères qui apportent la malédiction.'),
(3812, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 19, 'OT', 'Le sacrificateur la fera jurer et dira à la femme : Si aucun homme n''a couché avec toi, et si tu ne t''es pas égarée en impureté sous ton homme, sois libre de ces eaux amères qui apportent la malédiction.'),
(3813, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 20, 'OT', 'Et toi, si tu t''es égarée loin de ton homme, et si tu t''es souillée, et qu''un homme a déposé en toi son coucher, en dehors de ton homme,'),
(3814, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 21, 'OT', 'Le sacrificateur fera jurer la femme par le serment de malédiction, et le sacrificateur dira à la femme : Que l''Éternel te donne pour malédiction et pour serment au milieu de ton peuple, en faisant tomber ton côté et en gonflant ton ventre.'),
(3815, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 22, 'OT', 'Et ces eaux qui apportent la malédiction entreront dans tes entrailles pour faire gonfler le ventre et faire tomber le côté, et la femme dira : Amen, amen.'),
(3816, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 23, 'OT', 'Le sacrificateur écrira ces malédictions dans le livre, et il les effacera dans les eaux amères.'),
(3817, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 24, 'OT', 'Et il fera boire à la femme les eaux amères qui portent malédiction, et les eaux qui portent malédiction entreront en elle pour produire l''amertume.'),
(3818, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 25, 'OT', 'Le sacrificateur prendra de la main de la femme l''offrande de jalousie, il élèvera l''offrande devant la face de l''Éternel, et il la présentera à l''autel.'),
(3819, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 26, 'OT', 'Le sacrificateur prendra de l''offrande son mémorial, et il le fera fumer sur l''autel ; ensuite, il fera boire les eaux à la femme.'),
(3820, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 27, 'OT', 'Il lui fera boire les eaux, et il arrivera que, si elle s''est souillée et a commis une perfidie contre son homme, les eaux qui apportent l''amertume entreront en elle, son ventre enflera, son côté tombera, et la femme deviendra une malédiction au milieu de son peuple.'),
(3821, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 28, 'OT', 'Mais si la femme ne s''est pas souillée et qu''elle est pure, elle sera déclarée innocente et aura une postérité.'),
(3822, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 29, 'OT', 'Voici la loi de la jalousie, lorsqu''une femme s''égare de son homme et se souille.'),
(3823, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 30, 'OT', 'Ou bien un homme sur qui passe un esprit de jalousie, et qui est jaloux de sa femme, il placera la femme devant l''Éternel, et le sacrificateur accomplira pour elle toute cette loi.'),
(3824, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 5, 31, 'OT', 'L''homme sera absous de son iniquité, et cette femme-là portera son iniquité.'),
(3825, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 1, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3826, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 2, 'OT', 'Parle aux fils d''Israël et dis-leur : Si un homme ou une femme fait un vœu spécial, un vœu de naziréen, pour se consacrer à l''Éternel,'),
(3827, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 3, 'OT', 'Il s''abstiendra de vin et de boisson forte ; il ne boira ni vinaigre de vin ni vinaigre de boisson forte ; et il ne boira toute liqueur de raisin ; et il ne mangera ni raisins frais ni raisins secs.'),
(3828, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 4, 'OT', 'Tout les jours de son diadème, de tout ce qui est fait de la vigne du vin, depuis les pépins jusqu''au pépin, il ne mangera point.'),
(3829, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 5, 'OT', 'Tout les jours de son vœu de diadème, un rasoir ne passera point sur sa tête ; jusqu''à l''accomplissement des jours qu''il se consacre à l''Éternel, il sera saint, laissant croître les cheveux de sa tête.'),
(3830, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 6, 'OT', 'Tous les jours de sa consécration à l''Éternel, il ne s''approchera point d''une âme morte.'),
(3831, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 7, 'OT', 'Il ne se rendra pas impur pour son père, ni pour sa mère, ni pour son frère, ni pour sa sœur, à leur mort, car le diadème de son Dieu est sur sa tête.'),
(3832, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 8, 'OT', 'Tous les jours de son diadème, il est saint à l''Éternel.'),
(3833, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 9, 'OT', 'Et si quelqu''un meurt subitement sur lui, soudainement, et souille la tête de son diadème, il rasera sa tête au jour de sa purification ; au septième jour, il la rasera.'),
(3834, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 10, 'OT', 'Et au huitième jour, il apportera deux tourterelles ou deux jeunes pigeons au sacrificateur, à l''entrée de la tente d''assignation.'),
(3835, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 11, 'OT', 'Le sacrificateur offrira l''un en sacrifice pour le péché et l''autre en holocauste, et il fera l''expiation pour lui à cause du péché qu''il a commis en touchant l''âme, et il sanctifiera sa tête en ce jour-là.'),
(3836, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 12, 'OT', 'Il consacrera à l''Éternel les jours de son diadème, et il apportera un agneau d''un an, en sacrifice de culpabilité ; et les jours précédents seront perdus, car son diadème a été souillé.'),
(3837, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 13, 'OT', 'Et voici la loi du naziréen : au jour où seront accomplis les jours de son diadème, il l''amènera à l''entrée de la tente d''assignation.'),
(3838, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 14, 'OT', 'Il offrira son offrande à l''Éternel : un agneau d''un an, sans défaut, pour holocauste, et une agnelle d''un an, sans défaut, pour le péché, et un bélier sans défaut pour le sacrifice d''actions de grâces.'),
(3839, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 15, 'OT', 'une corbeille de pains sans levain, des gâteaux de fleur de farine pétris à l''huile, et des galettes sans levain ointes d''huile, avec leur offrande et leurs libations.'),
(3840, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 16, 'OT', 'Le sacrificateur l''offrira devant la face de l''Éternel, et il fera son péché et son holocauste.'),
(3841, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 17, 'OT', 'Il offrira le bélier en sacrifice d''actions de grâces à l''Éternel, avec la corbeille de pains sans levain ; et le sacrificateur fera son offrande et sa libation.'),
(3842, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 18, 'OT', 'Le naziréen rasera, à l''entrée de la tente d''assignation, la tête de son diadème ; il prendra les cheveux de la tête de son diadème, et les mettra sur le feu qui est sous le sacrifice d''actions de grâces.'),
(3843, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 19, 'OT', 'Le sacrificateur prendra le bras cuit du bélier, un gâteau de pains sans levain de la corbeille, et une galette de pains sans levain, et les mettra sur les mains du naziréen, après qu''il aura rasé son diadème.'),
(3844, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 20, 'OT', 'Le sacrificateur les balancera en offrande devant l''Éternel ; c''est une chose sainte pour le sacrificateur, avec la poitrine de l''offrande balancée et l''épaule de l''offrande élevée ; et après cela, le naziréen pourra boire du vin.'),
(3845, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 21, 'OT', 'Voici la loi du naziréen qui fait vœu : son offrande à l''Éternel pour son diadème, en dehors de ce que sa main peut atteindre ; selon la bouche de son vœu qu''il voue, ainsi fera-t-il, conformément à la loi de son diadème.'),
(3846, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 22, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3847, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 23, 'OT', 'Parle à Aaron et à ses fils, en disant : Ainsi vous bénirez les fils d''Israël, en leur disant :'),
(3848, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 24, 'OT', 'Que l''Éternel te bénisse et te garde.'),
(3849, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 25, 'OT', 'Que l''Éternel fasse resplendir sa face sur toi et te fasse grâce.'),
(3850, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 26, 'OT', 'Que l''Éternel élève sa face vers toi et te donne la paix.'),
(3851, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 6, 27, 'OT', 'Ils mettront mon nom sur les fils d''Israël, et moi, je les bénirai.'),
(3852, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 1, 'OT', 'Il arriva, au jour où Moïse acheva de dresser le tabernacle, qu''il l''oignit et le sanctifia, avec tous ses ustensiles, ainsi que l''autel et tous ses ustensiles ; il les oignit et les sanctifia.'),
(3853, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 2, 'OT', 'Les princes d''Israël, les têtes de la maison de leurs pères, eux les princes des tribus, eux qui se tenaient sur les recensés, offrirent.'),
(3854, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 3, 'OT', 'Ils apportèrent leur offrande devant l''Éternel : six chars de litière et douze bœufs, un char pour deux princes et un bœuf pour chacun ; et ils les présentèrent devant le tabernacle.'),
(3855, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 4, 'OT', 'L''Éternel parla à Moïse, en disant :'),
(3856, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 5, 'OT', 'Prends-les d''eux, et ils seront pour le service de la tente d''assignation ; et tu les donneras aux Lévites, à chaque homme selon sa bouche de service.'),
(3857, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 6, 'OT', 'Moïse prit les chars et les bœufs, et les donna aux Lévites.'),
(3858, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 7, 'OT', 'Il donna les deux chars et les quatre bœufs aux fils de Guerschon, selon la bouche de leur service.'),
(3859, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 8, 'OT', 'Et les quatre chars et les huit bœufs, il les donna aux fils de Merari, selon le service qu''ils avaient à faire, par la main d''Ithamar, fils d''Aaron, le sacrificateur, selon la bouche de leur service.'),
(3860, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 9, 'OT', 'Mais aux fils de Kehath il ne donna rien, car le service du saint reposait sur eux ; c''est sur le côté qu''ils porteront.'),
(3861, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 10, 'OT', 'Les princes offrirent la dédicace de l''autel au jour où on l''oignit, et les princes présentèrent leur offrande devant l''autel.'),
(3862, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 11, 'OT', 'L''Éternel dit à Moïse : Un prince par jour, un prince par jour, ils présenteront leur offrande pour la dédicace de l''autel.'),
(3863, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 12, 'OT', 'Il arriva que celui qui offrit son offrande le premier jour fut Nachschon, fils d''Amminadab, de la tribu de Juda.'),
(3864, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 13, 'OT', 'Son offrande était un plat d''argent, son poids de cent trente sicles, un bassin d''argent de soixante-dix sicles, selon le sicle du sanctuaire, tous deux remplis de fleur de farine pétrie à l''huile, pour une offrande.'),
(3865, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 14, 'OT', 'une main, dix sicles d''or, pleine d''encens'),
(3866, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 15, 'OT', 'Un jeune taureau, un bélier, un agneau d''un an, pour holocauste.'),
(3867, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 16, 'OT', 'Un bouc, un mâle de chèvre, pour le péché.'),
(3868, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 17, 'OT', 'Et pour le sacrifice d''actions de grâces : deux bœufs, cinq béliers, cinq boucs, cinq agneaux âgés d''un an ; telle fut l''offrande de Nachschon, fils d''Amminadab.'),
(3869, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 18, 'OT', 'Le deuxième jour, Nethaneel, fils de Tsuar, prince d''Issacar, offrit son offrande.'),
(3870, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 19, 'OT', 'Il offrit son offrande : un plat d''argent du poids de cent trente sicles, un bassin d''argent de soixante-dix sicles, selon le sicle du sanctuaire ; tous deux pleins de fleur de farine pétrie à l''huile, pour une offrande.'),
(3871, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 20, 'OT', 'une main, dix sicles d''or, pleine d''encens'),
(3872, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 21, 'OT', 'Un jeune taureau, un bélier, un agneau d''un an, pour holocauste.'),
(3873, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 22, 'OT', 'Un bouc, un seul, pour le péché.'),
(3874, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 23, 'OT', 'Et pour le sacrifice d''actions de grâces, deux bœufs, cinq béliers, cinq boucs, cinq agneaux d''un an ; telle fut l''offrande de Nethaneel, fils de Tsuar.'),
(3875, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 24, 'OT', 'Le troisième jour, le prince des fils de Zabulon, Éliab, fils d''Hélon.'),
(3876, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 25, 'OT', 'Son offrande était un plat d''argent, dont le poids était de cent trente sicles, un bassin d''argent de soixante-dix sicles, selon le sicle du sanctuaire, tous deux pleins de fleur de farine pétrie à l''huile, pour une offrande.'),
(3877, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 26, 'OT', 'une main, dix sicles d''or, pleine d''encens'),
(3878, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 27, 'OT', 'Un jeune taureau, un bélier, un agneau d''un an, pour holocauste.'),
(3879, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 28, 'OT', 'Un bouc des chèvres, un seul, pour le péché.'),
(3880, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 29, 'OT', 'Et pour le sacrifice d''actions de grâces : deux bœufs, cinq béliers, cinq boucs, cinq agneaux âgés d''un an ; telle fut l''offrande d''Éliab, fils de Hélon.'),
(3881, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 30, 'OT', 'Le quatrième jour, prince des fils de Ruben, Élitsur, fils de Schedéur.'),
(3882, 4, 'GOI_Fr', 'GOI_Fr', 'fr', 'NUM', 7, 31, 'OT', 'Son offrande était un plat d''argent du poids de cent trente sicles, un bassin d''argent de soixante-dix sicles, selon le sicle du sanctuaire, tous deux pleins de fleur de farine pétrie à l''huile, pour une offrande.'),
